insert into public.recipes (title, description, meal_type, category, budget_tier, tags, ingredients, instructions, serving_size, prep_time_minutes, cook_time_minutes, cost_per_serving, cost_estimate, calories, protein_g, carbs_g, fats_g, fiber_g, sodium_mg, kid_friendly, is_public, is_active, source) values
  ('Peanut Spread Banana Overnight Oats', 'Creamy rolled oats soaked overnight with peanut spread and ripe banana for a ready-to-eat morning jar.', 'breakfast', 'No-Cook', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','meal-prep','no-cook','one-pot','soy-free','vegan','vegetarian']::text[], '["1 cup rolled oats", "1 cup water", "2 tbsp peanut spread", "1 banana", "1 tbsp maple syrup", "1 tsp vanilla extract", "1 pinch salt"]'::jsonb, '["Combine rolled oats and water in a jar or bowl.", "Stir in peanut spread, maple syrup, vanilla extract, and salt.", "Slice banana and fold half into the oat mixture.", "Cover and refrigerate overnight or at least 6 hours.", "Top with remaining banana slices before serving."]'::jsonb, 2, 5, 0, 0.85, 1.7, 320, 9, 52, 9, 6, 95, true, true, true, 'curated'),
  ('Spiced Chickpea Scramble', 'Mashed chickpeas cooked with turmeric, cumin, and peppers for a savory, satisfying morning scramble.', 'breakfast', 'Skillet', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','one-pan','quick','soy-free','spiced','vegan','vegetarian']::text[], '["2 cans chickpeas", "1 bell pepper", "1 onion", "2 cloves garlic", "1 tbsp olive oil", "1 tsp turmeric", "1 tsp cumin", "1 tsp paprika", "salt", "pepper", "2 tbsp nutritional yeast"]'::jsonb, '["Dice onion, bell pepper, and mince garlic.", "Heat olive oil in a skillet over medium heat and saut\u00e9 onion and pepper for 4 minutes.", "Add garlic and spices, cook 1 minute until fragrant.", "Drain chickpeas and add to pan, mashing roughly with a fork.", "Stir in nutritional yeast, season with salt and pepper, and cook 3 more minutes."]'::jsonb, 4, 8, 10, 0.95, 3.8, 285, 14, 42, 6, 10, 310, true, true, true, 'curated'),
  ('Apple Cinnamon Steel-Cut Porridge', 'Hearty steel-cut oats simmered with diced apple, cinnamon, and a drizzle of maple syrup for a warming bowl.', 'breakfast', 'Porridge', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','meal-prep','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["1 cup steel-cut oats", "3 cups water", "2 apples", "1 tsp cinnamon", "1 tbsp maple syrup", "1 pinch salt", "1 tsp vanilla extract"]'::jsonb, '["Bring water to a boil in a saucepan and add steel-cut oats and salt.", "Reduce heat to low and simmer for 20 minutes, stirring occasionally.", "Peel and dice apples; stir into the oats after 15 minutes.", "Add cinnamon and vanilla extract in the final 5 minutes.", "Serve topped with a drizzle of maple syrup."]'::jsonb, 4, 5, 22, 0.7, 2.8, 230, 6, 48, 2, 7, 80, true, true, true, 'curated'),
  ('Black Bean Breakfast Tacos', 'Warm corn tortillas packed with seasoned black beans, fresh salsa, and avocado for a bold morning bite.', 'breakfast', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','kid-friendly','mexican','nut-free','one-pan','quick','soy-free','vegan','vegetarian']::text[], '["2 cans black beans", "8 corn tortillas", "1 avocado", "1 cup salsa", "1 tsp cumin", "1 tsp chili powder", "1 tbsp olive oil", "1 lime", "salt", "pepper"]'::jsonb, '["Drain and rinse black beans; heat in a skillet with olive oil, cumin, and chili powder for 5 minutes.", "Warm corn tortillas in a dry pan or directly over a flame for 30 seconds each side.", "Slice avocado and squeeze lime juice over it.", "Fill each tortilla with beans, avocado slices, and a spoonful of salsa.", "Season with salt and pepper and serve immediately."]'::jsonb, 4, 8, 8, 1.8, 7.2, 360, 15, 58, 10, 14, 420, true, true, true, 'curated'),
  ('Savory Oatmeal with White Beans and Spinach', 'Quick-cooking oats topped with sautéed spinach, white beans, and garlic for a protein-packed savory morning bowl.', 'breakfast', 'Bowl', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','nut-free','one-pot','quick','savory','soy-free','vegan','vegetarian']::text[], '["1 cup rolled oats", "2 cups water", "1 can white beans", "2 cups baby spinach", "2 cloves garlic", "1 tbsp olive oil", "1 tsp paprika", "salt", "pepper"]'::jsonb, '["Cook oats in water according to package directions.", "Mince garlic and saut\u00e9 in olive oil over medium heat for 1 minute.", "Add spinach and cook until wilted, about 2 minutes.", "Drain and rinse white beans; stir into the spinach mixture with paprika.", "Spoon oatmeal into bowls and top with the bean and spinach mixture, season to taste."]'::jsonb, 2, 5, 10, 1.1, 2.2, 340, 16, 56, 7, 12, 290, false, true, true, 'curated'),
  ('Mango Ginger Chia Pudding', 'Chia seeds soaked in coconut water and blended with mango and fresh ginger for a tropical breakfast pudding.', 'breakfast', 'No-Cook', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','meal-prep','no-cook','nut-free','soy-free','tropical','vegan','vegetarian']::text[], '["1/2 cup chia seeds", "2 cups coconut water", "2 mangos", "1 tsp fresh ginger", "1 tbsp maple syrup", "1 tsp lime juice"]'::jsonb, '["Combine chia seeds and coconut water in a bowl and whisk well.", "Refrigerate for at least 4 hours or overnight, stirring once after 30 minutes.", "Peel and dice mangos; blend half with ginger, lime juice, and maple syrup until smooth.", "Stir the mango pur\u00e9e into the chia pudding.", "Serve topped with diced fresh mango."]'::jsonb, 4, 10, 0, 1.65, 6.6, 210, 7, 36, 8, 11, 55, true, true, true, 'curated'),
  ('Sweet Potato and Lentil Hash', 'Diced sweet potato and red lentils pan-fried with smoked paprika and onion into a hearty, caramelized morning hash.', 'breakfast', 'Hash', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','kid-friendly','meal-prep','nut-free','one-pan','soy-free','vegan','vegetarian']::text[], '["2 sweet potatoes", "1 cup red lentils", "1 onion", "2 cloves garlic", "1 tbsp olive oil", "1 tsp smoked paprika", "1 tsp cumin", "salt", "pepper", "2 cups water"]'::jsonb, '["Cook red lentils in 2 cups water for 12 minutes until just tender; drain and set aside.", "Peel and dice sweet potatoes into small cubes; dice onion and mince garlic.", "Heat olive oil in a large skillet, add sweet potato and onion, cook 8 minutes until golden.", "Add garlic, paprika, and cumin; stir 1 minute.", "Fold in cooked lentils, press down gently, and cook 3 more minutes to crisp the bottom.", "Season with salt and pepper and serve directly from the pan."]'::jsonb, 4, 10, 25, 1.2, 4.8, 295, 13, 52, 4, 11, 180, true, true, true, 'curated'),
  ('Blueberry Lemon Baked Oatmeal', 'A pan of rolled oats baked with fresh blueberries, lemon zest, and maple syrup that slices into portable squares.', 'breakfast', 'Baked', 'ultra_budget', ARRAY['baked','budget','dairy-free','egg-free','freezer-friendly','gluten-free','high-fiber','kid-friendly','meal-prep','nut-free','soy-free','vegan','vegetarian']::text[], '["3 cups rolled oats", "2 cups blueberries", "2 cups water", "1/4 cup maple syrup", "1 lemon", "1 tsp vanilla extract", "1 tsp cinnamon", "1/2 tsp baking powder", "1 pinch salt"]'::jsonb, '["Preheat oven to 375\u00b0F and lightly grease an 8x8 baking dish.", "Zest and juice the lemon; combine oats, baking powder, cinnamon, and salt in a bowl.", "Mix in water, maple syrup, vanilla, and lemon juice; fold in blueberries.", "Pour into the baking dish, top with lemon zest, and bake 35 minutes until set.", "Let cool 10 minutes before slicing into squares."]'::jsonb, 6, 10, 35, 1.4, 8.4, 250, 7, 50, 3, 6, 95, true, true, true, 'curated'),
  ('Tofu and Pepper Breakfast Burrito', 'Crumbled tofu stir-fried with colorful peppers and wrapped in a warm flour tortilla for a filling morning burrito.', 'breakfast', 'Burrito', 'budget', ARRAY['budget','dairy-free','egg-free','kid-friendly','meal-prep','mexican','nut-free','one-pan','vegan','vegetarian']::text[], '["1 lb firm tofu", "4 large flour tortillas", "1 bell pepper", "1 cup frozen corn", "1 onion", "2 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp paprika", "1/2 tsp turmeric", "salt", "pepper", "1 cup salsa"]'::jsonb, '["Press tofu between towels for 5 minutes, then crumble into small pieces.", "Dice onion and pepper; mince garlic.", "Heat olive oil in a skillet; saut\u00e9 onion and pepper 4 minutes.", "Add garlic and tofu; stir in turmeric, cumin, and paprika and cook 6 minutes until golden.", "Add corn and cook 2 more minutes; season with salt and pepper.", "Warm tortillas, fill with tofu mixture, top with salsa, and roll up."]'::jsonb, 4, 12, 14, 2.1, 8.4, 380, 18, 50, 11, 6, 490, true, true, true, 'curated'),
  ('Banana Walnut Oat Pancakes', 'Fluffy, golden pancakes made from blended oats, ripe banana, and walnuts with no fuss and big flavor.', 'breakfast', 'Pancakes', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','kid-favorite','kid-friendly','one-pan','quick','soy-free','vegan','vegetarian']::text[], '["2 cups rolled oats", "2 ripe bananas", "1 cup water", "1/3 cup chopped walnuts", "1 tsp vanilla extract", "1 tsp baking powder", "1 tsp cinnamon", "1 pinch salt", "1 tbsp maple syrup"]'::jsonb, '["Blend rolled oats into a fine flour in a blender.", "Add bananas, water, vanilla, baking powder, cinnamon, and salt; blend until smooth.", "Fold in walnuts by hand.", "Heat a non-stick skillet over medium heat and pour 1/4 cup batter per pancake.", "Cook 2-3 minutes per side until golden; serve with maple syrup."]'::jsonb, 4, 8, 15, 1.3, 5.2, 310, 8, 50, 9, 6, 130, true, true, true, 'curated'),
  ('Red Lentil Dal Breakfast Bowl', 'A warming bowl of spiced red lentils cooked down into a thick, golden dal served over fluffy white rice.', 'breakfast', 'Indian', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','indian','nut-free','one-pot','soy-free','spiced','vegan','vegetarian']::text[], '["1 cup red lentils", "2 cups white rice", "1 onion", "2 cloves garlic", "1 tsp fresh ginger", "1 can diced tomatoes", "1 tsp cumin", "1 tsp coriander", "1/2 tsp turmeric", "1 tbsp olive oil", "salt", "3 cups water"]'::jsonb, '["Cook rice according to package directions.", "Dice onion, mince garlic and ginger; saut\u00e9 in olive oil 4 minutes.", "Add cumin, coriander, and turmeric; stir 1 minute.", "Add rinsed red lentils, diced tomatoes, and water; bring to a boil.", "Reduce heat and simmer 20 minutes until lentils are soft; season with salt.", "Serve dal over rice."]'::jsonb, 4, 10, 25, 1.05, 4.2, 410, 18, 74, 5, 12, 260, false, true, true, 'curated'),
  ('Strawberry Almond Smoothie Bowl', 'Thick blended strawberries and banana topped with granola, sliced almonds, and fresh fruit for a colorful morning bowl.', 'breakfast', 'Smoothie Bowl', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','kid-favorite','kid-friendly','no-cook','quick','soy-free','vegan','vegetarian']::text[], '["2 cups frozen strawberries", "1 banana", "1/4 cup orange juice", "1/2 cup granola", "2 tbsp sliced almonds", "1 tbsp maple syrup"]'::jsonb, '["Blend frozen strawberries, banana, and orange juice until very thick and smooth.", "Pour into bowls.", "Top with granola, sliced almonds, and a drizzle of maple syrup.", "Serve immediately."]'::jsonb, 2, 5, 0, 1.9, 3.8, 320, 7, 62, 7, 8, 45, true, true, true, 'curated'),
  ('Pumpkin Spice Oatmeal Cups', 'Baked individual oatmeal cups packed with canned pumpkin, warm spices, and pecans that travel well all week.', 'breakfast', 'Baked', 'ultra_budget', ARRAY['baked','budget','dairy-free','egg-free','freezer-friendly','gluten-free','high-fiber','kid-friendly','meal-prep','nut-free','soy-free','vegan','vegetarian']::text[], '["2 cups rolled oats", "1 can pumpkin puree", "1/4 cup maple syrup", "1 cup water", "1/3 cup chopped pecans", "1 tsp cinnamon", "1/2 tsp nutmeg", "1/4 tsp cloves", "1 tsp baking powder", "1 pinch salt"]'::jsonb, '["Preheat oven to 350\u00b0F and grease a 12-cup muffin tin.", "Combine all ingredients in a large bowl and mix well.", "Divide batter evenly among muffin cups.", "Bake 22-25 minutes until set and lightly golden.", "Cool 10 minutes in pan, then remove and store in an airtight container."]'::jsonb, 6, 10, 25, 1.45, 8.7, 240, 6, 42, 7, 6, 110, true, true, true, 'curated'),
  ('Turmeric Tofu Scramble with Kale', 'Silky tofu crumbled and pan-cooked with kale, turmeric, and black pepper for a vibrant golden morning scramble.', 'breakfast', 'Skillet', 'budget', ARRAY['budget','dairy-free','egg-free','nut-free','one-pan','quick','savory','vegan','vegetarian']::text[], '["1 lb firm tofu", "3 cups chopped kale", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp turmeric", "1/2 tsp black pepper", "2 tbsp nutritional yeast", "1 tbsp soy sauce", "salt"]'::jsonb, '["Press tofu and crumble into rough chunks.", "Dice onion and mince garlic; saut\u00e9 in olive oil 3 minutes.", "Add tofu and cook over medium-high heat 5 minutes, stirring occasionally.", "Add turmeric, black pepper, nutritional yeast, and soy sauce; stir well.", "Add kale and cook until wilted, about 3 minutes.", "Taste and adjust salt, then serve."]'::jsonb, 4, 8, 12, 2.0, 8.0, 200, 17, 14, 10, 3, 310, false, true, true, 'curated'),
  ('Maple Tahini Granola', 'Clusters of oats, sunflower seeds, and sesame drizzled with maple and tahini and baked until deeply golden and crunchy.', 'breakfast', 'Baked', 'budget', ARRAY['baked','budget','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','meal-prep','nut-free','snackable','soy-free','vegan','vegetarian']::text[], '["3 cups rolled oats", "1/4 cup tahini", "1/4 cup maple syrup", "1/4 cup sunflower seeds", "2 tbsp sesame seeds", "1 tsp vanilla extract", "1/2 tsp cinnamon", "1 pinch salt"]'::jsonb, '["Preheat oven to 325\u00b0F and line a baking sheet with parchment paper.", "Whisk together tahini, maple syrup, vanilla, and cinnamon.", "Toss oats, sunflower seeds, and sesame seeds with the tahini mixture until coated.", "Spread evenly on the baking sheet and bake 25-30 minutes, stirring halfway, until golden.", "Let cool completely on the pan \u2014 it will crisp as it cools.", "Break into clusters and store in an airtight jar."]'::jsonb, 6, 8, 28, 1.55, 9.3, 320, 9, 46, 12, 5, 60, true, true, true, 'curated'),
  ('Avocado Toast with Pinto Beans', 'Thick slices of toasted whole-wheat bread piled high with smashed avocado and well-seasoned pinto beans.', 'breakfast', 'Toast', 'budget', ARRAY['budget','dairy-free','egg-free','high-fiber','kid-friendly','no-cook','nut-free','quick','soy-free','vegan','vegetarian']::text[], '["4 slices whole-wheat bread", "2 avocados", "1 can pinto beans", "1 lime", "1 tsp cumin", "1/2 tsp chili powder", "salt", "pepper", "1/4 tsp red pepper flakes"]'::jsonb, '["Toast bread slices until golden.", "Drain and rinse pinto beans; season with cumin, chili powder, and salt.", "Halve and pit avocados; scoop flesh into a bowl with lime juice, salt, and pepper and mash.", "Spread smashed avocado generously over toast.", "Spoon seasoned pinto beans on top and finish with red pepper flakes."]'::jsonb, 4, 8, 4, 2.2, 8.8, 375, 13, 50, 16, 14, 340, true, true, true, 'curated'),
  ('Cinnamon Raisin Breakfast Quinoa', 'Quinoa simmered until fluffy with cinnamon and raisins then topped with sliced almonds for a protein-rich cereal alternative.', 'breakfast', 'Porridge', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','kid-friendly','meal-prep','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["1 cup quinoa", "2 cups water", "1/3 cup raisins", "1 tsp cinnamon", "2 tbsp maple syrup", "1/4 cup sliced almonds", "1 pinch salt"]'::jsonb, '["Rinse quinoa under cold water and drain.", "Bring water to a boil, add quinoa, raisins, cinnamon, and salt.", "Reduce heat to low, cover, and cook 15 minutes until liquid is absorbed.", "Fluff with a fork and stir in maple syrup.", "Serve topped with sliced almonds."]'::jsonb, 3, 5, 18, 1.7, 5.1, 310, 10, 56, 6, 5, 85, true, true, true, 'curated'),
  ('Spiced Roasted Chickpea Snack', 'Canned chickpeas tossed in olive oil and bold spices, then roasted until audibly crunchy and deeply flavorful.', 'snack', 'Roasted', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','kid-friendly','meal-prep','nut-free','roasted','snackable','soy-free','vegan','vegetarian']::text[], '["2 cans chickpeas", "1 tbsp olive oil", "1 tsp smoked paprika", "1 tsp cumin", "1/2 tsp garlic powder", "1/4 tsp cayenne pepper", "1/2 tsp salt"]'::jsonb, '["Preheat oven to 400\u00b0F and line a baking sheet with parchment.", "Drain, rinse, and thoroughly dry chickpeas with paper towels.", "Toss chickpeas with olive oil, paprika, cumin, garlic powder, cayenne, and salt.", "Spread in a single layer on the baking sheet.", "Roast 35-40 minutes, shaking the pan halfway, until crispy.", "Cool completely before storing in an airtight container."]'::jsonb, 4, 8, 38, 0.8, 3.2, 195, 10, 30, 5, 8, 330, true, true, true, 'curated'),
  ('Avocado and Carrot Dipper Plate', 'Freshly mashed avocado with lime and garlic served alongside crisp carrot, celery, and bell pepper strips for easy snacking.', 'snack', 'Dip', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','kid-favorite','kid-friendly','no-cook','nut-free','quick','soy-free','vegan','vegetarian']::text[], '["2 avocados", "1 lime", "1/4 cup diced tomato", "2 tbsp diced onion", "1 clove garlic", "4 stalks celery", "3 carrots", "1 bell pepper", "salt"]'::jsonb, '["Halve and pit avocados; mash flesh in a bowl with lime juice and salt.", "Mince garlic and stir in with diced tomato and onion.", "Slice celery, carrots, and bell pepper into sticks.", "Serve mashed avocado dip with the vegetable sticks."]'::jsonb, 4, 10, 0, 1.6, 6.4, 165, 3, 16, 12, 7, 120, true, true, true, 'curated'),
  ('White Bean Hummus with Pita Wedges', 'Silky white beans blended with tahini, lemon, and garlic into a smooth, scoopable dip served with warm pita.', 'snack', 'Dip', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','kid-friendly','meal-prep','no-cook','nut-free','snackable','soy-free','vegan','vegetarian']::text[], '["2 cans white beans", "3 tbsp tahini", "2 lemons", "2 cloves garlic", "2 tbsp olive oil", "1/2 tsp cumin", "salt", "4 pita breads"]'::jsonb, '["Drain and rinse white beans, reserving 4 tablespoons of the liquid.", "Add beans, tahini, juice of both lemons, garlic, cumin, and salt to a blender or food processor.", "Blend until very smooth, adding reserved bean liquid one tablespoon at a time as needed.", "Taste and adjust lemon and salt.", "Toast pita and cut into wedges; drizzle dip with olive oil before serving."]'::jsonb, 6, 10, 0, 1.0, 6.0, 245, 11, 38, 7, 8, 290, true, true, true, 'curated'),
  ('Oat and Peanut Spread Energy Balls', 'No-bake oat bites rolled with peanut spread, chocolate chips, and flaxseed into grab-and-go spheres of energy.', 'snack', 'No-Bake', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','kid-favorite','kid-friendly','meal-prep','no-cook','soy-free','vegan','vegetarian']::text[], '["1 cup rolled oats", "1/2 cup peanut spread", "3 tbsp maple syrup", "2 tbsp ground flaxseed", "1/4 cup semi-sweet chocolate chips", "1 tsp vanilla extract", "1 pinch salt"]'::jsonb, '["Combine all ingredients in a bowl and stir until a sticky dough forms.", "Refrigerate the mixture for 30 minutes to firm up.", "Scoop tablespoon-sized portions and roll between your palms into balls.", "Place on a parchment-lined tray and refrigerate at least 15 more minutes.", "Store in an airtight container in the refrigerator for up to one week."]'::jsonb, 5, 10, 0, 1.35, 6.75, 250, 8, 32, 11, 4, 80, true, true, true, 'curated'),
  ('Edamame with Sea Salt and Lemon', 'Frozen edamame pods steamed until tender, tossed with sea salt and a squeeze of bright lemon juice.', 'snack', 'Steamed', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','kid-favorite','kid-friendly','nut-free','quick','snackable','vegan','vegetarian']::text[], '["1 lb frozen edamame in pods", "1 lemon", "1 tsp sea salt", "1/4 tsp chili flakes"]'::jsonb, '["Cook edamame in boiling salted water for 4 minutes or according to package directions.", "Drain and transfer to a serving bowl.", "Squeeze lemon juice over the edamame.", "Toss with sea salt and chili flakes and serve warm."]'::jsonb, 4, 2, 5, 1.5, 6.0, 135, 12, 11, 5, 5, 240, true, true, true, 'curated'),
  ('Cinnamon Apple Slices with Almond Dip', 'Crisp apple wedges dusted with cinnamon served alongside a smooth, sweet almond spread dip for a wholesome afternoon snack.', 'snack', 'No-Cook', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','kid-favorite','kid-friendly','no-cook','quick','soy-free','vegan','vegetarian']::text[], '["4 apples", "1/2 cup almond spread", "1 tsp cinnamon", "1 tsp maple syrup"]'::jsonb, '["Core and slice apples into wedges.", "Arrange on a plate and dust with cinnamon.", "Mix almond spread with maple syrup in a small bowl.", "Serve apple slices alongside the almond dip."]'::jsonb, 4, 5, 0, 1.4, 5.6, 210, 5, 30, 9, 5, 40, true, true, true, 'curated'),
  ('Black Bean and Corn Salsa Cups', 'Crisp tortilla chips piled with a zesty mix of black beans, corn, tomato, and cilantro for easy, shareable snacking.', 'snack', 'Mexican', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','kid-friendly','mexican','no-cook','nut-free','quick','soy-free','vegan','vegetarian']::text[], '["1 can black beans", "1 cup frozen corn", "2 tomatoes", "1/4 cup diced onion", "2 tbsp fresh cilantro", "1 lime", "1/2 tsp cumin", "salt", "tortilla chips"]'::jsonb, '["Thaw corn under warm water and drain.", "Drain and rinse black beans.", "Dice tomatoes and combine with black beans, corn, onion, and cilantro.", "Add lime juice, cumin, and salt; stir well.", "Serve salsa with tortilla chips for scooping."]'::jsonb, 4, 10, 0, 0.9, 3.6, 175, 8, 34, 2, 7, 260, true, true, true, 'curated'),
  ('Seed and Fruit Trail Mix', 'A portable mix of sunflower seeds, pumpkin seeds, dried cranberries, and dark chocolate chips for on-the-go munching.', 'snack', 'Trail Mix', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','kid-favorite','kid-friendly','meal-prep','no-cook','nut-free','snackable','soy-free','vegan','vegetarian']::text[], '["1 cup sunflower seeds", "1 cup pumpkin seeds", "1/2 cup dried cranberries", "1/2 cup semi-sweet chocolate chips", "1/4 cup raisins", "1/4 tsp salt"]'::jsonb, '["Combine all ingredients in a large bowl and toss to mix evenly.", "Taste and add salt if desired.", "Portion into individual snack bags or small airtight containers.", "Store at room temperature for up to two weeks."]'::jsonb, 6, 5, 0, 1.7, 10.2, 240, 8, 28, 13, 3, 55, true, true, true, 'curated'),
  ('Chili-Lime Roasted Pumpkin Seeds', 'Raw pumpkin seeds tossed in chili-lime seasoning and roasted until they crackle and pop with every bite.', 'snack', 'Roasted', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','meal-prep','nut-free','roasted','snackable','soy-free','vegan','vegetarian']::text[], '["2 cups raw pumpkin seeds", "1 tbsp olive oil", "1 lime", "1 tsp chili powder", "1/2 tsp cumin", "1/2 tsp garlic powder", "1/2 tsp salt"]'::jsonb, '["Preheat oven to 350\u00b0F and line a baking sheet with parchment.", "Toss pumpkin seeds with olive oil, lime juice, chili powder, cumin, garlic powder, and salt.", "Spread in a single layer on the baking sheet.", "Roast 15-18 minutes, stirring once, until golden and crispy.", "Cool completely before eating or storing in an airtight jar."]'::jsonb, 4, 5, 17, 1.1, 4.4, 265, 14, 8, 22, 2, 195, false, true, true, 'curated'),
  ('Tomato and Avocado Baguette Bites', 'Mini toasted baguette rounds topped with lemon-spiked mashed avocado and juicy ripe tomato for simple, fresh snacking.', 'snack', 'Toast', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','kid-favorite','kid-friendly','no-cook','nut-free','quick','soy-free','vegan','vegetarian']::text[], '["1 baguette", "2 avocados", "2 tomatoes", "1 lemon", "1 clove garlic", "salt", "pepper", "1/4 tsp red pepper flakes"]'::jsonb, '["Slice baguette into rounds and toast under the broiler for 2 minutes per side.", "Mash avocado with lemon juice, minced garlic, salt, and pepper.", "Dice tomatoes and season with a pinch of salt.", "Spread avocado mash onto each toast round.", "Top with a spoonful of diced tomato and a pinch of red pepper flakes."]'::jsonb, 5, 8, 5, 1.55, 7.75, 195, 4, 25, 10, 5, 230, true, true, true, 'curated'),
  ('Spiced Red Lentil Soup with Bread', 'A thick, warmly spiced red lentil soup simmered with carrots and tomatoes, perfect for a satisfying midday snack.', 'snack', 'Soup', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','kid-friendly','meal-prep','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["1 cup red lentils", "3 carrots", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp coriander", "1/2 tsp turmeric", "4 cups water", "salt", "pepper", "4 slices whole-wheat bread"]'::jsonb, '["Dice onion and carrots; mince garlic.", "Heat olive oil in a pot over medium heat and saut\u00e9 onion and carrots 5 minutes.", "Add garlic, cumin, coriander, and turmeric; cook 1 minute.", "Add rinsed lentils, diced tomatoes, and water; bring to a boil.", "Simmer 20 minutes until lentils are completely soft; blend partially for a thicker texture.", "Season with salt and pepper and serve with whole-wheat bread."]'::jsonb, 4, 10, 25, 1.25, 5.0, 285, 15, 50, 4, 12, 310, true, true, true, 'curated'),
  ('Smoky Black Bean Tacos', 'Spiced black beans piled into warm corn tortillas with fresh salsa and crisp cabbage slaw.', 'lunch', 'Mexican', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','kid-friendly','mexican','nut-free','one-pot','quick','soy-free','vegan','vegetarian']::text[], '["2 cans black beans", "8 corn tortillas", "1 cup shredded cabbage", "1 tomato", "1 onion", "2 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp smoked paprika", "1 lime", "salt", "pepper"]'::jsonb, '["Dice onion and garlic; saut\u00e9 in olive oil over medium heat until soft.", "Add drained black beans, cumin, smoked paprika, salt, and pepper; cook 5 minutes.", "Shred cabbage and dice tomato; toss with lime juice for a quick slaw.", "Warm tortillas in a dry skillet or directly over a gas flame.", "Fill tortillas with bean mixture and top with slaw."]'::jsonb, 4, 10, 10, 1.2, 4.8, 320, 14, 52, 6, 12, 480, true, true, true, 'curated'),
  ('Red Lentil Tomato Soup', 'A thick, warming soup of red lentils simmered with tomatoes, cumin, and a squeeze of lemon.', 'lunch', 'Soup', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','kid-friendly','middle-eastern','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["1 cup red lentils", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp coriander", "4 cups water", "1 lemon", "salt", "pepper"]'::jsonb, '["Dice onion and mince garlic; cook in olive oil over medium heat until golden.", "Add cumin and coriander; stir 30 seconds.", "Add rinsed lentils, canned tomatoes, and water; bring to a boil.", "Reduce heat and simmer 20 minutes until lentils break down.", "Squeeze in lemon juice, adjust seasoning, and serve."]'::jsonb, 4, 10, 25, 0.9, 3.6, 270, 16, 42, 4, 14, 390, true, true, true, 'curated'),
  ('Chickpea and Spinach Stir-Fry', 'Tender chickpeas and wilted spinach tossed in a garlic-soy sauce served over steamed rice.', 'lunch', 'Stir-Fry', 'ultra_budget', ARRAY['asian-inspired','budget','dairy-free','egg-free','kid-friendly','nut-free','one-pan','stir-fry','vegan','vegetarian']::text[], '["2 cans chickpeas", "4 cups fresh spinach", "2 cups white rice", "3 cloves garlic", "2 tbsp soy sauce", "1 tbsp olive oil", "1 tsp sesame oil", "1 tsp ground ginger", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Heat olive oil in a large skillet; saut\u00e9 minced garlic and ginger 1 minute.", "Add drained chickpeas; cook 4 minutes until lightly browned.", "Add spinach and soy sauce; stir until spinach wilts.", "Drizzle sesame oil, season with pepper, and serve over rice."]'::jsonb, 4, 8, 20, 1.3, 5.2, 390, 15, 66, 6, 9, 520, true, true, true, 'curated'),
  ('Peanut Sauce Noodle Bowl', 'Lo mein noodles tossed in a rich peanut-soy sauce with shredded carrots and sliced green onions.', 'lunch', 'Asian Noodles', 'budget', ARRAY['asian-inspired','budget','dairy-free','egg-free','kid-friendly','noodles','one-bowl','quick','vegan','vegetarian']::text[], '["8 oz lo mein noodles", "2 carrots", "3 green onions", "3 tbsp peanut paste", "2 tbsp soy sauce", "1 tbsp rice vinegar", "1 tsp sesame oil", "1 tsp sugar", "2 cloves garlic", "1 tsp ginger", "water"]'::jsonb, '["Cook noodles according to package; drain and rinse with cold water.", "Whisk together peanut paste, soy sauce, rice vinegar, sesame oil, sugar, garlic, ginger, and 3 tbsp water until smooth.", "Shred carrots and slice green onions.", "Toss noodles with sauce, carrots, and green onions.", "Serve immediately or chilled."]'::jsonb, 4, 10, 12, 1.6, 6.4, 370, 12, 55, 11, 4, 580, true, true, true, 'curated'),
  ('White Bean and Kale Minestrone', 'A hearty Italian-style soup packed with white beans, kale, diced tomatoes, and small pasta.', 'lunch', 'Soup', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','high-fiber','italian','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["2 cans white beans", "1 can diced tomatoes", "2 cups kale", "1 cup small pasta", "1 onion", "3 cloves garlic", "2 carrots", "2 stalks celery", "1 tbsp olive oil", "1 tsp Italian seasoning", "4 cups vegetable broth", "salt", "pepper"]'::jsonb, '["Dice onion, carrots, and celery; cook in olive oil over medium heat 5 minutes.", "Add garlic and Italian seasoning; stir 1 minute.", "Pour in broth and canned tomatoes; bring to a boil.", "Add pasta and cook 8 minutes.", "Stir in white beans and kale; simmer until kale wilts.", "Season with salt and pepper and serve."]'::jsonb, 6, 12, 25, 1.4, 8.4, 300, 14, 48, 4, 11, 610, false, true, true, 'curated'),
  ('Tempeh Teriyaki Rice Bowl', 'Pan-seared tempeh glazed with homemade teriyaki sauce served over fluffy brown rice and steamed broccoli.', 'lunch', 'Rice Bowl', 'budget', ARRAY['asian-inspired','budget','dairy-free','egg-free','high-protein','kid-friendly','nut-free','one-pan','tempeh','vegan','vegetarian']::text[], '["1 pkg tempeh", "2 cups brown rice", "2 cups broccoli florets", "3 tbsp soy sauce", "1 tbsp sugar", "1 tbsp rice vinegar", "1 tsp sesame oil", "2 cloves garlic", "1 tsp ginger", "1 tbsp olive oil"]'::jsonb, '["Cook brown rice according to package directions.", "Slice tempeh into thin strips; pan-fry in olive oil over medium-high heat until golden, about 4 minutes per side.", "Whisk soy sauce, sugar, rice vinegar, garlic, ginger, and sesame oil; pour over tempeh and cook 2 minutes.", "Steam broccoli until bright green and tender-crisp.", "Assemble bowls with rice, broccoli, and tempeh; spoon any remaining sauce over top."]'::jsonb, 4, 10, 30, 2.5, 10.0, 420, 22, 54, 12, 6, 620, true, true, true, 'curated'),
  ('Spiced Lentil and Potato Stew', 'A filling stew of green lentils and cubed potatoes simmered in a gently spiced tomato broth.', 'lunch', 'Stew', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["1 cup green lentils", "3 potatoes", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp turmeric", "1 tsp paprika", "4 cups water", "salt", "pepper"]'::jsonb, '["Dice onion and potatoes; mince garlic.", "Cook onion in olive oil over medium heat until translucent.", "Add garlic, cumin, turmeric, and paprika; cook 1 minute.", "Add rinsed lentils, potatoes, tomatoes, and water; bring to a boil.", "Simmer 25 minutes until lentils and potatoes are tender.", "Season with salt and pepper and serve."]'::jsonb, 4, 10, 30, 1.0, 4.0, 310, 15, 55, 4, 13, 400, true, true, true, 'curated'),
  ('Roasted Veggie Hummus Wrap', 'Savory hummus and oven-roasted zucchini, bell pepper, and red onion rolled up in a whole-wheat tortilla.', 'lunch', 'Wrap', 'budget', ARRAY['budget','dairy-free','egg-free','kid-friendly','mediterranean','nut-free','portable','quick','sheet-pan','soy-free','vegan','vegetarian']::text[], '["4 whole-wheat tortillas", "1 cup hummus", "1 zucchini", "1 red bell pepper", "1 red onion", "2 tbsp olive oil", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F.", "Slice zucchini, bell pepper, and red onion; toss with olive oil, Italian seasoning, salt, and pepper.", "Spread on a baking sheet and roast 20 minutes until tender and lightly charred.", "Spread hummus on each tortilla.", "Pile on roasted vegetables, roll tightly, and slice in half."]'::jsonb, 4, 10, 20, 2.0, 8.0, 330, 9, 44, 13, 7, 490, true, true, true, 'curated'),
  ('Tofu Fried Rice', 'Fluffy rice stir-fried with golden tofu, peas, corn, and soy sauce for a fast one-pan lunch.', 'lunch', 'Stir-Fry', 'budget', ARRAY['asian-inspired','budget','dairy-free','egg-free','kid-friendly','nut-free','one-pan','stir-fry','vegan','vegetarian']::text[], '["1 pkg firm tofu", "3 cups cooked white rice", "1 cup frozen peas", "1 cup frozen corn", "3 green onions", "3 cloves garlic", "3 tbsp soy sauce", "1 tbsp sesame oil", "2 tbsp olive oil", "pepper"]'::jsonb, '["Press tofu dry and cube it; fry in olive oil over high heat until golden on all sides, then set aside.", "Add garlic to the same pan; cook 30 seconds.", "Add cold rice and stir-fry 3 minutes, breaking up clumps.", "Add peas, corn, soy sauce, and tofu; stir-fry 3 more minutes.", "Drizzle sesame oil, top with sliced green onions, and serve."]'::jsonb, 4, 10, 15, 1.8, 7.2, 380, 17, 52, 12, 5, 570, true, true, true, 'curated'),
  ('Black-Eyed Pea and Greens Bowl', 'Southern-style black-eyed peas braised with hearty braised greens and smoked paprika over white rice.', 'lunch', 'Southern', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','nut-free','one-pot','southern','soy-free','vegan','vegetarian']::text[], '["2 cans black-eyed peas", "3 cups chopped braising greens", "2 cups white rice", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp smoked paprika", "1 tsp apple cider vinegar", "2 cups vegetable broth", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Dice onion and mince garlic; cook in olive oil over medium heat until soft.", "Add smoked paprika; stir 30 seconds.", "Add drained black-eyed peas and broth; simmer 10 minutes.", "Stir in chopped braising greens and apple cider vinegar; cook until wilted.", "Season and serve over rice."]'::jsonb, 4, 10, 25, 1.25, 5.0, 350, 15, 62, 4, 10, 490, false, true, true, 'curated'),
  ('Moroccan Chickpea Stew', 'A fragrant North African stew of chickpeas, sweet potato, and tomatoes scented with cinnamon and cumin.', 'lunch', 'Moroccan', 'budget', ARRAY['aromatic','budget','dairy-free','egg-free','gluten-free','kid-friendly','moroccan','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["2 cans chickpeas", "1 sweet potato", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp cinnamon", "1 tsp coriander", "2 cups vegetable broth", "salt", "pepper"]'::jsonb, '["Peel and cube sweet potato; dice onion and mince garlic.", "Cook onion in olive oil over medium heat until soft.", "Add garlic, cumin, cinnamon, and coriander; cook 1 minute.", "Add chickpeas, sweet potato, tomatoes, and broth.", "Simmer 20 minutes until sweet potato is tender.", "Season with salt and pepper and serve."]'::jsonb, 4, 12, 25, 1.7, 6.8, 330, 13, 54, 5, 11, 440, true, true, true, 'curated'),
  ('Corn and Poblano Quesadillas', 'Crispy flour tortillas filled with roasted corn, poblano pepper, and mashed pinto beans.', 'lunch', 'Mexican', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','kid-friendly','mexican','nut-free','one-pan','quick','soy-free','vegan','vegetarian']::text[], '["4 large flour tortillas", "1 can pinto beans", "1 cup frozen corn", "1 poblano pepper", "1 onion", "1 tbsp olive oil", "1 tsp cumin", "salt", "pepper"]'::jsonb, '["Char poblano over flame or under broiler; peel, seed, and dice.", "Drain and mash pinto beans with cumin, salt, and pepper.", "Cook corn and diced onion in olive oil until lightly browned.", "Spread mashed beans on half of each tortilla; top with corn mixture and poblano.", "Fold and cook in a dry skillet over medium heat 3 minutes per side until golden.", "Slice into wedges and serve."]'::jsonb, 4, 12, 15, 1.5, 6.0, 340, 11, 57, 7, 8, 530, true, true, true, 'curated'),
  ('Curried Split Pea Soup', 'Silky split pea soup simmered with curry powder, carrots, and a touch of turmeric for golden color.', 'lunch', 'Soup', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','indian-inspired','kid-friendly','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["1 cup green split peas", "2 carrots", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp curry powder", "1 tsp turmeric", "5 cups water", "salt", "pepper"]'::jsonb, '["Dice onion and carrots; mince garlic.", "Cook onion in olive oil over medium heat until soft.", "Add garlic, curry powder, and turmeric; stir 1 minute.", "Add rinsed split peas, carrots, and water; bring to a boil.", "Simmer 30 minutes until peas are very soft.", "Blend partially for a smooth texture; season and serve."]'::jsonb, 4, 10, 35, 0.85, 3.4, 265, 15, 44, 4, 15, 380, true, true, true, 'curated'),
  ('Mediterranean Farro Salad', 'Chewy farro tossed with cucumber, cherry tomatoes, olives, red onion, and a bright lemon-herb dressing.', 'lunch', 'Grain Salad', 'budget', ARRAY['budget','dairy-free','egg-free','fresh','grain-bowl','meal-prep','mediterranean','nut-free','soy-free','vegan','vegetarian']::text[], '["1 cup farro", "1 cucumber", "1 cup cherry tomatoes", "0.25 cup kalamata olives", "0.5 red onion", "2 tbsp olive oil", "2 tbsp lemon juice", "1 tsp dried oregano", "salt", "pepper"]'::jsonb, '["Cook farro according to package directions; cool to room temperature.", "Dice cucumber and halve cherry tomatoes.", "Thinly slice red onion and halve olives.", "Whisk olive oil, lemon juice, oregano, salt, and pepper.", "Toss all ingredients with dressing and serve or refrigerate."]'::jsonb, 4, 10, 30, 1.8, 7.2, 310, 9, 50, 8, 6, 340, false, true, true, 'curated'),
  ('Sweet and Sour Tofu with Pineapple', 'Crispy tofu cubes and bell peppers glazed in a tangy pineapple sauce over steamed rice.', 'lunch', 'Stir-Fry', 'budget', ARRAY['asian-inspired','budget','dairy-free','egg-free','kid-friendly','nut-free','stir-fry','sweet-savory','vegan','vegetarian']::text[], '["1 pkg firm tofu", "1 can pineapple chunks", "1 green bell pepper", "1 red bell pepper", "2 cups white rice", "3 tbsp soy sauce", "2 tbsp rice vinegar", "1 tbsp sugar", "1 tbsp cornstarch", "2 tbsp olive oil", "3 cloves garlic"]'::jsonb, '["Cook rice according to package directions.", "Press and cube tofu; pan-fry in olive oil until golden, then set aside.", "Slice bell peppers and cook in the same pan 3 minutes.", "Whisk soy sauce, vinegar, sugar, and pineapple juice from the can with cornstarch.", "Add garlic, pineapple chunks, and tofu back to pan; pour in sauce and stir until thickened.", "Serve over rice."]'::jsonb, 4, 12, 20, 2.2, 8.8, 410, 16, 65, 9, 3, 560, true, true, true, 'curated'),
  ('Tuscan White Bean Salad', 'A no-cook salad of white beans, roasted red peppers, sun-dried tomatoes, and fresh basil with a lemon dressing.', 'lunch', 'Salad', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','italian','meal-prep','no-cook','nut-free','soy-free','vegan','vegetarian']::text[], '["2 cans white beans", "0.5 cup roasted red peppers", "0.25 cup sun-dried tomatoes", "0.25 cup fresh basil", "2 stalks celery", "2 tbsp olive oil", "2 tbsp lemon juice", "1 clove garlic", "salt", "pepper"]'::jsonb, '["Drain and rinse white beans.", "Slice roasted red peppers and sun-dried tomatoes into strips.", "Dice celery and mince garlic.", "Whisk olive oil, lemon juice, and garlic; season with salt and pepper.", "Toss all ingredients with dressing and top with torn basil."]'::jsonb, 4, 10, 0, 2.0, 8.0, 280, 13, 38, 8, 10, 430, false, true, true, 'curated'),
  ('Thai-Style Peanut Tempeh Bowl', 'Sliced tempeh and shredded cabbage dressed with a spicy Thai peanut sauce and served over rice noodles.', 'lunch', 'Thai', 'budget', ARRAY['budget','dairy-free','egg-free','high-protein','noodles','tempeh','thai','vegan','vegetarian']::text[], '["1 pkg tempeh", "6 oz rice noodles", "2 cups shredded cabbage", "1 carrot", "3 tbsp peanut paste", "2 tbsp soy sauce", "1 tbsp lime juice", "1 tsp sriracha", "1 tsp sugar", "2 cloves garlic", "2 tbsp olive oil"]'::jsonb, '["Soak rice noodles in hot water 8 minutes; drain.", "Slice tempeh and cook in olive oil until browned on both sides.", "Whisk peanut paste, soy sauce, lime juice, sriracha, sugar, and garlic with 3 tbsp water.", "Shred carrot.", "Toss noodles, cabbage, and carrot with half the sauce; top with tempeh and remaining sauce."]'::jsonb, 4, 12, 12, 2.6, 10.4, 430, 21, 52, 15, 5, 600, false, true, true, 'curated'),
  ('Smoky Lentil Sloppy Joes', 'Hearty cooked lentils in a tangy smoky tomato sauce piled onto toasted buns for a classic comfort lunch.', 'lunch', 'Sandwich', 'ultra_budget', ARRAY['american','budget','comfort-food','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','one-pan','soy-free','vegan','vegetarian']::text[], '["1 cup brown lentils", "4 burger buns", "1 can tomato sauce", "1 onion", "1 green bell pepper", "2 cloves garlic", "1 tbsp olive oil", "1 tbsp apple cider vinegar", "1 tbsp brown sugar", "1 tsp smoked paprika", "1 tsp Worcestershire sauce", "salt", "pepper"]'::jsonb, '["Simmer lentils in 2.5 cups water until tender, about 20 minutes; drain.", "Dice onion and bell pepper; cook in olive oil over medium heat until soft.", "Add garlic and smoked paprika; cook 1 minute.", "Stir in tomato sauce, vinegar, brown sugar, and Worcestershire; simmer 5 minutes.", "Add cooked lentils and simmer 5 more minutes.", "Spoon onto toasted buns and serve."]'::jsonb, 4, 10, 35, 1.4, 5.6, 360, 17, 60, 5, 12, 570, true, true, true, 'curated'),
  ('Indian Aloo Chhole', 'Punjabi-style chickpeas and potatoes cooked together in a bold tomato and spice gravy.', 'lunch', 'Indian', 'ultra_budget', ARRAY['aromatic','budget','dairy-free','egg-free','gluten-free','indian','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["2 cans chickpeas", "2 potatoes", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp coriander", "1 tsp garam masala", "1 tsp turmeric", "salt", "water"]'::jsonb, '["Peel and cube potatoes; dice onion and mince garlic.", "Cook onion in olive oil over medium heat until golden.", "Add garlic, cumin, coriander, turmeric, and garam masala; stir 1 minute.", "Add tomatoes and cook 3 minutes.", "Add chickpeas, potatoes, and 1 cup water; cover and cook 20 minutes until potatoes are tender.", "Season with salt and serve with rice or bread."]'::jsonb, 4, 12, 28, 1.3, 5.2, 320, 14, 55, 5, 11, 460, false, true, true, 'curated'),
  ('Summer Corn and Tomato Pasta', 'Rigatoni tossed with fresh corn, cherry tomatoes, garlic, and basil in a light olive oil sauce.', 'lunch', 'Pasta', 'budget', ARRAY['budget','dairy-free','egg-free','italian','kid-friendly','nut-free','pasta','quick','soy-free','summer','vegan','vegetarian']::text[], '["12 oz rigatoni", "2 cups fresh corn kernels", "1 cup cherry tomatoes", "3 cloves garlic", "3 tbsp olive oil", "0.25 cup fresh basil", "salt", "pepper"]'::jsonb, '["Cook pasta in salted boiling water until al dente; reserve 0.5 cup pasta water, then drain.", "Heat olive oil in a large skillet; cook garlic 1 minute.", "Add corn and halved cherry tomatoes; cook 4 minutes.", "Add drained pasta and splash of pasta water; toss well.", "Season with salt and pepper; top with torn basil."]'::jsonb, 4, 8, 20, 1.6, 6.4, 400, 12, 70, 9, 4, 350, true, true, true, 'curated'),
  ('Crispy Chickpea Caesar Salad', 'Romaine lettuce topped with oven-crisped chickpeas and a tangy tahini Caesar dressing.', 'lunch', 'Salad', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','nut-free','salad','sheet-pan','soy-free','tahini','vegan','vegetarian']::text[], '["2 cans chickpeas", "1 head romaine lettuce", "3 tbsp tahini", "2 tbsp lemon juice", "1 clove garlic", "1 tsp Dijon mustard", "2 tbsp olive oil", "salt", "pepper", "1 tsp capers"]'::jsonb, '["Preheat oven to 425\u00b0F.", "Drain and dry chickpeas; toss with olive oil, salt, and pepper; roast 25 minutes until crispy.", "Blend tahini, lemon juice, garlic, mustard, and 3 tbsp water until smooth; season.", "Chop romaine and toss with dressing.", "Top with crispy chickpeas and capers."]'::jsonb, 4, 10, 25, 1.9, 7.6, 300, 13, 32, 14, 9, 490, false, true, true, 'curated'),
  ('Bean and Rice Stuffed Peppers', 'Colorful bell peppers stuffed with seasoned black beans and rice then baked until tender.', 'lunch', 'Baked', 'budget', ARRAY['baked','budget','dairy-free','egg-free','gluten-free','kid-friendly','mexican','nut-free','one-dish','soy-free','vegan','vegetarian']::text[], '["4 bell peppers", "1 can black beans", "1 cup white rice", "1 can diced tomatoes", "1 onion", "2 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp chili powder", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Cut tops off peppers and remove seeds; preheat oven to 375\u00b0F.", "Saut\u00e9 diced onion and garlic in olive oil; add beans, half the tomatoes, cumin, chili powder, salt, and pepper.", "Stir in cooked rice.", "Fill peppers with mixture; top with remaining tomatoes.", "Bake covered 30 minutes, uncover, and bake 10 more minutes."]'::jsonb, 4, 15, 45, 1.8, 7.2, 350, 13, 64, 5, 9, 500, true, true, true, 'curated'),
  ('Vietnamese Lentil Lettuce Cups', 'Spiced lentils with water chestnuts served in crisp leaves with a sweet chili dipping sauce.', 'lunch', 'Vietnamese', 'budget', ARRAY['budget','dairy-free','egg-free','fresh','low-carb','nut-free','vegan','vegetarian','vietnamese']::text[], '["1 cup brown lentils", "1 can water chestnuts", "1 head bibb lettuce", "3 cloves garlic", "2 green onions", "2 tbsp soy sauce", "1 tbsp rice vinegar", "1 tsp sesame oil", "1 tbsp olive oil", "2 tbsp sweet chili sauce", "1 tsp ground ginger"]'::jsonb, '["Cook lentils in 2.5 cups water until tender, about 20 minutes; drain.", "Dice water chestnuts; slice green onions.", "Cook garlic and ginger in olive oil 1 minute.", "Add water chestnuts and cook 2 minutes.", "Stir in lentils, soy sauce, rice vinegar, and sesame oil; cook 2 minutes.", "Spoon into lettuce leaves and serve with sweet chili sauce."]'::jsonb, 4, 10, 25, 2.0, 8.0, 280, 15, 42, 5, 10, 540, false, true, true, 'curated'),
  ('Spicy Pinto Bean Burrito', 'A hearty flour tortilla packed with spiced pinto beans, Spanish rice, and fresh pico de gallo.', 'lunch', 'Mexican', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','kid-friendly','mexican','nut-free','one-dish','portable','soy-free','vegan','vegetarian']::text[], '["4 large flour tortillas", "2 cans pinto beans", "1 cup white rice", "2 tomatoes", "0.5 onion", "1 jalape\u00f1o", "2 cloves garlic", "1 lime", "1 tbsp olive oil", "1 tsp cumin", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Cook garlic in olive oil; add drained pinto beans and cumin; mash half the beans.", "Dice tomatoes, onion, and jalape\u00f1o; toss with lime juice and salt for pico de gallo.", "Warm tortillas.", "Fill each tortilla with beans, rice, and pico de gallo; fold and roll into burritos."]'::jsonb, 4, 12, 20, 1.35, 5.4, 430, 16, 76, 6, 13, 520, true, true, true, 'curated'),
  ('Miso Soup with Tofu and Seaweed', 'A soothing Japanese broth with silken tofu, dried seaweed, and green onions, deeply savory from white miso.', 'lunch', 'Japanese', 'budget', ARRAY['budget','dairy-free','egg-free','japanese','kid-friendly','light','nut-free','one-pot','soup','vegan','vegetarian']::text[], '["1 pkg silken tofu", "3 tbsp white miso paste", "2 tbsp dried wakame seaweed", "3 green onions", "4 cups water", "1 tsp soy sauce"]'::jsonb, '["Bring water to a gentle simmer; do not boil.", "Soak wakame in warm water 5 minutes; drain.", "Whisk miso paste with a ladle of hot water until dissolved, then stir into the pot.", "Add cubed silken tofu and wakame; heat through 2 minutes.", "Add soy sauce and ladle into bowls; top with sliced green onions."]'::jsonb, 4, 8, 10, 1.7, 6.8, 120, 8, 10, 4, 1, 780, true, true, true, 'curated'),
  ('Greek Chickpea Tomato Skillet', 'Chickpeas baked with crushed tomatoes, oregano, and olive oil in a one-skillet Mediterranean meal.', 'lunch', 'Greek', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','greek','mediterranean','nut-free','one-pan','soy-free','vegan','vegetarian']::text[], '["2 cans chickpeas", "1 can crushed tomatoes", "1 onion", "3 cloves garlic", "2 tbsp olive oil", "1 tsp dried oregano", "0.5 tsp cinnamon", "4 pita breads", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F.", "Cook onion in olive oil in an oven-safe skillet until soft; add garlic, oregano, and cinnamon.", "Stir in crushed tomatoes; bring to a simmer.", "Add drained chickpeas; season with salt and pepper.", "Transfer skillet to oven and bake 20 minutes until sauce thickens.", "Serve with warm pita bread."]'::jsonb, 4, 10, 30, 1.9, 7.6, 360, 14, 57, 9, 10, 490, false, true, true, 'curated'),
  ('Smashed White Bean and Avocado Toast', 'Thick slices of toasted bread loaded with lemony smashed white beans and sliced ripe avocado.', 'lunch', 'Toast', 'budget', ARRAY['american','budget','dairy-free','egg-free','kid-friendly','no-cook','nut-free','quick','soy-free','vegan','vegetarian']::text[], '["1 can white beans", "2 avocados", "4 slices bread", "1 lemon", "1 clove garlic", "2 tbsp olive oil", "0.5 tsp red pepper flakes", "salt", "pepper"]'::jsonb, '["Toast bread slices until golden.", "Drain and rinse white beans; mash with olive oil, lemon juice, garlic, salt, and pepper until smooth.", "Spread mashed beans generously on toast.", "Slice avocado and layer on top.", "Sprinkle with red pepper flakes and a final squeeze of lemon."]'::jsonb, 2, 8, 5, 2.8, 5.6, 440, 15, 46, 22, 14, 420, true, true, true, 'curated'),
  ('Ethiopian Red Lentil Stew', 'Berbere-spiced red lentils slow-cooked until thick and served with warm flatbread for scooping.', 'lunch', 'Ethiopian', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','ethiopian','gluten-free','nut-free','one-pot','soy-free','spicy','vegan','vegetarian']::text[], '["1 cup red lentils", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp berbere spice blend", "1 tsp cumin", "1 tsp paprika", "1 can diced tomatoes", "3 cups water", "4 flatbreads", "salt"]'::jsonb, '["Finely dice onion; cook in olive oil over medium heat until deep golden, about 10 minutes.", "Add garlic, berbere, cumin, and paprika; stir 1 minute.", "Add tomatoes and cook 3 minutes.", "Add rinsed lentils and water; bring to a boil, then simmer 20 minutes until thick.", "Season with salt and serve with flatbread."]'::jsonb, 4, 10, 35, 1.1, 4.4, 290, 15, 48, 5, 12, 430, false, true, true, 'curated'),
  ('Red Lentil Dal', 'A rich, warmly spiced Indian-style lentil stew that comes together in under 30 minutes.', 'dinner', 'Indian', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','indian','kid-friendly','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["1.5 cups red lentils", "1 can diced tomatoes", "1 onion", "4 cloves garlic", "1 tbsp fresh ginger", "1 tsp cumin", "1 tsp turmeric", "1 tsp garam masala", "2 tbsp olive oil", "4 cups water", "salt", "pepper"]'::jsonb, '["Saut\u00e9 diced onion in olive oil over medium heat until soft, about 5 minutes.", "Add minced garlic and grated ginger; cook 1 minute until fragrant.", "Stir in cumin, turmeric, and garam masala; toast spices 30 seconds.", "Add rinsed lentils, diced tomatoes, and water; bring to a boil.", "Reduce heat and simmer 20 minutes until lentils are very soft.", "Season with salt and pepper; serve over rice or with flatbread."]'::jsonb, 4, 10, 25, 1.1, 4.4, 310, 18, 48, 5, 14, 390, true, true, true, 'curated'),
  ('Garlic Stir-Fried Tofu and Broccoli', 'Crispy pan-fried tofu and tender broccoli tossed in a savory garlic soy sauce.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','egg-free','high-protein','kid-friendly','nut-free','quick','stir-fry','vegan','vegetarian']::text[], '["1 lb firm tofu", "3 cups broccoli florets", "4 cloves garlic", "3 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp olive oil", "1 tsp cornstarch", "1 tsp sugar", "2 cups brown rice"]'::jsonb, '["Press tofu dry with paper towels, then cut into 1-inch cubes.", "Cook brown rice according to package directions.", "Heat olive oil in a large skillet over high heat; cook tofu until golden on all sides, about 8 minutes; remove.", "Add broccoli to the skillet and stir-fry 4 minutes until bright green and tender-crisp.", "Add minced garlic and cook 30 seconds, then stir in soy sauce, sesame oil, sugar, and cornstarch mixed with 2 tbsp water.", "Return tofu to the pan, toss to coat, and serve over brown rice."]'::jsonb, 4, 10, 20, 2.4, 9.6, 380, 22, 50, 11, 6, 620, true, true, true, 'curated'),
  ('White Bean and Kale Soup', 'A hearty Italian-inspired soup loaded with cannellini beans, kale, and herbs.', 'dinner', 'Soup', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','italian','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["2 cans cannellini beans", "4 cups chopped kale", "1 can diced tomatoes", "1 onion", "4 cloves garlic", "4 cups vegetable broth", "1 tsp dried thyme", "1 tsp dried rosemary", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Saut\u00e9 diced onion in olive oil over medium heat for 5 minutes.", "Add minced garlic, thyme, and rosemary; cook 1 minute.", "Add drained beans, diced tomatoes, and broth; bring to a boil.", "Stir in kale and simmer 10 minutes until wilted and tender.", "Season with salt and pepper before serving."]'::jsonb, 4, 10, 20, 1.45, 5.8, 280, 15, 42, 5, 11, 520, false, true, true, 'curated'),
  ('Chickpea Tikka Masala', 'Plump chickpeas simmered in a bold tomato-based tikka masala sauce served with basmati rice.', 'dinner', 'Indian', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','indian','kid-friendly','nut-free','one-pot','soy-free','tomato-based','vegan','vegetarian']::text[], '["2 cans chickpeas", "1 can diced tomatoes", "1 can tomato sauce", "1 onion", "4 cloves garlic", "1 tbsp fresh ginger", "2 tsp garam masala", "1 tsp cumin", "1 tsp turmeric", "1 tsp paprika", "2 tbsp olive oil", "2 cups basmati rice", "salt"]'::jsonb, '["Saut\u00e9 diced onion in olive oil over medium heat until golden, about 7 minutes.", "Add minced garlic and grated ginger; cook 2 minutes.", "Add all spices and stir 30 seconds until fragrant.", "Pour in diced tomatoes and tomato sauce; simmer 10 minutes.", "Add drained chickpeas and simmer 10 more minutes.", "Cook basmati rice per package instructions and serve alongside."]'::jsonb, 4, 10, 30, 1.9, 7.6, 420, 17, 72, 7, 10, 540, true, true, true, 'curated'),
  ('Tempeh Stir-Fry with Snap Peas', 'Savory marinated tempeh strips stir-fried with crisp snap peas in a ginger-soy glaze.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','egg-free','high-protein','nut-free','quick','stir-fry','vegan','vegetarian']::text[], '["1 pkg tempeh", "2 cups snap peas", "1 red bell pepper", "3 cloves garlic", "1 tbsp fresh ginger", "3 tbsp soy sauce", "1 tbsp rice vinegar", "1 tsp sesame oil", "2 tbsp olive oil", "2 cups white rice", "1 tsp cornstarch"]'::jsonb, '["Cube tempeh and marinate in 2 tbsp soy sauce for 10 minutes.", "Cook rice per package directions.", "Heat olive oil in a wok over high heat; cook tempeh until browned, about 6 minutes; set aside.", "Add snap peas and sliced bell pepper to the wok; stir-fry 3 minutes.", "Add garlic and ginger; cook 30 seconds, then pour in remaining soy sauce, rice vinegar, sesame oil, and cornstarch mixed with 2 tbsp water.", "Return tempeh, toss to combine, and serve over rice."]'::jsonb, 4, 15, 20, 2.7, 10.8, 390, 24, 48, 12, 5, 670, false, true, true, 'curated'),
  ('Roasted Vegetable Sheet-Pan Dinner', 'Colorful seasonal vegetables roasted until caramelized and served over herbed quinoa.', 'dinner', 'Sheet-Pan', 'budget', ARRAY['budget','colorful','dairy-free','egg-free','gluten-free','kid-friendly','mediterranean','nut-free','one-pan','sheet-pan','soy-free','vegan','vegetarian']::text[], '["2 zucchini", "2 bell peppers", "1 lb sweet potatoes", "1 red onion", "3 tbsp olive oil", "1 tsp garlic powder", "1 tsp dried oregano", "1 tsp smoked paprika", "1.5 cups quinoa", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F; line two sheet pans with foil.", "Chop all vegetables into 1-inch pieces and toss with olive oil, garlic powder, oregano, smoked paprika, salt, and pepper.", "Spread evenly on sheet pans and roast 25-30 minutes, flipping halfway, until caramelized.", "Cook quinoa per package directions while vegetables roast.", "Serve roasted vegetables over quinoa."]'::jsonb, 4, 15, 30, 2.2, 8.8, 360, 10, 60, 9, 8, 340, true, true, true, 'curated'),
  ('Smoky Lentil Stuffed Peppers', 'Bell peppers filled with a savory blend of lentils, tomatoes, and smoky spices, baked until tender.', 'dinner', 'Baked', 'budget', ARRAY['baked','budget','dairy-free','egg-free','gluten-free','hearty','kid-friendly','nut-free','soy-free','stuffed','vegan','vegetarian']::text[], '["4 bell peppers", "1 cup green lentils", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tsp smoked paprika", "1 tsp cumin", "2 cups vegetable broth", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Cook lentils in broth over medium heat for 20 minutes until tender; drain excess liquid.", "Saut\u00e9 diced onion and garlic in olive oil until soft; add spices and diced tomatoes; cook 5 minutes.", "Combine lentil mixture with tomato mixture and season with salt and pepper.", "Preheat oven to 375\u00b0F; cut tops off peppers and remove seeds.", "Fill peppers with lentil filling, place in a baking dish with \u00bc cup water, cover with foil, and bake 35 minutes.", "Uncover and bake 10 more minutes until peppers are tender."]'::jsonb, 4, 15, 50, 2.1, 8.4, 300, 16, 46, 6, 13, 420, true, true, true, 'curated'),
  ('Spicy Peanut Noodles', 'Chewy noodles coated in a bold peanut sauce with shredded carrots and green onions.', 'dinner', 'Asian Noodles', 'budget', ARRAY['asian','budget','dairy-free','egg-free','kid-friendly','noodles','peanut','quick','vegan','vegetarian']::text[], '["12 oz lo mein noodles", "3 tbsp peanut paste", "3 tbsp soy sauce", "1 tbsp rice vinegar", "1 tsp sesame oil", "1 tsp chili flakes", "2 cloves garlic", "1 tsp fresh ginger", "2 carrots", "3 green onions", "1 tbsp olive oil", "2 tbsp water"]'::jsonb, '["Cook noodles per package directions; drain and rinse with cold water.", "Whisk together peanut paste, soy sauce, rice vinegar, sesame oil, chili flakes, minced garlic, grated ginger, and water to make sauce.", "Julienne or shred carrots and thinly slice green onions.", "Toss noodles with peanut sauce until evenly coated.", "Top with carrots and green onions; drizzle with olive oil and serve."]'::jsonb, 4, 10, 10, 1.8, 7.2, 410, 13, 62, 13, 4, 590, true, true, true, 'curated'),
  ('Black-Eyed Pea and Collard Greens Stew', 'A Southern-inspired stew of black-eyed peas and slow-cooked collard greens in a smoky broth.', 'dinner', 'Southern', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','nut-free','one-pot','soul-food','southern','soy-free','vegan','vegetarian']::text[], '["2 cans black-eyed peas", "4 cups chopped collard greens", "1 onion", "4 cloves garlic", "1 can diced tomatoes", "4 cups vegetable broth", "1 tsp smoked paprika", "1 tsp apple cider vinegar", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Saut\u00e9 diced onion in olive oil over medium heat until soft, about 5 minutes.", "Add minced garlic and smoked paprika; cook 1 minute.", "Add drained black-eyed peas, diced tomatoes, and broth; bring to a boil.", "Stir in collard greens and simmer 20 minutes until greens are tender.", "Add apple cider vinegar, season with salt and pepper, and serve with cornbread."]'::jsonb, 4, 10, 30, 1.35, 5.4, 270, 14, 40, 5, 10, 510, false, true, true, 'curated'),
  ('Mushroom and Lentil Bolognese', 'A rich, meaty-textured pasta sauce made with mushrooms and lentils over spaghetti.', 'dinner', 'Italian', 'budget', ARRAY['budget','dairy-free','egg-free','high-protein','italian','kid-friendly','nut-free','one-pot','pasta','soy-free','vegan','vegetarian']::text[], '["12 oz spaghetti", "1 cup green lentils", "8 oz mushrooms", "1 can crushed tomatoes", "1 onion", "4 cloves garlic", "2 stalks celery", "2 carrots", "1 tsp dried basil", "1 tsp dried oregano", "2 tbsp olive oil", "2 cups water", "salt", "pepper"]'::jsonb, '["Cook lentils in 2 cups water until just tender, about 20 minutes; drain.", "Saut\u00e9 diced onion, celery, and carrot in olive oil for 6 minutes.", "Add minced garlic and chopped mushrooms; cook until mushrooms release moisture, about 8 minutes.", "Stir in crushed tomatoes, basil, and oregano; simmer 10 minutes.", "Add cooked lentils to sauce; season with salt and pepper.", "Cook spaghetti per package directions and serve topped with sauce."]'::jsonb, 4, 15, 40, 2.3, 9.2, 470, 22, 80, 7, 14, 430, true, true, true, 'curated'),
  ('Spiced Cauliflower and Potato Curry', 'Tender cauliflower and potatoes cooked in a fragrant tomato-spice sauce served over rice.', 'dinner', 'Indian', 'ultra_budget', ARRAY['budget','budget-friendly','dairy-free','egg-free','gluten-free','indian','kid-friendly','nut-free','one-pot','soy-free','vegan','vegetable','vegetarian']::text[], '["1 head cauliflower", "1 lb potatoes", "1 can diced tomatoes", "1 onion", "4 cloves garlic", "1 tbsp fresh ginger", "1 tsp cumin", "1 tsp turmeric", "1 tsp coriander", "1 tsp garam masala", "2 tbsp olive oil", "0.5 cup water", "2 cups white rice", "salt"]'::jsonb, '["Cut cauliflower into florets and dice potatoes into \u00bd-inch cubes.", "Saut\u00e9 onion in olive oil for 5 minutes; add garlic and ginger, cook 1 minute.", "Add all spices and toast 30 seconds, then add diced tomatoes and water.", "Add cauliflower and potatoes; stir to coat, cover, and simmer 20 minutes until fork-tender.", "Cook rice per package directions.", "Season curry with salt and serve over rice."]'::jsonb, 4, 15, 30, 1.4, 5.6, 350, 8, 66, 6, 7, 360, true, true, true, 'curated'),
  ('Pinto Bean and Sweet Potato Enchiladas', 'Rolled corn tortillas filled with smoky pinto beans and sweet potato, baked in red enchilada sauce.', 'dinner', 'Mexican', 'budget', ARRAY['baked','budget','dairy-free','egg-free','gluten-free','kid-friendly','mexican','nut-free','sheet-pan','soy-free','vegan','vegetarian']::text[], '["2 cans pinto beans", "1 lb sweet potatoes", "12 corn tortillas", "2 cups red enchilada sauce", "1 onion", "3 cloves garlic", "1 tsp cumin", "1 tsp chili powder", "2 tbsp olive oil", "salt"]'::jsonb, '["Preheat oven to 375\u00b0F; peel and dice sweet potatoes; roast on a sheet pan with olive oil and salt for 20 minutes.", "Saut\u00e9 onion and garlic in olive oil until soft; add drained pinto beans and spices; mash lightly.", "Combine roasted sweet potato with bean mixture.", "Warm tortillas, fill each with the bean-potato mixture, roll tightly, and arrange seam-side down in a baking dish.", "Pour enchilada sauce over the top and bake 20 minutes until bubbling.", "Rest 5 minutes before serving."]'::jsonb, 4, 20, 45, 2.5, 10.0, 450, 16, 78, 8, 13, 640, true, true, true, 'curated'),
  ('Korean-Style Spicy Tofu Rice Bowl', 'Crispy tofu in a gochujang-soy glaze served over steamed rice with pickled cucumbers.', 'dinner', 'Korean', 'budget', ARRAY['budget','dairy-free','egg-free','high-protein','korean','nut-free','rice-bowl','spicy','vegan','vegetarian']::text[], '["1 lb firm tofu", "2 cups white rice", "2 tbsp gochujang", "2 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp sugar", "3 cloves garlic", "1 cucumber", "2 tbsp rice vinegar", "2 tbsp olive oil", "2 green onions", "salt"]'::jsonb, '["Press and cube tofu; pan-fry in olive oil over high heat until golden, about 8 minutes; set aside.", "Cook rice per package directions.", "Whisk together gochujang, soy sauce, sesame oil, sugar, and minced garlic for the glaze.", "Toss tofu with glaze in the pan over medium heat for 2 minutes until coated.", "Thinly slice cucumber and toss with rice vinegar and salt to pickle briefly.", "Serve rice bowls topped with glazed tofu, pickled cucumber, and sliced green onions."]'::jsonb, 4, 15, 20, 2.6, 10.4, 390, 20, 55, 11, 3, 680, false, true, true, 'curated'),
  ('Tuscan White Bean Skillet', 'Cannellini beans sautéed with sun-dried tomatoes, spinach, and garlic in a savory pan sauce.', 'dinner', 'Italian', 'budget', ARRAY['budget','dairy-free','egg-free','italian','kid-friendly','nut-free','one-pan','quick','soy-free','vegan','vegetarian']::text[], '["2 cans cannellini beans", "4 cups baby spinach", "0.33 cup sun-dried tomatoes", "4 cloves garlic", "1 cup vegetable broth", "1 tsp dried basil", "1 tsp dried thyme", "2 tbsp olive oil", "4 slices Italian bread", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large skillet over medium heat; saut\u00e9 minced garlic 1 minute.", "Add chopped sun-dried tomatoes and cook 2 minutes.", "Add drained beans and broth; simmer 5 minutes until sauce reduces slightly.", "Stir in spinach, basil, and thyme; cook 2 minutes until wilted.", "Season with salt and pepper and serve with crusty bread for dipping."]'::jsonb, 4, 5, 15, 2.0, 8.0, 320, 16, 50, 7, 11, 490, true, true, true, 'curated'),
  ('Jamaican Jerk Chickpea Bowl', 'Bold jerk-seasoned chickpeas served with rice, mango salsa, and shredded cabbage.', 'dinner', 'Caribbean', 'budget', ARRAY['budget','caribbean','dairy-free','egg-free','gluten-free','nut-free','rice-bowl','soy-free','spicy','vegan','vegetarian']::text[], '["2 cans chickpeas", "2 cups long-grain white rice", "2 tbsp olive oil", "2 tsp jerk seasoning", "1 tsp smoked paprika", "1 tsp allspice", "1 can mango chunks", "0.5 red onion", "1 lime", "2 cups shredded cabbage", "2 green onions", "salt"]'::jsonb, '["Cook rice per package directions.", "Toss drained chickpeas with olive oil, jerk seasoning, smoked paprika, and allspice.", "Pan-fry seasoned chickpeas in a dry skillet over medium-high heat for 8 minutes until crispy.", "Dice mango and red onion; toss with lime juice and a pinch of salt for salsa.", "Assemble bowls with rice, crispy chickpeas, cabbage, mango salsa, and sliced green onions."]'::jsonb, 4, 10, 20, 2.2, 8.8, 430, 15, 74, 8, 9, 420, false, true, true, 'curated'),
  ('Split Pea and Carrot Soup', 'A thick, creamy split pea soup with carrots and aromatics that is comforting and deeply satisfying.', 'dinner', 'Soup', 'ultra_budget', ARRAY['budget','budget-friendly','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["1.5 cups green split peas", "4 carrots", "1 onion", "4 cloves garlic", "2 stalks celery", "6 cups vegetable broth", "1 tsp cumin", "1 tsp smoked paprika", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Saut\u00e9 diced onion, celery, and carrots in olive oil for 5 minutes.", "Add minced garlic, cumin, and smoked paprika; cook 1 minute.", "Add rinsed split peas and broth; bring to a boil.", "Reduce heat, cover, and simmer 40 minutes until peas are completely soft.", "Use an immersion blender to partially blend the soup for a creamy yet chunky texture.", "Season with salt and pepper and serve with crusty bread."]'::jsonb, 6, 10, 45, 0.95, 5.7, 250, 14, 40, 4, 13, 430, true, true, true, 'curated'),
  ('Teriyaki Tempeh Bowls', 'Sweet and savory teriyaki-glazed tempeh served over fluffy rice with steamed broccoli.', 'dinner', 'Asian', 'budget', ARRAY['asian','budget','dairy-free','egg-free','high-protein','kid-friendly','nut-free','quick','rice-bowl','vegan','vegetarian']::text[], '["1 pkg tempeh", "3 tbsp soy sauce", "2 tbsp maple syrup", "1 tbsp rice vinegar", "1 tsp sesame oil", "2 cloves garlic", "1 tsp fresh ginger", "1 tsp cornstarch", "3 cups broccoli florets", "2 cups white rice", "2 tbsp olive oil", "2 green onions"]'::jsonb, '["Slice tempeh into strips and brown in olive oil over medium heat, about 4 minutes per side.", "Cook rice and steam broccoli simultaneously per package directions.", "Mix soy sauce, maple syrup, rice vinegar, sesame oil, minced garlic, grated ginger, and cornstarch for glaze.", "Pour glaze over tempeh strips in the pan; cook 2 minutes until thickened and sticky.", "Assemble bowls with rice, broccoli, and teriyaki tempeh; garnish with sliced green onions."]'::jsonb, 4, 10, 20, 2.8, 11.2, 400, 23, 54, 11, 5, 610, true, true, true, 'curated'),
  ('Moroccan Chickpea and Vegetable Tagine', 'A warming North African stew of chickpeas, zucchini, and sweet spices served over couscous.', 'dinner', 'Moroccan', 'budget', ARRAY['aromatic','budget','dairy-free','egg-free','kid-friendly','moroccan','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["2 cans chickpeas", "2 zucchini", "1 can diced tomatoes", "1 onion", "4 cloves garlic", "1 tsp cumin", "1 tsp cinnamon", "1 tsp coriander", "1 tsp turmeric", "2 tbsp olive oil", "2 cups couscous", "2 cups vegetable broth", "salt"]'::jsonb, '["Saut\u00e9 diced onion in olive oil until golden, about 6 minutes.", "Add garlic and all spices; cook 1 minute.", "Add diced zucchini, diced tomatoes, and drained chickpeas; stir to combine.", "Add 1 cup broth, bring to a simmer, cover, and cook 20 minutes.", "Place couscous in a bowl, pour boiling remaining broth over it, cover, and rest 5 minutes; fluff with fork.", "Season tagine with salt and serve over couscous."]'::jsonb, 4, 15, 30, 2.3, 9.2, 440, 17, 73, 8, 11, 450, true, true, true, 'curated'),
  ('Tex-Mex Bean and Rice Skillet', 'A one-pan fiesta of seasoned rice, black beans, corn, and roasted tomatoes with warm spices.', 'dinner', 'Tex-Mex', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','one-pan','quick','soy-free','tex-mex','vegan','vegetarian']::text[], '["1 can black beans", "1 cup long-grain white rice", "1 can corn", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "2 cups vegetable broth", "1 tsp cumin", "1 tsp chili powder", "2 tbsp olive oil", "salt"]'::jsonb, '["Saut\u00e9 diced onion in olive oil over medium heat for 4 minutes.", "Add minced garlic, cumin, and chili powder; cook 30 seconds.", "Stir in uncooked rice; toast 2 minutes until lightly golden.", "Add diced tomatoes, drained corn, drained beans, and broth; bring to a boil.", "Cover, reduce heat, and cook 18-20 minutes until rice is cooked and liquid is absorbed.", "Fluff with a fork, season with salt, and serve."]'::jsonb, 4, 10, 25, 1.2, 4.8, 350, 13, 62, 5, 9, 510, true, true, true, 'curated'),
  ('Tahini-Roasted Eggplant with Lentils', 'Silky roasted eggplant drizzled with tahini dressing over a bed of warm herbed lentils.', 'dinner', 'Mediterranean', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','mediterranean','nut-free','roasted','soy-free','tahini','vegan','vegetarian']::text[], '["2 large eggplants", "1 cup green lentils", "3 tbsp tahini", "2 tbsp lemon juice", "3 cloves garlic", "2 cups water", "1 tsp cumin", "1 tsp smoked paprika", "3 tbsp olive oil", "2 tbsp fresh parsley", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F; slice eggplant into rounds, brush with olive oil, season with salt and smoked paprika, and roast 25 minutes until golden.", "Cook lentils in water with cumin and a pinch of salt for 20 minutes until tender; drain.", "Whisk tahini with lemon juice, minced garlic, and 3 tbsp water until smooth dressing forms.", "Toss warm lentils with 1 tbsp olive oil and season with salt and pepper.", "Arrange lentils on plates, top with roasted eggplant, drizzle with tahini dressing, and garnish with parsley."]'::jsonb, 4, 10, 30, 2.4, 9.6, 370, 17, 44, 14, 14, 310, false, true, true, 'curated'),
  ('Smoky Butternut Squash Chili', 'A hearty, smoke-kissed chili combining butternut squash and kidney beans in a rich tomato base.', 'dinner', 'American', 'budget', ARRAY['budget','chili','dairy-free','egg-free','gluten-free','hearty','kid-friendly','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["1 small butternut squash", "2 cans kidney beans", "1 can diced tomatoes", "1 can tomato sauce", "1 onion", "4 cloves garlic", "1 bell pepper", "2 tsp chili powder", "1 tsp cumin", "1 tsp smoked paprika", "2 tbsp olive oil", "1 cup vegetable broth", "salt", "pepper"]'::jsonb, '["Peel and cube butternut squash into 1-inch pieces.", "Saut\u00e9 diced onion and bell pepper in olive oil for 5 minutes.", "Add minced garlic and all spices; cook 1 minute.", "Add squash, drained kidney beans, diced tomatoes, tomato sauce, and broth; bring to a boil.", "Reduce heat, cover, and simmer 25 minutes until squash is tender.", "Season with salt and pepper and serve."]'::jsonb, 6, 15, 35, 1.7, 10.2, 310, 14, 52, 5, 13, 550, true, true, true, 'curated'),
  ('Thai Peanut Red Curry with Tofu', 'Creamy coconut-free red curry with blended white beans and tofu in a peanut-spice sauce.', 'dinner', 'Thai', 'budget', ARRAY['budget','curry','dairy-free','egg-free','high-protein','spicy','thai','vegan','vegetarian']::text[], '["1 lb firm tofu", "1 can white beans", "1 red bell pepper", "2 cups broccoli florets", "3 tbsp red curry paste", "3 tbsp peanut paste", "2 cups vegetable broth", "2 tbsp soy sauce", "1 tbsp sugar", "1 tbsp olive oil", "2 cups white rice", "1 lime"]'::jsonb, '["Cook rice per package directions.", "Blend drained white beans with 1 cup broth until very smooth for creaminess base.", "Press and cube tofu; pan-fry in olive oil until golden, about 6 minutes; set aside.", "In the same pan, fry red curry paste 1 minute; add peanut paste and stir until combined.", "Pour in bean pur\u00e9e and remaining broth; add soy sauce and sugar; simmer 5 minutes.", "Add tofu, bell pepper, and broccoli; cook 8 minutes; finish with a squeeze of lime and serve over rice."]'::jsonb, 4, 15, 25, 2.9, 11.6, 450, 26, 58, 14, 8, 680, false, true, true, 'curated'),
  ('Smoky Fajita Vegetable Bowls', 'Sizzling strips of pepper, onion, and mushroom with smoky spices served over cilantro rice.', 'dinner', 'Tex-Mex', 'budget', ARRAY['budget','colorful','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','one-pan','quick','soy-free','tex-mex','vegan','vegetarian']::text[], '["3 bell peppers", "2 large portobello mushrooms", "1 onion", "1 can black beans", "2 tsp smoked paprika", "1 tsp cumin", "1 tsp garlic powder", "2 tbsp olive oil", "2 cups long-grain white rice", "2 tbsp fresh cilantro", "1 lime", "salt", "pepper"]'::jsonb, '["Cook rice per package directions; stir in chopped cilantro and lime juice when done.", "Slice peppers, onion, and mushrooms into strips.", "Heat olive oil in a large cast-iron skillet over high heat until smoking.", "Add vegetables and cook without stirring for 3 minutes, then stir and cook 4 more minutes until charred.", "Season with smoked paprika, cumin, garlic powder, salt, and pepper.", "Warm drained black beans in a small pot and serve everything over cilantro rice."]'::jsonb, 4, 10, 20, 2.1, 8.4, 370, 12, 64, 7, 9, 440, true, true, true, 'curated'),
  ('Garlic and Herb White Bean Mash with Roasted Tomatoes', 'Velvety mashed white beans seasoned with garlic and herbs, topped with burst oven-roasted tomatoes.', 'dinner', 'Mediterranean', 'budget', ARRAY['budget','comforting','dairy-free','egg-free','kid-friendly','mediterranean','nut-free','one-pan','soy-free','vegan','vegetarian']::text[], '["2 cans cannellini beans", "2 cups cherry tomatoes", "5 cloves garlic", "3 tbsp olive oil", "1 tsp dried rosemary", "1 tsp dried thyme", "4 slices crusty bread", "1 tbsp lemon juice", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F; toss cherry tomatoes with 1 tbsp olive oil and salt; roast 20 minutes until burst.", "In a saucepan, heat remaining olive oil over medium heat; add minced garlic and cook 1 minute.", "Add drained beans, rosemary, thyme, and a pinch of salt; cook 5 minutes, stirring.", "Mash beans with a fork or potato masher until smooth and creamy; stir in lemon juice.", "Serve white bean mash topped with roasted tomatoes and their juices, alongside crusty bread."]'::jsonb, 4, 5, 25, 2.0, 8.0, 340, 16, 50, 9, 12, 460, true, true, true, 'curated'),
  ('Garlicky Spaghetti Aglio e Olio with Chickpeas', 'Classic Italian pasta tossed with golden garlic, chili flakes, and protein-rich chickpeas.', 'dinner', 'Italian', 'budget', ARRAY['budget','dairy-free','egg-free','italian','nut-free','pasta','quick','soy-free','vegan','vegetarian']::text[], '["12 oz spaghetti", "1 can chickpeas", "6 cloves garlic", "0.5 tsp chili flakes", "4 tbsp olive oil", "2 tbsp fresh parsley", "1 lemon", "salt", "pepper"]'::jsonb, '["Cook spaghetti in heavily salted boiling water until al dente; reserve 1 cup pasta water before draining.", "While pasta cooks, slice garlic thinly and fry in olive oil over low heat until golden, about 4 minutes.", "Add chili flakes and drained chickpeas; cook 3 minutes until chickpeas are slightly crisped.", "Add drained pasta and a splash of pasta water; toss vigorously to emulsify.", "Add lemon juice, fresh parsley, salt, and pepper; toss again and serve immediately."]'::jsonb, 4, 5, 15, 1.8, 7.2, 430, 16, 72, 10, 7, 380, false, true, true, 'curated'),
  ('Baked Falafel Bowls with Tahini Sauce', 'Herb-packed baked falafel patties served over tabbouleh-style bulgur with creamy tahini dressing.', 'dinner', 'Middle Eastern', 'budget', ARRAY['baked','budget','dairy-free','egg-free','kid-friendly','middle-eastern','nut-free','soy-free','tahini','vegan','vegetarian']::text[], '["2 cans chickpeas", "1 cup bulgur wheat", "1 onion", "4 cloves garlic", "2 tbsp fresh parsley", "1 tsp cumin", "1 tsp coriander", "3 tbsp all-purpose flour", "3 tbsp tahini", "2 tbsp lemon juice", "2 tbsp olive oil", "2 cups water", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F; cook bulgur in 2 cups water for 15 minutes until fluffy.", "Process drained chickpeas with onion, garlic, parsley, cumin, coriander, flour, salt, and pepper in a food processor until a coarse dough forms.", "Form into 16 small patties, brush with olive oil, and bake 25 minutes flipping halfway.", "Whisk tahini with lemon juice, 4 tbsp water, and a pinch of salt into a smooth sauce.", "Toss cooked bulgur with a drizzle of olive oil, salt, and pepper.", "Serve bulgur bowls topped with falafel patties and tahini sauce."]'::jsonb, 4, 20, 30, 2.5, 10.0, 450, 19, 66, 13, 12, 480, true, true, true, 'curated'),
  ('Tofu and Broccoli Stir-Fry', 'Crispy pan-fried tofu and tender broccoli tossed in a savory ginger-soy sauce over steamed rice.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','egg-free','kid-friendly','nut-free','quick','stir-fry','vegan','vegetarian']::text[], '["1 lb firm tofu", "2 cups broccoli florets", "2 cloves garlic", "1 tbsp soy sauce", "1 tbsp olive oil", "1 tsp ginger powder", "1 tbsp cornstarch", "1 tbsp rice vinegar", "1 tsp sesame oil", "3 cups cooked white rice", "salt", "pepper"]'::jsonb, '["Press tofu dry and cut into cubes; toss with cornstarch, salt, and pepper.", "Heat olive oil in a large skillet over high heat; cook tofu until golden on all sides, about 8 minutes. Remove.", "Add broccoli to skillet; stir-fry 4 minutes.", "Add garlic and ginger; cook 1 minute.", "Return tofu to skillet; add soy sauce, rice vinegar, and sesame oil. Toss to coat.", "Serve over cooked rice."]'::jsonb, 4, 15, 20, 2.2, 8.8, 380, 18, 52, 10, 4, 540, true, true, true, 'curated'),
  ('Minestrone Soup', 'A hearty Italian soup loaded with white beans, zucchini, carrots, and pasta in a rich tomato broth.', 'dinner', 'Soup', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','italian','kid-friendly','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["1 can white beans", "1 can diced tomatoes", "2 carrots", "2 stalks celery", "1 zucchini", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 cup elbow pasta", "4 cups water", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Dice onion, carrots, celery, and zucchini.", "Heat olive oil in a large pot; cook onion, carrots, and celery 5 minutes.", "Add garlic and Italian seasoning; cook 1 minute.", "Add tomatoes, white beans, and water; bring to a boil.", "Add pasta and cook 10 minutes until tender.", "Season with salt and pepper and serve hot."]'::jsonb, 6, 15, 25, 1.0, 6.0, 230, 10, 40, 3, 8, 450, true, true, true, 'curated'),
  ('Black Bean Enchiladas', 'Corn tortillas filled with seasoned black beans and peppers, smothered in red enchilada sauce.', 'dinner', 'Mexican', 'budget', ARRAY['baked','budget','comfort-food','dairy-free','egg-free','gluten-free','kid-friendly','mexican','nut-free','soy-free','vegan','vegetarian']::text[], '["2 cans black beans", "8 corn tortillas", "1 can enchilada sauce", "1 bell pepper", "1 onion", "2 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp chili powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 375 degrees F.", "Dice onion and bell pepper; cook in olive oil over medium heat until soft, 5 minutes.", "Add garlic, cumin, and chili powder; cook 1 minute. Add drained beans and stir.", "Warm tortillas briefly in a dry pan to make pliable.", "Fill each tortilla with bean mixture, roll up, and place seam-side down in a baking dish.", "Pour enchilada sauce over top; bake 20 minutes until bubbly."]'::jsonb, 4, 15, 30, 1.8, 7.2, 370, 15, 62, 5, 13, 720, true, true, true, 'curated'),
  ('Lentil and Vegetable Curry', 'Brown lentils and seasonal vegetables slow-simmered in a fragrant tomato-based curry sauce.', 'dinner', 'Indian', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','indian','kid-friendly','meal-prep','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["2 cups brown lentils", "2 carrots", "1 onion", "3 cloves garlic", "1 can diced tomatoes", "1 tbsp olive oil", "1 tbsp curry powder", "1 tsp cumin", "1 tsp turmeric", "4 cups water", "3 cups cooked brown rice", "salt"]'::jsonb, '["Dice carrots and onion; mince garlic.", "Heat olive oil in a pot; cook onion and carrots 5 minutes.", "Add garlic, curry powder, cumin, and turmeric; stir 1 minute.", "Add lentils, tomatoes, and water; bring to a boil.", "Simmer 25 minutes until lentils and carrots are tender.", "Season with salt and serve over brown rice."]'::jsonb, 6, 10, 30, 1.1, 6.6, 320, 17, 56, 3, 15, 330, true, true, true, 'curated'),
  ('Roasted Sweet Potato and Black Bean Bowl', 'Caramelized roasted sweet potatoes and smoky black beans served over rice with a fresh lime dressing.', 'dinner', 'Bowl', 'budget', ARRAY['bowl','budget','dairy-free','egg-free','gluten-free','kid-friendly','meal-prep','nut-free','sheet-pan','soy-free','vegan','vegetarian']::text[], '["2 large sweet potatoes", "1 can black beans", "2 cups cooked brown rice", "1 tbsp olive oil", "1 tsp cumin", "1 tsp smoked paprika", "1 lime", "salt", "pepper"]'::jsonb, '["Preheat oven to 425 degrees F.", "Peel and cube sweet potatoes; toss with olive oil, cumin, smoked paprika, salt, and pepper.", "Roast on a baking sheet 25 minutes, flipping halfway, until golden.", "Warm drained black beans in a small pot.", "Assemble bowls with rice, sweet potatoes, and black beans.", "Squeeze lime juice over each bowl before serving."]'::jsonb, 4, 10, 30, 2.0, 8.0, 400, 13, 76, 5, 14, 380, true, true, true, 'curated'),
  ('Tuscan White Bean Soup', 'A rustic Italian soup of white beans, kale, and tomatoes slow-simmered with rosemary and garlic.', 'dinner', 'Soup', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','italian','kid-friendly','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["2 cans white beans", "1 can diced tomatoes", "3 cups kale", "1 onion", "4 cloves garlic", "1 tbsp olive oil", "1 tsp dried rosemary", "1 tsp Italian seasoning", "4 cups water", "salt", "pepper"]'::jsonb, '["Dice onion and mince garlic; strip and roughly chop kale.", "Heat olive oil in a large pot; cook onion 5 minutes.", "Add garlic, rosemary, and Italian seasoning; cook 1 minute.", "Add white beans, tomatoes, and water; bring to a boil.", "Add kale and simmer 15 minutes.", "Season with salt and pepper; serve with crusty bread."]'::jsonb, 6, 10, 25, 1.0, 6.0, 220, 12, 36, 3, 10, 420, true, true, true, 'curated'),
  ('Spiced Chickpea Buddha Bowl', 'Roasted spiced chickpeas and fresh vegetables over quinoa with a zesty tahini dressing.', 'dinner', 'Bowl', 'budget', ARRAY['bowl','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','meal-prep','nut-free','sheet-pan','soy-free','vegan','vegetarian']::text[], '["2 cans chickpeas", "2 cups quinoa", "1 cucumber", "2 carrots", "1 tbsp olive oil", "1 tsp cumin", "1 tsp paprika", "2 tbsp tahini", "1 lemon", "2 cloves garlic", "3 tbsp water", "salt", "pepper"]'::jsonb, '["Preheat oven to 400 degrees F.", "Drain and dry chickpeas; toss with olive oil, cumin, paprika, salt, and pepper. Roast 25 minutes.", "Cook quinoa according to package directions.", "Whisk tahini, lemon juice, minced garlic, and water into a dressing.", "Slice cucumber and carrots.", "Assemble bowls with quinoa, chickpeas, and vegetables; drizzle with tahini dressing."]'::jsonb, 4, 15, 30, 2.7, 10.8, 450, 20, 64, 12, 12, 410, true, true, true, 'curated'),
  ('Mexican Street Corn Pasta', 'Pasta tossed with charred corn, lime juice, spices, and a silky white bean sauce for richness.', 'dinner', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','kid-friendly','mexican','nut-free','one-pot','pasta','quick','soy-free','vegan','vegetarian']::text[], '["12 oz penne pasta", "2 cups frozen corn", "1 can white beans", "1 lime", "2 cloves garlic", "1 tbsp olive oil", "1 tsp chili powder", "1 tsp cumin", "0.5 cup pasta water", "salt", "pepper"]'::jsonb, '["Cook pasta according to package directions; reserve 0.5 cup pasta water before draining.", "Blend drained white beans with a splash of pasta water and garlic until smooth.", "Cook frozen corn in olive oil over high heat until charred, about 5 minutes.", "Add chili powder and cumin to the corn; stir 30 seconds.", "Toss pasta with white bean sauce, charred corn, lime juice, salt, and pepper. Add pasta water to loosen as needed.", "Serve immediately."]'::jsonb, 4, 10, 20, 1.8, 7.2, 410, 17, 75, 5, 10, 360, true, true, true, 'curated'),
  ('Pinto Bean Burrito Bowl', 'Seasoned pinto beans and cilantro-lime rice served with fresh tomato pico de gallo and shredded lettuce.', 'dinner', 'Mexican', 'ultra_budget', ARRAY['bowl','budget','dairy-free','egg-free','gluten-free','kid-friendly','meal-prep','mexican','nut-free','soy-free','vegan','vegetarian']::text[], '["2 cans pinto beans", "2 cups long-grain white rice", "2 tomatoes", "1 onion", "1 lime", "2 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "2 cups lettuce", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions; fluff with a fork and stir in lime juice.", "Dice tomatoes and half the onion; mix with lime juice and a pinch of salt for pico de gallo.", "Cook remaining diced onion in olive oil until softened; add garlic and cumin, then add pinto beans.", "Simmer beans 10 minutes until flavors meld; mash slightly if desired.", "Assemble bowls with rice, beans, pico de gallo, and lettuce."]'::jsonb, 4, 15, 20, 1.4, 5.6, 390, 14, 74, 4, 12, 390, true, true, true, 'curated'),
  ('Stuffed Bell Peppers with Rice and Lentils', 'Colorful bell peppers filled with a savory herbed lentil and rice mixture, baked until tender.', 'dinner', 'Baked', 'budget', ARRAY['baked','budget','comfort-food','dairy-free','egg-free','gluten-free','kid-friendly','meal-prep','nut-free','soy-free','vegan','vegetarian']::text[], '["4 bell peppers", "1 cup green lentils", "1 cup white rice", "1 can diced tomatoes", "1 onion", "2 cloves garlic", "1 tbsp olive oil", "1 tsp Italian seasoning", "1 tsp cumin", "2 cups water", "salt", "pepper"]'::jsonb, '["Cook lentils in water 20 minutes; cook rice separately.", "Preheat oven to 375 degrees F; cut tops off peppers and remove seeds.", "Cook diced onion in olive oil until soft; add garlic, Italian seasoning, and cumin.", "Mix in drained lentils, cooked rice, and half the tomatoes. Season with salt and pepper.", "Fill each pepper with the mixture; pour remaining tomatoes into baking dish around peppers.", "Cover with foil and bake 30 minutes until peppers are tender."]'::jsonb, 4, 20, 45, 2.4, 9.6, 370, 16, 66, 4, 14, 430, true, true, true, 'curated'),
  ('Garden Vegetable Fried Rice', 'Classic fried rice loaded with frozen peas, carrots, corn, and green onions in a savory soy glaze.', 'dinner', 'Asian', 'ultra_budget', ARRAY['asian','budget','dairy-free','egg-free','kid-friendly','nut-free','one-pan','quick','stir-fry','vegan','vegetarian']::text[], '["3 cups cooked rice", "1 cup frozen peas", "1 cup frozen corn", "2 carrots", "3 green onions", "3 cloves garlic", "2 tbsp soy sauce", "1 tbsp olive oil", "1 tsp sesame oil", "salt", "pepper"]'::jsonb, '["Dice carrots; slice green onions.", "Heat olive oil in a large skillet or wok over high heat.", "Cook carrots 3 minutes; add garlic and cook 1 minute more.", "Add frozen peas and corn; cook 2 minutes.", "Push vegetables to the side; add rice and press flat to let it crisp, about 3 minutes.", "Add soy sauce and sesame oil; toss everything together. Top with green onions."]'::jsonb, 4, 10, 15, 1.2, 4.8, 310, 8, 58, 5, 5, 490, true, true, true, 'curated'),
  ('Hearty Vegetable and Bean Chili', 'A bold and smoky chili packed with kidney beans, bell peppers, zucchini, and fire-roasted tomatoes.', 'dinner', 'Chili', 'ultra_budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','kid-friendly','meal-prep','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["2 cans kidney beans", "1 can diced tomatoes", "1 can tomato paste", "1 bell pepper", "1 zucchini", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "2 tsp chili powder", "1 tsp cumin", "1 tsp smoked paprika", "2 cups water", "salt", "pepper"]'::jsonb, '["Dice onion, bell pepper, and zucchini.", "Heat olive oil in a large pot; cook onion and bell pepper 5 minutes.", "Add garlic, chili powder, cumin, and smoked paprika; stir 1 minute.", "Stir in tomato paste, diced tomatoes, beans, zucchini, and water.", "Bring to a boil then simmer 25 minutes until thickened.", "Season with salt and pepper."]'::jsonb, 6, 15, 30, 1.1, 6.6, 270, 14, 46, 3, 14, 520, true, true, true, 'curated'),
  ('Tofu Shakshuka', 'Crumbled tofu poached in a spiced tomato and pepper sauce seasoned with cumin and smoked paprika.', 'dinner', 'Mediterranean', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','mediterranean','nut-free','one-pan','quick','vegan','vegetarian']::text[], '["1 lb firm tofu", "1 can diced tomatoes", "1 bell pepper", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp smoked paprika", "0.5 tsp cayenne pepper", "4 pita breads", "salt", "pepper"]'::jsonb, '["Dice onion and bell pepper.", "Heat olive oil in a wide skillet; cook onion and pepper until softened.", "Add garlic, cumin, smoked paprika, and cayenne; cook 1 minute.", "Stir in diced tomatoes; simmer 10 minutes.", "Crumble tofu over the sauce; cover and cook 10 minutes.", "Serve with warm pita bread."]'::jsonb, 4, 10, 25, 2.3, 9.2, 330, 17, 40, 9, 5, 560, false, true, true, 'curated'),
  ('Korean-Style Tempeh Rice Bowl', 'Marinated and pan-glazed tempeh over steamed rice with stir-fried cabbage and a sweet-savory gochujang sauce.', 'dinner', 'Korean', 'budget', ARRAY['bowl','budget','dairy-free','egg-free','high-protein','korean','meal-prep','nut-free','vegan','vegetarian']::text[], '["1 pkg tempeh", "3 cups cooked white rice", "2 cups shredded cabbage", "2 tbsp soy sauce", "1 tbsp gochujang", "1 tbsp rice vinegar", "1 tsp sesame oil", "2 cloves garlic", "1 tsp ginger powder", "1 tbsp olive oil", "2 green onions"]'::jsonb, '["Slice tempeh into thin strips.", "Mix soy sauce, gochujang, rice vinegar, sesame oil, garlic, and ginger for a marinade.", "Coat tempeh in half the sauce; let sit 5 minutes.", "Heat olive oil in a skillet; cook tempeh 4 minutes per side until caramelized.", "Toss cabbage in remaining sauce for 2 minutes in the same pan.", "Serve tempeh and cabbage over rice; top with sliced green onions."]'::jsonb, 4, 15, 20, 2.8, 11.2, 410, 24, 52, 12, 5, 620, false, true, true, 'curated'),
  ('Split Pea Soup', 'A thick and satisfying green split pea soup simmered low and slow with carrots, celery, and smoky spices.', 'dinner', 'Soup', 'ultra_budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','kid-friendly','meal-prep','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["2 cups green split peas", "3 carrots", "3 stalks celery", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp smoked paprika", "1 tsp thyme", "6 cups water", "salt", "pepper"]'::jsonb, '["Dice onion, carrots, and celery.", "Heat olive oil in a large pot; cook onion, carrots, and celery 5 minutes.", "Add garlic, smoked paprika, and thyme; cook 1 minute.", "Rinse split peas and add with water; bring to a boil.", "Reduce heat and simmer 45 minutes, stirring occasionally, until peas break down and soup thickens.", "Season with salt and pepper."]'::jsonb, 6, 10, 50, 0.8, 4.8, 280, 17, 48, 3, 16, 310, true, true, true, 'curated'),
  ('Loaded Baked Potato Soup', 'A velvety potato soup thickened with blended white beans and topped with green onions and crispy chickpeas.', 'dinner', 'Soup', 'budget', ARRAY['american','budget','comfort-food','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["4 large russet potatoes", "1 can white beans", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "4 cups water", "1 tsp onion powder", "1 tsp garlic powder", "3 green onions", "1 can chickpeas", "salt", "pepper"]'::jsonb, '["Peel and cube potatoes; dice onion.", "Heat olive oil in a pot; cook onion until soft. Add garlic and cook 1 minute.", "Add potatoes, white beans, water, onion powder, and garlic powder; boil 20 minutes until potatoes are tender.", "Meanwhile, roast drained chickpeas in a dry skillet until crispy, about 10 minutes.", "Blend half the soup with an immersion blender until smooth, leaving some chunks.", "Season with salt and pepper; serve topped with green onions and crispy chickpeas."]'::jsonb, 6, 15, 30, 1.6, 9.6, 310, 12, 58, 4, 9, 390, true, true, true, 'curated'),
  ('Smoky Chipotle Lentil Tacos', 'Spiced lentils with chipotle flavor served in crispy corn shells with avocado and shredded cabbage.', 'dinner', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','mexican','nut-free','one-pot','quick','soy-free','vegan','vegetarian']::text[], '["2 cups green lentils", "8 corn taco shells", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tbsp chipotle chili powder", "1 tsp cumin", "1 tsp oregano", "3 cups water", "1 avocado", "2 cups shredded cabbage", "salt"]'::jsonb, '["Cook onion in olive oil until soft; add garlic, chipotle chili powder, cumin, and oregano.", "Add rinsed lentils and water; bring to boil then simmer 25 minutes until tender.", "Mash lentils slightly to thicken; season with salt.", "Slice avocado.", "Fill taco shells with lentil mixture, cabbage, and avocado slices."]'::jsonb, 4, 10, 30, 2.2, 8.8, 420, 19, 62, 11, 16, 440, false, true, true, 'curated'),
  ('Mujaddara', 'A classic Middle Eastern dish of rice and lentils topped with deeply caramelized crispy onions.', 'dinner', 'Middle Eastern', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','kid-friendly','middle-eastern','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["1 cup green lentils", "1 cup long-grain white rice", "3 onions", "3 tbsp olive oil", "1 tsp cumin", "0.5 tsp allspice", "3.5 cups water", "salt", "pepper"]'::jsonb, '["Slice onions thin; cook in 2 tbsp olive oil over medium-low heat 30-35 minutes until deeply caramelized.", "Rinse lentils and cook in 2 cups water 15 minutes until almost tender; drain.", "Cook rice in 1.5 cups salted water 18 minutes.", "Heat 1 tbsp olive oil in a pot; add cumin and allspice for 30 seconds.", "Add lentils and rice; stir gently to combine. Season with salt and pepper.", "Top bowls with caramelized onions."]'::jsonb, 4, 10, 50, 1.2, 4.8, 380, 15, 66, 8, 12, 280, true, true, true, 'curated'),
  ('Pea and Potato Aloo Matar', 'A comforting North Indian dish of tender potatoes and green peas braised in a fragrant spiced tomato sauce.', 'dinner', 'Indian', 'ultra_budget', ARRAY['budget','budget-friendly','comfort-food','dairy-free','egg-free','gluten-free','indian','kid-friendly','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["4 medium potatoes", "2 cups frozen peas", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp ginger powder", "1 tsp cumin", "1 tsp turmeric", "1 tsp garam masala", "3 cups cooked rice", "salt"]'::jsonb, '["Peel and cube potatoes; dice onion.", "Heat olive oil in a pot; cook onion until golden.", "Add garlic, ginger, cumin, turmeric, and garam masala; stir 1 minute.", "Add diced tomatoes and potatoes; stir to coat. Add 0.5 cup water.", "Cover and cook 20 minutes until potatoes are fork-tender.", "Add peas and cook 5 minutes; season with salt. Serve over rice."]'::jsonb, 4, 15, 30, 1.3, 5.2, 340, 9, 68, 4, 8, 340, true, true, true, 'curated'),
  ('Spaghetti with Marinara and White Bean Meatballs', 'Tender herb-seasoned white bean and oat balls simmered in a bright tomato marinara over spaghetti.', 'dinner', 'Italian', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','italian','kid-friendly','nut-free','pasta','soy-free','vegan','vegetarian']::text[], '["12 oz spaghetti", "1 can white beans", "0.5 cup rolled oats", "1 can crushed tomatoes", "1 onion", "4 cloves garlic", "2 tbsp olive oil", "2 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Drain and rinse beans; mash well with oats, half the garlic, 1 tsp Italian seasoning, salt, and pepper.", "Roll mixture into small balls and bake at 400 degrees F for 20 minutes until firm.", "Meanwhile, cook spaghetti according to package directions.", "Cook onion in 1 tbsp olive oil; add remaining garlic and Italian seasoning.", "Add crushed tomatoes and simmer 15 minutes; gently add baked bean balls.", "Serve sauce and balls over spaghetti."]'::jsonb, 4, 20, 30, 2.5, 10.0, 480, 19, 82, 7, 11, 560, true, true, true, 'curated'),
  ('Pasta e Fagioli', 'A thick Italian pasta and bean soup simmered with tomatoes, rosemary, and garlic in the old-world tradition.', 'dinner', 'Italian', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','italian','kid-friendly','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["2 cans cannellini beans", "1 can diced tomatoes", "1 cup ditalini pasta", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp dried rosemary", "1 tsp Italian seasoning", "4 cups water", "salt", "pepper"]'::jsonb, '["Dice onion and mince garlic.", "Heat olive oil in a large pot; cook onion 5 minutes until soft.", "Add garlic, rosemary, and Italian seasoning; cook 1 minute.", "Add beans, tomatoes, and water; bring to a boil.", "Add pasta and simmer 10-12 minutes until pasta is tender.", "Mash some beans to thicken the broth; season with salt and pepper."]'::jsonb, 6, 10, 25, 0.95, 5.7, 260, 13, 46, 3, 10, 450, true, true, true, 'curated'),
  ('Ethiopian Red Lentil Wot', 'A deeply spiced Ethiopian stew of red lentils in a berbere-seasoned sauce served over injera-style flatbread.', 'dinner', 'Ethiopian', 'budget', ARRAY['budget','dairy-free','egg-free','ethiopian','gluten-free','high-protein','meal-prep','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["2 cups red lentils", "2 onions", "4 cloves garlic", "1 can diced tomatoes", "2 tbsp olive oil", "1 tbsp paprika", "1 tsp cumin", "1 tsp coriander", "0.5 tsp cinnamon", "0.5 tsp cayenne pepper", "4 cups water", "4 flatbreads", "salt"]'::jsonb, '["Finely dice onions and mince garlic.", "Cook onions in olive oil over medium-low heat 15 minutes, stirring often, until deeply browned.", "Add garlic, paprika, cumin, coriander, cinnamon, and cayenne; cook 2 minutes.", "Add diced tomatoes and lentils; stir to combine.", "Add water; bring to a boil then simmer 25 minutes until lentils are very soft.", "Season with salt; serve over flatbread."]'::jsonb, 4, 15, 45, 2.1, 8.4, 420, 22, 68, 7, 18, 380, false, true, true, 'curated'),
  ('Black-Eyed Pea and Braised Kale Stew', 'A Southern-inspired stew of black-eyed peas and tender braised kale in a smoky seasoned tomato broth.', 'dinner', 'Southern', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','one-pot','southern','soy-free','vegan','vegetarian']::text[], '["2 cans black-eyed peas", "1 bunch kale", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp smoked paprika", "1 tsp thyme", "3 cups water", "3 cups cooked rice", "salt", "pepper"]'::jsonb, '["Remove stems and roughly chop kale; dice onion.", "Heat olive oil in a pot; cook onion until soft.", "Add garlic, smoked paprika, and thyme; cook 1 minute.", "Add tomatoes, black-eyed peas, and water; bring to a boil.", "Add kale; cover and simmer 25 minutes until greens are tender.", "Season with salt and pepper; serve over rice."]'::jsonb, 6, 15, 30, 1.3, 7.8, 300, 14, 54, 3, 10, 430, true, true, true, 'curated'),
  ('Black Bean Tacos with Lime Crema', 'Smoky spiced black beans piled into warm tortillas with a tangy lime-sour cream drizzle and fresh pico de gallo.', 'dinner', 'Mexican', 'ultra_budget', ARRAY['budget','egg-free','kid-friendly','mexican','nut-free','one-pot','quick','soy-free','vegetarian']::text[], '["2 cans black beans", "8 small flour tortillas", "1 cup sour cream", "2 limes", "1 onion", "2 tomatoes", "1 cup shredded cheddar cheese", "2 cloves garlic", "1 tsp cumin", "1 tsp chili powder", "salt", "pepper", "2 tbsp olive oil"]'::jsonb, '["Dice onion and tomatoes; mix with juice of 1 lime and a pinch of salt to make pico de gallo.", "Heat olive oil in a skillet over medium heat; saut\u00e9 garlic and onion 3 minutes.", "Add drained black beans, cumin, chili powder, salt, and pepper; cook 5 minutes until heated through.", "Stir together sour cream and juice of remaining lime to make crema.", "Warm tortillas in a dry skillet or microwave.", "Assemble tacos with beans, pico de gallo, cheese, and lime crema."]'::jsonb, 4, 10, 10, 1.4, 5.6, 420, 18, 55, 14, 11, 620, true, true, true, 'curated'),
  ('Creamy Tomato Lentil Soup', 'Red lentils simmer with crushed tomatoes, garlic, and warm spices into a velvety, filling soup perfect for any weeknight.', 'dinner', 'Soup', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["1.5 cups red lentils", "1 can crushed tomatoes", "1 onion", "3 cloves garlic", "2 tbsp olive oil", "1 tsp cumin", "1 tsp paprika", "0.5 tsp turmeric", "4 cups vegetable broth", "salt", "pepper", "1 lemon"]'::jsonb, '["Heat olive oil in a large pot; saut\u00e9 diced onion 5 minutes until softened.", "Add garlic, cumin, paprika, and turmeric; stir 1 minute.", "Pour in crushed tomatoes, rinsed lentils, and vegetable broth.", "Bring to a boil, reduce heat, and simmer 20 minutes until lentils are tender.", "Use an immersion blender to partially blend for a creamy texture.", "Season with salt, pepper, and a squeeze of lemon juice before serving."]'::jsonb, 6, 10, 25, 0.9, 5.4, 280, 16, 42, 5, 14, 480, true, true, true, 'curated'),
  ('Sheet-Pan Honey-Garlic Tofu with Broccoli', 'Crispy oven-baked tofu and tender broccoli florets glazed with a sweet and savory honey-garlic sauce over fluffy white rice.', 'dinner', 'Sheet-Pan', 'budget', ARRAY['asian-inspired','budget','dairy-free','egg-free','kid-friendly','nut-free','quick','sheet-pan','vegetarian']::text[], '["1 lb firm tofu", "4 cups broccoli florets", "2 cups white rice", "3 tbsp soy sauce", "2 tbsp honey", "3 cloves garlic", "1 tbsp olive oil", "1 tbsp cornstarch", "1 tsp sesame oil", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F. Press tofu dry and cut into 1-inch cubes; toss with cornstarch and a pinch of pepper.", "Arrange tofu and broccoli on a lined sheet pan; drizzle with olive oil.", "Roast 20 minutes, flipping halfway, until tofu is golden and broccoli is tender.", "Whisk together soy sauce, honey, minced garlic, and sesame oil.", "Drizzle sauce over tofu and broccoli; return to oven 5 minutes.", "Cook rice according to package instructions and serve everything together."]'::jsonb, 4, 15, 25, 2.2, 8.8, 390, 18, 58, 8, 4, 710, true, true, true, 'curated'),
  ('Egg Fried Rice with Peas and Corn', 'Day-old rice stir-fried with scrambled eggs, sweet peas, corn, and a savory splash of soy sauce for a fast and satisfying meal.', 'dinner', 'Stir-Fry', 'ultra_budget', ARRAY['asian-inspired','budget','dairy-free','kid-friendly','nut-free','one-pan','quick','stir-fry','vegetarian']::text[], '["3 cups cooked white rice", "4 eggs", "1 cup frozen peas", "1 cup frozen corn", "3 tbsp soy sauce", "1 onion", "2 cloves garlic", "2 tbsp vegetable oil", "1 tsp sesame oil", "pepper"]'::jsonb, '["Heat vegetable oil in a large skillet or wok over high heat.", "Saut\u00e9 diced onion and garlic 2 minutes.", "Add frozen peas and corn; stir-fry 2 minutes until heated through.", "Push vegetables to the side; scramble eggs in the empty space until just set.", "Add rice and soy sauce; toss everything together over high heat 3 minutes.", "Finish with sesame oil and pepper; serve hot."]'::jsonb, 4, 5, 12, 0.95, 3.8, 330, 13, 52, 8, 4, 690, true, true, true, 'curated'),
  ('Spinach and Ricotta Stuffed Shells', 'Jumbo pasta shells filled with creamy ricotta and wilted spinach, baked under a blanket of marinara and melted mozzarella.', 'dinner', 'Italian', 'budget', ARRAY['baked','budget','comfort-food','high-protein','italian','kid-friendly','nut-free','soy-free','vegetarian']::text[], '["12 oz jumbo pasta shells", "15 oz ricotta cheese", "2 cups frozen spinach", "2 cups marinara sauce", "1 cup shredded mozzarella cheese", "1 egg", "2 cloves garlic", "1 tsp dried basil", "0.5 tsp dried oregano", "salt", "pepper"]'::jsonb, '["Preheat oven to 375\u00b0F. Cook shells in salted boiling water until al dente; drain and cool.", "Thaw and squeeze spinach dry; mix with ricotta, egg, garlic, basil, oregano, salt, and pepper.", "Spread half the marinara in a 9x13 baking dish.", "Fill each shell with the ricotta mixture and arrange in the dish.", "Top with remaining marinara and shredded mozzarella.", "Cover with foil and bake 25 minutes; uncover and bake 10 more minutes until bubbly."]'::jsonb, 4, 20, 35, 2.6, 10.4, 460, 24, 55, 15, 5, 740, true, true, true, 'curated'),
  ('Chickpea and Potato Curry', 'Hearty chickpeas and golden potatoes slow-simmered in a fragrant tomato-coconut curry sauce served over steamed basmati rice.', 'dinner', 'Indian', 'budget', ARRAY['budget','comfort-food','egg-free','gluten-free','high-fiber','indian','kid-friendly','nut-free','one-pot','soy-free','vegetarian']::text[], '["2 cans chickpeas", "3 medium potatoes", "1 can coconut milk", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp ginger", "2 tbsp curry powder", "1 tsp cumin", "2 tbsp vegetable oil", "2 cups basmati rice", "salt"]'::jsonb, '["Peel and cube potatoes; cook rice according to package instructions.", "Heat oil in a large pot; saut\u00e9 onion 5 minutes until golden.", "Add garlic, ginger, curry powder, and cumin; cook 1 minute until fragrant.", "Add diced tomatoes and cook 3 minutes, stirring occasionally.", "Add chickpeas, potatoes, and coconut milk; bring to a simmer.", "Cook 20 minutes until potatoes are tender; season with salt and serve over rice."]'::jsonb, 6, 15, 30, 1.8, 10.8, 450, 14, 72, 11, 10, 540, true, true, true, 'curated'),
  ('Classic Veggie Quesadillas', 'Flour tortillas stuffed with sautéed bell peppers, onions, and melted cheddar cheese, pan-crisped until golden and irresistible.', 'lunch', 'Mexican', 'ultra_budget', ARRAY['budget','egg-free','kid-favorite','kid-friendly','mexican','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["6 large flour tortillas", "2 cups shredded cheddar cheese", "1 red bell pepper", "1 green bell pepper", "1 onion", "1 tbsp olive oil", "1 tsp cumin", "salt", "pepper", "0.5 cup sour cream"]'::jsonb, '["Slice bell peppers and onion into thin strips.", "Heat olive oil in a skillet; saut\u00e9 peppers and onion with cumin, salt, and pepper for 6 minutes.", "Remove vegetables and wipe skillet clean.", "Place a tortilla in the skillet over medium heat; sprinkle cheese on half, add some vegetables, fold over.", "Cook 2 minutes per side until golden and cheese is melted.", "Repeat with remaining tortillas; cut into wedges and serve with sour cream."]'::jsonb, 3, 10, 15, 1.3, 3.9, 380, 16, 40, 18, 3, 580, true, true, true, 'curated'),
  ('Caprese Grilled Cheese', 'Thick-sliced bread layered with fresh mozzarella, ripe tomato, and a drizzle of balsamic glaze, pan-grilled to golden perfection.', 'lunch', 'American', 'budget', ARRAY['budget','comfort-food','egg-free','italian-inspired','kid-friendly','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["8 slices bread", "8 oz fresh mozzarella", "2 tomatoes", "2 tbsp balsamic glaze", "2 tbsp butter", "1 tsp dried basil", "salt", "pepper"]'::jsonb, '["Slice mozzarella and tomatoes into thin rounds.", "Layer mozzarella and tomato slices on 4 bread slices; sprinkle with basil, salt, and pepper.", "Drizzle balsamic glaze over the filling; top with remaining bread slices.", "Butter the outsides of each sandwich.", "Cook in a skillet over medium heat 3-4 minutes per side until bread is golden and cheese melts.", "Slice diagonally and serve immediately."]'::jsonb, 4, 5, 10, 2.1, 8.4, 360, 17, 34, 17, 2, 530, true, true, true, 'curated'),
  ('Shakshuka with Crusty Bread', 'Eggs poached directly in a spiced tomato and pepper sauce and served alongside warm bread for a vibrant, satisfying meal.', 'lunch', 'Middle Eastern', 'ultra_budget', ARRAY['budget','dairy-free','eggs','middle-eastern','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["6 eggs", "1 can crushed tomatoes", "1 red bell pepper", "1 onion", "3 cloves garlic", "2 tbsp olive oil", "1 tsp cumin", "1 tsp paprika", "0.5 tsp cayenne pepper", "salt", "pepper", "4 slices crusty bread", "2 tbsp fresh parsley"]'::jsonb, '["Heat olive oil in a large skillet; saut\u00e9 diced onion and bell pepper 5 minutes.", "Add garlic, cumin, paprika, and cayenne; cook 1 minute.", "Pour in crushed tomatoes; season with salt and pepper and simmer 10 minutes.", "Make 6 wells in the sauce and crack an egg into each.", "Cover and cook 6-8 minutes until whites are set but yolks are still runny.", "Garnish with parsley and serve with bread for dipping."]'::jsonb, 3, 10, 20, 1.2, 3.6, 300, 17, 28, 13, 4, 560, false, true, true, 'curated'),
  ('Roasted Vegetable Buddha Bowl', 'A hearty bowl of roasted sweet potato, zucchini, and chickpeas over brown rice drizzled with tahini-lemon dressing.', 'lunch', 'Bowl', 'budget', ARRAY['bowl','budget','dairy-free','egg-free','gluten-free','high-fiber','meal-prep','nut-free','sheet-pan','soy-free','vegan','vegetarian']::text[], '["2 sweet potatoes", "2 zucchini", "1 can chickpeas", "2 cups brown rice", "3 tbsp tahini", "1 lemon", "2 cloves garlic", "3 tbsp olive oil", "1 tsp cumin", "1 tsp paprika", "salt", "pepper", "2 tbsp water"]'::jsonb, '["Preheat oven to 425\u00b0F. Cube sweet potatoes and slice zucchini; toss with 2 tbsp olive oil, cumin, paprika, salt, and pepper.", "Drain and pat dry chickpeas; toss with remaining olive oil and a pinch of salt.", "Spread vegetables and chickpeas on a sheet pan; roast 25 minutes until golden.", "Cook brown rice according to package directions.", "Whisk tahini, lemon juice, minced garlic, water, salt, and pepper into a smooth dressing.", "Assemble bowls with rice, roasted vegetables, chickpeas, and tahini dressing."]'::jsonb, 4, 15, 30, 2.4, 9.6, 480, 14, 70, 16, 10, 420, false, true, true, 'curated'),
  ('Korean-Style Bibimbap', 'Steamed rice topped with seasoned sautéed vegetables, a fried egg, and spicy-sweet gochujang sauce in a classic Korean rice bowl.', 'dinner', 'Korean', 'budget', ARRAY['bowl','budget','dairy-free','eggs','korean','nut-free','one-pan','vegetarian']::text[], '["2 cups white rice", "4 eggs", "2 cups spinach", "2 carrots", "1 zucchini", "1 cup bean sprouts", "3 tbsp soy sauce", "2 tbsp gochujang", "1 tbsp sesame oil", "1 tbsp honey", "2 cloves garlic", "2 tbsp vegetable oil", "1 tbsp sesame seeds"]'::jsonb, '["Cook rice according to package instructions; keep warm.", "Julienne carrots and zucchini; saut\u00e9 each vegetable separately in a little oil with garlic and soy sauce for 3 minutes, then set aside.", "Briefly saut\u00e9 spinach and bean sprouts with a splash of soy sauce.", "Fry eggs sunny-side up in remaining oil.", "Mix gochujang, honey, and sesame oil into a sauce.", "Assemble bowls with rice, arranged vegetables, a fried egg on top, a drizzle of sauce, and sesame seeds."]'::jsonb, 4, 20, 20, 1.9, 7.6, 420, 16, 62, 12, 5, 720, false, true, true, 'curated'),
  ('Veggie Sloppy Joes', 'Lentils and diced mushrooms cooked in a tangy, slightly sweet tomato sauce and piled onto soft sandwich rolls for a messy, crowd-pleasing dinner.', 'dinner', 'American', 'ultra_budget', ARRAY['american','budget','comfort-food','dairy-free','egg-free','gluten-free','high-fiber','kid-favorite','kid-friendly','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["1 cup green lentils", "8 oz mushrooms", "1 can tomato sauce", "2 tbsp tomato paste", "1 onion", "1 green bell pepper", "2 cloves garlic", "2 tbsp vegetable oil", "1 tbsp Worcestershire sauce", "1 tbsp brown sugar", "1 tsp chili powder", "1 tsp mustard", "4 sandwich rolls", "salt", "pepper"]'::jsonb, '["Cook lentils in 2 cups water until tender, about 20 minutes; drain and set aside.", "Dice mushrooms, onion, and bell pepper; saut\u00e9 in oil over medium heat for 8 minutes.", "Add garlic, chili powder, salt, and pepper; cook 1 minute.", "Stir in tomato sauce, tomato paste, Worcestershire, brown sugar, and mustard.", "Add cooked lentils and simmer 10 minutes until thick.", "Spoon onto buns and serve."]'::jsonb, 4, 10, 35, 1.3, 5.2, 370, 18, 60, 6, 13, 680, true, true, true, 'curated'),
  ('Greek Lemon Orzo with Feta', 'Tender orzo pasta tossed with cherry tomatoes, Kalamata olives, crumbled feta, spinach, and bright lemon in a simple one-pot dish.', 'lunch', 'Greek', 'budget', ARRAY['budget','egg-free','greek','mediterranean','nut-free','one-pot','quick','soy-free','vegetarian']::text[], '["1.5 cups orzo pasta", "1 cup cherry tomatoes", "0.5 cup Kalamata olives", "4 oz crumbled feta cheese", "2 cups baby spinach", "1 lemon", "2 cloves garlic", "2 tbsp olive oil", "3 cups vegetable broth", "1 tsp dried oregano", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large skillet; saut\u00e9 garlic 1 minute.", "Add orzo and toast lightly for 2 minutes.", "Pour in vegetable broth and bring to a boil; reduce heat and simmer 10 minutes until orzo is tender and liquid mostly absorbed.", "Stir in cherry tomatoes, olives, and spinach; cook 2 minutes until spinach wilts.", "Remove from heat; squeeze in lemon juice and sprinkle with oregano.", "Top with crumbled feta and serve warm or at room temperature."]'::jsonb, 4, 10, 15, 2.3, 9.2, 380, 13, 50, 14, 3, 680, false, true, true, 'curated'),
  ('Cheesy Broccoli Rice Casserole', 'Fluffy rice and tender broccoli baked together in a creamy cheddar cheese sauce until bubbling and golden on top.', 'dinner', 'American', 'budget', ARRAY['american','baked','budget','comfort-food','egg-free','gluten-free','kid-favorite','kid-friendly','nut-free','one-dish','soy-free','vegetarian']::text[], '["2 cups white rice", "4 cups broccoli florets", "2 cups shredded cheddar cheese", "1 can cream of mushroom soup", "1 cup milk", "1 onion", "2 tbsp butter", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 350\u00b0F. Cook rice according to package instructions.", "Steam broccoli until just tender, about 5 minutes.", "Dice and saut\u00e9 onion in butter 4 minutes until soft.", "Whisk together cream of mushroom soup, milk, garlic powder, salt, pepper, and half the cheese.", "Combine rice, broccoli, onion, and sauce in a greased 9x13 baking dish.", "Top with remaining cheese and bake 25 minutes until bubbly and golden."]'::jsonb, 6, 15, 30, 1.7, 10.2, 410, 15, 52, 16, 3, 620, true, true, true, 'curated'),
  ('Spiced Moroccan Chickpea Stew', 'Chickpeas and diced butternut squash braised in a warmly spiced tomato sauce with cinnamon, cumin, and ginger over fluffy couscous.', 'dinner', 'Moroccan', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','high-fiber','moroccan','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["2 cans chickpeas", "1 small butternut squash", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp ginger", "2 tbsp olive oil", "1 tsp cumin", "1 tsp cinnamon", "1 tsp turmeric", "1 tsp paprika", "2 cups couscous", "salt", "pepper", "2 tbsp fresh cilantro"]'::jsonb, '["Peel and cube butternut squash; cook couscous according to package instructions.", "Heat olive oil in a large pot; saut\u00e9 onion 5 minutes until golden.", "Add garlic, ginger, cumin, cinnamon, turmeric, and paprika; stir 1 minute.", "Add diced tomatoes and cook 3 minutes.", "Add chickpeas, squash, and 1 cup water; bring to a simmer.", "Cook 20 minutes until squash is tender; season with salt and pepper, garnish with cilantro, and serve over couscous."]'::jsonb, 4, 15, 30, 2.0, 8.0, 460, 16, 78, 8, 12, 500, false, true, true, 'curated'),
  ('Baked Margherita Flatbread Pizzas', 'Crispy store-bought flatbreads topped with crushed tomatoes, fresh mozzarella, and dried basil and baked until the cheese is melted and golden.', 'lunch', 'Italian', 'budget', ARRAY['baked','budget','egg-free','gluten-free','italian','kid-favorite','kid-friendly','nut-free','quick','soy-free','vegetarian']::text[], '["4 flatbreads", "1 can crushed tomatoes", "8 oz fresh mozzarella", "2 tbsp olive oil", "1 tsp dried basil", "1 tsp dried oregano", "0.5 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F.", "Mix crushed tomatoes with garlic powder, dried oregano, salt, and pepper.", "Place flatbreads on a baking sheet; brush edges with olive oil.", "Spread tomato sauce evenly over each flatbread.", "Tear mozzarella and distribute over the sauce; sprinkle with dried basil.", "Bake 12-14 minutes until cheese is melted and edges are golden."]'::jsonb, 4, 10, 14, 2.5, 10.0, 380, 18, 42, 15, 2, 640, true, true, true, 'curated'),
  ('Sweet Potato and Black Bean Burrito Bowl', 'Roasted cubed sweet potatoes and seasoned black beans served over cilantro-lime rice with avocado, salsa, and a dollop of sour cream.', 'lunch', 'Mexican', 'budget', ARRAY['bowl','budget','egg-free','gluten-free','high-fiber','kid-friendly','meal-prep','mexican','nut-free','soy-free','vegetarian']::text[], '["2 sweet potatoes", "2 cans black beans", "2 cups white rice", "1 avocado", "0.5 cup salsa", "0.5 cup sour cream", "2 limes", "2 tbsp fresh cilantro", "2 tbsp olive oil", "1 tsp cumin", "1 tsp chili powder", "salt"]'::jsonb, '["Preheat oven to 425\u00b0F. Cube sweet potatoes, toss with olive oil, cumin, chili powder, and salt; roast 25 minutes.", "Cook rice; fluff with lime juice and chopped cilantro for cilantro-lime rice.", "Heat drained black beans in a small pot with a pinch of cumin and salt.", "Slice avocado.", "Build bowls starting with rice, then sweet potatoes and black beans.", "Top with avocado slices, salsa, and sour cream."]'::jsonb, 4, 10, 30, 2.3, 9.2, 500, 15, 80, 13, 14, 560, true, true, true, 'curated'),
  ('Vegetable Fried Noodles', 'Chewy lo mein noodles stir-fried with a rainbow of crunchy vegetables in a savory garlic-soy sauce for a takeout-style dinner at home.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian-inspired','budget','dairy-free','egg-free','kid-friendly','nut-free','one-pan','quick','stir-fry','vegan','vegetarian']::text[], '["8 oz lo mein noodles", "2 cups shredded cabbage", "1 carrot", "1 red bell pepper", "2 cups bean sprouts", "3 cloves garlic", "3 tbsp soy sauce", "1 tbsp hoisin sauce", "1 tsp sesame oil", "2 tbsp vegetable oil", "1 tsp sugar", "pepper"]'::jsonb, '["Cook noodles according to package instructions; drain and toss with a little oil to prevent sticking.", "Julienne carrot and bell pepper; shred cabbage.", "Heat vegetable oil in a large wok over high heat; saut\u00e9 garlic 30 seconds.", "Add harder vegetables (carrot, bell pepper, cabbage) and stir-fry 3 minutes.", "Add noodles, soy sauce, hoisin sauce, sugar, and pepper; toss vigorously 2 minutes.", "Add bean sprouts and sesame oil; toss 1 more minute and serve hot."]'::jsonb, 4, 15, 15, 1.8, 7.2, 360, 10, 60, 8, 5, 820, true, true, true, 'curated'),
  ('Huevos Rancheros', 'Fried eggs resting on warm corn tortillas smothered in homemade ranchero tomato sauce and topped with crumbled cotija cheese.', 'lunch', 'Mexican', 'ultra_budget', ARRAY['budget','eggs','gluten-free','mexican','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["6 eggs", "6 corn tortillas", "1 can diced tomatoes", "1 jalape\u00f1o", "1 onion", "2 cloves garlic", "2 tbsp olive oil", "0.5 tsp cumin", "0.5 tsp chili powder", "2 oz cotija cheese", "salt", "pepper", "2 tbsp fresh cilantro"]'::jsonb, '["Saut\u00e9 diced onion and jalape\u00f1o in 1 tbsp olive oil 4 minutes until softened.", "Add garlic, cumin, and chili powder; cook 1 minute.", "Add diced tomatoes, salt, and pepper; simmer 10 minutes until sauce thickens.", "Warm corn tortillas in a dry skillet or over an open flame.", "Fry eggs in remaining olive oil to desired doneness.", "Place tortillas on plates, top with sauce and a fried egg; garnish with cotija and cilantro."]'::jsonb, 3, 10, 18, 1.4, 4.2, 310, 16, 30, 14, 4, 520, false, true, true, 'curated'),
  ('Smoky Split Pea Soup', 'A warming, thick split pea soup simmered with carrots, celery, and smoked paprika into a deeply comforting and filling bowl.', 'dinner', 'Soup', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','meal-prep','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["1.5 cups green split peas", "2 carrots", "2 stalks celery", "1 onion", "3 cloves garlic", "2 tbsp olive oil", "1 tsp smoked paprika", "1 tsp cumin", "1 tsp dried thyme", "4 cups vegetable broth", "2 cups water", "salt", "pepper"]'::jsonb, '["Rinse split peas under cold water.", "Heat olive oil in a large pot; saut\u00e9 diced onion, carrots, and celery 6 minutes.", "Add garlic, smoked paprika, cumin, and thyme; cook 1 minute.", "Add split peas, vegetable broth, and water; bring to a boil.", "Reduce heat and simmer 45 minutes, stirring occasionally, until peas are very soft.", "Season with salt and pepper; serve as-is or blend partially for a smoother texture."]'::jsonb, 6, 10, 50, 0.8, 4.8, 250, 14, 40, 5, 15, 440, true, true, true, 'curated'),
  ('Pesto Tortellini with Roasted Cherry Tomatoes', 'Cheese tortellini tossed with vibrant basil pesto and burst oven-roasted cherry tomatoes for a quick, impressive pasta dinner.', 'dinner', 'Italian', 'budget', ARRAY['budget','egg-free','high-protein','italian','kid-favorite','kid-friendly','nut-free','one-pan','pasta','quick','soy-free','vegetarian']::text[], '["18 oz cheese tortellini", "2 cups cherry tomatoes", "0.5 cup basil pesto", "0.5 cup grated parmesan cheese", "2 tbsp olive oil", "3 cloves garlic", "salt", "pepper", "1 tsp dried basil"]'::jsonb, '["Preheat oven to 425\u00b0F. Toss cherry tomatoes with olive oil, garlic, salt, and pepper; roast 15 minutes until blistered.", "Cook tortellini in salted boiling water according to package directions; reserve 0.5 cup pasta water.", "Drain tortellini and return to pot over low heat.", "Add pesto and a splash of pasta water; toss to coat.", "Fold in roasted tomatoes with their juices.", "Serve topped with parmesan and dried basil."]'::jsonb, 4, 10, 20, 2.8, 11.2, 490, 20, 58, 20, 4, 720, true, true, true, 'curated'),
  ('Mujaddara (Lebanese Lentils and Rice)', 'A beloved Lebanese dish of spiced lentils and rice topped with a generous pile of deeply caramelized onions and a dollop of yogurt.', 'dinner', 'Middle Eastern', 'ultra_budget', ARRAY['budget','egg-free','gluten-free','high-fiber','middle-eastern','nut-free','one-pot','soy-free','vegetarian']::text[], '["1 cup green lentils", "1 cup white rice", "3 large onions", "4 tbsp olive oil", "1 tsp cumin", "1 tsp allspice", "0.5 tsp cinnamon", "salt", "pepper", "1 cup plain yogurt", "3.5 cups water"]'::jsonb, '["Rinse lentils; simmer in 2 cups water for 15 minutes until partially cooked; drain.", "While lentils cook, thinly slice onions and cook in olive oil over medium-low heat, stirring often, for 30 minutes until deeply caramelized.", "Reserve half the onions; add cumin, allspice, and cinnamon to the pot with remaining onions.", "Add partially cooked lentils and rinsed rice to the pot with 2 cups water; season with salt and pepper.", "Bring to a boil, cover tightly, reduce to low, and cook 18 minutes.", "Let rest 5 minutes; serve topped with reserved caramelized onions and yogurt."]'::jsonb, 4, 10, 50, 1.1, 4.4, 410, 16, 65, 10, 11, 310, false, true, true, 'curated'),
  ('Cheesy Spinach and Egg Quesadillas', 'Fluffy scrambled eggs, wilted spinach, and melted Monterey Jack cheese folded into a golden-crisp flour tortilla for a satisfying midday meal.', 'lunch', 'American', 'ultra_budget', ARRAY['budget','eggs','kid-favorite','kid-friendly','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["4 large flour tortillas", "6 eggs", "2 cups baby spinach", "1 cup shredded Monterey Jack cheese", "1 tbsp butter", "2 cloves garlic", "salt", "pepper", "0.5 cup salsa"]'::jsonb, '["Melt butter in a nonstick skillet over medium heat; saut\u00e9 garlic 30 seconds.", "Add spinach and cook until just wilted, about 2 minutes.", "Whisk eggs with salt and pepper; pour over spinach and scramble gently until just set.", "Lay a tortilla in a separate dry skillet over medium heat; sprinkle cheese on half.", "Add a scoop of egg and spinach mixture; fold tortilla over.", "Cook 2 minutes per side until golden; cut into wedges and serve with salsa."]'::jsonb, 4, 5, 12, 1.3, 5.2, 350, 19, 30, 17, 2, 510, true, true, true, 'curated'),
  ('Vegetable Coconut Curry Noodle Soup', 'Silky coconut milk broth with rice noodles, bok choy, shiitake mushrooms, and tofu in a fragrant red curry base.', 'dinner', 'Thai', 'budget', ARRAY['asian-inspired','budget','egg-free','nut-free','one-pot','soup','thai','vegetarian']::text[], '["8 oz rice noodles", "14 oz firm tofu", "1 can coconut milk", "2 cups vegetable broth", "2 cups bok choy", "1 cup shiitake mushrooms", "2 tbsp red curry paste", "2 tbsp soy sauce", "1 tbsp lime juice", "1 tbsp vegetable oil", "2 cloves garlic", "1 tbsp ginger", "1 tsp brown sugar", "2 tbsp fresh cilantro"]'::jsonb, '["Press and cube tofu; cook rice noodles according to package instructions, then drain.", "Heat oil in a large pot; saut\u00e9 garlic and ginger 1 minute until fragrant.", "Add red curry paste and stir-fry 1 minute.", "Pour in coconut milk and vegetable broth; bring to a simmer.", "Add tofu, sliced mushrooms, and soy sauce; simmer 10 minutes.", "Stir in bok choy, lime juice, and brown sugar; cook 2 more minutes; divide noodles into bowls, ladle soup over, and garnish with cilantro."]'::jsonb, 4, 15, 18, 2.6, 10.4, 420, 16, 52, 16, 4, 740, false, true, true, 'curated'),
  ('Black-Eyed Pea and Southern Braising Greens Stew', 'Slow-simmered black-eyed peas and hearty braising greens in a savory tomato broth seasoned with smoked paprika and apple cider vinegar.', 'dinner', 'Southern', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','nut-free','one-pot','soul-food','southern','soy-free','vegan','vegetarian']::text[], '["2 cans black-eyed peas", "1 bunch braising greens", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "2 tbsp olive oil", "1 tsp smoked paprika", "1 tsp cumin", "1 tbsp apple cider vinegar", "2 cups vegetable broth", "salt", "pepper", "red pepper flakes"]'::jsonb, '["Remove braising green stems; stack and slice leaves into thin ribbons.", "Heat olive oil in a large pot; saut\u00e9 diced onion 5 minutes until soft.", "Add garlic, smoked paprika, cumin, and red pepper flakes; cook 1 minute.", "Add diced tomatoes and cook 3 minutes.", "Add black-eyed peas, braising greens, and vegetable broth; bring to a simmer.", "Cook 20 minutes until greens are tender; stir in apple cider vinegar and season with salt and pepper."]'::jsonb, 4, 15, 30, 1.4, 5.6, 290, 14, 42, 7, 12, 580, false, true, true, 'curated'),
  ('Spinach and Feta Scrambled Eggs', 'Fluffy scrambled eggs folded with wilted spinach and crumbled feta cheese for a satisfying morning plate.', 'breakfast', 'Eggs', 'budget', ARRAY['budget','eggs','gluten-free','kid-friendly','mediterranean','nut-free','quick','soy-free','vegetarian']::text[], '["4 eggs", "2 cups fresh spinach", "2 oz feta cheese", "1 tbsp butter", "1 clove garlic", "salt", "pepper"]'::jsonb, '["Whisk eggs with a pinch of salt and pepper in a bowl.", "Melt butter in a skillet over medium heat and saut\u00e9 garlic for 30 seconds.", "Add spinach and cook until wilted, about 1 minute.", "Pour in eggs and gently stir until just set.", "Remove from heat, top with crumbled feta, and serve immediately."]'::jsonb, 2, 5, 8, 1.8, 3.6, 220, 15, 3, 16, 1, 390, true, true, true, 'curated'),
  ('Oatmeal with Brown Sugar and Cinnamon Apples', 'Creamy stovetop oats topped with warm cinnamon-spiced apple slices and a drizzle of brown sugar.', 'breakfast', 'Oatmeal', 'ultra_budget', ARRAY['budget','comfort-food','egg-free','fruit','gluten-free','kid-friendly','nut-free','oats','one-pot','soy-free','vegetarian']::text[], '["2 cups rolled oats", "4 cups water", "2 apples", "2 tbsp brown sugar", "1 tsp cinnamon", "1 tbsp butter", "1 pinch salt"]'::jsonb, '["Bring water and salt to a boil in a medium pot, then stir in oats.", "Cook over medium heat for 5 minutes, stirring occasionally.", "Meanwhile, melt butter in a small pan and add sliced apples, cinnamon, and brown sugar.", "Cook apples for 3-4 minutes until tender.", "Spoon oatmeal into bowls and top with the warm cinnamon apples."]'::jsonb, 4, 5, 10, 0.7, 2.8, 270, 6, 52, 5, 6, 85, true, true, true, 'curated'),
  ('Potato and Egg Breakfast Hash', 'Crispy diced potatoes and peppers pan-fried with eggs for a hearty one-skillet morning meal.', 'breakfast', 'Hash', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','eggs','gluten-free','kid-friendly','nut-free','one-pan','potatoes','soy-free','vegetarian']::text[], '["3 medium potatoes", "4 eggs", "1 bell pepper", "1 onion", "2 tbsp olive oil", "1 tsp paprika", "salt", "pepper"]'::jsonb, '["Dice potatoes into small cubes and microwave for 4 minutes to partially cook.", "Heat oil in a large skillet over medium-high heat.", "Add potatoes, onion, and bell pepper; cook 8-10 minutes until potatoes are golden.", "Season with paprika, salt, and pepper.", "Make wells in the hash and crack in eggs; cover and cook 3-4 minutes until whites are set.", "Serve directly from the skillet."]'::jsonb, 4, 10, 15, 1.1, 4.4, 290, 11, 38, 11, 4, 210, true, true, true, 'curated'),
  ('Ricotta Banana Pancakes', 'Light and creamy pancakes made with ricotta cheese and mashed banana for natural sweetness.', 'breakfast', 'Pancakes', 'budget', ARRAY['budget','comfort-food','eggs','fruit','kid-friendly','nut-free','soy-free','vegetarian','weekend']::text[], '["1 cup ricotta cheese", "2 bananas", "2 eggs", "1 cup all-purpose flour", "1 tbsp sugar", "1 tsp baking powder", "1 tsp vanilla extract", "1 tbsp butter"]'::jsonb, '["Mash bananas in a large bowl, then stir in ricotta, eggs, and vanilla.", "Fold in flour, sugar, and baking powder until just combined.", "Heat a nonstick skillet over medium heat and add a small pat of butter.", "Pour 1/4 cup batter per pancake and cook 2-3 minutes per side until golden.", "Serve warm with maple syrup or fresh fruit."]'::jsonb, 4, 10, 15, 1.6, 6.4, 310, 13, 42, 9, 2, 190, true, true, true, 'curated'),
  ('Cheesy Grits with Soft-Boiled Eggs', 'Stone-ground grits cooked low and slow with sharp cheddar, served alongside perfectly soft-boiled eggs.', 'breakfast', 'Grits', 'ultra_budget', ARRAY['budget','comfort-food','eggs','gluten-free','kid-friendly','nut-free','southern','soy-free','vegetarian']::text[], '["1 cup quick-cooking grits", "4 cups water", "1 cup shredded cheddar cheese", "2 tbsp butter", "4 eggs", "salt", "pepper"]'::jsonb, '["Bring water to a boil in a medium pot with a pinch of salt.", "Whisk in grits, reduce heat, and cook 5-7 minutes, stirring often.", "Meanwhile, bring a small pot of water to a boil and gently add eggs; cook 7 minutes.", "Transfer eggs to ice water, then peel and halve.", "Stir butter and cheddar into grits until melted and creamy.", "Serve grits in bowls topped with soft-boiled egg halves and a crack of pepper."]'::jsonb, 4, 5, 15, 1.2, 4.8, 340, 16, 36, 15, 1, 330, true, true, true, 'curated'),
  ('Yogurt Parfait with Granola and Berries', 'Layers of thick Greek yogurt, crunchy granola, and mixed berries make a colorful no-cook morning treat.', 'breakfast', 'Parfait', 'budget', ARRAY['budget','egg-free','fruit','gluten-free','kid-friendly','layered','no-cook','nut-free','quick','soy-free','vegetarian']::text[], '["2 cups plain Greek yogurt", "1 cup granola", "1 cup mixed frozen berries", "2 tbsp honey"]'::jsonb, '["Thaw frozen berries slightly or leave fully frozen for a chilled parfait.", "Spoon 1/2 cup yogurt into each glass or bowl.", "Add a layer of granola and then a layer of berries.", "Drizzle honey over the top and serve immediately."]'::jsonb, 4, 5, 0, 1.9, 7.6, 250, 12, 38, 5, 3, 90, true, true, true, 'curated'),
  ('Peanut Butter Banana Toast', 'Toasted whole-wheat bread spread with creamy peanut butter and topped with banana slices and a dash of cinnamon.', 'breakfast', 'Toast', 'ultra_budget', ARRAY['budget','comfort-food','egg-free','fruit','kid-friendly','no-cook','quick','soy-free','vegetarian']::text[], '["4 slices whole-wheat bread", "4 tbsp peanut butter", "2 bananas", "1 tsp cinnamon", "1 tsp honey"]'::jsonb, '["Toast bread slices to your preferred level of doneness.", "Spread 1 tablespoon of peanut butter on each slice.", "Slice bananas and layer over the peanut butter.", "Sprinkle with cinnamon and drizzle with honey before serving."]'::jsonb, 4, 5, 3, 0.8, 3.2, 270, 8, 38, 10, 5, 200, true, true, true, 'curated'),
  ('Veggie Loaded Breakfast Burritos', 'Large flour tortillas filled with scrambled eggs, peppers, black beans, and melted cheese for a filling handheld breakfast.', 'breakfast', 'Burrito', 'budget', ARRAY['budget','eggs','high-protein','kid-friendly','mexican','nut-free','one-pan','soy-free','vegetarian']::text[], '["4 large flour tortillas", "6 eggs", "1 can black beans", "1 bell pepper", "1 cup shredded cheddar cheese", "1 tbsp olive oil", "1 tsp cumin", "salt", "pepper"]'::jsonb, '["Dice bell pepper and saut\u00e9 in oil over medium heat for 3 minutes.", "Add drained black beans and cumin; cook 2 more minutes.", "Push veggies to the side, pour in beaten eggs, and scramble together.", "Warm tortillas in a dry skillet, then fill with egg mixture.", "Sprinkle cheese over filling, fold and roll into burritos, and serve."]'::jsonb, 4, 10, 12, 2.0, 8.0, 420, 22, 48, 16, 8, 580, true, true, true, 'curated'),
  ('Cottage Cheese Fruit Bowl', 'Creamy cottage cheese paired with sweet seasonal fruit and a drizzle of honey for an effortless protein-rich morning bowl.', 'breakfast', 'Bowl', 'budget', ARRAY['budget','egg-free','fruit','gluten-free','kid-friendly','no-cook','nut-free','quick','soy-free','vegetarian']::text[], '["2 cups cottage cheese", "1 cup strawberries", "1 banana", "2 tbsp honey", "1 tsp vanilla extract"]'::jsonb, '["Slice strawberries and banana.", "Divide cottage cheese evenly among bowls.", "Arrange fruit on top.", "Stir vanilla into honey and drizzle over each bowl before serving."]'::jsonb, 4, 5, 0, 1.8, 7.2, 180, 14, 24, 3, 2, 310, true, true, true, 'curated'),
  ('Cinnamon French Toast Sticks', 'Thick-cut bread dipped in a vanilla-cinnamon egg custard and pan-fried until golden for a shareable breakfast treat.', 'breakfast', 'French Toast', 'ultra_budget', ARRAY['budget','comfort-food','eggs','kid-friendly','nut-free','quick','soy-free','sweet','vegetarian']::text[], '["6 slices thick bread", "3 eggs", "1/3 cup milk", "1 tsp cinnamon", "1 tsp vanilla extract", "1 tbsp butter", "2 tbsp maple syrup"]'::jsonb, '["Cut each bread slice into 3 sticks.", "Whisk together eggs, milk, cinnamon, and vanilla in a shallow dish.", "Dip bread sticks into egg mixture, letting them soak for a few seconds.", "Melt butter in a nonstick skillet over medium heat.", "Cook sticks 2-3 minutes per side until golden brown.", "Serve with maple syrup for dipping."]'::jsonb, 3, 5, 10, 1.0, 3.0, 280, 9, 36, 9, 1, 240, true, true, true, 'curated'),
  ('Avocado Toast with Everything Bagel Seasoning', 'Crusty toasted bread spread with smashed avocado and finished with everything bagel seasoning for a trendy, simple breakfast.', 'breakfast', 'Toast', 'budget', ARRAY['avocado','budget','dairy-free','egg-free','modern','no-cook','nut-free','quick','soy-free','vegan','vegetarian']::text[], '["4 slices sourdough bread", "2 avocados", "1 tbsp lemon juice", "2 tsp everything bagel seasoning", "salt", "pepper"]'::jsonb, '["Toast bread slices until golden and sturdy.", "Halve and pit avocados; scoop flesh into a bowl.", "Mash avocado with lemon juice, salt, and pepper to desired consistency.", "Spread avocado mixture generously on each toast.", "Sprinkle everything bagel seasoning over the top and serve immediately."]'::jsonb, 4, 5, 3, 2.2, 8.8, 260, 6, 28, 15, 7, 350, false, true, true, 'curated'),
  ('Sweet Potato and Black Bean Enchiladas', 'Corn tortillas stuffed with roasted sweet potato and black beans, smothered in red enchilada sauce and melted cheese.', 'dinner', 'Mexican', 'budget', ARRAY['baked','budget','egg-free','gluten-free','high-fiber','kid-friendly','mexican','nut-free','one-dish','soy-free','vegetarian']::text[], '["8 corn tortillas", "2 medium sweet potatoes", "1 can black beans", "2 cups red enchilada sauce", "1 cup shredded cheddar cheese", "1 tsp cumin", "1 tsp chili powder", "1 tbsp olive oil", "salt"]'::jsonb, '["Preheat oven to 400\u00b0F. Peel and dice sweet potatoes, toss with olive oil, cumin, chili powder, and salt.", "Roast sweet potatoes on a baking sheet for 20 minutes until tender.", "Mix roasted sweet potato with drained black beans.", "Warm tortillas, fill each with the sweet potato mixture, and roll tightly.", "Arrange in a baking dish, pour enchilada sauce over top, and sprinkle with cheese.", "Bake 15 minutes until cheese is melted and bubbly."]'::jsonb, 4, 15, 35, 2.4, 9.6, 410, 16, 62, 11, 12, 620, true, true, true, 'curated'),
  ('Lentil and Vegetable Soup', 'A hearty one-pot soup of red lentils, carrots, celery, and tomatoes simmered with warm spices until thick and comforting.', 'dinner', 'Soup', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','meal-prep','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["1 cup red lentils", "3 carrots", "3 stalks celery", "1 onion", "3 cloves garlic", "1 can diced tomatoes", "6 cups water", "2 tbsp olive oil", "1 tsp cumin", "1 tsp turmeric", "salt", "pepper"]'::jsonb, '["Dice onion, carrots, and celery; mince garlic.", "Heat oil in a large pot over medium heat and saut\u00e9 onion, carrots, and celery for 5 minutes.", "Add garlic, cumin, and turmeric; cook 1 minute.", "Stir in lentils, diced tomatoes, and water; bring to a boil.", "Reduce heat and simmer 25 minutes until lentils are soft.", "Season with salt and pepper and serve with crusty bread."]'::jsonb, 6, 10, 30, 0.9, 5.4, 210, 12, 34, 4, 10, 310, true, true, true, 'curated'),
  ('Caprese Stuffed Portobello Mushrooms', 'Jumbo portobello caps filled with fresh tomato, mozzarella, and basil then roasted until tender and golden.', 'dinner', 'Italian', 'standard', ARRAY['baked','cheese','egg-free','gluten-free','italian','nut-free','sheet-pan','soy-free','vegetarian']::text[], '["4 large portobello mushrooms", "2 cups fresh mozzarella", "2 medium tomatoes", "1/4 cup fresh basil", "2 tbsp olive oil", "1 tbsp balsamic vinegar", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F and line a baking sheet with foil.", "Remove mushroom stems and brush caps with olive oil; season with salt and pepper.", "Place mushrooms gill-side up on baking sheet and roast 10 minutes.", "Slice tomatoes and mozzarella; layer inside mushroom caps.", "Return to oven for 8-10 minutes until cheese melts.", "Drizzle with balsamic vinegar and top with fresh basil before serving."]'::jsonb, 4, 10, 20, 3.8, 15.2, 240, 14, 10, 17, 2, 380, false, true, true, 'curated'),
  ('Vegetable Fried Rice', 'Day-old rice stir-fried with mixed vegetables, soy sauce, sesame oil, and scrambled eggs in a hot wok.', 'dinner', 'Stir-Fry', 'ultra_budget', ARRAY['asian','budget','dairy-free','eggs','kid-friendly','meal-prep','nut-free','one-pan','stir-fry','vegetarian']::text[], '["3 cups cooked white rice", "3 eggs", "1 cup frozen peas and carrots", "1 onion", "3 cloves garlic", "3 tbsp soy sauce", "1 tsp sesame oil", "2 tbsp vegetable oil"]'::jsonb, '["Heat vegetable oil in a large skillet or wok over high heat.", "Add onion and garlic; stir-fry 2 minutes.", "Add frozen peas and carrots and cook 2 minutes.", "Push vegetables to the side, crack in eggs, and scramble until just set.", "Add rice and soy sauce; toss everything together over high heat for 3 minutes.", "Drizzle sesame oil over the top and serve immediately."]'::jsonb, 4, 5, 12, 1.0, 4.0, 320, 11, 52, 8, 3, 610, true, true, true, 'curated'),
  ('Three-Bean Chili', 'A smoky, hearty pot of kidney, black, and pinto beans simmered with tomatoes, peppers, and bold chili spices.', 'dinner', 'Chili', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','meal-prep','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["1 can kidney beans", "1 can black beans", "1 can pinto beans", "1 can diced tomatoes", "1 can tomato sauce", "1 onion", "1 bell pepper", "3 cloves garlic", "2 tbsp olive oil", "2 tsp chili powder", "1 tsp cumin", "1 tsp smoked paprika", "salt", "pepper"]'::jsonb, '["Dice onion and bell pepper; mince garlic.", "Heat oil in a large pot and saut\u00e9 onion and pepper for 5 minutes.", "Add garlic, chili powder, cumin, and paprika; cook 1 minute.", "Add all drained beans, diced tomatoes, and tomato sauce.", "Bring to a boil, reduce heat, and simmer 25 minutes.", "Season with salt and pepper; serve topped with shredded cheese or sour cream if desired."]'::jsonb, 6, 10, 30, 1.3, 7.8, 290, 16, 48, 5, 15, 550, true, true, true, 'curated'),
  ('Shakshuka with Feta', 'Eggs poached directly in a spiced tomato and pepper sauce topped with crumbled feta and fresh herbs.', 'dinner', 'Middle Eastern', 'budget', ARRAY['budget','eggs','gluten-free','middle-eastern','nut-free','one-pan','soy-free','spicy','vegetarian']::text[], '["6 eggs", "2 cans diced tomatoes", "1 onion", "2 bell peppers", "4 cloves garlic", "2 oz feta cheese", "2 tbsp olive oil", "1 tsp cumin", "1 tsp paprika", "1/2 tsp cayenne pepper", "salt", "pepper", "2 tbsp fresh parsley"]'::jsonb, '["Dice onion and peppers; mince garlic.", "Heat oil in a wide skillet over medium heat; cook onion and peppers 6 minutes.", "Add garlic, cumin, paprika, and cayenne; cook 1 minute.", "Pour in tomatoes, season with salt and pepper, and simmer 10 minutes.", "Make 6 wells and crack an egg into each; cover and cook 6-8 minutes until whites are set.", "Top with crumbled feta and parsley; serve with crusty bread."]'::jsonb, 4, 10, 25, 2.1, 8.4, 250, 14, 18, 14, 4, 480, false, true, true, 'curated'),
  ('Broccoli Cheddar Baked Potatoes', 'Fluffy baked russet potatoes loaded with steamed broccoli and rich cheddar cheese sauce.', 'dinner', 'American', 'ultra_budget', ARRAY['baked','budget','cheese','comfort-food','egg-free','gluten-free','kid-friendly','nut-free','one-dish','soy-free','vegetarian']::text[], '["4 large russet potatoes", "2 cups broccoli florets", "1 cup shredded cheddar cheese", "1/2 cup sour cream", "2 tbsp butter", "1/2 cup milk", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F; scrub potatoes, pierce with a fork, and rub with oil and salt.", "Bake potatoes directly on the oven rack for 50-60 minutes until tender.", "Steam broccoli florets until bright green and tender, about 5 minutes.", "In a small saucepan, melt butter, whisk in milk, and add most of the cheddar; stir until smooth.", "Cut potatoes open and fluff the inside with a fork.", "Top each potato with broccoli, pour cheese sauce over, and add a dollop of sour cream."]'::jsonb, 4, 10, 60, 1.5, 6.0, 400, 13, 58, 15, 6, 360, true, true, true, 'curated'),
  ('Black Bean Quesadillas', 'Crispy flour tortillas stuffed with seasoned black beans, melted cheese, and diced peppers for a quick weeknight dinner.', 'dinner', 'Mexican', 'ultra_budget', ARRAY['budget','egg-free','kid-favorite','kid-friendly','mexican','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["4 large flour tortillas", "1 can black beans", "1 cup shredded cheddar cheese", "1 bell pepper", "1 tsp cumin", "1 tsp chili powder", "1 tbsp olive oil", "1 cup salsa"]'::jsonb, '["Drain and rinse black beans; dice bell pepper.", "Mix beans, bell pepper, cumin, and chili powder in a bowl.", "Place a tortilla in a lightly oiled skillet over medium heat.", "Spread bean mixture over half the tortilla, top with cheese, and fold in half.", "Cook 2-3 minutes per side until golden and crispy.", "Cut into wedges and serve with salsa for dipping."]'::jsonb, 4, 5, 12, 1.2, 4.8, 380, 16, 54, 12, 10, 590, true, true, true, 'curated'),
  ('Zucchini and Tomato Frittata', 'An oven-baked Italian egg dish packed with sliced zucchini, cherry tomatoes, and Parmesan cheese.', 'dinner', 'Italian', 'budget', ARRAY['baked','budget','eggs','gluten-free','italian','kid-friendly','nut-free','one-pan','soy-free','vegetarian']::text[], '["8 eggs", "2 medium zucchini", "1 cup cherry tomatoes", "1/2 cup grated Parmesan cheese", "2 cloves garlic", "2 tbsp olive oil", "1/4 cup milk", "salt", "pepper", "1 tsp dried basil"]'::jsonb, '["Preheat oven to 375\u00b0F.", "Slice zucchini and halve cherry tomatoes.", "Heat oil in an oven-safe skillet over medium heat; cook garlic and zucchini for 4 minutes.", "Whisk eggs with milk, Parmesan, basil, salt, and pepper.", "Pour egg mixture over zucchini; press tomatoes into the top.", "Transfer skillet to oven and bake 18-20 minutes until eggs are set in the center."]'::jsonb, 4, 10, 25, 2.3, 9.2, 260, 18, 7, 18, 2, 380, true, true, true, 'curated'),
  ('Spiced Red Lentil Dal', 'A warming Indian-style dal of red lentils cooked down with tomatoes, coconut milk, and fragrant spices.', 'dinner', 'Indian', 'ultra_budget', ARRAY['budget','egg-free','gluten-free','high-fiber','indian','meal-prep','nut-free','one-pot','soy-free','spicy','vegetarian']::text[], '["1 cup red lentils", "1 can diced tomatoes", "1 can coconut milk", "1 onion", "4 cloves garlic", "1 tbsp fresh ginger", "2 cups water", "2 tbsp olive oil", "1 tsp turmeric", "1 tsp garam masala", "1 tsp cumin", "salt", "2 cups white rice"]'::jsonb, '["Cook rice according to package directions.", "Dice onion; mince garlic and ginger.", "Heat oil in a pot over medium heat and saut\u00e9 onion for 5 minutes.", "Add garlic, ginger, turmeric, cumin, and garam masala; cook 2 minutes.", "Add lentils, tomatoes, coconut milk, and water; bring to a boil.", "Reduce heat and simmer 20 minutes, stirring occasionally, until thick; serve over rice."]'::jsonb, 4, 10, 30, 1.5, 6.0, 480, 17, 72, 14, 11, 320, false, true, true, 'curated'),
  ('Cheesy Vegetable Pasta Bake', 'Penne pasta tossed with roasted vegetables and a creamy tomato sauce then baked under a blanket of melted mozzarella.', 'dinner', 'Pasta', 'budget', ARRAY['baked','budget','comfort-food','egg-free','italian','kid-friendly','nut-free','one-dish','pasta','soy-free','vegetarian']::text[], '["12 oz penne pasta", "1 zucchini", "1 bell pepper", "1 cup mushrooms", "2 cups marinara sauce", "1 cup shredded mozzarella cheese", "2 tbsp olive oil", "2 cloves garlic", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F. Cook pasta until just al dente; drain.", "Chop zucchini, bell pepper, and mushrooms; toss with olive oil, garlic, Italian seasoning, salt, and pepper.", "Roast vegetables on a baking sheet for 15 minutes.", "Combine cooked pasta, roasted vegetables, and marinara sauce in a large baking dish.", "Top with shredded mozzarella.", "Bake 20 minutes until cheese is bubbly and golden."]'::jsonb, 6, 15, 35, 2.0, 12.0, 390, 14, 58, 11, 5, 420, true, true, true, 'curated'),
  ('Korean-Style Tofu Stir-Fry', 'Crispy pan-fried tofu tossed with broccoli, carrots, and a sweet-savory gochujang sauce over steamed rice.', 'dinner', 'Stir-Fry', 'budget', ARRAY['budget','dairy-free','egg-free','korean','nut-free','spicy','stir-fry','tofu','vegetarian']::text[], '["1 lb firm tofu", "2 cups broccoli florets", "2 carrots", "3 cloves garlic", "2 tbsp soy sauce", "1 tbsp gochujang", "1 tbsp honey", "1 tsp sesame oil", "2 tbsp vegetable oil", "2 cups white rice", "1 tsp cornstarch"]'::jsonb, '["Press tofu for 10 minutes then cut into cubes.", "Cook rice according to package directions.", "Heat 1 tablespoon oil in a skillet over high heat and pan-fry tofu until golden on all sides; set aside.", "Add remaining oil and stir-fry broccoli and carrots for 4 minutes.", "Mix soy sauce, gochujang, honey, sesame oil, and cornstarch; add to pan with garlic and cook 1 minute.", "Return tofu to pan, toss to coat, and serve over rice."]'::jsonb, 4, 15, 20, 2.6, 10.4, 400, 18, 55, 12, 4, 530, false, true, true, 'curated'),
  ('Roasted Tomato and White Bean Soup', 'Oven-roasted tomatoes and garlic blended with creamy white beans into a velvety, deeply flavored soup.', 'dinner', 'Soup', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','meal-prep','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["2 lbs Roma tomatoes", "2 cans cannellini beans", "6 cloves garlic", "1 onion", "3 cups vegetable broth", "3 tbsp olive oil", "1 tsp dried basil", "1 tsp dried oregano", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F. Halve tomatoes and toss with garlic, onion quarters, 2 tablespoons olive oil, salt, and pepper.", "Roast on a baking sheet for 30 minutes until caramelized.", "Transfer roasted vegetables and their juices to a blender; blend until smooth.", "Pour into a pot over medium heat; add drained beans and vegetable broth.", "Add basil and oregano; simmer 10 minutes.", "Adjust seasoning and serve with crusty bread."]'::jsonb, 6, 10, 40, 1.8, 10.8, 270, 13, 38, 8, 10, 400, true, true, true, 'curated'),
  ('Mujaddara (Lentils and Rice with Caramelized Onions)', 'A beloved Middle Eastern dish of lentils and rice topped with crispy golden caramelized onions and warm spices.', 'dinner', 'Middle Eastern', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','middle-eastern','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["1 cup green lentils", "1 cup long-grain white rice", "3 large onions", "4 cups water", "3 tbsp olive oil", "1 tsp cumin", "1 tsp allspice", "salt", "pepper"]'::jsonb, '["Simmer lentils in 2 cups water for 15 minutes until just tender; drain.", "Meanwhile, thinly slice onions and cook in oil over medium-low heat for 25-30 minutes, stirring often, until deep golden brown.", "Remove half the onions for topping.", "Add rice, lentils, remaining water, cumin, allspice, salt, and pepper to the pot.", "Cover and cook on low heat for 20 minutes until rice is tender.", "Fluff with a fork and serve topped with the reserved crispy onions."]'::jsonb, 6, 10, 50, 0.7, 4.2, 320, 13, 56, 7, 9, 200, true, true, true, 'curated'),
  ('Smoky Chipotle Chicken Tacos', 'Tender shredded chicken simmered in a smoky chipotle sauce and served in warm corn tortillas with fresh toppings.', 'dinner', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','family-friendly','gluten-free','high-protein','kid-friendly','mexican','nut-free','one-pot','soy-free','standard']::text[], '["2 lbs chicken thighs", "1 can chipotle peppers in adobo", "1 onion", "4 cloves garlic", "1 can diced tomatoes", "1 tsp cumin", "1 tsp chili powder", "salt", "pepper", "12 corn tortillas", "1 cup shredded cabbage", "2 tbsp olive oil"]'::jsonb, '["Season chicken thighs with cumin, chili powder, salt, and pepper.", "Heat olive oil in a large pot over medium heat; sear chicken 3 minutes per side.", "Add diced onion, garlic, chipotle peppers, and canned tomatoes; stir to combine.", "Cover and simmer on low heat for 25 minutes until chicken is tender.", "Shred chicken with two forks and stir back into sauce.", "Serve in warmed corn tortillas topped with shredded cabbage."]'::jsonb, 4, 10, 30, 2.75, 11.0, 420, 35, 32, 14, 4, 620, true, true, true, 'curated'),
  ('Hearty Lentil and Sausage Stew', 'A thick, warming stew packed with green lentils, smoked sausage, carrots, and celery in a savory broth.', 'dinner', 'Soup', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb smoked sausage", "2 cups green lentils", "3 carrots", "3 stalks celery", "1 onion", "4 cloves garlic", "1 can diced tomatoes", "6 cups chicken broth", "1 tsp smoked paprika", "1 tsp thyme", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Slice sausage into coins and brown in a large pot with olive oil over medium heat; set aside.", "Saute diced onion, carrots, and celery in the same pot for 5 minutes.", "Add garlic, smoked paprika, and thyme; cook 1 minute until fragrant.", "Stir in rinsed lentils, diced tomatoes, and chicken broth; bring to a boil.", "Return sausage to pot, reduce heat, and simmer 30 minutes until lentils are tender.", "Season with salt and pepper before serving."]'::jsonb, 6, 10, 35, 2.2, 13.2, 390, 28, 38, 13, 10, 780, true, true, true, 'curated'),
  ('Sheet-Pan Turkey Meatballs with Marinara', 'Juicy oven-baked turkey meatballs roasted on a sheet pan and served over spaghetti with a rich tomato marinara.', 'dinner', 'Sheet-Pan', 'budget', ARRAY['budget','high-protein','italian','kid-friendly','nut-free','pasta','sheet-pan','soy-free','standard']::text[], '["1 lb ground turkey", "2 eggs", "1/2 cup breadcrumbs", "1/4 cup grated Parmesan", "4 cloves garlic", "1 tsp Italian seasoning", "1 jar marinara sauce", "12 oz spaghetti", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Preheat oven to 400F and line a sheet pan with foil; drizzle with olive oil.", "Combine ground turkey, eggs, breadcrumbs, Parmesan, minced garlic, Italian seasoning, salt, and pepper; mix until just combined.", "Roll mixture into 1.5-inch meatballs and place on prepared sheet pan.", "Bake 20 minutes until cooked through and lightly browned.", "Cook spaghetti according to package directions; drain.", "Heat marinara sauce and serve meatballs over pasta with sauce."]'::jsonb, 4, 15, 22, 2.9, 11.6, 510, 36, 58, 12, 4, 740, true, true, true, 'curated'),
  ('Slow Cooker Black Bean Chili', 'A rich, deeply flavored chili made with two kinds of beans, ground beef, and bold spices slow-cooked all day.', 'dinner', 'Slow Cooker', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','slow-cooker','soy-free','standard']::text[], '["1 lb ground beef", "2 cans black beans", "1 can kidney beans", "1 can diced tomatoes", "1 can tomato sauce", "1 onion", "3 cloves garlic", "2 tsp chili powder", "1 tsp cumin", "1 tsp smoked paprika", "salt", "pepper"]'::jsonb, '["Brown ground beef in a skillet over medium heat; drain fat.", "Transfer beef to slow cooker with all remaining ingredients.", "Stir well to combine all spices and sauce.", "Cook on low for 6-8 hours or high for 3-4 hours.", "Taste and adjust seasoning before serving.", "Serve with cornbread, shredded cheese, or sour cream as desired."]'::jsonb, 6, 10, 360, 2.1, 12.6, 370, 30, 34, 11, 12, 660, true, true, true, 'curated'),
  ('Garlic Butter Shrimp and Rice', 'Plump shrimp tossed in a garlicky butter sauce served over fluffy white rice with a squeeze of lemon.', 'dinner', 'Stir-Fry', 'budget', ARRAY['budget','egg-free','family-friendly','gluten-free','high-protein','kid-friendly','nut-free','quick','seafood','soy-free','standard']::text[], '["1 lb frozen shrimp", "2 cups white rice", "4 tbsp butter", "5 cloves garlic", "1 lemon", "1 tsp paprika", "2 tbsp fresh parsley", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions; keep warm.", "Thaw shrimp under cold water; pat dry and season with paprika, salt, and pepper.", "Melt butter in a large skillet over medium-high heat.", "Add minced garlic and cook 30 seconds until fragrant.", "Add shrimp and cook 2-3 minutes per side until pink and opaque.", "Squeeze lemon over shrimp, sprinkle parsley, and serve over rice."]'::jsonb, 4, 5, 20, 2.8, 11.2, 390, 31, 44, 10, 1, 540, true, true, true, 'curated'),
  ('Baked Chicken and Rice Casserole', 'A comforting one-dish casserole where chicken thighs bake directly on top of seasoned rice, soaking up all the savory juices.', 'dinner', 'Casserole', 'budget', ARRAY['american','budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soy-free','standard']::text[], '["6 bone-in chicken thighs", "2 cups long-grain white rice", "3 cups chicken broth", "1 onion", "3 cloves garlic", "1 tsp garlic powder", "1 tsp onion powder", "1 tsp paprika", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Preheat oven to 375F.", "Spread uncooked rice and diced onion in a greased 9x13 baking dish.", "Pour chicken broth over rice and stir in minced garlic.", "Rub chicken thighs with olive oil, garlic powder, onion powder, paprika, salt, and pepper.", "Place seasoned chicken on top of the rice mixture.", "Cover tightly with foil and bake 50-55 minutes until rice is tender and chicken is cooked through."]'::jsonb, 6, 10, 55, 2.4, 14.4, 450, 33, 46, 12, 1, 580, true, true, true, 'curated'),
  ('Beef and Broccoli Stir-Fry', 'Tender strips of beef and crisp broccoli florets coated in a savory soy-ginger sauce over steamed rice.', 'dinner', 'Stir-Fry', 'standard', ARRAY['asian','dairy-free','egg-free','high-protein','kid-friendly','nut-free','quick','standard','stir-fry']::text[], '["1 lb flank steak", "4 cups broccoli florets", "3 tbsp soy sauce", "2 tbsp oyster sauce", "1 tbsp cornstarch", "1 tbsp sesame oil", "3 cloves garlic", "1 tsp fresh ginger", "2 tbsp vegetable oil", "2 cups white rice", "1/4 cup beef broth"]'::jsonb, '["Cook rice according to package directions.", "Slice flank steak thinly against the grain; toss with cornstarch, half the soy sauce, and sesame oil.", "Mix remaining soy sauce, oyster sauce, and beef broth for the sauce.", "Heat vegetable oil in a wok over high heat; stir-fry beef 2-3 minutes until browned; remove.", "Add broccoli to the wok and cook 3 minutes; add garlic and ginger and cook 30 seconds.", "Return beef to wok, pour sauce over everything, and toss to coat; serve over rice."]'::jsonb, 4, 15, 20, 3.5, 14.0, 430, 34, 42, 13, 3, 820, true, true, true, 'curated'),
  ('Spiced Turkey and Sweet Potato Skillet', 'Ground turkey cooked with sweet potatoes, black beans, and warm spices all in one skillet for a quick weeknight dinner.', 'dinner', 'Skillet', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','quick','soy-free','standard']::text[], '["1 lb ground turkey", "2 sweet potatoes", "1 can black beans", "1 onion", "3 cloves garlic", "1 tsp cumin", "1 tsp chili powder", "1/2 tsp cinnamon", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Peel and dice sweet potatoes into 1/2-inch cubes.", "Heat olive oil in a large skillet; cook sweet potatoes 8 minutes until softened.", "Add diced onion and cook 3 minutes more; add minced garlic and spices.", "Push vegetables to the side; add ground turkey and cook, breaking it up, until browned.", "Drain and rinse black beans; add to skillet and stir everything together.", "Season with salt and pepper; cook 5 more minutes until heated through."]'::jsonb, 4, 10, 25, 2.6, 10.4, 395, 32, 36, 11, 9, 490, true, true, true, 'curated'),
  ('Classic Egg and Potato Shakshuka', 'Eggs poached in a spiced tomato sauce with tender potatoes and bell peppers, served straight from the skillet.', 'dinner', 'Skillet', 'ultra_budget', ARRAY['budget','dairy-free','gluten-free','middle-eastern','nut-free','one-pot','soy-free','vegetarian','vegetarian-style']::text[], '["6 eggs", "2 potatoes", "1 can crushed tomatoes", "1 bell pepper", "1 onion", "3 cloves garlic", "1 tsp cumin", "1 tsp paprika", "1/4 tsp cayenne", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Peel and dice potatoes; boil 8 minutes until just tender, then drain.", "Heat olive oil in a large oven-safe skillet; saute diced onion and bell pepper 5 minutes.", "Add garlic, cumin, paprika, and cayenne; cook 1 minute.", "Add crushed tomatoes and potatoes; simmer 10 minutes.", "Make 6 wells in the sauce and crack an egg into each well.", "Cover and cook on low 8-10 minutes until egg whites are set but yolks are still runny."]'::jsonb, 3, 10, 28, 1.4, 4.2, 330, 17, 30, 15, 5, 470, false, true, true, 'curated'),
  ('Pinto Bean and Chorizo Burritos', 'Hearty burritos stuffed with spicy chorizo, creamy pinto beans, rice, and melted cheddar wrapped in a large flour tortilla.', 'dinner', 'Mexican', 'budget', ARRAY['budget','egg-free','family-friendly','high-protein','mexican','nut-free','quick','soy-free','vegetarian']::text[], '["12 oz Mexican chorizo", "2 cans pinto beans", "1 cup white rice", "1 cup shredded cheddar cheese", "4 large flour tortillas", "1 onion", "2 cloves garlic", "1 tsp cumin", "salt", "pepper", "2 tbsp vegetable oil"]'::jsonb, '["Cook rice according to package directions.", "Remove chorizo from casing and cook in a skillet over medium heat, breaking it up, until browned.", "Add diced onion and garlic to skillet; cook 3 minutes.", "Drain and add pinto beans; season with cumin, salt, and pepper; cook 5 minutes.", "Warm tortillas in a dry skillet or microwave.", "Fill each tortilla with rice, chorizo-bean mixture, and shredded cheese; fold and serve."]'::jsonb, 4, 5, 25, 2.75, 11.0, 560, 29, 60, 20, 10, 860, false, true, true, 'curated'),
  ('Lemon Herb Baked Cod', 'Flaky cod fillets baked with a bright lemon herb crust and served alongside roasted green beans.', 'dinner', 'Sheet-Pan', 'standard', ARRAY['egg-free','gluten-free','high-protein','kid-friendly','light','nut-free','seafood','sheet-pan','soy-free','standard']::text[], '["4 cod fillets", "1 lb green beans", "2 lemons", "3 tbsp butter", "3 cloves garlic", "1 tsp dried oregano", "1 tsp dried thyme", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Preheat oven to 400F and line a sheet pan with parchment.", "Toss green beans with olive oil, salt, and pepper; arrange on one side of pan.", "Place cod fillets on the other side of the pan.", "Mix melted butter, lemon juice, minced garlic, oregano, and thyme; spoon over cod.", "Top cod with lemon slices and season everything with salt and pepper.", "Bake 18-20 minutes until fish flakes easily with a fork."]'::jsonb, 4, 10, 20, 4.2, 16.8, 280, 36, 8, 12, 3, 380, true, true, true, 'curated'),
  ('Chicken Tikka Masala', 'Creamy, fragrant tomato-based curry loaded with tender chunks of chicken simmered in a bold blend of Indian spices.', 'dinner', 'Indian', 'standard', ARRAY['comfort-food','egg-free','gluten-free','high-protein','indian','nut-free','one-pot','soy-free','standard']::text[], '["1.5 lbs chicken breast", "1 can crushed tomatoes", "1 cup heavy cream", "1 onion", "4 cloves garlic", "1 tbsp fresh ginger", "2 tsp garam masala", "1 tsp cumin", "1 tsp turmeric", "1 tsp paprika", "3 tbsp butter", "2 cups basmati rice", "salt"]'::jsonb, '["Cut chicken into 1-inch cubes; season with half the spices and a pinch of salt.", "Cook chicken in butter over medium-high heat 5-6 minutes until browned; remove.", "In the same pan, saute diced onion 5 minutes; add garlic, ginger, and remaining spices.", "Add crushed tomatoes and simmer 10 minutes.", "Stir in heavy cream and return chicken to pan; simmer 10 more minutes.", "Cook basmati rice and serve curry over rice."]'::jsonb, 4, 15, 30, 3.8, 15.2, 530, 38, 48, 18, 2, 620, false, true, true, 'curated'),
  ('Ground Beef Stuffed Bell Peppers', 'Colorful bell peppers packed with seasoned ground beef, rice, and tomato sauce then baked until tender and bubbling.', 'dinner', 'Casserole', 'budget', ARRAY['american','baked','budget','egg-free','family-friendly','gluten-free','high-protein','kid-friendly','nut-free','soy-free','standard']::text[], '["1 lb ground beef", "6 bell peppers", "1 cup white rice", "1 can diced tomatoes", "1 can tomato sauce", "1 onion", "3 cloves garlic", "1 tsp Italian seasoning", "1 cup shredded mozzarella", "salt", "pepper"]'::jsonb, '["Preheat oven to 375F; cook rice until slightly underdone.", "Cut tops off peppers and remove seeds; place upright in a baking dish.", "Brown ground beef with diced onion and garlic; drain fat.", "Stir in diced tomatoes, half the tomato sauce, rice, Italian seasoning, salt, and pepper.", "Fill each pepper with the meat mixture; pour remaining tomato sauce around peppers.", "Cover with foil and bake 35 minutes; uncover, top with mozzarella, and bake 10 more minutes."]'::jsonb, 6, 15, 50, 2.5, 15.0, 410, 27, 38, 14, 4, 580, true, true, true, 'curated'),
  ('Thai Peanut Noodles with Chicken', 'Savory and slightly spicy noodles coated in a creamy peanut sauce tossed with shredded chicken and crunchy vegetables.', 'dinner', 'Asian', 'budget', ARRAY['asian','budget','egg-free','high-protein','kid-friendly','noodles','standard','thai']::text[], '["1 lb chicken breast", "8 oz spaghetti", "3 tbsp peanut butter", "3 tbsp soy sauce", "1 tbsp honey", "1 tbsp rice vinegar", "1 tsp sesame oil", "2 cloves garlic", "1 tsp fresh ginger", "2 cups shredded cabbage", "2 green onions", "1 tbsp vegetable oil"]'::jsonb, '["Cook chicken breast in simmering water 15 minutes; shred and set aside.", "Cook spaghetti according to package directions; drain and reserve 1/2 cup pasta water.", "Whisk together peanut butter, soy sauce, honey, rice vinegar, sesame oil, garlic, and ginger; thin with pasta water as needed.", "Toss hot noodles with peanut sauce, shredded chicken, and cabbage.", "Garnish with sliced green onions and serve immediately."]'::jsonb, 4, 10, 20, 2.65, 10.6, 470, 35, 50, 14, 4, 720, true, true, true, 'curated'),
  ('Cottage Cheese and Spinach Stuffed Shells', 'Jumbo pasta shells packed with a creamy cottage cheese and spinach filling baked under a blanket of marinara and mozzarella.', 'dinner', 'Italian', 'budget', ARRAY['baked','budget','comfort-food','high-protein','italian','kid-friendly','nut-free','soy-free','vegetarian']::text[], '["12 oz jumbo pasta shells", "2 cups cottage cheese", "2 cups frozen spinach", "2 eggs", "1 cup shredded mozzarella", "1/4 cup grated Parmesan", "1 jar marinara sauce", "2 cloves garlic", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Preheat oven to 375F; cook shells al dente, drain, and let cool.", "Thaw and squeeze dry frozen spinach.", "Mix cottage cheese, spinach, eggs, half the mozzarella, Parmesan, garlic, Italian seasoning, salt, and pepper.", "Spread 1 cup marinara in the bottom of a 9x13 baking dish.", "Fill each shell with cottage cheese mixture and arrange in the dish; pour remaining marinara over top.", "Sprinkle with remaining mozzarella and bake 30 minutes until bubbly."]'::jsonb, 5, 20, 30, 2.3, 11.5, 430, 30, 50, 11, 4, 640, true, true, true, 'curated'),
  ('Cuban-Style Black Beans and Pork', 'Slow-simmered black beans with tender pork shoulder, onions, and a classic sofrito bursting with Cuban flavors.', 'dinner', 'Caribbean', 'budget', ARRAY['budget','caribbean','cuban','dairy-free','egg-free','gluten-free','high-protein','nut-free','one-pot','slow-cook','soy-free','standard']::text[], '["1 lb pork shoulder", "2 cans black beans", "1 onion", "1 green bell pepper", "4 cloves garlic", "1 tsp cumin", "1 tsp oregano", "2 bay leaves", "2 tbsp olive oil", "1 cup chicken broth", "2 cups white rice", "salt", "pepper"]'::jsonb, '["Cut pork shoulder into 1-inch cubes; season with cumin, oregano, salt, and pepper.", "Brown pork in olive oil over medium-high heat; remove and set aside.", "Saute diced onion, bell pepper, and garlic in the same pot 4 minutes.", "Add pork back, pour in chicken broth, add bay leaves and black beans.", "Bring to a boil, then reduce heat and simmer 40 minutes until pork is tender.", "Cook white rice separately and serve beans and pork over rice."]'::jsonb, 4, 10, 50, 2.9, 11.6, 490, 32, 54, 13, 9, 560, false, true, true, 'curated'),
  ('Crispy Baked Fish Sticks with Tartar Sauce', 'Golden, crunchy breadcrumb-coated fish sticks baked in the oven and served with a quick homemade tartar sauce.', 'dinner', 'American', 'budget', ARRAY['american','baked','budget','dairy-free','high-protein','kid-friendly','nut-free','seafood','soy-free','standard']::text[], '["1.5 lbs tilapia fillets", "1 cup breadcrumbs", "1/2 cup flour", "2 eggs", "1 tsp garlic powder", "1 tsp paprika", "3 tbsp mayonnaise", "2 tbsp relish", "1 tbsp lemon juice", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Preheat oven to 425F; line a baking sheet and brush with olive oil.", "Cut tilapia into 1-inch strips; season with salt and pepper.", "Set up three bowls: flour, beaten eggs, and breadcrumbs mixed with garlic powder and paprika.", "Coat each fish strip in flour, then egg, then breadcrumbs; place on baking sheet.", "Bake 18-20 minutes, flipping halfway, until golden and crispy.", "Mix mayonnaise, relish, and lemon juice for tartar sauce; serve alongside fish sticks."]'::jsonb, 4, 15, 20, 2.7, 10.8, 360, 34, 26, 13, 1, 490, true, true, true, 'curated'),
  ('White Chicken Enchiladas', 'Rolled corn tortillas stuffed with shredded chicken and smothered in a creamy green chile white sauce and melted cheese.', 'dinner', 'Mexican', 'standard', ARRAY['baked','egg-free','family-friendly','high-protein','kid-friendly','mexican','nut-free','soy-free','standard']::text[], '["2 lbs chicken breast", "10 corn tortillas", "2 cups shredded Monterey Jack cheese", "1 can green chiles", "2 tbsp butter", "2 tbsp flour", "2 cups chicken broth", "1 cup sour cream", "1 onion", "3 cloves garlic", "salt", "pepper"]'::jsonb, '["Boil chicken breast 15 minutes; shred and mix with diced onion, garlic, half the cheese, and green chiles.", "Preheat oven to 350F; warm tortillas so they roll without cracking.", "Fill each tortilla with chicken mixture, roll up, and place seam-side down in a greased baking dish.", "Melt butter in a saucepan; whisk in flour, then slowly add chicken broth and cook until thickened.", "Remove from heat and stir in sour cream; pour sauce over enchiladas.", "Top with remaining cheese and bake 25-30 minutes until bubbly and golden."]'::jsonb, 5, 20, 35, 3.4, 17.0, 510, 40, 32, 22, 3, 710, true, true, true, 'curated'),
  ('One-Pan Sausage and Vegetable Bake', 'Smoky sliced sausage roasted on a sheet pan with zucchini, bell peppers, and onions in a simple herbed olive oil.', 'dinner', 'Sheet-Pan', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','one-pot','quick','sheet-pan','soy-free','standard']::text[], '["1 lb smoked sausage", "2 zucchini", "2 bell peppers", "1 onion", "3 tbsp olive oil", "1 tsp Italian seasoning", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 400F and line a large sheet pan with foil.", "Slice sausage into coins; cut zucchini, bell peppers, and onion into 1-inch pieces.", "Toss all vegetables and sausage with olive oil, Italian seasoning, garlic powder, salt, and pepper.", "Spread in a single layer on the prepared sheet pan.", "Roast 25-30 minutes, stirring once halfway through, until vegetables are tender and sausage is caramelized.", "Serve as-is or over rice or pasta."]'::jsonb, 4, 10, 30, 2.2, 8.8, 340, 19, 14, 24, 3, 820, true, true, true, 'curated'),
  ('Red Lentil Dal with Naan', 'A silky, warmly spiced Indian red lentil stew simmered with tomatoes and coconut milk, served with warm naan bread.', 'dinner', 'Indian', 'ultra_budget', ARRAY['budget','egg-free','high-protein','indian','nut-free','one-pot','soy-free','vegetarian','vegetarian-style']::text[], '["2 cups red lentils", "1 can coconut milk", "1 can diced tomatoes", "1 onion", "4 cloves garlic", "1 tbsp fresh ginger", "2 tsp curry powder", "1 tsp turmeric", "1 tsp cumin", "2 tbsp vegetable oil", "4 cups vegetable broth", "4 naan breads", "salt"]'::jsonb, '["Rinse lentils under cold water until water runs clear.", "Heat oil in a large pot; saute diced onion 5 minutes until softened.", "Add minced garlic, ginger, curry powder, turmeric, and cumin; cook 1 minute.", "Stir in lentils, diced tomatoes, vegetable broth, and coconut milk.", "Bring to a boil, reduce heat, and simmer 20-25 minutes stirring occasionally until lentils are completely soft.", "Season with salt and serve over rice or with warmed naan bread."]'::jsonb, 4, 5, 30, 1.45, 5.8, 420, 25, 58, 12, 15, 520, false, true, true, 'curated'),
  ('Korean Beef Bulgogi Bowl', 'Marinated beef strips cooked until caramelized and served over steamed rice with cucumber and a drizzle of sesame.', 'dinner', 'Korean', 'standard', ARRAY['asian','dairy-free','egg-free','high-protein','kid-friendly','korean','nut-free','quick','rice-bowl','standard']::text[], '["1 lb ground beef", "2 cups white rice", "3 tbsp soy sauce", "1 tbsp brown sugar", "1 tsp sesame oil", "3 cloves garlic", "1 tsp fresh ginger", "2 green onions", "1 cucumber", "1 tbsp sesame seeds", "2 tbsp vegetable oil"]'::jsonb, '["Cook white rice according to package directions.", "Mix soy sauce, brown sugar, sesame oil, minced garlic, and ginger for marinade.", "Heat vegetable oil in a skillet over medium-high heat; brown ground beef, breaking it up.", "Pour marinade over beef and cook 3-4 minutes until sauce is absorbed.", "Slice cucumber into thin rounds.", "Serve beef over rice topped with cucumber, sliced green onions, and sesame seeds."]'::jsonb, 4, 10, 20, 3.1, 12.4, 480, 28, 50, 16, 2, 700, true, true, true, 'curated'),
  ('Chicken and White Bean Soup', 'A cozy, nourishing soup with tender chicken, creamy white beans, kale, and rosemary simmered in a golden broth.', 'dinner', 'Soup', 'budget', ARRAY['american','budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb chicken breast", "2 cans white beans", "2 cups chopped kale", "1 onion", "3 carrots", "3 stalks celery", "4 cloves garlic", "6 cups chicken broth", "1 tsp rosemary", "1 tsp thyme", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Dice onion, carrots, and celery; heat olive oil in a large pot and saute 5 minutes.", "Add minced garlic, rosemary, and thyme; cook 1 minute.", "Add whole chicken breasts and chicken broth; bring to a boil.", "Reduce heat and simmer 20 minutes; remove chicken, shred, and return to pot.", "Add drained white beans and chopped kale; simmer 10 more minutes.", "Season with salt and pepper; serve with crusty bread."]'::jsonb, 6, 10, 35, 2.1, 12.6, 320, 33, 28, 7, 7, 560, true, true, true, 'curated'),
  ('Baked Salmon with Dill and Asparagus', 'Salmon fillets seasoned with fresh dill and lemon baked alongside asparagus spears for a bright and elegant dinner.', 'dinner', 'Sheet-Pan', 'standard', ARRAY['dairy-free','egg-free','gluten-free','high-protein','light','nut-free','quick','seafood','sheet-pan','soy-free','standard']::text[], '["4 salmon fillets", "1 bunch asparagus", "2 tbsp olive oil", "2 tbsp fresh dill", "2 lemons", "3 cloves garlic", "salt", "pepper"]'::jsonb, '["Preheat oven to 400F and line a sheet pan with parchment.", "Trim asparagus and toss with 1 tbsp olive oil, salt, and pepper on one side of pan.", "Place salmon fillets on the other side; brush with remaining olive oil.", "Mix minced garlic and fresh dill; press onto top of each salmon fillet.", "Layer lemon slices over salmon and asparagus.", "Bake 15-18 minutes until salmon flakes easily and asparagus is tender."]'::jsonb, 4, 8, 18, 4.5, 18.0, 340, 38, 6, 18, 3, 350, false, true, true, 'curated'),
  ('Picadillo-Style Ground Beef Plate', 'Savory Latin-style ground beef cooked with olives, raisins, tomatoes, and spices over white rice with black beans.', 'dinner', 'Latin', 'budget', ARRAY['budget','cuban','dairy-free','egg-free','family-friendly','gluten-free','high-protein','latin','nut-free','one-pot','soy-free','standard']::text[], '["1 lb ground beef", "1 can diced tomatoes", "1 can black beans", "2 cups white rice", "1/2 cup green olives", "1/4 cup raisins", "1 onion", "1 green bell pepper", "3 cloves garlic", "1 tsp cumin", "1 tsp oregano", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Cook white rice according to package directions.", "Brown ground beef in olive oil in a large skillet; drain fat.", "Add diced onion, bell pepper, and garlic; cook 4 minutes.", "Stir in diced tomatoes, cumin, oregano, salt, and pepper; simmer 5 minutes.", "Add olives and raisins; cook 5 more minutes until flavors meld.", "Serve picadillo over rice alongside warmed black beans."]'::jsonb, 4, 10, 25, 2.8, 11.2, 490, 28, 56, 14, 7, 680, false, true, true, 'curated'),
  ('Pasta Fagioli', 'A thick Italian-American pasta and bean soup loaded with ditalini, cannellini beans, tomatoes, and fragrant herbs.', 'dinner', 'Italian', 'ultra_budget', ARRAY['budget','comfort-food','egg-free','italian','kid-friendly','nut-free','one-pot','soup','soy-free','vegetarian']::text[], '["2 cans cannellini beans", "1 cup ditalini pasta", "1 can crushed tomatoes", "1 onion", "3 cloves garlic", "2 stalks celery", "2 carrots", "5 cups vegetable broth", "1 tsp rosemary", "1 tsp thyme", "3 tbsp olive oil", "1/4 cup grated Parmesan", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large pot; saute diced onion, carrots, and celery 6 minutes.", "Add minced garlic, rosemary, and thyme; cook 1 minute.", "Add crushed tomatoes and vegetable broth; bring to a simmer.", "Add cannellini beans and cook 15 minutes.", "Mash about a quarter of the beans to thicken the broth.", "Add ditalini and cook 10 minutes until pasta is tender; season and serve with Parmesan."]'::jsonb, 6, 10, 35, 1.2, 7.2, 310, 16, 48, 7, 10, 540, true, true, true, 'curated'),
  ('Skillet Chicken Fajitas', 'Sizzling strips of seasoned chicken cooked with colorful bell peppers and onions and served in warm flour tortillas.', 'dinner', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','family-friendly','high-protein','kid-friendly','mexican','nut-free','quick','skillet','soy-free','standard']::text[], '["1.5 lbs chicken breast", "3 bell peppers", "1 onion", "3 tbsp olive oil", "2 tsp chili powder", "1 tsp cumin", "1 tsp garlic powder", "1 lime", "8 flour tortillas", "salt", "pepper"]'::jsonb, '["Slice chicken breast, bell peppers, and onion into thin strips.", "Season chicken with chili powder, cumin, garlic powder, salt, and pepper.", "Heat 2 tbsp olive oil in a large cast-iron skillet over high heat.", "Cook chicken strips 5-6 minutes until cooked through; remove from skillet.", "Add remaining oil; cook peppers and onions 5 minutes until softened.", "Return chicken to skillet, squeeze lime over everything, and serve in warmed tortillas."]'::jsonb, 4, 10, 15, 2.9, 11.6, 450, 40, 40, 13, 4, 620, true, true, true, 'curated'),
  ('Turkey Taco Rice Skillet', 'A fast one-pan dinner with ground turkey, taco-seasoned rice, corn, and tomatoes all cooked together and topped with cheese.', 'dinner', 'Skillet', 'budget', ARRAY['budget','egg-free','family-friendly','gluten-free','high-protein','kid-friendly','mexican','nut-free','one-pot','quick','skillet','soy-free','standard']::text[], '["1 lb ground turkey", "1 cup white rice", "1 can diced tomatoes", "1 cup frozen corn", "2 cups chicken broth", "1 onion", "3 cloves garlic", "2 tsp chili powder", "1 tsp cumin", "1 cup shredded cheddar cheese", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large deep skillet over medium-high heat.", "Brown ground turkey with diced onion and garlic; drain any excess fat.", "Stir in chili powder, cumin, salt, and pepper.", "Add uncooked rice, diced tomatoes, corn, and chicken broth; stir well.", "Bring to a boil, reduce heat to low, cover, and cook 20 minutes until rice is tender.", "Top with shredded cheddar, cover for 2 minutes to melt, and serve."]'::jsonb, 4, 5, 28, 2.55, 10.2, 480, 34, 47, 16, 3, 680, true, true, true, 'curated'),
  ('Chicken Sausage and Kale Pasta', 'Hearty pasta tossed with sliced chicken sausage, wilted kale, garlic, and a light Parmesan cream sauce.', 'dinner', 'Italian', 'standard', ARRAY['egg-free','family-friendly','high-protein','italian','nut-free','pasta','quick','soy-free','standard']::text[], '["12 oz penne pasta", "1 pkg chicken sausage", "4 cups chopped kale", "4 cloves garlic", "1/2 cup heavy cream", "1/2 cup grated Parmesan", "1/2 cup chicken broth", "2 tbsp olive oil", "1/2 tsp red pepper flakes", "salt", "pepper"]'::jsonb, '["Cook penne according to package directions; reserve 1/2 cup pasta water, then drain.", "Slice chicken sausage into rounds; brown in olive oil in a large skillet over medium heat.", "Add minced garlic and red pepper flakes; cook 1 minute.", "Add kale and chicken broth; cook 3-4 minutes until kale wilts.", "Stir in heavy cream and Parmesan; bring to a gentle simmer.", "Add drained pasta and toss to coat, adding pasta water as needed to loosen sauce."]'::jsonb, 4, 5, 22, 3.2, 12.8, 530, 29, 56, 20, 4, 750, false, true, true, 'curated'),
  ('Spicy Pork and Cabbage Stir-Fry', 'Ground pork and shredded green cabbage tossed in a bold, garlicky soy and chili sauce over fluffy steamed rice.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','egg-free','high-protein','nut-free','quick','standard','stir-fry']::text[], '["1 lb ground pork", "4 cups shredded green cabbage", "3 tbsp soy sauce", "1 tbsp chili garlic sauce", "1 tbsp rice vinegar", "1 tsp sesame oil", "4 cloves garlic", "1 tsp fresh ginger", "2 green onions", "2 cups white rice", "2 tbsp vegetable oil"]'::jsonb, '["Cook white rice according to package directions.", "Mix soy sauce, chili garlic sauce, rice vinegar, and sesame oil in a small bowl.", "Heat vegetable oil in a large wok or skillet over high heat; brown ground pork, breaking it up.", "Add minced garlic and ginger; cook 1 minute.", "Add shredded cabbage and toss; cook 3-4 minutes until just wilted.", "Pour sauce over pork and cabbage, toss to coat, and serve over rice garnished with green onions."]'::jsonb, 4, 10, 20, 2.3, 9.2, 440, 27, 46, 15, 3, 740, false, true, true, 'curated'),
  ('Smoky Chipotle Chicken Burrito Bowl', 'Tender chipotle-spiced chicken thighs served over cilantro rice with black beans, corn, and a squeeze of lime.', 'lunch', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','mexican','nut-free','one-pot','rice-bowl','soy-free','standard']::text[], '["1.5 lbs chicken thighs", "2 cups white rice", "1 can black beans", "1 cup frozen corn", "1 onion", "3 cloves garlic", "2 tbsp chipotle in adobo", "2 tbsp olive oil", "1 tsp cumin", "1 tsp smoked paprika", "1 lime", "salt", "pepper"]'::jsonb, '["Season chicken thighs with chipotle, cumin, paprika, salt, and pepper.", "Heat olive oil in a skillet over medium-high heat and cook chicken 6-7 minutes per side until cooked through. Rest and slice.", "Cook rice according to package directions; stir in lime juice.", "Warm black beans and corn together in a small saucepan.", "Assemble bowls with rice, beans and corn, then top with sliced chicken."]'::jsonb, 4, 10, 25, 2.75, 11.0, 520, 38, 55, 12, 7, 540, true, true, true, 'curated'),
  ('Lemon Herb Turkey and White Bean Soup', 'A hearty, bright soup of ground turkey, creamy white beans, and fresh herbs in a light lemon broth.', 'lunch', 'Soup', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb ground turkey", "2 cans white beans", "4 cups chicken broth", "1 onion", "3 cloves garlic", "2 stalks celery", "2 carrots", "1 lemon", "1 tsp dried thyme", "1 tsp dried oregano", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large pot; saut\u00e9 onion, celery, and carrots for 5 minutes.", "Add garlic and cook 1 minute more.", "Add ground turkey and cook until browned, breaking it apart.", "Pour in chicken broth, white beans, thyme, and oregano. Simmer 15 minutes.", "Stir in lemon juice, season with salt and pepper, and serve."]'::jsonb, 5, 10, 25, 2.5, 12.5, 390, 32, 30, 10, 8, 620, true, true, true, 'curated'),
  ('Classic Egg Salad Stuffed Pitas', 'Creamy egg salad loaded with mustard, celery, and green onion packed into fluffy pita pockets.', 'lunch', 'Sandwich', 'ultra_budget', ARRAY['budget','budget-friendly','gluten-free','high-protein','kid-friendly','nut-free','quick','sandwich','soy-free','vegetarian']::text[], '["10 eggs", "0.5 cup cottage cheese", "2 tbsp mayonnaise", "1 tbsp yellow mustard", "2 stalks celery", "3 green onions", "4 pita breads", "1 tsp paprika", "salt", "pepper"]'::jsonb, '["Hard-boil eggs for 10 minutes, then cool in ice water and peel.", "Chop eggs and place in a bowl with cottage cheese, mayonnaise, mustard, celery, and green onion.", "Mix well, season with paprika, salt, and pepper.", "Cut pitas in half and fill each pocket with egg salad.", "Serve immediately or refrigerate filling until ready to eat."]'::jsonb, 4, 15, 12, 1.4, 5.6, 390, 27, 31, 14, 2, 510, true, true, true, 'curated'),
  ('Teriyaki Salmon Rice Bowls', 'Flaky baked salmon glazed with a simple teriyaki sauce served over steamed rice with broccoli.', 'lunch', 'Asian', 'standard', ARRAY['asian','dairy-free','egg-free','fish','high-protein','kid-friendly','nut-free','rice-bowl','standard']::text[], '["1.5 lbs salmon fillets", "2 cups white rice", "3 cups broccoli florets", "3 tbsp soy sauce", "2 tbsp brown sugar", "1 tbsp rice vinegar", "2 cloves garlic", "1 tsp sesame oil", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F. Mix soy sauce, brown sugar, vinegar, garlic, and sesame oil for the teriyaki glaze.", "Place salmon on a foil-lined baking sheet, brush with glaze, and bake 12-15 minutes.", "Steam or roast broccoli alongside salmon for the last 10 minutes.", "Cook rice according to package directions.", "Flake salmon over rice, add broccoli, and drizzle with remaining glaze."]'::jsonb, 4, 10, 20, 4.25, 17.0, 490, 40, 48, 13, 3, 680, true, true, true, 'curated'),
  ('Spicy Black Bean and Beef Tacos', 'Seasoned lean ground beef and black beans piled into warm corn tortillas with crunchy cabbage slaw.', 'lunch', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','mexican','nut-free','quick','soy-free','standard','tacos']::text[], '["1 lb lean ground beef", "1 can black beans", "8 corn tortillas", "2 cups shredded cabbage", "1 onion", "2 cloves garlic", "1 tsp cumin", "1 tsp chili powder", "1 tsp smoked paprika", "2 tbsp olive oil", "1 lime", "salt", "pepper"]'::jsonb, '["Heat olive oil in a skillet, saut\u00e9 onion until soft, then add garlic and cook 1 minute.", "Add ground beef and cook until browned; drain excess fat.", "Stir in drained black beans, cumin, chili powder, paprika, salt, and pepper. Cook 3 minutes.", "Warm tortillas in a dry skillet or microwave.", "Fill tortillas with beef mixture and top with cabbage slaw and lime juice."]'::jsonb, 4, 10, 20, 2.9, 11.6, 430, 31, 38, 14, 9, 510, true, true, true, 'curated'),
  ('Greek Chicken Pita Wraps', 'Juicy pan-seared chicken strips seasoned with oregano and garlic wrapped in warm pitas with cucumber and tomato.', 'lunch', 'Mediterranean', 'budget', ARRAY['budget','egg-free','gluten-free','high-protein','kid-friendly','mediterranean','nut-free','quick','soy-free','standard','wrap']::text[], '["1.5 lbs chicken breast", "4 pita breads", "1 cucumber", "2 tomatoes", "1 cup plain Greek yogurt", "3 cloves garlic", "1 lemon", "1 tsp dried oregano", "1 tsp garlic powder", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Slice chicken breast into strips and season with oregano, garlic powder, salt, and pepper.", "Heat olive oil in a skillet over medium-high heat and cook chicken strips 4-5 minutes per side.", "Mix Greek yogurt with minced garlic, lemon juice, and a pinch of salt for a simple tzatziki.", "Dice cucumber and tomatoes.", "Spread tzatziki on warm pitas, add chicken strips, cucumber, and tomato, then roll up."]'::jsonb, 4, 12, 15, 2.8, 11.2, 440, 39, 35, 11, 2, 490, true, true, true, 'curated'),
  ('Red Lentil Coconut Curry', 'Creamy red lentils simmered in coconut milk with warming spices and served over fluffy basmati rice.', 'lunch', 'Indian', 'ultra_budget', ARRAY['budget','egg-free','gluten-free','high-protein','indian','legumes','nut-free','one-pot','soy-free','vegetarian']::text[], '["2 cups red lentils", "1 can coconut milk", "2 cups vegetable broth", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp fresh ginger", "2 cups basmati rice", "1 tsp turmeric", "1 tsp cumin", "1 tsp garam masala", "2 tbsp olive oil", "salt"]'::jsonb, '["Rinse lentils and set aside. Cook basmati rice according to package directions.", "Saut\u00e9 onion in olive oil over medium heat for 5 minutes; add garlic and ginger and cook 2 minutes.", "Stir in turmeric, cumin, and garam masala and cook 1 minute.", "Add lentils, diced tomatoes, broth, and coconut milk; bring to a boil.", "Reduce heat and simmer 20 minutes until lentils are soft. Season with salt and serve over rice."]'::jsonb, 6, 10, 30, 1.5, 9.0, 430, 26, 62, 10, 12, 370, false, true, true, 'curated'),
  ('Buffalo Chicken Lettuce Cups', 'Saucy shredded buffalo chicken served in crisp lettuce cups with blue cheese crumbles and celery.', 'lunch', 'American', 'budget', ARRAY['american','budget','egg-free','gluten-free','high-protein','low-carb','nut-free','quick','soy-free','standard']::text[], '["1.5 lbs chicken breast", "1 head iceberg lettuce", "3 stalks celery", "0.5 cup buffalo sauce", "2 tbsp butter", "0.5 cup blue cheese crumbles", "1 cup chicken broth", "salt", "pepper"]'::jsonb, '["Simmer chicken breast in broth until cooked through, about 15 minutes. Shred with two forks.", "Melt butter in a skillet, add shredded chicken and buffalo sauce, and toss to coat. Cook 3 minutes.", "Separate lettuce leaves to form cups.", "Fill each lettuce cup with buffalo chicken.", "Top with sliced celery and blue cheese crumbles and serve immediately."]'::jsonb, 4, 10, 20, 2.9, 11.6, 310, 38, 5, 14, 1, 920, false, true, true, 'curated'),
  ('Cottage Cheese and Veggie Stuffed Peppers', 'Colorful bell peppers filled with a savory blend of cottage cheese, brown rice, and sautéed vegetables.', 'lunch', 'Comfort Food', 'budget', ARRAY['budget','comfort-food','egg-free','gluten-free','high-protein','kid-friendly','nut-free','soy-free','stuffed','vegetarian','vegetarian-friendly']::text[], '["4 bell peppers", "2 cups cottage cheese", "1 cup brown rice", "1 can diced tomatoes", "1 zucchini", "1 onion", "2 cloves garlic", "1 tsp Italian seasoning", "0.5 cup shredded mozzarella", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Cook brown rice according to package directions. Preheat oven to 375\u00b0F.", "Saut\u00e9 onion, garlic, and zucchini in olive oil until softened, about 5 minutes.", "Mix cooked rice, cottage cheese, diced tomatoes, saut\u00e9ed vegetables, and Italian seasoning.", "Cut tops off peppers and remove seeds. Fill each with the rice mixture.", "Top with mozzarella and bake 30 minutes until peppers are tender and cheese is bubbly."]'::jsonb, 4, 15, 40, 2.5, 10.0, 380, 26, 42, 11, 5, 520, true, true, true, 'curated'),
  ('Thai Peanut Chicken Noodle Bowl', 'Tender chicken and rice noodles tossed in a creamy peanut sauce with shredded carrots and cucumbers.', 'lunch', 'Asian', 'budget', ARRAY['asian','budget','egg-free','high-protein','kid-friendly','noodles','standard','thai']::text[], '["1.5 lbs chicken breast", "8 oz rice noodles", "2 carrots", "1 cucumber", "3 green onions", "3 tbsp peanut butter", "3 tbsp soy sauce", "2 tbsp rice vinegar", "1 tbsp honey", "2 cloves garlic", "1 tsp sesame oil", "salt", "pepper"]'::jsonb, '["Cook rice noodles according to package directions; drain and rinse with cold water.", "Season chicken with salt and pepper and cook in a skillet over medium-high heat, 6 minutes per side. Slice thin.", "Whisk together peanut butter, soy sauce, rice vinegar, honey, garlic, and sesame oil to make the sauce. Thin with water if needed.", "Shred carrots and slice cucumbers into thin strips.", "Toss noodles with peanut sauce, then top with chicken, carrots, cucumber, and green onion."]'::jsonb, 4, 15, 20, 2.8, 11.2, 480, 37, 50, 13, 4, 680, true, true, true, 'curated'),
  ('Hearty Chicken and Chickpea Stew', 'A warming one-pot stew of chicken drumsticks and chickpeas slow-simmered in a spiced tomato broth.', 'lunch', 'Stew', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soy-free','standard','stew']::text[], '["2 lbs chicken drumsticks", "2 cans chickpeas", "1 can diced tomatoes", "2 cups chicken broth", "1 onion", "3 cloves garlic", "2 carrots", "1 tsp smoked paprika", "1 tsp cumin", "1 tsp turmeric", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Season chicken drumsticks with salt, pepper, paprika, and cumin.", "Brown drumsticks in olive oil in a large pot over medium-high heat, 3-4 minutes per side. Remove and set aside.", "Saut\u00e9 onion, garlic, and carrots in the same pot for 5 minutes.", "Add chickpeas, diced tomatoes, broth, turmeric, and browned chicken. Bring to a boil.", "Reduce heat and simmer covered for 30 minutes until chicken is tender. Adjust seasoning."]'::jsonb, 5, 10, 45, 2.6, 13.0, 420, 35, 30, 14, 8, 560, true, true, true, 'curated'),
  ('Beef and Vegetable Fried Rice', 'Savory ground beef stir-fried with day-old rice, peas, carrots, and scrambled egg in a soy-ginger sauce.', 'lunch', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','high-protein','kid-friendly','nut-free','one-pan','rice','standard','stir-fry']::text[], '["1 lb lean ground beef", "3 cups cooked rice", "1 cup frozen peas", "2 carrots", "3 eggs", "3 cloves garlic", "1 tbsp fresh ginger", "3 tbsp soy sauce", "1 tbsp sesame oil", "2 tbsp olive oil", "3 green onions", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large skillet or wok over high heat. Add ground beef and cook until browned; drain excess fat.", "Push beef to one side, add scrambled eggs and cook until set, then mix with beef.", "Add garlic and ginger and cook 1 minute. Add carrots and peas and stir-fry 3 minutes.", "Add rice and soy sauce; toss everything together and cook 3-4 minutes until heated through.", "Drizzle sesame oil over top, garnish with green onions, and serve hot."]'::jsonb, 4, 10, 20, 2.7, 10.8, 460, 30, 45, 15, 4, 700, true, true, true, 'curated'),
  ('Tuna Melt Quesadillas', 'Crispy flour tortillas stuffed with seasoned tuna, melted cheddar, and corn for an easy weekday lunch.', 'lunch', 'American', 'ultra_budget', ARRAY['american','budget','fish','high-protein','kid-friendly','nut-free','quesadilla','quick','soy-free','standard']::text[], '["2 cans tuna in water", "4 flour tortillas", "1 cup shredded cheddar", "0.5 cup frozen corn", "2 tbsp mayonnaise", "1 tbsp lemon juice", "1 tsp garlic powder", "2 green onions", "salt", "pepper"]'::jsonb, '["Drain tuna and mix with mayonnaise, lemon juice, garlic powder, green onions, corn, salt, and pepper.", "Spread tuna mixture on half of each tortilla and top with shredded cheddar.", "Fold tortillas in half.", "Cook in a dry skillet over medium heat 2-3 minutes per side until golden and cheese is melted.", "Cut into wedges and serve with salsa or hot sauce."]'::jsonb, 4, 8, 10, 1.4, 5.6, 370, 28, 30, 14, 2, 610, true, true, true, 'curated'),
  ('Moroccan Spiced Lentil Bowls', 'Earthy green lentils simmered with Moroccan spices and served over couscous with roasted carrots.', 'lunch', 'Moroccan', 'ultra_budget', ARRAY['budget','budget-friendly','dairy-free','egg-free','high-protein','legumes','moroccan','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["2 cups green lentils", "2 cups couscous", "3 carrots", "1 onion", "3 cloves garlic", "1 can diced tomatoes", "3 cups vegetable broth", "1 tsp cumin", "1 tsp coriander", "0.5 tsp cinnamon", "1 tsp smoked paprika", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F. Toss carrots with olive oil, salt, and pepper; roast 20 minutes.", "Saut\u00e9 onion in olive oil until soft; add garlic and spices and cook 2 minutes.", "Add lentils, diced tomatoes, and broth. Bring to a boil then simmer 25 minutes until lentils are tender.", "Prepare couscous: pour 2 cups boiling water over couscous, cover, and let sit 5 minutes. Fluff with a fork.", "Serve lentils over couscous with roasted carrots on the side."]'::jsonb, 6, 10, 35, 1.1, 6.6, 400, 25, 65, 6, 14, 380, false, true, true, 'curated'),
  ('Korean-Style Beef Lettuce Wraps', 'Savory ground beef cooked with gochujang and sesame wrapped in cool crisp butter lettuce leaves.', 'lunch', 'Korean', 'budget', ARRAY['asian','budget','egg-free','high-protein','korean','low-carb','nut-free','quick','standard']::text[], '["1.5 lbs lean ground beef", "1 head butter lettuce", "3 cloves garlic", "1 tbsp fresh ginger", "3 tbsp soy sauce", "1 tbsp gochujang", "1 tbsp brown sugar", "1 tsp sesame oil", "1 tbsp rice vinegar", "3 green onions", "1 tbsp olive oil", "sesame seeds"]'::jsonb, '["Brown ground beef in olive oil over medium-high heat, breaking it up as it cooks. Drain fat.", "Add garlic and ginger to the beef and cook 1 minute.", "Stir in soy sauce, gochujang, brown sugar, rice vinegar, and sesame oil. Cook 3 minutes.", "Separate butter lettuce leaves into cups.", "Spoon beef mixture into lettuce cups, top with green onions and sesame seeds."]'::jsonb, 4, 10, 15, 2.85, 11.4, 370, 34, 10, 20, 1, 710, false, true, true, 'curated'),
  ('Creamy White Chicken Chili', 'Thick and satisfying chicken chili with white beans, green chiles, and a splash of cream stirred in at the end.', 'lunch', 'Chili', 'budget', ARRAY['budget','chili','comfort-food','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soy-free','standard']::text[], '["1.5 lbs chicken breast", "2 cans white beans", "1 can green chiles", "3 cups chicken broth", "1 onion", "3 cloves garlic", "0.5 cup sour cream", "1 tsp cumin", "1 tsp garlic powder", "1 tsp oregano", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large pot; saut\u00e9 onion until softened, about 5 minutes. Add garlic and cook 1 minute.", "Add chicken breast, white beans, green chiles, broth, cumin, garlic powder, and oregano.", "Bring to a boil, then reduce heat and simmer 20 minutes until chicken is cooked through.", "Remove chicken, shred with two forks, and return to the pot.", "Stir in sour cream, season with salt and pepper, and simmer 5 more minutes before serving."]'::jsonb, 5, 10, 30, 2.4, 12.0, 380, 36, 28, 12, 7, 590, true, true, true, 'curated'),
  ('Sheet-Pan Sausage and Pepper Heroes', 'Roasted Italian chicken sausage with sweet peppers and onions piled into crusty hoagie rolls.', 'lunch', 'Sheet-Pan', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','italian','kid-friendly','nut-free','sandwich','sheet-pan','soy-free','standard']::text[], '["1 lb Italian chicken sausage links", "3 bell peppers", "2 onions", "4 hoagie rolls", "3 cloves garlic", "2 tbsp olive oil", "1 tsp Italian seasoning", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F. Slice peppers and onions into strips.", "Toss peppers and onions with olive oil, garlic powder, Italian seasoning, salt, and pepper on a sheet pan.", "Add sausage links to the pan and roast 25-30 minutes, flipping halfway through, until sausages are browned and vegetables are tender.", "Slice sausages and return to the pan to absorb the juices.", "Fill hoagie rolls with sausages and roasted peppers and onions."]'::jsonb, 4, 10, 30, 2.7, 10.8, 450, 27, 42, 17, 3, 830, true, true, true, 'curated'),
  ('Spinach and Feta Egg Muffin Cups', 'Portable baked egg cups packed with wilted spinach, feta cheese, and sun-dried tomatoes for a protein-rich lunch.', 'lunch', 'Mediterranean', 'budget', ARRAY['budget','gluten-free','high-protein','meal-prep','mediterranean','nut-free','quick','soy-free','vegetarian']::text[], '["10 eggs", "1 cup cottage cheese", "2 cups fresh spinach", "0.5 cup feta cheese", "0.25 cup sun-dried tomatoes", "2 cloves garlic", "1 tbsp olive oil", "1 tsp dried oregano", "salt", "pepper"]'::jsonb, '["Preheat oven to 375\u00b0F. Grease a 12-cup muffin tin with olive oil.", "Saut\u00e9 spinach and garlic in olive oil until wilted, about 2 minutes. Chop roughly.", "Whisk eggs with cottage cheese, oregano, salt, and pepper until smooth.", "Distribute spinach, feta, and sun-dried tomatoes evenly among muffin cups.", "Pour egg mixture into each cup and bake 18-20 minutes until set. Cool slightly before removing."]'::jsonb, 4, 10, 22, 2.2, 8.8, 320, 28, 8, 19, 1, 510, false, true, true, 'curated'),
  ('Black Bean Turkey Tostadas', 'Crispy baked tostada shells layered with seasoned turkey, refried-style black beans, and fresh pico de gallo.', 'lunch', 'Mexican', 'budget', ARRAY['bean','budget','egg-free','gluten-free','high-protein','kid-friendly','mexican','nut-free','quick','soy-free','standard']::text[], '["1 lb ground turkey", "1 can black beans", "6 corn tortillas", "2 tomatoes", "1 onion", "2 cloves garlic", "1 lime", "1 tsp cumin", "1 tsp chili powder", "0.5 cup shredded cheddar", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F. Brush tortillas with olive oil and bake 8-10 minutes until crispy.", "Saut\u00e9 onion and garlic in olive oil; add turkey and cook until browned. Season with cumin, chili powder, salt, and pepper.", "Drain and lightly mash black beans in a small saucepan over low heat with a pinch of salt.", "Dice tomatoes and mix with remaining onion, lime juice, and salt for pico de gallo.", "Spread mashed beans on each tostada, top with turkey, cheddar, and pico de gallo."]'::jsonb, 4, 12, 20, 2.65, 10.6, 420, 32, 36, 14, 8, 520, true, true, true, 'curated'),
  ('Chickpea and Spinach Power Soup', 'A thick, nourishing soup of chickpeas and spinach cooked in garlicky tomato broth with Parmesan.', 'lunch', 'Soup', 'budget', ARRAY['budget','egg-free','gluten-free','high-protein','italian','kid-friendly','legumes','nut-free','one-pot','soup','soy-free','standard']::text[], '["3 cans chickpeas", "4 cups fresh spinach", "1 can diced tomatoes", "4 cups chicken broth", "4 cloves garlic", "1 onion", "1 lb Italian chicken sausage", "0.5 cup grated Parmesan", "1 tsp Italian seasoning", "0.5 tsp red pepper flakes", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Slice chicken sausage and brown in olive oil in a large pot over medium-high heat, 4-5 minutes. Remove and set aside.", "In the same pot saut\u00e9 onion until soft; add garlic and red pepper flakes and cook 1 minute.", "Add chickpeas, diced tomatoes, broth, Italian seasoning, and sausage. Bring to a boil.", "Reduce heat and simmer 15 minutes. Use a potato masher to lightly crush some chickpeas to thicken the soup.", "Stir in spinach and cook until wilted, about 2 minutes. Ladle into bowls and top with Parmesan."]'::jsonb, 5, 8, 28, 2.8, 14.0, 420, 30, 38, 16, 10, 750, true, true, true, 'curated'),
  ('Grilled Chicken Caesar Wraps', 'Classic Caesar-dressed grilled chicken and crisp romaine rolled up tightly in large flour tortillas.', 'lunch', 'American', 'budget', ARRAY['american','budget','egg-free','high-protein','kid-friendly','nut-free','quick','soy-free','standard','wrap']::text[], '["1.5 lbs chicken breast", "4 large flour tortillas", "4 cups romaine lettuce", "0.5 cup grated Parmesan", "3 tbsp Caesar dressing", "1 lemon", "1 tsp garlic powder", "1 tsp onion powder", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Season chicken with garlic powder, onion powder, salt, and pepper.", "Heat olive oil in a grill pan or skillet and cook chicken 6-7 minutes per side until cooked through. Rest 5 minutes then slice.", "Chop romaine and toss with Caesar dressing and Parmesan.", "Warm tortillas in the microwave for 20 seconds.", "Layer sliced chicken and Caesar salad on each tortilla, roll tightly, slice in half, and serve."]'::jsonb, 4, 10, 18, 2.9, 11.6, 450, 40, 32, 16, 2, 620, true, true, true, 'curated'),
  ('Cajun Shrimp and Corn Chowder', 'A rich and smoky chowder packed with Cajun-spiced shrimp, sweet corn, and creamy potatoes.', 'lunch', 'Soup', 'standard', ARRAY['cajun','comfort-food','egg-free','gluten-free','high-protein','nut-free','seafood','soup','soy-free','standard']::text[], '["1 lb shrimp peeled and deveined", "2 cups frozen corn", "3 potatoes", "1 onion", "3 cloves garlic", "3 stalks celery", "2 cups chicken broth", "1 cup milk", "2 tbsp butter", "1 tsp Cajun seasoning", "0.5 tsp smoked paprika", "salt", "pepper"]'::jsonb, '["Dice potatoes and boil in salted water for 10 minutes until just tender. Drain and set aside.", "Melt butter in a large pot; saut\u00e9 onion, celery, and garlic for 5 minutes.", "Add corn, potatoes, broth, Cajun seasoning, and paprika. Simmer 10 minutes.", "Stir in milk and bring to a gentle simmer. Add shrimp and cook 3-4 minutes until pink.", "Adjust seasoning with salt and pepper and serve hot."]'::jsonb, 4, 12, 28, 3.9, 15.6, 370, 28, 42, 10, 4, 730, false, true, true, 'curated'),
  ('Slow Cooker Pulled Chicken Sandwiches', 'Melt-in-your-mouth slow cooker pulled chicken tossed in tangy barbecue sauce piled onto soft buns.', 'lunch', 'American', 'budget', ARRAY['american','budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','sandwich','slow-cooker','soy-free','standard']::text[], '["2 lbs chicken breast", "1 cup barbecue sauce", "0.5 cup chicken broth", "1 onion", "3 cloves garlic", "1 tbsp apple cider vinegar", "1 tsp smoked paprika", "1 tsp garlic powder", "6 hamburger buns", "salt", "pepper"]'::jsonb, '["Place chicken breast in the slow cooker with onion, garlic, broth, paprika, garlic powder, salt, and pepper.", "Cook on low for 6 hours or high for 3 hours until chicken is tender.", "Shred chicken with two forks directly in the slow cooker.", "Stir in barbecue sauce and apple cider vinegar. Cook on high 15 more minutes.", "Pile pulled chicken onto buns and serve."]'::jsonb, 6, 8, 360, 2.5, 15.0, 400, 35, 38, 8, 2, 650, true, true, true, 'curated'),
  ('Spiced Lamb and Rice Stuffed Cabbage Rolls', 'Tender cabbage leaves rolled around a fragrant mixture of ground lamb, rice, and warm spices in tomato sauce.', 'lunch', 'Middle Eastern', 'standard', ARRAY['comfort-food','dairy-free','egg-free','gluten-free','high-protein','middle-eastern','nut-free','soy-free','standard','stuffed']::text[], '["1 lb ground lamb", "1 head green cabbage", "1 cup white rice", "1 can crushed tomatoes", "1 onion", "3 cloves garlic", "1 tsp allspice", "1 tsp cinnamon", "1 tsp cumin", "2 tbsp olive oil", "1 cup water", "salt", "pepper"]'::jsonb, '["Par-cook rice to just under done, about 10 minutes. Preheat oven to 375\u00b0F.", "Blanch whole cabbage leaves in boiling water for 3 minutes until pliable. Drain and cool.", "Mix lamb with par-cooked rice, half the onion (grated), allspice, cinnamon, cumin, salt, and pepper.", "Place 2 tablespoons of filling in the center of each cabbage leaf and roll up tightly.", "Arrange rolls seam-side down in a baking dish. Mix crushed tomatoes with water, garlic, and olive oil; pour over rolls. Cover tightly and bake 45 minutes."]'::jsonb, 5, 20, 55, 4.2, 21.0, 430, 26, 38, 18, 4, 430, false, true, true, 'curated'),
  ('Quick Chicken Tikka Masala with Naan', 'Chunks of chicken breast simmered in a creamy tomato-spiced tikka masala sauce served with warm naan bread.', 'lunch', 'Indian', 'budget', ARRAY['budget','comfort-food','egg-free','high-protein','indian','kid-friendly','nut-free','one-pan','soy-free','standard']::text[], '["1.5 lbs chicken breast", "1 can crushed tomatoes", "0.5 cup plain Greek yogurt", "1 onion", "3 cloves garlic", "1 tbsp fresh ginger", "2 tbsp garam masala", "1 tsp turmeric", "1 tsp cumin", "0.5 cup heavy cream", "2 tbsp olive oil", "4 naan breads", "salt"]'::jsonb, '["Cut chicken into bite-sized cubes and marinate in yogurt, half the garam masala, turmeric, and salt for 10 minutes.", "Cook chicken in olive oil over medium-high heat until lightly browned; remove and set aside.", "Saut\u00e9 onion in the same pan until golden; add garlic, ginger, and remaining spices. Cook 2 minutes.", "Stir in crushed tomatoes; simmer 10 minutes. Add cream and return chicken to the pan.", "Simmer 10 minutes until sauce thickens. Warm naan and serve alongside."]'::jsonb, 4, 15, 30, 2.95, 11.8, 500, 40, 40, 18, 3, 580, true, true, true, 'curated'),
  ('Hearty Split Pea and Ham Soup', 'A thick, old-fashioned split pea soup with chunks of smoky ham and tender carrots that simmers into pure comfort.', 'lunch', 'Soup', 'ultra_budget', ARRAY['budget','budget-friendly','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["2 cups dried split peas", "1 lb ham steak", "6 cups chicken broth", "3 carrots", "3 stalks celery", "1 onion", "3 cloves garlic", "1 tsp thyme", "1 bay leaf", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Rinse split peas and set aside. Dice ham steak into bite-sized cubes.", "Saut\u00e9 onion, celery, and carrots in olive oil in a large pot for 5 minutes. Add garlic and cook 1 minute.", "Add split peas, ham, broth, thyme, and bay leaf. Bring to a boil.", "Reduce heat and simmer uncovered for 45-50 minutes, stirring occasionally, until peas have completely broken down and soup thickens.", "Remove bay leaf, adjust seasoning, and serve hot."]'::jsonb, 6, 10, 55, 1.4, 8.4, 360, 30, 42, 7, 13, 720, true, true, true, 'curated'),
  ('Honey Garlic Chicken Rice Casserole', 'Tender chicken thighs and fluffy rice baked together in a sticky honey-garlic sauce in a single pan.', 'lunch', 'Casserole', 'budget', ARRAY['budget','casserole','comfort-food','dairy-free','egg-free','high-protein','kid-friendly','nut-free','one-pot','sheet-pan','standard']::text[], '["1.5 lbs chicken thighs", "1.5 cups long grain white rice", "3 cups chicken broth", "4 cloves garlic", "3 tbsp honey", "3 tbsp soy sauce", "1 tbsp rice vinegar", "2 tbsp olive oil", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 375\u00b0F. Whisk honey, soy sauce, minced garlic, and rice vinegar together.", "Spread uncooked rice in the bottom of a 9x13 baking dish. Pour broth over the rice.", "Season chicken thighs with garlic powder, salt, and pepper. Nestle them skin-side up over the rice.", "Brush honey garlic sauce generously over each chicken thigh.", "Cover tightly with foil and bake 40 minutes; uncover and bake 15 more minutes until chicken is golden."]'::jsonb, 4, 10, 55, 2.75, 11.0, 490, 35, 55, 12, 1, 680, true, true, true, 'curated'),
  ('Cajun Chicken and Sausage Jambalaya', 'A deeply flavored one-pot Cajun classic with chicken, andouille sausage, rice, and the holy trinity of vegetables.', 'lunch', 'Cajun', 'budget', ARRAY['budget','cajun','comfort-food','dairy-free','egg-free','gluten-free','high-protein','nut-free','one-pot','rice','soy-free','standard']::text[], '["1 lb chicken thighs", "0.5 lb andouille sausage", "2 cups long grain white rice", "1 can diced tomatoes", "3 cups chicken broth", "1 onion", "1 green bell pepper", "3 stalks celery", "3 cloves garlic", "2 tsp Cajun seasoning", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Cut chicken into bite-sized pieces. Season with Cajun seasoning, salt, and pepper.", "Brown chicken in olive oil in a large Dutch oven; remove and set aside. Slice sausage and brown in the same pot.", "Saut\u00e9 onion, bell pepper, celery, and garlic in the drippings for 5 minutes.", "Add rice and stir 2 minutes to toast. Add chicken, sausage, diced tomatoes, and broth.", "Bring to a boil, reduce heat to low, cover, and cook 25 minutes until rice is cooked and liquid is absorbed."]'::jsonb, 6, 15, 45, 2.8, 16.8, 470, 30, 48, 15, 3, 760, false, true, true, 'curated'),
  ('Skillet Chorizo and Egg Scramble', 'Spicy chorizo crumbles folded into fluffy scrambled eggs with sauteed peppers and onions.', 'breakfast', 'Skillet', 'budget', ARRAY['budget','dairy-free','gluten-free','high-protein','kid-friendly','mexican','nut-free','one-pot','quick','soy-free','standard']::text[], '["6 oz chorizo sausage", "6 eggs", "1 bell pepper", "1 onion", "2 cloves garlic", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Heat olive oil in a skillet over medium heat. Add chorizo and cook, breaking it up, for 4 minutes.", "Add diced onion, bell pepper, and garlic. Cook until softened, about 3 minutes.", "Whisk eggs with salt and pepper, pour into skillet.", "Stir gently until eggs are just set. Serve immediately."]'::jsonb, 3, 5, 10, 2.1, 6.3, 370, 28, 6, 27, 1, 620, true, true, true, 'curated'),
  ('Greek Yogurt Parfait with Honey and Granola', 'Thick, creamy yogurt layered with crunchy oat granola and a drizzle of golden honey.', 'breakfast', 'No-Cook', 'budget', ARRAY['budget','egg-free','gluten-free','high-protein','kid-friendly','mediterranean','no-cook','nut-free','quick','soy-free','vegetarian']::text[], '["2 cups plain Greek yogurt", "1 cup granola", "2 tbsp honey", "1 cup frozen mixed berries, thawed"]'::jsonb, '["Divide Greek yogurt evenly between two bowls or glasses.", "Top each with granola and thawed berries.", "Drizzle honey over each parfait and serve."]'::jsonb, 2, 5, 0, 2.4, 4.8, 380, 26, 52, 6, 3, 110, true, true, true, 'curated'),
  ('Black Bean and Egg Breakfast Burritos', 'Scrambled eggs, seasoned black beans, and melted cheddar wrapped in warm flour tortillas.', 'breakfast', 'Mexican', 'ultra_budget', ARRAY['budget','budget-friendly','high-protein','kid-friendly','mexican','nut-free','one-pan','soy-free','vegetarian']::text[], '["1 can black beans, drained", "6 eggs", "4 flour tortillas", "1 cup shredded cheddar cheese", "1 tsp cumin", "1 tsp chili powder", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Warm black beans in a small saucepan with cumin, chili powder, salt, and pepper.", "Whisk eggs and scramble in olive oil over medium heat until fluffy.", "Warm tortillas in a dry skillet or microwave.", "Layer beans, eggs, and cheese on each tortilla, roll up, and serve."]'::jsonb, 4, 5, 10, 1.3, 5.2, 400, 25, 44, 15, 8, 540, true, true, true, 'curated'),
  ('Cottage Cheese Pancakes with Maple Syrup', 'Fluffy protein-rich pancakes made with cottage cheese and oats, served with warm maple syrup.', 'breakfast', 'American', 'budget', ARRAY['american','budget','gluten-free','high-protein','kid-friendly','nut-free','one-pan','soy-free','vegetarian']::text[], '["1 cup cottage cheese", "1 cup rolled oats", "2 eggs", "1 tsp vanilla extract", "1 tsp baking powder", "2 tbsp maple syrup", "1 tbsp butter"]'::jsonb, '["Blend cottage cheese, oats, eggs, vanilla, and baking powder in a blender until smooth.", "Heat butter in a nonstick skillet over medium heat.", "Pour small rounds of batter into skillet and cook 2-3 minutes per side until golden.", "Serve with maple syrup drizzled on top."]'::jsonb, 3, 5, 15, 1.8, 5.4, 310, 25, 35, 8, 3, 320, true, true, true, 'curated'),
  ('Turkey Sausage and Spinach Egg Muffins', 'Savory baked egg cups packed with turkey sausage, fresh spinach, and melted mozzarella.', 'breakfast', 'Baked', 'budget', ARRAY['american','baked','budget','gluten-free','high-protein','kid-friendly','meal-prep','nut-free','soy-free','standard']::text[], '["8 oz turkey breakfast sausage", "8 eggs", "2 cups fresh spinach, chopped", "1 cup shredded mozzarella cheese", "1 tsp garlic powder", "salt", "pepper", "cooking spray"]'::jsonb, '["Preheat oven to 375 degrees F. Spray a 12-cup muffin tin with cooking spray.", "Cook turkey sausage in a skillet, breaking it up, until browned. Drain fat.", "Whisk eggs with garlic powder, salt, and pepper. Stir in sausage and spinach.", "Pour mixture evenly into muffin cups. Top each with shredded mozzarella.", "Bake 18-20 minutes until eggs are set. Let cool slightly before removing."]'::jsonb, 6, 10, 20, 2.2, 13.2, 240, 27, 2, 14, 0, 480, true, true, true, 'curated'),
  ('Lentil and Veggie Hash with Poached Eggs', 'A hearty skillet of tender green lentils, roasted potatoes, and crispy vegetables topped with runny poached eggs.', 'breakfast', 'Skillet', 'ultra_budget', ARRAY['budget','budget-friendly','dairy-free','gluten-free','hearty','high-protein','nut-free','one-pan','soy-free','vegetarian']::text[], '["1 cup green lentils", "2 medium potatoes, diced", "1 onion, diced", "1 bell pepper, diced", "4 eggs", "2 cloves garlic", "1 tsp smoked paprika", "1 tbsp olive oil", "salt", "pepper", "2 cups water"]'::jsonb, '["Cook lentils in 2 cups water until tender, about 20 minutes. Drain and set aside.", "Heat olive oil in a large skillet. Add potatoes and cook 8 minutes until browned.", "Add onion, bell pepper, and garlic. Cook 4 minutes more. Stir in lentils and paprika.", "Make four wells in the hash. Crack an egg into each well.", "Cover and cook 4-5 minutes until egg whites are set but yolks are still runny. Season and serve."]'::jsonb, 4, 10, 35, 1.2, 4.8, 340, 25, 48, 7, 12, 210, false, true, true, 'curated'),
  ('Chicken Apple Sausage Breakfast Bowl', 'Savory chicken apple sausage slices served over seasoned sweet potato cubes with sauteed kale.', 'breakfast', 'Bowl', 'standard', ARRAY['american','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','meal-prep','nut-free','one-pan','soy-free','standard']::text[], '["1 pkg chicken apple sausage links", "2 medium sweet potatoes, diced", "2 cups kale, chopped", "1 onion, diced", "2 tbsp olive oil", "1 tsp garlic powder", "1 tsp cinnamon", "salt", "pepper"]'::jsonb, '["Preheat oven to 400 degrees F. Toss sweet potatoes with 1 tbsp olive oil, garlic powder, cinnamon, salt, and pepper. Roast 25 minutes.", "Slice sausage and brown in a skillet over medium heat, 4-5 minutes.", "Add remaining olive oil to the same skillet, saute onion and kale until wilted.", "Divide sweet potatoes into bowls, top with kale mixture and sausage slices."]'::jsonb, 4, 10, 30, 3.5, 14.0, 390, 26, 38, 14, 5, 570, true, true, true, 'curated'),
  ('Salmon and Cream Cheese Egg Scramble', 'Silky scrambled eggs with flaked canned salmon and creamy cream cheese folded in at the end.', 'breakfast', 'Skillet', 'budget', ARRAY['american','budget','gluten-free','high-protein','nut-free','quick','seafood','soy-free','standard']::text[], '["1 can salmon, drained", "6 eggs", "2 oz cream cheese, cubed", "2 green onions, sliced", "1 tbsp butter", "salt", "pepper"]'::jsonb, '["Whisk eggs with salt and pepper in a bowl.", "Melt butter in a nonstick skillet over low-medium heat.", "Add eggs and stir slowly with a spatula. When mostly set, fold in salmon and cream cheese.", "Cook until cheese melts and eggs are just cooked. Top with green onions and serve."]'::jsonb, 3, 5, 8, 2.6, 7.8, 310, 32, 2, 19, 0, 490, false, true, true, 'curated'),
  ('Huevos Rancheros with Refried Beans', 'Fried eggs nestled on crispy corn tortillas smothered in warm salsa and creamy refried beans.', 'breakfast', 'Mexican', 'ultra_budget', ARRAY['budget','budget-friendly','gluten-free','high-protein','kid-friendly','mexican','nut-free','one-pan','soy-free','vegetarian']::text[], '["1 can refried beans", "8 eggs", "8 corn tortillas", "1 cup salsa", "1 cup shredded cheddar cheese", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Warm refried beans in a small saucepan over low heat.", "Heat olive oil in a large skillet. Fry eggs two at a time to desired doneness. Season with salt and pepper.", "Warm tortillas in a dry skillet until pliable.", "Spread refried beans on two tortillas per serving, top each with a fried egg.", "Spoon salsa over eggs and sprinkle with cheddar cheese. Serve immediately."]'::jsonb, 4, 5, 15, 1.4, 5.6, 450, 28, 48, 17, 9, 700, true, true, true, 'curated'),
  ('Spicy Turkey and Sweet Potato Breakfast Skillet', 'Seasoned ground turkey crumbled with diced sweet potato, black beans, and a kick of sriracha.', 'breakfast', 'Skillet', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','meal-prep','nut-free','one-pan','soy-free','standard']::text[], '["1 lb ground turkey", "2 medium sweet potatoes, diced small", "1 can black beans, drained", "1 onion, diced", "2 cloves garlic", "1 tbsp sriracha", "1 tsp cumin", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large skillet. Add sweet potatoes and cook 8-10 minutes until tender.", "Push sweet potatoes to the side, add turkey and cook, breaking it apart, until browned.", "Add onion and garlic and cook 3 minutes. Stir in black beans, cumin, sriracha, salt, and pepper.", "Mix everything together and cook 2 more minutes until heated through. Serve hot."]'::jsonb, 4, 10, 20, 2.5, 10.0, 400, 36, 36, 9, 9, 460, false, true, true, 'curated'),
  ('Ham and Cheddar Breakfast Casserole', 'A crowd-pleasing baked casserole layered with cubed bread, diced ham, eggs, and melted cheddar.', 'breakfast', 'Baked', 'budget', ARRAY['american','baked','budget','high-protein','kid-friendly','meal-prep','nut-free','soy-free','standard']::text[], '["8 oz diced ham", "8 eggs", "4 cups bread, cubed", "2 cups shredded cheddar cheese", "1 cup milk", "1 tsp garlic powder", "1 tsp onion powder", "salt", "pepper", "cooking spray"]'::jsonb, '["Preheat oven to 350 degrees F. Spray a 9x13 baking dish with cooking spray.", "Layer bread cubes in the dish. Scatter ham and 1.5 cups cheddar over top.", "Whisk eggs, milk, garlic powder, onion powder, salt, and pepper. Pour evenly over bread mixture.", "Sprinkle remaining cheddar on top. Bake 40-45 minutes until puffed and golden."]'::jsonb, 6, 10, 45, 2.3, 13.8, 430, 32, 28, 21, 1, 780, true, true, true, 'curated'),
  ('Cottage Cheese and Egg White Veggie Scramble', 'Protein-loaded egg whites scrambled with creamy cottage cheese, diced tomatoes, and baby spinach.', 'breakfast', 'Skillet', 'budget', ARRAY['american','budget','gluten-free','high-protein','kid-friendly','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["1 cup cottage cheese", "6 egg whites", "2 eggs", "1 cup baby spinach", "1 tomato, diced", "2 green onions, sliced", "1 tsp garlic powder", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Whisk egg whites, whole eggs, garlic powder, salt, and pepper together.", "Heat olive oil in a nonstick skillet over medium heat. Add tomato and cook 1 minute.", "Pour in egg mixture and stir gently, folding in cottage cheese as eggs begin to set.", "Add spinach and green onions. Cook until spinach wilts and eggs are fully set. Serve immediately."]'::jsonb, 3, 5, 8, 1.9, 5.7, 220, 28, 6, 9, 1, 390, true, true, true, 'curated'),
  ('Ground Turkey and Egg Breakfast Fried Rice', 'Day-old rice stir-fried with seasoned ground turkey, scrambled eggs, and peas in savory soy sauce.', 'breakfast', 'Asian', 'budget', ARRAY['asian','budget','dairy-free','high-protein','kid-friendly','meal-prep','nut-free','one-pan','standard']::text[], '["8 oz ground turkey", "3 cups cooked rice, cold", "3 eggs", "1 cup frozen peas, thawed", "3 green onions, sliced", "3 cloves garlic, minced", "3 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large skillet or wok over high heat. Add turkey and cook until browned, breaking it apart.", "Push turkey to one side, crack in eggs, and scramble on the other side of the pan.", "Add rice and garlic, stir everything together and cook 3-4 minutes until rice is heated through.", "Add peas and soy sauce, toss well. Drizzle with sesame oil and top with green onions."]'::jsonb, 4, 5, 15, 2.0, 8.0, 410, 30, 44, 12, 3, 660, true, true, true, 'curated'),
  ('High-Protein Yogurt Bowl with Almonds and Oats', 'A no-fuss bowl of thick Greek yogurt layered with toasted oats, sliced almonds, and a sweet honey swirl.', 'breakfast', 'No-Cook', 'budget', ARRAY['american','budget','egg-free','gluten-free','high-protein','kid-friendly','no-cook','nut-free','quick','soy-free','vegetarian']::text[], '["2 cups plain Greek yogurt", "4 tbsp sliced almonds", "4 tbsp rolled oats", "2 tbsp honey", "1 tsp cinnamon", "1 cup frozen blueberries, thawed"]'::jsonb, '["Divide Greek yogurt into two bowls.", "Top each bowl with rolled oats, sliced almonds, and blueberries.", "Drizzle with honey and sprinkle with cinnamon. Serve immediately."]'::jsonb, 2, 5, 0, 2.5, 5.0, 360, 25, 45, 9, 4, 120, true, true, true, 'curated'),
  ('One-Pan Chicken Thighs with Roasted Vegetables', 'Juicy bone-in chicken thighs roasted alongside seasoned potatoes, carrots, and zucchini in one pan.', 'dinner', 'Sheet-Pan', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','sheet-pan','soy-free','standard']::text[], '["4 bone-in chicken thighs", "3 medium potatoes, cubed", "3 carrots, chopped", "2 zucchini, sliced", "3 tbsp olive oil", "1 tsp garlic powder", "1 tsp paprika", "1 tsp dried oregano", "salt", "pepper"]'::jsonb, '["Preheat oven to 425 degrees F. Line a sheet pan with foil.", "Toss all vegetables with 2 tbsp olive oil, garlic powder, and salt and pepper. Spread on the pan.", "Rub chicken thighs with remaining olive oil, paprika, oregano, salt, and pepper. Place on top of vegetables.", "Roast 35-40 minutes until chicken reaches 165 degrees F and vegetables are tender."]'::jsonb, 4, 10, 40, 2.7, 10.8, 480, 38, 30, 22, 5, 380, true, true, true, 'curated'),
  ('Ground Beef Taco Bowls with Rice and Beans', 'Seasoned ground beef served over fluffy white rice with black beans, salsa, and shredded cheese.', 'dinner', 'Mexican', 'budget', ARRAY['budget','egg-free','family-style','gluten-free','high-protein','kid-friendly','mexican','nut-free','one-pot','soy-free','standard']::text[], '["1 lb ground beef", "2 cups white rice", "1 can black beans, drained", "1 can diced tomatoes", "1 cup salsa", "1 cup shredded cheddar cheese", "2 tsp cumin", "2 tsp chili powder", "1 tsp garlic powder", "4 cups water", "salt"]'::jsonb, '["Cook rice in 4 cups water according to package directions.", "Brown ground beef in a skillet over medium-high heat. Drain excess fat.", "Stir in cumin, chili powder, garlic powder, diced tomatoes, and salsa. Simmer 5 minutes.", "Warm black beans separately. Assemble bowls with rice, beef mixture, and beans.", "Top each bowl with shredded cheddar and serve."]'::jsonb, 4, 5, 25, 2.8, 11.2, 610, 36, 68, 18, 9, 720, true, true, true, 'curated'),
  ('Slow Cooker White Chicken Chili', 'Tender shredded chicken simmered all day with white beans, green chiles, and warm spices.', 'dinner', 'Soup', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','slow-cooker','soy-free','standard']::text[], '["1.5 lbs chicken breasts", "2 cans white beans, drained", "1 can diced green chiles", "1 onion, diced", "3 cloves garlic, minced", "2 cups chicken broth", "1 tsp cumin", "1 tsp chili powder", "1 tsp oregano", "salt", "pepper"]'::jsonb, '["Add chicken breasts, white beans, green chiles, onion, and garlic to slow cooker.", "Pour in chicken broth and add cumin, chili powder, oregano, salt, and pepper.", "Cover and cook on low 6-8 hours or high 3-4 hours.", "Remove chicken, shred with two forks, and return to slow cooker.", "Stir to combine and serve hot."]'::jsonb, 6, 10, 360, 2.2, 13.2, 360, 42, 28, 6, 8, 580, true, true, true, 'curated'),
  ('Baked Lemon Herb Tilapia with Steamed Broccoli', 'Flaky tilapia fillets baked with lemon juice, garlic, and fresh herbs alongside bright steamed broccoli.', 'dinner', 'Baked', 'budget', ARRAY['baked','budget','dairy-free','egg-free','gluten-free','healthy','high-protein','kid-friendly','nut-free','seafood','soy-free','standard']::text[], '["4 tilapia fillets", "3 cups broccoli florets", "3 cloves garlic, minced", "2 lemons", "2 tbsp olive oil", "1 tsp dried oregano", "1 tsp dried thyme", "salt", "pepper"]'::jsonb, '["Preheat oven to 400 degrees F. Line a baking dish with foil.", "Place tilapia in the dish. Mix olive oil, garlic, juice of 1.5 lemons, oregano, and thyme. Pour over fish.", "Season with salt and pepper. Bake 12-15 minutes until fish flakes easily.", "Steam broccoli on the stovetop or microwave until tender.", "Serve tilapia alongside broccoli with remaining lemon wedges."]'::jsonb, 4, 5, 15, 2.6, 10.4, 260, 38, 8, 9, 3, 310, true, true, true, 'curated'),
  ('Turkey Meatball and Marinara Pasta', 'Tender homemade turkey meatballs nestled in rich tomato marinara tossed with al dente spaghetti.', 'dinner', 'Italian', 'budget', ARRAY['budget','family-style','high-protein','italian','kid-friendly','nut-free','one-pot','soy-free','standard']::text[], '["1 lb ground turkey", "1 lb spaghetti", "1 jar marinara sauce", "1 egg", "1/4 cup breadcrumbs", "2 cloves garlic, minced", "1 tsp Italian seasoning", "1/4 cup grated Parmesan cheese", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Combine turkey, egg, breadcrumbs, garlic, Italian seasoning, salt, and pepper. Roll into 1-inch balls.", "Heat olive oil in a large skillet and brown meatballs on all sides, about 6 minutes.", "Pour marinara sauce over meatballs and simmer 15 minutes on low heat.", "Meanwhile, cook spaghetti according to package directions. Drain.", "Serve meatballs and sauce over spaghetti. Top with Parmesan."]'::jsonb, 5, 15, 25, 2.6, 13.0, 530, 33, 69, 11, 4, 640, true, true, true, 'curated'),
  ('Honey Garlic Chicken Stir-Fry', 'Bite-sized chicken pieces tossed in a sticky honey garlic sauce with crisp broccoli and snap peas over rice.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','egg-free','high-protein','kid-friendly','nut-free','quick','standard','stir-fry']::text[], '["1.5 lbs chicken breast, diced", "3 cups broccoli florets", "1 cup snap peas", "3 cloves garlic, minced", "3 tbsp honey", "3 tbsp soy sauce", "1 tbsp cornstarch", "2 tbsp olive oil", "2 cups white rice", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Mix honey, soy sauce, and cornstarch in a small bowl. Set aside.", "Heat olive oil in a large skillet or wok over high heat. Add chicken, season with salt and pepper, and cook 5-6 minutes.", "Add broccoli, snap peas, and garlic. Stir-fry 3-4 minutes until vegetables are bright and tender-crisp.", "Pour sauce over the pan and toss to coat. Cook 1 minute until sauce thickens. Serve over rice."]'::jsonb, 4, 10, 20, 2.9, 11.6, 510, 42, 60, 9, 4, 680, true, true, true, 'curated'),
  ('Beef and Vegetable Stuffed Peppers', 'Colorful bell peppers stuffed with seasoned ground beef, brown rice, and topped with melted mozzarella.', 'dinner', 'American', 'budget', ARRAY['american','baked','budget','egg-free','family-style','gluten-free','high-protein','kid-friendly','nut-free','soy-free','standard']::text[], '["1 lb ground beef", "6 bell peppers", "1 cup brown rice, cooked", "1 can diced tomatoes", "1 onion, diced", "2 cloves garlic, minced", "1 cup shredded mozzarella cheese", "1 tsp Italian seasoning", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Preheat oven to 375 degrees F. Cut tops off peppers and remove seeds.", "Brown ground beef with onion and garlic in olive oil. Drain fat.", "Stir in cooked rice, diced tomatoes, Italian seasoning, salt, and pepper.", "Stuff each pepper with beef mixture and place in a baking dish. Top each with mozzarella.", "Add 1/2 cup water to the dish, cover with foil, and bake 40 minutes. Uncover and bake 10 more minutes."]'::jsonb, 6, 15, 50, 2.8, 16.8, 380, 28, 28, 17, 4, 450, true, true, true, 'curated'),
  ('Creamy Tuscan White Bean and Turkey Soup', 'A hearty, comforting soup with ground turkey, white beans, kale, and sun-dried tomatoes in a rich broth.', 'dinner', 'Soup', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','italian','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb ground turkey", "2 cans white beans, drained", "3 cups kale, chopped", "1 onion, diced", "3 cloves garlic, minced", "4 cups chicken broth", "1 can diced tomatoes", "1 tsp Italian seasoning", "1 tsp smoked paprika", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large pot. Brown ground turkey, breaking it apart. Drain fat.", "Add onion and garlic and cook 3 minutes until softened.", "Stir in Italian seasoning and smoked paprika. Add diced tomatoes and chicken broth.", "Add white beans and bring to a boil. Reduce heat and simmer 15 minutes.", "Stir in kale and cook 3-4 minutes until wilted. Season with salt and pepper and serve."]'::jsonb, 5, 10, 25, 2.4, 12.0, 360, 35, 30, 9, 9, 620, false, true, true, 'curated'),
  ('Sheet-Pan Sausage and Cabbage with Potatoes', 'Sliced smoked sausage roasted with tender cabbage wedges and golden potato rounds on a single pan.', 'dinner', 'Sheet-Pan', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','sheet-pan','soy-free','standard']::text[], '["1 lb smoked sausage, sliced", "4 cups cabbage, cut into wedges", "3 medium potatoes, sliced", "1 onion, sliced", "2 tbsp olive oil", "1 tsp garlic powder", "1 tsp smoked paprika", "salt", "pepper"]'::jsonb, '["Preheat oven to 400 degrees F. Line a large sheet pan with foil.", "Toss potatoes, cabbage, and onion with olive oil, garlic powder, paprika, salt, and pepper.", "Spread vegetables on the sheet pan. Scatter sausage slices on top.", "Roast 30-35 minutes, turning once halfway, until potatoes are golden and sausage is caramelized."]'::jsonb, 4, 10, 35, 2.5, 10.0, 490, 26, 38, 24, 5, 860, true, true, true, 'curated'),
  ('Pan-Seared Pork Chops with Garlic Green Beans', 'Juicy bone-in pork chops seared golden in a cast iron skillet alongside crispy garlic green beans.', 'dinner', 'American', 'budget', ARRAY['american','budget','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','quick','soy-free','standard']::text[], '["4 bone-in pork chops", "1 lb green beans, trimmed", "4 cloves garlic, minced", "2 tbsp olive oil", "1 tsp smoked paprika", "1 tsp onion powder", "1 tbsp butter", "salt", "pepper"]'::jsonb, '["Season pork chops generously with smoked paprika, onion powder, salt, and pepper.", "Heat 1 tbsp olive oil in a cast iron skillet over high heat. Sear pork chops 4 minutes per side until deeply golden.", "Remove chops and let rest. In the same skillet, add remaining oil and butter.", "Add garlic and green beans. Cook 5-6 minutes, tossing often, until beans are tender-crisp.", "Return pork chops to the pan to warm briefly. Serve together."]'::jsonb, 4, 5, 15, 2.9, 11.6, 410, 38, 8, 23, 3, 370, true, true, true, 'curated'),
  ('Teriyaki Chicken Rice Bowl', 'Sweet and savory teriyaki glazed chicken thighs served over steamed jasmine rice with edamame.', 'dinner', 'Asian', 'budget', ARRAY['asian','bowl','budget','dairy-free','egg-free','high-protein','kid-friendly','nut-free','quick','standard']::text[], '["1.5 lbs boneless chicken thighs", "2 cups jasmine rice", "1 cup frozen edamame, thawed", "4 tbsp soy sauce", "2 tbsp honey", "1 tbsp rice vinegar", "2 cloves garlic, minced", "1 tsp ginger, grated", "1 tbsp olive oil", "2 cups water"]'::jsonb, '["Cook rice in 2 cups water according to package directions.", "Mix soy sauce, honey, rice vinegar, garlic, and ginger in a small bowl.", "Heat olive oil in a skillet over medium-high heat. Add chicken thighs and cook 5 minutes per side.", "Pour teriyaki sauce over chicken and cook 3-4 minutes, turning to coat, until sauce thickens.", "Slice chicken and serve over rice with edamame on the side."]'::jsonb, 4, 10, 20, 2.9, 11.6, 540, 42, 60, 12, 3, 780, true, true, true, 'curated'),
  ('Baked Chicken and Black Bean Quesadillas', 'Crispy oven-baked quesadillas stuffed with shredded chicken, black beans, corn, and melted pepper jack cheese.', 'dinner', 'Mexican', 'budget', ARRAY['baked','budget','egg-free','high-protein','kid-friendly','mexican','nut-free','quick','soy-free','standard']::text[], '["2 cups cooked chicken, shredded", "1 can black beans, drained", "1 cup frozen corn, thawed", "2 cups shredded pepper jack cheese", "8 flour tortillas", "1 tsp cumin", "1 tsp chili powder", "cooking spray", "salt"]'::jsonb, '["Preheat oven to 400 degrees F. Spray two sheet pans with cooking spray.", "Mix chicken, black beans, corn, cumin, chili powder, and salt in a bowl.", "Lay 4 tortillas on pans. Divide chicken mixture among them, top with cheese, and place second tortilla on top.", "Lightly spray tops with cooking spray. Bake 12-15 minutes, flipping once, until golden and crispy.", "Cut into wedges and serve with salsa."]'::jsonb, 4, 10, 15, 2.7, 10.8, 540, 38, 58, 16, 8, 750, true, true, true, 'curated'),
  ('Skillet Salmon with Asparagus and Brown Rice', 'Pan-seared salmon fillets cooked in a lemon butter sauce alongside crispy asparagus and hearty brown rice.', 'dinner', 'Skillet', 'standard', ARRAY['american','egg-free','gluten-free','high-protein','nut-free','quick','seafood','soy-free','standard']::text[], '["4 salmon fillets", "1 lb asparagus, trimmed", "2 cups brown rice", "3 cloves garlic, minced", "2 tbsp butter", "1 lemon", "2 tbsp olive oil", "1 tsp dried dill", "4 cups water", "salt", "pepper"]'::jsonb, '["Cook brown rice in 4 cups water according to package directions.", "Season salmon with salt, pepper, and dill.", "Heat olive oil in a large skillet over medium-high heat. Sear salmon 4-5 minutes per side. Remove and set aside.", "In the same skillet, melt butter and cook asparagus and garlic 4-5 minutes until tender-crisp.", "Squeeze lemon juice over asparagus. Serve salmon over rice with asparagus alongside."]'::jsonb, 4, 5, 30, 4.5, 18.0, 540, 42, 48, 18, 4, 340, false, true, true, 'curated'),
  ('Cuban-Style Black Bean Soup with Chicken', 'A deeply savory Cuban-inspired soup with shredded chicken, earthy black beans, cumin, and citrus.', 'dinner', 'Soup', 'budget', ARRAY['budget','cuban','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb chicken breasts", "2 cans black beans, drained", "1 onion, diced", "4 cloves garlic, minced", "1 green bell pepper, diced", "4 cups chicken broth", "1 can diced tomatoes", "1 tsp cumin", "1 tsp oregano", "2 tbsp olive oil", "1 lime", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large pot. Saute onion and bell pepper 5 minutes. Add garlic and cook 1 minute.", "Add chicken breasts, black beans, diced tomatoes, chicken broth, cumin, oregano, salt, and pepper.", "Bring to a boil, reduce heat, and simmer 20-25 minutes until chicken is cooked through.", "Remove chicken, shred with forks, and return to pot. Simmer 5 more minutes.", "Squeeze lime juice over soup. Serve with rice or crusty bread."]'::jsonb, 5, 10, 30, 2.3, 11.5, 350, 36, 32, 7, 10, 600, true, true, true, 'curated'),
  ('Skillet Chicken Thighs with Garlic Green Beans', 'Juicy seared chicken thighs paired with tender garlic-kissed green beans all cooked in one pan for a satisfying weeknight dinner.', 'dinner', 'Skillet', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','quick','soy-free','standard']::text[], '["4 chicken thighs", "1 lb green beans", "4 cloves garlic", "2 tbsp olive oil", "1 tsp paprika", "1 tsp onion powder", "salt", "pepper"]'::jsonb, '["Season chicken thighs with paprika, onion powder, salt, and pepper.", "Heat olive oil in a large skillet over medium-high heat and sear chicken skin-side down for 6 minutes.", "Flip chicken and cook 6 more minutes until cooked through; remove and rest.", "Add green beans and garlic to the skillet and cook 5 minutes until tender.", "Serve green beans alongside chicken thighs."]'::jsonb, 4, 10, 20, 2.5, 10.0, 370, 28, 10, 22, 4, 420, true, true, true, 'curated'),
  ('Beef and Broccoli Rice Bowls', 'Savory ground beef and tender broccoli florets tossed in a simple soy-ginger sauce served over fluffy white rice.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','egg-free','high-protein','kid-friendly','nut-free','one-pan','rice-bowl','standard','stir-fry']::text[], '["1 lb ground beef", "2 cups broccoli florets", "2 cups white rice", "3 cloves garlic", "1 tbsp soy sauce", "1 tsp ginger powder", "1 tbsp vegetable oil", "1 tsp sesame oil", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Brown ground beef in a skillet over medium-high heat; drain excess fat.", "Add garlic and ginger powder, cook 1 minute.", "Add broccoli and soy sauce, stir-fry 4 minutes until broccoli is tender.", "Drizzle sesame oil, then serve over rice."]'::jsonb, 4, 8, 20, 2.75, 11.0, 480, 30, 52, 16, 3, 550, true, true, true, 'curated'),
  ('Black Bean and Chorizo Tacos', 'Spiced chorizo crumbles and hearty black beans piled into warm corn tortillas with fresh salsa and a squeeze of lime.', 'dinner', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','mexican','nut-free','quick','soy-free','tacos','vegan','vegetarian']::text[], '["8 oz chorizo", "1 can black beans", "8 corn tortillas", "1 cup salsa", "1 onion", "2 cloves garlic", "1 lime", "1 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Cook chorizo in a skillet over medium heat, breaking it up, until browned.", "Add diced onion and garlic, cook 3 minutes.", "Stir in drained black beans and cook until heated through.", "Warm tortillas in a dry pan or microwave.", "Fill tortillas with chorizo-bean mixture, top with salsa, and squeeze lime over the top."]'::jsonb, 4, 10, 15, 2.8, 11.2, 430, 22, 48, 17, 9, 720, true, true, true, 'curated'),
  ('Turkey and Vegetable Stuffed Bell Peppers', 'Colorful bell peppers loaded with a savory filling of seasoned ground turkey, rice, and tomatoes then baked until perfectly tender.', 'dinner', 'Baked', 'budget', ARRAY['american','baked','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','meal-prep','nut-free','soy-free','standard']::text[], '["4 bell peppers", "1 lb ground turkey", "1 cup white rice", "1 can diced tomatoes", "1 onion", "2 cloves garlic", "1 tsp Italian seasoning", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Preheat oven to 375\u00b0F. Cook rice according to package directions.", "Halve and seed bell peppers; arrange cut-side up in a baking dish.", "Saut\u00e9 onion and garlic in olive oil until soft; add ground turkey and cook through.", "Stir in diced tomatoes, cooked rice, Italian seasoning, salt, and pepper.", "Fill each pepper half with turkey mixture and bake 25 minutes until peppers are tender."]'::jsonb, 4, 15, 35, 2.9, 11.6, 400, 32, 38, 12, 4, 490, true, true, true, 'curated'),
  ('Slow Cooker Pinto Bean and Pork Shoulder Stew', 'Melt-in-your-mouth pork shoulder simmers low and slow with pinto beans, smoky spices, and a rich tomato broth for a deeply comforting stew.', 'dinner', 'Stew', 'budget', ARRAY['american','budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','meal-prep','nut-free','slow-cooker','soy-free','standard']::text[], '["1.5 lbs pork shoulder", "2 cans pinto beans", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tsp cumin", "1 tsp smoked paprika", "2 cups chicken broth", "salt", "pepper"]'::jsonb, '["Season pork shoulder with cumin, smoked paprika, salt, and pepper.", "Place pork in slow cooker; add diced onion, garlic, diced tomatoes, and chicken broth.", "Pour in drained pinto beans and stir gently.", "Cook on low 8 hours or high 4 hours until pork is fall-apart tender.", "Shred pork with two forks, stir into the stew, and serve."]'::jsonb, 6, 10, 480, 2.6, 15.6, 420, 35, 30, 16, 8, 580, true, true, true, 'curated'),
  ('Baked Lemon Herb Salmon with Roasted Potatoes', 'Flaky salmon fillets baked with bright lemon and fresh herbs alongside golden roasted baby potatoes for an elegant yet simple dinner.', 'dinner', 'Sheet-Pan', 'standard', ARRAY['american','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','seafood','sheet-pan','soy-free','standard']::text[], '["4 salmon fillets", "1 lb baby potatoes", "1 lemon", "2 tbsp olive oil", "2 cloves garlic", "1 tsp dried thyme", "1 tsp dried rosemary", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F. Halve baby potatoes and toss with 1 tbsp olive oil, salt, and pepper on a sheet pan.", "Roast potatoes 15 minutes, then push to one side.", "Place salmon on the sheet pan; drizzle with remaining olive oil, garlic, thyme, rosemary, and lemon juice.", "Roast everything together 12 to 15 minutes until salmon flakes easily.", "Serve salmon alongside roasted potatoes with lemon wedges."]'::jsonb, 4, 10, 30, 4.5, 18.0, 420, 38, 22, 20, 3, 380, true, true, true, 'curated'),
  ('Cheesy Egg and Potato Frittata', 'A golden frittata bursting with tender diced potatoes, sautéed onions, and melted cheddar cheese that works beautifully as a hearty dinner.', 'dinner', 'Skillet', 'ultra_budget', ARRAY['american','budget','gluten-free','kid-friendly','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["6 eggs", "2 potatoes", "1 onion", "1 cup shredded cheddar cheese", "2 tbsp butter", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Dice potatoes and boil in salted water 8 minutes until just tender; drain.", "Whisk eggs with garlic powder, salt, and pepper.", "Melt butter in an oven-safe skillet, saut\u00e9 onion until soft, then add potatoes.", "Pour egg mixture over the vegetables and cook on stovetop 3 minutes until edges set.", "Sprinkle cheese on top and broil 3 to 4 minutes until golden and set."]'::jsonb, 4, 10, 20, 1.4, 5.6, 320, 18, 22, 18, 2, 390, true, true, true, 'curated'),
  ('Chicken and Sweet Potato Curry', 'Tender chunks of chicken and sweet potato simmer in a fragrant coconut milk curry sauce with warming spices that fill the whole kitchen.', 'dinner', 'Curry', 'budget', ARRAY['budget','comfort-food','curry','egg-free','gluten-free','high-protein','indian','kid-friendly','nut-free','one-pot','soy-free','standard']::text[], '["1 lb chicken breast", "2 sweet potatoes", "1 can coconut milk", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "2 tsp curry powder", "1 tsp turmeric", "1 tbsp vegetable oil", "salt"]'::jsonb, '["Cube chicken and sweet potatoes into bite-sized pieces.", "Saut\u00e9 onion and garlic in oil over medium heat until softened.", "Add curry powder and turmeric, stir 1 minute until fragrant.", "Add chicken, sweet potatoes, diced tomatoes, and coconut milk; stir to combine.", "Simmer 20 minutes until chicken is cooked through and sweet potato is tender.", "Serve over rice or with flatbread."]'::jsonb, 4, 12, 25, 2.95, 11.8, 410, 28, 35, 18, 5, 460, true, true, true, 'curated'),
  ('Pork Fried Rice', 'Classic takeout-style fried rice loaded with tender pork, scrambled eggs, peas, and carrots in a savory soy-seasoned wok sauce.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','high-protein','kid-friendly','nut-free','one-pan','rice','standard','stir-fry']::text[], '["1 lb pork tenderloin", "3 cups cooked white rice", "3 eggs", "1 cup frozen peas and carrots", "3 cloves garlic", "3 tbsp soy sauce", "2 tbsp vegetable oil", "1 tsp sesame oil", "salt", "pepper"]'::jsonb, '["Dice pork into small cubes and season with salt and pepper.", "Heat vegetable oil in a wok or large skillet over high heat; cook pork until browned, set aside.", "Scramble eggs in the pan, breaking into small pieces; add garlic and cook 30 seconds.", "Add frozen peas and carrots and stir-fry 2 minutes.", "Add cooked rice and pork back; pour in soy sauce and toss everything together.", "Drizzle with sesame oil before serving."]'::jsonb, 4, 10, 15, 2.65, 10.6, 450, 30, 50, 13, 3, 690, true, true, true, 'curated'),
  ('Homestyle Beef Chili', 'A rich and thick chili loaded with ground beef, kidney beans, and a bold blend of spices that gets better the longer it simmers.', 'dinner', 'Chili', 'budget', ARRAY['american','budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','meal-prep','nut-free','one-pot','soy-free','standard']::text[], '["1 lb ground beef", "2 cans kidney beans", "1 can diced tomatoes", "1 can tomato sauce", "1 onion", "3 cloves garlic", "2 tsp chili powder", "1 tsp cumin", "1 tsp smoked paprika", "salt", "pepper"]'::jsonb, '["Brown ground beef in a large pot over medium-high heat; drain excess fat.", "Add diced onion and garlic, cook 4 minutes until softened.", "Stir in chili powder, cumin, and smoked paprika; cook 1 minute.", "Add diced tomatoes, tomato sauce, and drained kidney beans; stir well.", "Simmer on low 25 minutes, stirring occasionally.", "Taste and adjust seasoning before serving with cornbread or crackers."]'::jsonb, 6, 10, 35, 2.2, 13.2, 390, 28, 33, 15, 10, 640, true, true, true, 'curated'),
  ('Sheet-Pan Sausage and Peppers', 'Sliced Italian sausage roasted with colorful bell peppers and onions until caramelized and tender, perfect served over pasta or in a roll.', 'dinner', 'Sheet-Pan', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','high-protein','italian','kid-friendly','nut-free','one-pan','quick','sheet-pan','soy-free','standard']::text[], '["1 lb Italian sausage links", "3 bell peppers", "1 large onion", "3 cloves garlic", "2 tbsp olive oil", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F.", "Slice sausage into thick rounds; slice peppers and onion into strips.", "Toss sausage, peppers, onion, and garlic with olive oil, Italian seasoning, salt, and pepper.", "Spread on a sheet pan in a single layer.", "Roast 30 minutes, turning once halfway through, until sausage is cooked and vegetables are caramelized."]'::jsonb, 4, 10, 30, 2.8, 11.2, 420, 22, 14, 32, 3, 750, true, true, true, 'curated'),
  ('Creamy Tuscan White Bean and Chicken Soup', 'A velvety soup with shredded chicken, creamy white beans, and spinach in a garlicky broth that tastes like a cozy Italian trattoria.', 'dinner', 'Soup', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','italian','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb chicken breast", "2 cans white beans", "2 cups fresh spinach", "4 cups chicken broth", "1 onion", "4 cloves garlic", "1 tsp Italian seasoning", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Saut\u00e9 onion and garlic in olive oil in a large pot over medium heat until soft.", "Add chicken breast and chicken broth; bring to a boil.", "Reduce heat and simmer 15 minutes until chicken is cooked through; remove and shred.", "Mash half the white beans with a fork; add all beans and shredded chicken to the pot.", "Stir in spinach and Italian seasoning; cook 2 minutes until wilted.", "Season with salt and pepper and serve with crusty bread."]'::jsonb, 4, 10, 25, 2.7, 10.8, 370, 32, 36, 10, 9, 590, true, true, true, 'curated'),
  ('Fish Tacos with Cabbage Slaw', 'Crispy pan-fried tilapia nestled in warm corn tortillas with a crunchy tangy cabbage slaw and a drizzle of creamy sauce.', 'dinner', 'Mexican', 'budget', ARRAY['budget','dairy-free','gluten-free','high-protein','kid-friendly','mexican','nut-free','quick','seafood','soy-free','standard','tacos']::text[], '["1 lb tilapia fillets", "8 corn tortillas", "2 cups shredded cabbage", "2 tbsp mayonnaise", "1 lime", "1 tsp cumin", "1 tsp chili powder", "1 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Season tilapia with cumin, chili powder, salt, and pepper.", "Cook tilapia in oil over medium-high heat 3 to 4 minutes per side; break into chunks.", "Mix shredded cabbage with mayonnaise and a squeeze of lime juice for the slaw.", "Warm tortillas in a dry skillet.", "Fill each tortilla with fish and top generously with cabbage slaw and lime."]'::jsonb, 4, 10, 12, 2.85, 11.4, 360, 26, 38, 12, 3, 430, true, true, true, 'curated'),
  ('Baked Chicken Drumsticks with Roasted Carrots', 'Fall-off-the-bone oven-baked chicken drumsticks seasoned with a smoky spice rub served alongside sweet caramelized roasted carrots.', 'dinner', 'Baked', 'ultra_budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-favorite','kid-friendly','nut-free','sheet-pan','soy-free','standard']::text[], '["8 chicken drumsticks", "4 carrots", "2 tbsp olive oil", "1 tsp smoked paprika", "1 tsp garlic powder", "1 tsp onion powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F.", "Toss drumsticks with 1 tbsp olive oil and all dry spices; place on a sheet pan.", "Peel and slice carrots; toss with remaining olive oil, salt, and pepper; add to pan.", "Bake 35 to 40 minutes, turning drumsticks halfway, until golden and cooked through.", "Rest 5 minutes before serving."]'::jsonb, 4, 8, 40, 1.5, 6.0, 380, 30, 12, 24, 3, 390, true, true, true, 'curated'),
  ('Ground Turkey and Zucchini Pasta', 'Savory ground turkey and tender zucchini ribbons tossed with penne pasta in a garlic tomato sauce that comes together in under 30 minutes.', 'dinner', 'Pasta', 'budget', ARRAY['budget','dairy-free','egg-free','high-protein','italian','kid-friendly','nut-free','one-pot','pasta','quick','soy-free','standard']::text[], '["1 lb ground turkey", "12 oz penne pasta", "2 zucchini", "1 can crushed tomatoes", "4 cloves garlic", "1 onion", "2 tbsp olive oil", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Cook penne according to package directions; reserve 1 cup pasta water.", "Saut\u00e9 onion and garlic in olive oil until soft; add ground turkey and cook through.", "Add sliced zucchini and cook 3 minutes.", "Pour in crushed tomatoes and Italian seasoning; simmer 10 minutes.", "Toss in cooked pasta, adding pasta water as needed to loosen sauce.", "Season with salt and pepper before serving."]'::jsonb, 4, 10, 25, 2.6, 10.4, 480, 35, 58, 12, 5, 520, true, true, true, 'curated'),
  ('Loaded Baked Potato Bar', 'Giant fluffy baked russet potatoes served with a spread of classic toppings like cheddar cheese, sour cream, and seasoned ground beef.', 'dinner', 'American', 'budget', ARRAY['american','budget','comfort-food','customizable','egg-free','gluten-free','high-protein','kid-favorite','kid-friendly','nut-free','soy-free','standard']::text[], '["4 large russet potatoes", "0.5 lb ground beef", "1 cup shredded cheddar cheese", "0.5 cup sour cream", "2 cloves garlic", "1 tbsp olive oil", "1 tsp chili powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F. Scrub potatoes, poke with a fork, rub with olive oil and salt.", "Bake potatoes directly on oven rack 50 to 60 minutes until tender.", "Cook ground beef with garlic and chili powder in a skillet; drain fat.", "Split open baked potatoes and fluff the insides with a fork.", "Top each potato with seasoned beef, cheddar cheese, and sour cream."]'::jsonb, 4, 10, 60, 2.4, 9.6, 550, 28, 62, 22, 6, 520, true, true, true, 'curated'),
  ('Honey Garlic Shrimp and Rice', 'Plump juicy shrimp glazed in a sweet and savory honey garlic sauce served over a bed of steamed jasmine rice for a restaurant-worthy dinner.', 'dinner', 'Stir-Fry', 'standard', ARRAY['asian','egg-free','high-protein','kid-friendly','nut-free','quick','rice-bowl','seafood','standard']::text[], '["1 lb shrimp", "2 cups jasmine rice", "3 cloves garlic", "3 tbsp honey", "2 tbsp soy sauce", "1 tbsp butter", "1 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Cook jasmine rice according to package directions.", "Pat shrimp dry and season with salt and pepper.", "Heat oil in a skillet over medium-high heat; cook shrimp 2 minutes per side; set aside.", "Add butter and garlic to the pan, cook 1 minute; whisk in honey and soy sauce.", "Return shrimp to pan and toss to coat in the glaze.", "Serve shrimp and sauce over rice."]'::jsonb, 4, 8, 15, 3.8, 15.2, 420, 30, 55, 8, 1, 620, true, true, true, 'curated'),
  ('Chicken Tortilla Soup', 'A smoky, hearty soup with shredded chicken, corn, black beans, and tomatoes topped with crunchy tortilla strips for incredible texture.', 'dinner', 'Soup', 'budget', ARRAY['budget','dairy-free','egg-free','high-protein','kid-friendly','meal-prep','mexican','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb chicken breast", "1 can black beans", "1 can corn", "1 can diced tomatoes", "4 cups chicken broth", "1 onion", "3 cloves garlic", "2 tsp cumin", "1 tsp chili powder", "6 corn tortillas", "2 tbsp vegetable oil", "salt"]'::jsonb, '["Saut\u00e9 onion and garlic in 1 tbsp oil in a large pot until soft.", "Add chicken breast, broth, diced tomatoes, black beans, corn, cumin, and chili powder.", "Bring to a boil, then simmer 15 minutes until chicken is cooked; shred chicken.", "Return shredded chicken to soup and simmer 5 more minutes.", "Cut tortillas into strips, toss with remaining oil, and bake at 375\u00b0F for 10 minutes until crispy.", "Ladle soup into bowls and top with tortilla strips."]'::jsonb, 6, 12, 30, 2.3, 13.8, 350, 28, 38, 8, 8, 620, true, true, true, 'curated'),
  ('Beef and Potato Hash', 'A rustic and hearty skillet hash of seasoned ground beef and crispy potatoes with onions and peppers that makes any night feel like Sunday brunch.', 'dinner', 'Skillet', 'ultra_budget', ARRAY['american','budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','soy-free','standard']::text[], '["0.75 lb ground beef", "3 potatoes", "1 bell pepper", "1 onion", "2 cloves garlic", "1 tsp smoked paprika", "1 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Dice potatoes into small cubes and parboil in salted water 6 minutes; drain.", "Brown ground beef in a cast iron skillet; drain excess fat and set aside.", "Cook onion, bell pepper, and garlic in the skillet with oil until softened.", "Add potatoes and press into the pan; cook undisturbed 4 minutes until crispy.", "Stir in beef and paprika, season with salt and pepper, and cook 3 more minutes."]'::jsonb, 4, 12, 20, 1.5, 6.0, 380, 24, 32, 17, 4, 410, true, true, true, 'curated'),
  ('Lemon Chicken Orzo Soup', 'Bright and comforting chicken broth soup with tiny orzo pasta, tender shredded chicken, and a generous squeeze of fresh lemon for a light but satisfying dinner.', 'dinner', 'Soup', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','high-protein','kid-friendly','mediterranean','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb chicken thighs", "1 cup orzo pasta", "1 lemon", "5 cups chicken broth", "2 carrots", "2 stalks celery", "1 onion", "2 cloves garlic", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Saut\u00e9 diced onion, carrots, celery, and garlic in olive oil in a pot until softened.", "Add chicken thighs and chicken broth; bring to a boil.", "Simmer 20 minutes until chicken is cooked through; remove and shred.", "Add orzo to the broth and cook 8 minutes until tender.", "Return shredded chicken; stir in lemon juice, season with salt and pepper."]'::jsonb, 6, 12, 30, 2.5, 15.0, 320, 26, 32, 9, 3, 550, true, true, true, 'curated'),
  ('Beef Bulgogi Rice Bowls', 'Thin strips of marinated beef quickly cooked in a sweet soy and sesame marinade served over steamed rice with crisp cucumber slices.', 'dinner', 'Korean', 'standard', ARRAY['asian','dairy-free','egg-free','high-protein','kid-friendly','korean','nut-free','quick','rice-bowl','standard']::text[], '["1 lb beef sirloin", "2 cups white rice", "3 tbsp soy sauce", "2 tbsp brown sugar", "1 tbsp sesame oil", "3 cloves garlic", "1 tsp ginger powder", "1 cucumber", "1 tbsp vegetable oil", "salt"]'::jsonb, '["Slice beef very thin; mix soy sauce, brown sugar, sesame oil, garlic, and ginger into a marinade.", "Marinate beef at least 20 minutes in the refrigerator.", "Cook rice according to package directions.", "Cook marinated beef in vegetable oil over high heat in batches, 2 minutes per batch.", "Serve beef over rice with sliced cucumber."]'::jsonb, 4, 25, 15, 4.2, 16.8, 490, 34, 50, 16, 1, 680, true, true, true, 'curated'),
  ('Pork and Cabbage Egg Roll Bowl', 'All the delicious flavors of an egg roll without the wrapper — savory ground pork and sautéed cabbage in a garlicky ginger sauce served over rice.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','high-protein','kid-friendly','nut-free','one-pan','quick','standard','stir-fry']::text[], '["1 lb ground pork", "4 cups shredded cabbage", "2 cups white rice", "3 cloves garlic", "1 tsp ginger powder", "3 tbsp soy sauce", "1 tsp sesame oil", "1 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Brown ground pork in a skillet over medium-high heat; drain fat.", "Add garlic and ginger powder to pork, cook 1 minute.", "Add shredded cabbage and soy sauce; stir-fry until cabbage wilts, about 5 minutes.", "Drizzle with sesame oil and serve over rice."]'::jsonb, 4, 8, 20, 2.5, 10.0, 460, 28, 48, 17, 4, 630, true, true, true, 'curated'),
  ('Slow Cooker Chicken Enchilada Casserole', 'Layers of shredded chicken, corn tortillas, red enchilada sauce, and melted cheese slow-cooked into one bubbling and irresistible casserole.', 'dinner', 'Mexican', 'budget', ARRAY['budget','comfort-food','egg-free','gluten-free','high-protein','kid-friendly','meal-prep','mexican','nut-free','slow-cooker','soy-free','standard']::text[], '["1.5 lbs chicken breast", "1 can red enchilada sauce", "8 corn tortillas", "1 can black beans", "1 cup shredded cheddar cheese", "1 cup salsa", "1 tsp cumin", "salt"]'::jsonb, '["Layer half the corn tortillas on the bottom of a slow cooker.", "Mix enchilada sauce, salsa, black beans, and cumin; pour half over tortillas.", "Place chicken breast on top and add remaining sauce mixture.", "Cover with remaining tortillas and sprinkle with cheese.", "Cook on low 5 hours or high 3 hours until chicken shreds easily.", "Shred chicken into the casserole, stir, and serve."]'::jsonb, 6, 10, 300, 2.45, 14.7, 400, 32, 38, 12, 7, 710, true, true, true, 'curated'),
  ('Spaghetti with Meat Sauce', 'A classic and deeply satisfying spaghetti with a rich slow-simmered ground beef and tomato meat sauce that feeds a hungry family every time.', 'dinner', 'Pasta', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','italian','kid-favorite','kid-friendly','nut-free','one-pot','pasta','soy-free','standard']::text[], '["1 lb ground beef", "12 oz spaghetti", "1 can crushed tomatoes", "1 can tomato paste", "1 onion", "4 cloves garlic", "2 tbsp olive oil", "2 tsp Italian seasoning", "1 tsp sugar", "salt", "pepper"]'::jsonb, '["Saut\u00e9 onion and garlic in olive oil until soft; add ground beef and brown.", "Drain excess fat; stir in tomato paste and cook 2 minutes.", "Add crushed tomatoes, Italian seasoning, sugar, salt, and pepper.", "Simmer sauce 20 minutes, stirring occasionally.", "Cook spaghetti according to package directions; drain.", "Serve meat sauce over spaghetti."]'::jsonb, 6, 10, 30, 2.1, 12.6, 490, 28, 62, 14, 5, 560, true, true, true, 'curated'),
  ('Pan-Seared Tilapia with Corn and Tomato Salsa', 'Golden-crusted tilapia fillets topped with a vibrant fresh salsa of sweet corn, ripe tomatoes, and cilantro for a light and colorful dinner.', 'dinner', 'Skillet', 'budget', ARRAY['american','budget','dairy-free','egg-free','fresh','gluten-free','high-protein','kid-friendly','nut-free','quick','seafood','soy-free','standard']::text[], '["4 tilapia fillets", "1 can corn", "2 tomatoes", "1 lime", "2 cloves garlic", "2 tbsp fresh cilantro", "2 tbsp vegetable oil", "1 tsp cumin", "salt", "pepper"]'::jsonb, '["Combine drained corn, diced tomatoes, cilantro, lime juice, and a pinch of salt to make salsa.", "Season tilapia with cumin, salt, and pepper.", "Heat oil in a skillet over medium-high heat; cook tilapia 3 to 4 minutes per side until golden.", "Spoon fresh corn and tomato salsa generously over each fillet before serving."]'::jsonb, 4, 10, 10, 2.75, 11.0, 290, 30, 18, 10, 3, 360, true, true, true, 'curated'),
  ('Turkey Meatball and Vegetable Soup', 'Tender homemade turkey meatballs simmered with zucchini, carrots, and pasta in a light herbed broth for a comforting and wholesome dinner.', 'dinner', 'Soup', 'budget', ARRAY['budget','comfort-food','dairy-free','high-protein','italian','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb ground turkey", "1 egg", "0.25 cup breadcrumbs", "2 carrots", "2 zucchini", "1 cup small pasta", "5 cups chicken broth", "1 onion", "3 cloves garlic", "1 tsp Italian seasoning", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Mix ground turkey, egg, breadcrumbs, half the garlic, Italian seasoning, salt, and pepper; roll into 1-inch meatballs.", "Brown meatballs in olive oil in a large pot; remove and set aside.", "Saut\u00e9 onion, remaining garlic, and carrots in the pot until softened.", "Add broth and bring to a boil; add pasta and cook 6 minutes.", "Add zucchini and meatballs; simmer 5 more minutes until everything is cooked through."]'::jsonb, 6, 20, 25, 2.55, 15.3, 340, 28, 28, 12, 3, 540, true, true, true, 'curated'),
  ('Black-Eyed Pea and Ham Hock Dinner', 'A deeply Southern pot of smoky black-eyed peas stewed low and slow with a ham hock until the broth turns silky and richly flavored.', 'dinner', 'Southern', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','meal-prep','nut-free','one-pot','southern','soy-free','standard']::text[], '["1 lb dried black-eyed peas", "1 ham hock", "1 onion", "3 cloves garlic", "4 cups chicken broth", "2 cups water", "1 tsp smoked paprika", "salt", "pepper"]'::jsonb, '["Soak black-eyed peas in cold water overnight; drain.", "Combine peas, ham hock, onion, garlic, broth, and water in a large pot.", "Bring to a boil, then reduce heat and simmer 1.5 hours until peas are tender.", "Remove ham hock, pull meat off the bone, and return meat to pot.", "Add smoked paprika, season with salt and pepper, and serve with cornbread."]'::jsonb, 6, 10, 100, 1.3, 7.8, 340, 26, 42, 7, 10, 590, true, true, true, 'curated'),
  ('Crispy Baked Fish and Chips', 'British pub-style baked cod fillets with a golden panko crust and thick-cut oven fries that are irresistibly crispy without all the frying mess.', 'dinner', 'Baked', 'budget', ARRAY['baked','british','budget','comfort-food','dairy-free','high-protein','kid-favorite','kid-friendly','nut-free','seafood','soy-free','standard']::text[], '["4 cod fillets", "3 russet potatoes", "1 cup panko breadcrumbs", "2 eggs", "1 tsp garlic powder", "3 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F. Cut potatoes into thick wedges; toss with 2 tbsp oil, salt, and pepper.", "Roast potato wedges 35 minutes, flipping halfway, until golden and crispy.", "Season panko with garlic powder, salt, and pepper; beat eggs in a separate bowl.", "Dip cod in egg then press into panko; place on an oiled baking sheet.", "Bake fish alongside chips for the last 15 minutes until golden and flaky.", "Serve fish and chips with malt vinegar or ketchup."]'::jsonb, 4, 15, 40, 2.9, 11.6, 430, 32, 48, 12, 4, 480, true, true, true, 'curated'),
  ('Skillet Chicken Thighs with Roasted Potatoes', 'Crispy pan-seared chicken thighs cooked alongside golden roasted potatoes in a single skillet for a satisfying weeknight dinner.', 'dinner', 'American', 'budget', ARRAY['american','budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','soy-free','standard']::text[], '["6 bone-in chicken thighs", "1.5 lbs baby potatoes", "3 cloves garlic", "2 tbsp olive oil", "1 tsp paprika", "1 tsp dried thyme", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F. Season chicken thighs with paprika, thyme, salt, and pepper.", "Heat olive oil in a large oven-safe skillet over medium-high heat and sear chicken skin-side down for 5 minutes until golden.", "Flip chicken, add halved potatoes and minced garlic around the pieces.", "Transfer skillet to oven and roast for 30 minutes until chicken is cooked through and potatoes are tender.", "Rest for 5 minutes before serving."]'::jsonb, 4, 10, 35, 2.5, 10.0, 480, 32, 28, 24, 3, 420, true, true, true, 'curated'),
  ('Beef and Cabbage Stir-Fry', 'Tender sliced beef and shredded cabbage tossed in a savory soy-ginger sauce served over steamed rice.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','egg-free','high-protein','kid-friendly','nut-free','one-pan','standard','stir-fry']::text[], '["1 lb ground beef", "4 cups shredded cabbage", "1 onion", "3 cloves garlic", "2 tbsp soy sauce", "1 tbsp sesame oil", "1 tsp fresh ginger", "2 cups white rice", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Brown ground beef in a large skillet over medium-high heat, then drain excess fat.", "Add diced onion and minced garlic, cook for 3 minutes until softened.", "Stir in cabbage and cook for 5 minutes until wilted.", "Add soy sauce, sesame oil, and ginger, toss to combine and heat through.", "Serve over steamed rice."]'::jsonb, 4, 10, 20, 2.25, 9.0, 460, 28, 48, 14, 4, 580, true, true, true, 'curated'),
  ('Smoky Black Bean and Pork Tacos', 'Seasoned ground pork and hearty black beans piled into warm tortillas with fresh salsa and crumbled cheese.', 'dinner', 'Mexican', 'budget', ARRAY['budget','egg-free','high-protein','kid-friendly','mexican','nut-free','quick','soy-free','standard','tacos']::text[], '["1 lb ground pork", "1 can black beans", "1 can diced tomatoes", "8 small flour tortillas", "1 onion", "2 cloves garlic", "1 tsp cumin", "1 tsp chili powder", "1 tsp smoked paprika", "0.5 cup shredded cheddar cheese", "salt", "pepper"]'::jsonb, '["Brown ground pork in a skillet over medium-high heat with diced onion, then drain fat.", "Add minced garlic, cumin, chili powder, and smoked paprika, cook for 1 minute.", "Stir in drained black beans and diced tomatoes, simmer for 8 minutes until thickened.", "Warm tortillas in a dry skillet or microwave.", "Assemble tacos with pork mixture topped with shredded cheese."]'::jsonb, 4, 10, 20, 2.4, 9.6, 520, 30, 46, 18, 7, 650, true, true, true, 'curated'),
  ('Lemon Herb Baked Tilapia with Green Beans', 'Flaky tilapia fillets baked with lemon slices and fresh herbs alongside crisp-tender green beans for a light but filling dinner.', 'dinner', 'Seafood', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','light','nut-free','quick','seafood','sheet-pan','soy-free','standard']::text[], '["4 tilapia fillets", "1 lb fresh green beans", "1 lemon", "3 tbsp olive oil", "2 cloves garlic", "1 tsp dried oregano", "1 tsp dried parsley", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F. Line a sheet pan with foil.", "Toss green beans with 1.5 tbsp olive oil, salt, and pepper, spread on one side of pan.", "Place tilapia fillets on the other side, drizzle with remaining olive oil.", "Top fish with sliced lemon, minced garlic, oregano, and parsley.", "Bake for 18-20 minutes until fish flakes easily and green beans are tender."]'::jsonb, 4, 8, 20, 2.8, 11.2, 290, 34, 10, 12, 4, 340, true, true, true, 'curated'),
  ('Turkey and Vegetable Soup', 'A hearty pot of ground turkey simmered with carrots, celery, potatoes, and broth into a warming homestyle soup.', 'dinner', 'Soup', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb ground turkey", "3 medium carrots", "3 stalks celery", "2 medium potatoes", "1 onion", "3 cloves garlic", "4 cups chicken broth", "2 cups water", "1 tsp dried thyme", "1 bay leaf", "salt", "pepper"]'::jsonb, '["Brown ground turkey in a large pot over medium-high heat, breaking it apart, then drain fat.", "Add diced onion, sliced carrots, and sliced celery, cook for 5 minutes until softened.", "Stir in minced garlic, thyme, and bay leaf, cook for 1 minute.", "Add diced potatoes, chicken broth, and water, bring to a boil.", "Reduce heat and simmer for 20 minutes until potatoes are tender.", "Remove bay leaf, season with salt and pepper, and serve."]'::jsonb, 6, 15, 30, 1.8, 10.8, 260, 22, 22, 8, 3, 520, true, true, true, 'curated'),
  ('Cheesy Baked Pasta with Ground Beef', 'Rotini pasta baked with seasoned ground beef in a rich tomato sauce blanketed in melted mozzarella and parmesan cheese.', 'dinner', 'Italian', 'budget', ARRAY['baked','budget','comfort-food','egg-free','high-protein','italian','kid-friendly','nut-free','pasta','soy-free','standard']::text[], '["1 lb rotini pasta", "1 lb ground beef", "1 jar marinara sauce", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1.5 cups shredded mozzarella cheese", "0.25 cup parmesan cheese", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Preheat oven to 375\u00b0F. Cook pasta according to package directions until just al dente, then drain.", "Brown ground beef with diced onion in a large skillet, drain fat, then add minced garlic and Italian seasoning.", "Stir in marinara sauce and diced tomatoes, simmer for 5 minutes.", "Combine cooked pasta with meat sauce and pour into a 9x13 baking dish.", "Top with mozzarella and parmesan, bake for 25 minutes until bubbly and golden.", "Rest for 5 minutes before serving."]'::jsonb, 6, 15, 40, 2.6, 15.6, 540, 32, 58, 17, 4, 680, true, true, true, 'curated'),
  ('Honey Garlic Pork Chops with Sweet Potato Mash', 'Pan-seared pork chops glazed in a sweet honey-garlic sauce served alongside creamy sweet potato mash.', 'dinner', 'American', 'budget', ARRAY['american','budget','comfort-food','egg-free','high-protein','kid-friendly','nut-free','pork','standard']::text[], '["4 bone-in pork chops", "3 large sweet potatoes", "4 cloves garlic", "3 tbsp honey", "2 tbsp soy sauce", "2 tbsp butter", "1 tbsp olive oil", "0.25 cup milk", "salt", "pepper"]'::jsonb, '["Boil peeled and cubed sweet potatoes in salted water for 15 minutes until tender, then drain and mash with butter, milk, salt, and pepper.", "Season pork chops with salt and pepper.", "Heat olive oil in a skillet over medium-high heat and sear pork chops for 4 minutes per side.", "Mix honey, soy sauce, and minced garlic, pour over pork chops, and cook for 2 more minutes, basting until glazed.", "Serve pork chops over sweet potato mash with pan sauce drizzled on top."]'::jsonb, 4, 10, 30, 2.9, 11.6, 510, 36, 42, 18, 5, 520, true, true, true, 'curated'),
  ('Slow Cooker Chicken Tortilla Soup', 'Tender shredded chicken simmered all day with corn, black beans, and tomatoes in a spiced broth topped with crushed tortilla chips.', 'dinner', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','high-protein','kid-friendly','mexican','nut-free','one-pot','slow-cooker','soup','soy-free','standard']::text[], '["1.5 lbs chicken breasts", "1 can black beans", "1 can corn", "1 can diced tomatoes", "1 can enchilada sauce", "4 cups chicken broth", "1 onion", "2 cloves garlic", "1 tsp cumin", "1 tsp chili powder", "1 cup tortilla chips", "salt", "pepper"]'::jsonb, '["Place chicken breasts in the slow cooker with diced onion, minced garlic, cumin, and chili powder.", "Pour in diced tomatoes, enchilada sauce, and chicken broth, stir to combine.", "Cook on low for 6-8 hours or high for 3-4 hours.", "Remove chicken and shred with two forks, return to the pot.", "Stir in drained black beans and corn, cook on high for 15 more minutes.", "Serve topped with crushed tortilla chips."]'::jsonb, 6, 10, 360, 1.9, 11.4, 320, 30, 30, 6, 6, 700, true, true, true, 'curated'),
  ('Teriyaki Chicken Rice Bowls', 'Grilled chicken strips glazed in homemade teriyaki sauce served over fluffy white rice with steamed broccoli.', 'dinner', 'Asian', 'budget', ARRAY['asian','budget','dairy-free','egg-free','high-protein','kid-friendly','nut-free','quick','rice-bowl','standard']::text[], '["1.5 lbs chicken breasts", "2 cups white rice", "3 cups broccoli florets", "4 tbsp soy sauce", "2 tbsp honey", "1 tbsp rice vinegar", "2 cloves garlic", "1 tsp cornstarch", "1 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Steam broccoli florets for 4-5 minutes until bright green and tender-crisp.", "Whisk together soy sauce, honey, rice vinegar, minced garlic, and cornstarch to make teriyaki sauce.", "Slice chicken into strips, season with salt and pepper, cook in oil over medium-high heat for 6-7 minutes until cooked through.", "Pour teriyaki sauce over chicken and cook for 2 minutes until sauce thickens and coats the chicken.", "Serve chicken over rice with broccoli on the side."]'::jsonb, 4, 10, 25, 2.6, 10.4, 490, 38, 52, 8, 3, 620, true, true, true, 'curated'),
  ('Hearty Beef and Potato Stew', 'Fork-tender chunks of beef stewed low and slow with potatoes, carrots, and onions in a rich, savory brown broth.', 'dinner', 'Stew', 'budget', ARRAY['american','budget','comfort-food','dairy-free','egg-free','high-protein','kid-friendly','nut-free','one-pot','soy-free','standard','stew']::text[], '["1.5 lbs beef stew meat", "4 medium potatoes", "3 carrots", "1 onion", "3 cloves garlic", "3 cups beef broth", "2 tbsp tomato paste", "1 tbsp Worcestershire sauce", "2 tbsp flour", "1 tsp dried rosemary", "1 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Toss beef cubes with flour, salt, and pepper. Brown in batches in oil in a large pot over medium-high heat, then set aside.", "Add diced onion to the pot and cook for 4 minutes, then add minced garlic and tomato paste, cook for 1 minute.", "Return beef to pot, add broth, Worcestershire sauce, and rosemary, bring to a boil.", "Reduce heat to low, cover, and simmer for 60 minutes.", "Add cubed potatoes and sliced carrots, simmer for 25 more minutes until vegetables are tender.", "Season to taste with salt and pepper before serving."]'::jsonb, 6, 15, 90, 2.8, 16.8, 380, 30, 30, 12, 4, 580, true, true, true, 'curated'),
  ('Baked Fish Sticks with Corn on the Cob', 'Crispy golden fish sticks baked in the oven paired with buttery sweet corn for a fun family dinner.', 'dinner', 'American', 'budget', ARRAY['baked','budget','high-protein','kid-favorite','kid-friendly','nut-free','quick','seafood','soy-free','standard']::text[], '["1.5 lbs cod fillets", "1 cup breadcrumbs", "0.5 cup flour", "2 eggs", "1 tsp garlic powder", "1 tsp paprika", "4 ears corn", "2 tbsp butter", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F. Line a baking sheet with a wire rack.", "Cut cod into strips. Set up a breading station with flour seasoned with salt and pepper, beaten eggs, and breadcrumbs mixed with garlic powder and paprika.", "Coat each fish strip in flour, then egg, then breadcrumbs and place on rack.", "Spray lightly with cooking spray and bake for 18-20 minutes until golden and crispy.", "Meanwhile, boil corn for 8 minutes until tender, drain, and serve with butter, salt, and pepper."]'::jsonb, 4, 15, 20, 2.75, 11.0, 420, 32, 44, 12, 4, 480, true, true, true, 'curated'),
  ('Chicken and Rice Casserole', 'Tender chicken thighs baked over fluffy rice infused with broth and cream of mushroom soup in one comforting dish.', 'dinner', 'Casserole', 'budget', ARRAY['american','budget','casserole','comfort-food','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','soy-free','standard']::text[], '["6 bone-in chicken thighs", "1.5 cups long-grain white rice", "1 can cream of mushroom soup", "2 cups chicken broth", "1 cup water", "1 onion", "1 tsp garlic powder", "1 tsp onion powder", "1 tsp paprika", "salt", "pepper"]'::jsonb, '["Preheat oven to 375\u00b0F. Grease a 9x13 baking dish.", "Whisk together cream of mushroom soup, chicken broth, water, garlic powder, and onion powder, then stir in diced onion.", "Pour soup mixture into baking dish and stir in uncooked rice.", "Season chicken thighs with paprika, salt, and pepper and nestle skin-side up over the rice.", "Cover tightly with foil and bake for 60 minutes.", "Uncover and bake an additional 15 minutes until chicken skin is golden and rice is fully cooked."]'::jsonb, 6, 10, 75, 2.1, 12.6, 450, 28, 46, 14, 1, 710, true, true, true, 'curated'),
  ('Spiced Lamb and Lentil Stew', 'Ground lamb simmered with red lentils and warm spices like cumin and cinnamon in a fragrant, thick stew.', 'dinner', 'Middle Eastern', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','middle-eastern','nut-free','one-pot','soy-free','standard','stew']::text[], '["1 lb ground lamb", "1.5 cups red lentils", "1 onion", "4 cloves garlic", "1 can diced tomatoes", "4 cups chicken broth", "1 tsp cumin", "1 tsp coriander", "0.5 tsp cinnamon", "0.5 tsp turmeric", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Brown ground lamb in a large pot over medium-high heat, drain excess fat.", "Add diced onion and cook for 4 minutes, then add minced garlic, cumin, coriander, cinnamon, and turmeric, cook for 1 minute.", "Stir in diced tomatoes and cook for 3 minutes.", "Add rinsed red lentils and chicken broth, bring to a boil.", "Reduce heat and simmer for 25 minutes, stirring occasionally, until lentils have broken down and stew is thick.", "Season with salt and pepper and serve with flatbread."]'::jsonb, 4, 10, 35, 2.9, 11.6, 420, 32, 34, 16, 10, 540, false, true, true, 'curated'),
  ('Egg Fried Rice with Ham and Peas', 'Classic takeout-style fried rice loaded with diced ham, sweet peas, and scrambled eggs in a savory soy sauce.', 'dinner', 'Asian', 'ultra_budget', ARRAY['asian','budget','dairy-free','fried-rice','kid-friendly','nut-free','one-pan','quick','standard']::text[], '["3 cups cooked white rice", "1 cup diced ham", "1 cup frozen peas", "3 eggs", "3 tbsp soy sauce", "1 tbsp sesame oil", "3 cloves garlic", "2 green onions", "1 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Heat vegetable oil in a large skillet or wok over high heat.", "Add minced garlic and cook for 30 seconds, then push to the side.", "Scramble eggs in the pan until just set, then break into pieces.", "Add cold rice and stir-fry for 3 minutes, breaking up clumps.", "Stir in ham and frozen peas, toss everything together for 2 minutes.", "Add soy sauce and sesame oil, toss to coat, garnish with sliced green onions."]'::jsonb, 4, 5, 15, 1.4, 5.6, 360, 18, 48, 10, 3, 720, true, true, true, 'curated'),
  ('Stuffed Bell Peppers with Ground Turkey', 'Colorful bell peppers stuffed with seasoned ground turkey, rice, and tomatoes then baked until tender and bubbly.', 'dinner', 'American', 'budget', ARRAY['american','baked','budget','egg-free','gluten-free','high-protein','kid-friendly','nut-free','soy-free','standard','stuffed']::text[], '["4 large bell peppers", "1 lb ground turkey", "1 cup white rice", "1 can diced tomatoes", "1 cup shredded mozzarella cheese", "1 onion", "2 cloves garlic", "1 tsp Italian seasoning", "1 tsp garlic powder", "2 cups tomato sauce", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions. Preheat oven to 375\u00b0F.", "Cut tops off peppers and remove seeds. Place cut-side up in a baking dish with 0.5 cup water in bottom.", "Brown ground turkey with diced onion and minced garlic in a skillet, drain fat.", "Stir in cooked rice, diced tomatoes, Italian seasoning, garlic powder, salt, and pepper.", "Fill peppers with turkey mixture, top with tomato sauce and mozzarella cheese.", "Cover with foil and bake for 35 minutes, then uncover and bake 10 more minutes until cheese is bubbly."]'::jsonb, 4, 15, 45, 2.5, 10.0, 430, 30, 42, 12, 5, 590, true, true, true, 'curated'),
  ('Pan-Seared Salmon with Garlic Butter Asparagus', 'Crispy-skinned salmon fillets served alongside asparagus spears sautéed in golden garlic butter for an elegant yet affordable dinner.', 'dinner', 'Seafood', 'standard', ARRAY['egg-free','gluten-free','high-protein','light','nut-free','quick','seafood','soy-free','standard']::text[], '["4 salmon fillets", "1 lb asparagus", "4 cloves garlic", "3 tbsp butter", "1 tbsp olive oil", "1 lemon", "1 tsp paprika", "salt", "pepper"]'::jsonb, '["Season salmon with paprika, salt, and pepper.", "Heat olive oil in a large skillet over medium-high heat and cook salmon skin-side up for 4 minutes, then flip and cook 3-4 more minutes until cooked through. Set aside.", "In the same skillet, melt butter over medium heat, add minced garlic and cook for 1 minute.", "Add asparagus spears (trimmed) and saut\u00e9 for 5-6 minutes until tender-crisp.", "Squeeze lemon over both salmon and asparagus before serving."]'::jsonb, 4, 8, 15, 4.5, 18.0, 380, 36, 6, 24, 3, 380, false, true, true, 'curated'),
  ('Creamy White Bean and Chicken Soup', 'Chunks of chicken breast simmered with cannellini beans, kale, and aromatics in a creamy, satisfying broth.', 'dinner', 'Soup', 'budget', ARRAY['budget','comfort-food','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1.5 lbs chicken breasts", "2 cans cannellini beans", "2 cups chopped kale", "1 onion", "4 cloves garlic", "4 cups chicken broth", "0.5 cup heavy cream", "2 tbsp olive oil", "1 tsp dried thyme", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large pot over medium heat. Add diced onion and cook for 5 minutes.", "Add minced garlic, thyme, and Italian seasoning, cook for 1 minute.", "Add chicken breasts and chicken broth, bring to a boil, then reduce heat and simmer for 20 minutes.", "Remove chicken, shred it, and return to pot.", "Mash one can of beans and add to soup along with whole beans and kale.", "Stir in heavy cream, simmer for 5 more minutes, season with salt and pepper."]'::jsonb, 6, 10, 30, 2.2, 13.2, 360, 34, 28, 12, 7, 580, true, true, true, 'curated'),
  ('Korean-Style Beef Bulgogi Bowls', 'Thinly sliced beef marinated in a sweet and savory soy-sesame sauce stir-fried and served over steamed rice with cucumber.', 'dinner', 'Korean', 'budget', ARRAY['budget','dairy-free','egg-free','high-protein','kid-friendly','korean','nut-free','rice-bowl','standard','stir-fry']::text[], '["1.5 lbs beef sirloin", "2 cups white rice", "1 cucumber", "4 tbsp soy sauce", "2 tbsp honey", "1 tbsp sesame oil", "4 cloves garlic", "1 tsp fresh ginger", "2 green onions", "1 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Thinly slice beef against the grain and mix with soy sauce, honey, sesame oil, minced garlic, and ginger. Marinate for 15 minutes.", "Heat vegetable oil in a large skillet over high heat and cook beef in batches for 2-3 minutes per batch until caramelized.", "Thinly slice cucumber and season with a pinch of salt.", "Serve beef over rice with cucumber slices and sliced green onions."]'::jsonb, 4, 20, 20, 2.8, 11.2, 490, 34, 50, 14, 2, 700, true, true, true, 'curated'),
  ('Chicken Enchiladas with Red Sauce', 'Rolled corn tortillas filled with shredded chicken and cheese smothered in red enchilada sauce and baked until melted and bubbly.', 'dinner', 'Mexican', 'budget', ARRAY['baked','budget','comfort-food','egg-free','gluten-free','high-protein','kid-friendly','mexican','nut-free','soy-free','standard']::text[], '["1.5 lbs chicken breasts", "10 corn tortillas", "2 cans enchilada sauce", "2 cups shredded Mexican cheese blend", "1 onion", "2 cloves garlic", "1 tsp cumin", "1 tsp chili powder", "salt", "pepper"]'::jsonb, '["Boil chicken breasts in salted water for 18 minutes, then shred and mix with diced onion, minced garlic, cumin, chili powder, salt, and pepper.", "Preheat oven to 375\u00b0F. Spread 0.5 cup enchilada sauce in a 9x13 baking dish.", "Warm tortillas briefly in microwave, then fill each with chicken mixture and a sprinkle of cheese, roll tightly and place seam-side down in dish.", "Pour remaining enchilada sauce over top and sprinkle with remaining cheese.", "Bake for 25-30 minutes until sauce is bubbling and cheese is melted."]'::jsonb, 5, 20, 45, 2.4, 12.0, 440, 32, 38, 16, 4, 740, true, true, true, 'curated'),
  ('Pork Tenderloin with Apple and Onion', 'Juicy roasted pork tenderloin paired with caramelized apples and onions for a sweet and savory one-pan dinner.', 'dinner', 'American', 'standard', ARRAY['american','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','pork','roasted','soy-free','standard']::text[], '["1.5 lbs pork tenderloin", "2 apples", "2 onions", "3 cloves garlic", "2 tbsp olive oil", "1 tbsp Dijon mustard", "1 tbsp brown sugar", "1 tsp dried thyme", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F. Rub pork with Dijon mustard, thyme, salt, and pepper.", "Heat olive oil in an oven-safe skillet over medium-high heat and sear pork on all sides for 4 minutes total.", "Slice onions and apples into wedges, toss with brown sugar, salt, and pepper, and arrange around pork.", "Add minced garlic to the pan and transfer to oven.", "Roast for 20-25 minutes until pork reaches 145\u00b0F internal temperature.", "Rest for 5 minutes before slicing, serve with pan juices."]'::jsonb, 4, 12, 30, 3.6, 14.4, 380, 36, 22, 14, 3, 420, true, true, true, 'curated'),
  ('Bean and Cheese Quesadillas with Salsa', 'Crispy flour tortillas stuffed with refried beans, cheddar cheese, and a kick of cumin served with fresh tomato salsa.', 'dinner', 'Mexican', 'ultra_budget', ARRAY['budget','egg-free','kid-favorite','kid-friendly','mexican','nut-free','quick','soy-free','vegetarian']::text[], '["8 large flour tortillas", "1 can refried beans", "2 cups shredded cheddar cheese", "0.5 tsp cumin", "3 roma tomatoes", "0.5 onion", "1 lime", "2 cloves garlic", "salt", "pepper"]'::jsonb, '["Dice tomatoes, onion, and garlic together, mix with lime juice, salt, and pepper to make salsa.", "Mix refried beans with cumin.", "Spread a thin layer of beans on one half of each tortilla and top with shredded cheddar.", "Fold tortillas in half and cook in a dry skillet over medium heat for 2-3 minutes per side until golden and cheese is melted.", "Slice into wedges and serve with fresh salsa."]'::jsonb, 4, 10, 15, 1.4, 5.6, 480, 18, 56, 18, 8, 680, true, true, true, 'curated'),
  ('Chicken Fajita Skillet', 'Sizzling strips of seasoned chicken breast cooked with vibrant bell peppers and onions served with warm flour tortillas.', 'dinner', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','high-protein','kid-friendly','mexican','nut-free','one-pan','quick','soy-free','standard']::text[], '["1.5 lbs chicken breasts", "3 bell peppers", "2 onions", "3 cloves garlic", "2 tbsp olive oil", "2 tsp cumin", "2 tsp chili powder", "1 tsp garlic powder", "1 lime", "8 flour tortillas", "salt", "pepper"]'::jsonb, '["Slice chicken, peppers, and onions into strips. Season chicken with cumin, chili powder, garlic powder, salt, and pepper.", "Heat 1 tbsp olive oil in a large skillet over high heat and cook chicken for 6-7 minutes until cooked through. Set aside.", "Add remaining oil to skillet and cook peppers and onions for 5 minutes until slightly charred.", "Return chicken to pan, add minced garlic, and toss together for 1 minute.", "Squeeze lime juice over everything and serve with warm tortillas."]'::jsonb, 4, 10, 20, 2.5, 10.0, 470, 36, 42, 14, 4, 520, true, true, true, 'curated'),
  ('Sloppy Joes on Toasted Buns', 'Sweet and tangy ground beef simmered in a homemade tomato sauce piled high on toasted hamburger buns.', 'dinner', 'American', 'ultra_budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-favorite','kid-friendly','nut-free','quick','sandwich','soy-free','standard']::text[], '["1.5 lbs ground beef", "1 can tomato sauce", "1 onion", "1 green bell pepper", "2 tbsp ketchup", "1 tbsp Worcestershire sauce", "1 tbsp brown sugar", "1 tsp mustard", "6 hamburger buns", "salt", "pepper"]'::jsonb, '["Brown ground beef with diced onion and diced bell pepper in a skillet over medium-high heat, then drain fat.", "Stir in tomato sauce, ketchup, Worcestershire sauce, brown sugar, and mustard.", "Simmer for 10-15 minutes, stirring occasionally, until sauce thickens.", "Season with salt and pepper.", "Toast hamburger buns lightly and pile with sloppy joe mixture."]'::jsonb, 6, 8, 20, 1.5, 9.0, 420, 26, 38, 16, 2, 640, true, true, true, 'curated'),
  ('Shrimp and Broccoli Lo Mein', 'Chewy egg noodles tossed with plump shrimp and fresh broccoli in a savory oyster sauce for a better-than-takeout dinner.', 'dinner', 'Asian', 'budget', ARRAY['asian','budget','dairy-free','high-protein','kid-friendly','noodles','nut-free','quick','seafood','standard','stir-fry']::text[], '["1 lb shrimp, peeled and deveined", "8 oz lo mein noodles", "3 cups broccoli florets", "3 cloves garlic", "3 tbsp soy sauce", "2 tbsp oyster sauce", "1 tbsp sesame oil", "1 tsp sugar", "1 tbsp vegetable oil", "2 green onions", "salt", "pepper"]'::jsonb, '["Cook noodles according to package directions, drain, and toss with a little sesame oil.", "Blanch broccoli in boiling water for 2 minutes, then drain.", "Mix soy sauce, oyster sauce, sesame oil, and sugar for the sauce.", "Heat vegetable oil in a wok over high heat, add shrimp and cook 2 minutes per side until pink. Set aside.", "Add minced garlic and broccoli to the wok, stir-fry for 2 minutes.", "Add noodles and shrimp, pour sauce over everything, and toss over high heat for 2 minutes until well coated."]'::jsonb, 4, 10, 20, 2.7, 10.8, 410, 28, 50, 10, 4, 820, true, true, true, 'curated'),
  ('Beef Chili with Kidney Beans', 'A bold and warming chili packed with ground beef, kidney beans, tomatoes, and a blend of smoky spices.', 'dinner', 'American', 'ultra_budget', ARRAY['american','budget','chili','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soy-free','standard']::text[], '["1.5 lbs ground beef", "2 cans kidney beans", "1 can diced tomatoes", "1 can tomato sauce", "1 onion", "3 cloves garlic", "2 tsp chili powder", "1 tsp cumin", "1 tsp smoked paprika", "0.5 tsp oregano", "1 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Brown ground beef with diced onion in a large pot over medium-high heat, then drain fat.", "Add minced garlic, chili powder, cumin, smoked paprika, and oregano, cook for 1 minute.", "Stir in diced tomatoes and tomato sauce, bring to a simmer.", "Add drained kidney beans, stir to combine.", "Simmer uncovered for 30 minutes, stirring occasionally, until chili thickens.", "Season with salt and pepper, serve with shredded cheese and crackers if desired."]'::jsonb, 6, 10, 40, 1.5, 9.0, 380, 30, 28, 14, 9, 660, true, true, true, 'curated'),
  ('Baked Meatballs in Marinara over Spaghetti', 'Classic beefy meatballs baked until golden and then simmered in rich marinara sauce served over a heap of spaghetti.', 'dinner', 'Italian', 'budget', ARRAY['baked','budget','comfort-food','high-protein','italian','kid-friendly','nut-free','pasta','soy-free','standard']::text[], '["1 lb ground beef", "0.5 lb ground pork", "1 lb spaghetti", "1 jar marinara sauce", "0.5 cup breadcrumbs", "1 egg", "0.25 cup parmesan cheese", "2 cloves garlic", "1 tsp Italian seasoning", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F. Mix beef, pork, breadcrumbs, egg, parmesan, minced garlic, Italian seasoning, garlic powder, salt, and pepper.", "Roll into 1.5-inch meatballs and place on a lined baking sheet.", "Bake for 20 minutes until browned and cooked through.", "Warm marinara sauce in a large pot and add baked meatballs, simmer for 10 minutes.", "Cook spaghetti according to package directions, drain.", "Serve meatballs and sauce over spaghetti with extra parmesan."]'::jsonb, 6, 15, 35, 2.3, 13.8, 560, 32, 62, 16, 4, 680, true, true, true, 'curated'),
  ('Tuna Noodle Casserole', 'A beloved family classic combining egg noodles, canned tuna, peas, and cream of mushroom soup baked with a crispy breadcrumb topping.', 'dinner', 'Casserole', 'ultra_budget', ARRAY['american','budget','casserole','comfort-food','high-protein','kid-friendly','nut-free','seafood','soy-free','standard']::text[], '["12 oz wide egg noodles", "2 cans tuna in water", "1 can cream of mushroom soup", "1 cup frozen peas", "0.5 cup milk", "0.5 cup sour cream", "1 cup shredded cheddar cheese", "0.5 cup breadcrumbs", "2 tbsp butter", "salt", "pepper"]'::jsonb, '["Preheat oven to 375\u00b0F. Cook egg noodles until just al dente, drain.", "Mix cream of mushroom soup, milk, sour cream, drained tuna, frozen peas, salt, and pepper in a large bowl.", "Stir in cooked noodles and half the cheddar cheese.", "Pour into a greased 9x13 baking dish and top with remaining cheese.", "Mix breadcrumbs with melted butter and sprinkle over the top.", "Bake for 30 minutes until bubbly and topping is golden brown."]'::jsonb, 6, 15, 35, 1.45, 8.7, 440, 24, 50, 14, 3, 720, true, true, true, 'curated'),
  ('Crispy Chicken Taquitos', 'Shredded seasoned chicken rolled in corn tortillas and pan-fried until golden and crunchy.', 'lunch', 'Mexican', 'budget', ARRAY['budget','egg-free','finger-food','gluten-free','high-protein','kid-friendly','mexican','nut-free','pan-fried','soy-free','standard']::text[], '["1 lb chicken thighs", "12 corn tortillas", "1 cup shredded cheddar cheese", "1 tsp cumin", "1 tsp chili powder", "1 tsp garlic powder", "salt", "pepper", "3 tbsp vegetable oil"]'::jsonb, '["Boil chicken thighs in salted water for 20 minutes, then shred with forks.", "Season shredded chicken with cumin, chili powder, garlic powder, salt, and pepper.", "Warm tortillas in a dry pan so they''re pliable.", "Place a strip of chicken and a pinch of cheese in each tortilla and roll tightly.", "Heat oil in a skillet over medium-high heat and fry taquitos seam-side down for 2-3 minutes per side until crispy.", "Drain on paper towels and serve with salsa."]'::jsonb, 4, 15, 30, 2.5, 10.0, 420, 28, 32, 18, 3, 520, true, true, true, 'curated'),
  ('Hearty Beef and Vegetable Soup', 'A thick, warming broth loaded with tender beef chunks, potatoes, carrots, and green beans.', 'lunch', 'Soup', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb beef stew meat", "3 cups beef broth", "2 potatoes", "2 carrots", "1 can green beans", "1 onion", "3 cloves garlic", "1 can diced tomatoes", "1 tsp Italian seasoning", "salt", "pepper", "1 tbsp vegetable oil"]'::jsonb, '["Heat oil in a large pot over medium-high heat and brown beef stew meat on all sides.", "Add diced onion and garlic and cook 2 minutes.", "Pour in beef broth and diced tomatoes, then bring to a boil.", "Add cubed potatoes and sliced carrots; reduce heat and simmer 20 minutes.", "Stir in drained green beans and Italian seasoning; simmer 5 more minutes.", "Season with salt and pepper and serve hot."]'::jsonb, 6, 15, 35, 2.8, 16.8, 310, 25, 28, 9, 5, 640, true, true, true, 'curated'),
  ('Turkey and Rice Stuffed Peppers', 'Colorful bell peppers packed with seasoned ground turkey, rice, and tomato sauce then baked until tender.', 'lunch', 'Baked', 'budget', ARRAY['baked','budget','comfort-food','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soy-free','standard']::text[], '["4 bell peppers", "1 lb ground turkey", "1 cup white rice", "1 can tomato sauce", "1 onion", "2 cloves garlic", "1 tsp Italian seasoning", "1 cup shredded mozzarella cheese", "salt", "pepper", "1 tbsp olive oil"]'::jsonb, '["Cook rice according to package directions and set aside.", "Preheat oven to 375\u00b0F. Cut tops off peppers and remove seeds.", "Brown ground turkey in oil with diced onion and garlic; season with salt, pepper, and Italian seasoning.", "Mix cooked rice and half the tomato sauce into the turkey.", "Fill each pepper with the turkey-rice mixture, top with remaining sauce and shredded cheese.", "Bake in a baking dish with \u00bc cup water in the bottom for 30 minutes until peppers are tender."]'::jsonb, 4, 15, 40, 2.9, 11.6, 390, 30, 38, 11, 4, 610, true, true, true, 'curated'),
  ('Black Bean and Egg Burrito Bowl', 'Fluffy scrambled eggs and seasoned black beans served over rice with salsa and shredded cheese.', 'lunch', 'Mexican', 'ultra_budget', ARRAY['budget','budget-friendly','gluten-free','high-protein','kid-friendly','mexican','nut-free','one-pot','soy-free','vegetarian']::text[], '["4 eggs", "2 cans black beans", "2 cups white rice", "1 cup salsa", "1 cup shredded cheddar cheese", "1 tsp cumin", "1 tsp chili powder", "2 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Drain and rinse black beans; heat in a saucepan with cumin and chili powder for 5 minutes.", "Scramble eggs in oil in a skillet over medium heat until just set.", "Divide rice among bowls and top with black beans, scrambled eggs, salsa, and shredded cheese.", "Season with salt and pepper to taste."]'::jsonb, 4, 5, 20, 1.3, 5.2, 460, 22, 62, 13, 10, 580, true, true, true, 'curated'),
  ('Chicken and Broccoli Stir-Fry', 'Juicy chicken breast strips and crisp broccoli florets tossed in a savory garlic-ginger sauce over steamed rice.', 'lunch', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','egg-free','high-protein','kid-friendly','nut-free','one-pan','standard','stir-fry']::text[], '["1 lb chicken breast", "3 cups broccoli florets", "2 cups white rice", "3 tbsp soy sauce", "1 tbsp cornstarch", "2 cloves garlic", "1 tsp ginger", "2 tbsp vegetable oil", "1 tbsp honey", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Slice chicken breast into thin strips and toss with cornstarch and pepper.", "Heat oil in a wok or large skillet over high heat and cook chicken until golden; remove and set aside.", "Add broccoli to the pan and stir-fry 3 minutes; add garlic and ginger for 1 more minute.", "Whisk together soy sauce and honey; add chicken back and pour in sauce.", "Toss everything together until coated and serve over rice."]'::jsonb, 4, 10, 20, 2.6, 10.4, 390, 34, 44, 8, 3, 720, true, true, true, 'curated'),
  ('Smoky Lentil and Sausage Stew', 'Earthy lentils slowly simmered with smoked sausage, carrots, and tomatoes for a deeply satisfying bowl.', 'lunch', 'Soup', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','nut-free','one-pot','smoky','soup','soy-free','standard']::text[], '["1 cup dry green lentils", "12 oz smoked sausage", "2 carrots", "1 onion", "3 cloves garlic", "1 can diced tomatoes", "4 cups chicken broth", "1 tsp smoked paprika", "1 tsp cumin", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Rinse lentils and set aside.", "Slice sausage into rounds and brown in oil in a large pot over medium heat; remove and set aside.", "Saut\u00e9 diced onion and carrots in the same pot for 4 minutes; add garlic, paprika, and cumin.", "Add lentils, diced tomatoes, and chicken broth; bring to a boil.", "Reduce heat and simmer 25 minutes until lentils are tender.", "Return sausage to the pot, season with salt and pepper, and serve."]'::jsonb, 6, 10, 35, 1.5, 9.0, 340, 22, 30, 13, 8, 730, false, true, true, 'curated'),
  ('Sheet-Pan Honey Mustard Chicken Thighs', 'Bone-in chicken thighs glazed with tangy honey mustard and roasted alongside potatoes and green beans.', 'lunch', 'Sheet-Pan', 'budget', ARRAY['baked','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','sheet-pan','soy-free','standard']::text[], '["4 chicken thighs", "1 lb baby potatoes", "2 cups green beans", "3 tbsp honey", "2 tbsp mustard", "1 tbsp olive oil", "2 cloves garlic", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F and line a sheet pan with foil.", "Whisk together honey, mustard, minced garlic, olive oil, salt, and pepper.", "Halve baby potatoes and toss with half the glaze; spread on the sheet pan.", "Roast potatoes for 15 minutes, then add chicken thighs and green beans.", "Brush chicken generously with remaining glaze and roast 30 more minutes until chicken reaches 165\u00b0F.", "Serve directly from the pan."]'::jsonb, 4, 10, 45, 2.75, 11.0, 450, 35, 34, 18, 4, 490, true, true, true, 'curated'),
  ('Ground Beef Tacos', 'Seasoned ground beef nestled in warm taco shells and topped with shredded lettuce, cheese, and tomato.', 'lunch', 'Mexican', 'budget', ARRAY['budget','egg-free','family-style','gluten-free','high-protein','kid-friendly','mexican','nut-free','quick','soy-free','standard']::text[], '["1 lb ground beef", "8 taco shells", "1 cup shredded cheddar cheese", "1 cup shredded lettuce", "1 tomato", "1 onion", "2 tbsp taco seasoning", "0.5 cup water", "0.5 cup sour cream"]'::jsonb, '["Brown ground beef with diced onion in a skillet over medium-high heat; drain excess fat.", "Stir in taco seasoning and water; simmer 5 minutes until thickened.", "Warm taco shells according to package directions.", "Fill shells with seasoned beef and top with shredded lettuce, diced tomato, cheddar cheese, and sour cream.", "Serve immediately."]'::jsonb, 4, 10, 15, 2.6, 10.4, 480, 28, 30, 26, 2, 660, true, true, true, 'curated'),
  ('Creamy Potato and Ham Soup', 'A rich, velvety soup made with diced potatoes, smoky ham, and a touch of cream for pure comfort in a bowl.', 'lunch', 'Soup', 'budget', ARRAY['budget','comfort-food','creamy','egg-free','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1.5 lbs potatoes", "1 cup diced ham", "1 onion", "3 cloves garlic", "3 cups chicken broth", "1 cup milk", "2 tbsp butter", "2 tbsp flour", "1 cup shredded cheddar cheese", "salt", "pepper"]'::jsonb, '["Melt butter in a large pot over medium heat; cook diced onion and garlic until softened.", "Whisk in flour and cook 1 minute, then gradually add chicken broth while whisking.", "Add cubed potatoes and bring to a boil; reduce heat and simmer 15 minutes until potatoes are tender.", "Stir in milk, diced ham, and cheddar cheese; cook until cheese melts.", "Season with salt and pepper and serve hot with crusty bread."]'::jsonb, 6, 15, 25, 2.2, 13.2, 310, 16, 30, 13, 3, 750, true, true, true, 'curated'),
  ('Spicy Pork and Cabbage Dumplings', 'Juicy pork and cabbage filling folded into wonton wrappers and pan-fried until crispy on the bottom.', 'lunch', 'Asian', 'budget', ARRAY['asian','budget','dairy-free','egg-free','finger-food','high-protein','nut-free','pan-fried','standard']::text[], '["0.5 lb ground pork", "2 cups shredded cabbage", "1 pkg wonton wrappers", "2 cloves garlic", "1 tsp ginger", "2 tbsp soy sauce", "1 tsp sesame oil", "0.5 tsp red pepper flakes", "2 tbsp vegetable oil", "0.25 cup water"]'::jsonb, '["Mix ground pork, shredded cabbage, garlic, ginger, soy sauce, sesame oil, and red pepper flakes in a bowl.", "Place a teaspoon of filling in the center of each wonton wrapper, wet the edges, and fold to seal.", "Heat oil in a large skillet over medium-high heat and place dumplings flat-side down.", "Cook 2-3 minutes until bottoms are golden, then carefully add water to the pan.", "Cover with a lid and steam 4-5 minutes until wrappers are cooked through.", "Remove lid, let remaining water evaporate, and serve with soy sauce for dipping."]'::jsonb, 4, 25, 15, 2.4, 9.6, 360, 20, 38, 13, 2, 680, false, true, true, 'curated'),
  ('Baja Fish Tacos with Slaw', 'Crispy battered white fish tucked into corn tortillas with a tangy cabbage slaw and a squeeze of lime.', 'lunch', 'Mexican', 'budget', ARRAY['budget','egg-free','fresh','high-protein','kid-friendly','mexican','nut-free','pan-fried','seafood','soy-free','standard']::text[], '["1 lb tilapia fillets", "8 corn tortillas", "2 cups shredded cabbage", "0.5 cup sour cream", "2 limes", "0.5 cup flour", "1 tsp chili powder", "1 tsp garlic powder", "salt", "pepper", "3 tbsp vegetable oil"]'::jsonb, '["Mix shredded cabbage with sour cream, juice of 1 lime, salt, and pepper; refrigerate slaw.", "Cut tilapia into strips; season flour with chili powder, garlic powder, salt, and pepper.", "Dredge fish in seasoned flour, shaking off excess.", "Fry fish in hot oil in a skillet over medium-high heat for 2-3 minutes per side until golden.", "Warm tortillas in a dry pan and fill with fish and slaw.", "Squeeze remaining lime over tacos and serve."]'::jsonb, 4, 15, 15, 2.9, 11.6, 370, 26, 35, 13, 3, 430, true, true, true, 'curated'),
  ('Classic Chicken Caesar Wrap', 'Grilled chicken strips and crisp romaine lettuce tossed in Caesar dressing and rolled in a flour tortilla.', 'lunch', 'Wrap', 'budget', ARRAY['american','budget','egg-free','high-protein','kid-friendly','nut-free','quick','soy-free','standard','wrap']::text[], '["2 chicken breasts", "4 large flour tortillas", "3 cups romaine lettuce", "0.5 cup Caesar dressing", "0.5 cup shredded Parmesan cheese", "1 cup croutons", "1 tsp garlic powder", "salt", "pepper", "1 tbsp olive oil"]'::jsonb, '["Season chicken breasts with garlic powder, salt, and pepper.", "Cook chicken in olive oil over medium heat 6-7 minutes per side until cooked through; let rest and slice.", "Toss romaine lettuce with Caesar dressing.", "Layer tortilla with dressed lettuce, sliced chicken, Parmesan, and croutons.", "Roll tightly, tucking in the sides, and cut in half to serve."]'::jsonb, 4, 10, 15, 2.8, 11.2, 450, 32, 38, 18, 2, 810, true, true, true, 'curated'),
  ('Teriyaki Beef Bowl', 'Thinly sliced beef sirloin glazed with homemade teriyaki sauce served over steamed white rice with broccoli.', 'lunch', 'Asian', 'standard', ARRAY['asian','dairy-free','egg-free','high-protein','kid-friendly','nut-free','one-pan','quick','standard']::text[], '["1 lb beef sirloin", "2 cups white rice", "2 cups broccoli florets", "3 tbsp soy sauce", "2 tbsp honey", "1 tbsp cornstarch", "1 clove garlic", "1 tsp ginger", "2 tbsp vegetable oil", "2 tbsp water"]'::jsonb, '["Cook rice according to package directions and steam broccoli until tender-crisp.", "Slice beef sirloin very thinly against the grain.", "Whisk together soy sauce, honey, cornstarch, garlic, ginger, and water to make the teriyaki sauce.", "Sear beef strips in hot oil over high heat for 1-2 minutes.", "Pour in teriyaki sauce and cook 1-2 minutes until sauce thickens and coats the beef.", "Serve beef and broccoli over rice."]'::jsonb, 4, 10, 20, 3.8, 15.2, 490, 32, 54, 14, 3, 740, true, true, true, 'curated'),
  ('White Bean and Chicken Chili', 'A white chili with tender chunks of chicken, creamy white beans, green chiles, and warming spices.', 'lunch', 'Chili', 'budget', ARRAY['budget','comfort-food','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb chicken breast", "2 cans white beans", "1 can diced green chiles", "1 onion", "3 cloves garlic", "3 cups chicken broth", "1 tsp cumin", "1 tsp chili powder", "0.5 tsp oregano", "1 tbsp olive oil", "1 cup sour cream", "salt", "pepper"]'::jsonb, '["Dice chicken breast and cook in olive oil over medium heat until cooked through; set aside.", "Saut\u00e9 onion and garlic in the same pot until softened.", "Add cumin, chili powder, and oregano and cook 1 minute.", "Pour in chicken broth, white beans, and green chiles; bring to a simmer.", "Return chicken to the pot and simmer 15 minutes.", "Stir in sour cream, season with salt and pepper, and serve."]'::jsonb, 6, 10, 25, 2.3, 13.8, 350, 30, 32, 10, 8, 640, true, true, true, 'curated'),
  ('Egg Salad Sandwich', 'Creamy, tangy egg salad piled high on toasted bread with crisp lettuce and sliced tomato.', 'lunch', 'Sandwich', 'ultra_budget', ARRAY['american','budget','budget-friendly','dairy-free','kid-friendly','nut-free','quick','sandwich','soy-free','vegetarian']::text[], '["6 eggs", "8 slices sandwich bread", "3 tbsp mayonnaise", "1 tsp mustard", "1 tbsp pickle relish", "1 cup shredded lettuce", "1 tomato", "salt", "pepper"]'::jsonb, '["Hard-boil eggs by placing in cold water, bringing to a boil, and cooking 10 minutes.", "Cool eggs in ice water, peel, and roughly chop.", "Mix chopped eggs with mayonnaise, mustard, pickle relish, salt, and pepper.", "Toast bread slices to your preference.", "Spread egg salad generously on bread and top with shredded lettuce and tomato slices.", "Close sandwich, cut diagonally, and serve."]'::jsonb, 4, 10, 12, 1.1, 4.4, 340, 16, 28, 17, 2, 510, true, true, true, 'curated'),
  ('Sloppy Joe Sliders', 'Sweet and tangy ground beef in a rich tomato sauce piled onto soft dinner rolls for a crowd-pleasing meal.', 'lunch', 'American', 'budget', ARRAY['american','budget','dairy-free','egg-free','family-style','gluten-free','high-protein','kid-friendly','nut-free','quick','soy-free','standard']::text[], '["1 lb ground beef", "1 pkg dinner rolls", "1 can tomato sauce", "2 tbsp ketchup", "1 tbsp brown sugar", "1 tbsp Worcestershire sauce", "1 onion", "1 bell pepper", "salt", "pepper", "1 tbsp vegetable oil"]'::jsonb, '["Brown ground beef in oil with diced onion and bell pepper over medium-high heat; drain fat.", "Stir in tomato sauce, ketchup, brown sugar, and Worcestershire sauce.", "Simmer on low heat for 10 minutes, stirring occasionally, until thickened.", "Season with salt and pepper.", "Spoon sloppy joe mixture onto slider rolls and serve."]'::jsonb, 6, 10, 20, 1.9, 11.4, 380, 22, 40, 14, 2, 620, true, true, true, 'curated'),
  ('Korean-Style Ground Beef Rice Bowl', 'Savory ground beef seasoned with soy sauce, sesame, and a hint of heat spooned over fluffy steamed rice.', 'lunch', 'Asian', 'budget', ARRAY['asian','budget','dairy-free','egg-free','high-protein','kid-friendly','nut-free','one-pan','quick','standard']::text[], '["1 lb ground beef", "2 cups white rice", "3 tbsp soy sauce", "1 tbsp brown sugar", "1 tsp sesame oil", "3 cloves garlic", "1 tsp ginger", "0.5 tsp red pepper flakes", "2 green onions", "1 tbsp vegetable oil"]'::jsonb, '["Cook rice according to package directions.", "Brown ground beef in oil in a skillet over medium-high heat, breaking it apart.", "Add garlic and ginger and cook 1 minute.", "Stir in soy sauce, brown sugar, sesame oil, and red pepper flakes; cook 2 minutes until combined.", "Serve beef mixture over rice and garnish with sliced green onions."]'::jsonb, 4, 5, 15, 2.5, 10.0, 470, 28, 48, 17, 1, 760, true, true, true, 'curated'),
  ('BLT Pasta Salad', 'A crowd-pleasing cold pasta salad tossed with crispy bacon, cherry tomatoes, lettuce, and a creamy ranch dressing.', 'lunch', 'Pasta Salad', 'budget', ARRAY['american','budget','cold','egg-free','kid-friendly','nut-free','pasta','quick','soy-free','standard']::text[], '["8 oz rotini pasta", "6 slices bacon", "1 cup cherry tomatoes", "2 cups romaine lettuce", "0.5 cup ranch dressing", "0.5 cup shredded cheddar cheese", "salt", "pepper"]'::jsonb, '["Cook pasta according to package directions; rinse with cold water and drain.", "Cook bacon until crispy, crumble, and set aside.", "Halve cherry tomatoes and chop romaine into bite-sized pieces.", "Combine pasta, bacon, tomatoes, lettuce, and cheese in a large bowl.", "Toss with ranch dressing and season with salt and pepper.", "Refrigerate 15 minutes before serving for best flavor."]'::jsonb, 4, 15, 15, 2.1, 8.4, 420, 16, 44, 20, 3, 690, true, true, true, 'curated'),
  ('Spiced Chickpea and Spinach Stew', 'Tender chickpeas and wilted spinach simmered in a tomato broth fragrant with cumin and smoked paprika.', 'lunch', 'Mediterranean', 'ultra_budget', ARRAY['budget','budget-friendly','dairy-free','egg-free','gluten-free','mediterranean','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["2 cans chickpeas", "3 cups fresh spinach", "1 can diced tomatoes", "1 onion", "4 cloves garlic", "2 cups vegetable broth", "1 tsp cumin", "1 tsp smoked paprika", "0.5 tsp coriander", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large pot over medium heat; saut\u00e9 diced onion and garlic 5 minutes.", "Add cumin, paprika, and coriander and toast spices 1 minute.", "Stir in diced tomatoes and vegetable broth; bring to a simmer.", "Add drained chickpeas and simmer 15 minutes.", "Stir in fresh spinach and cook until wilted, about 2 minutes.", "Season with salt and pepper and serve with crusty bread."]'::jsonb, 4, 10, 25, 1.4, 5.6, 280, 13, 40, 9, 10, 560, false, true, true, 'curated'),
  ('Chicken Quesadillas with Peppers', 'Melty cheese, seasoned chicken, and sautéed peppers sandwiched in a crispy flour tortilla and cut into wedges.', 'lunch', 'Mexican', 'budget', ARRAY['budget','egg-free','family-style','high-protein','kid-friendly','mexican','nut-free','quick','soy-free','standard']::text[], '["2 chicken breasts", "4 large flour tortillas", "2 cups shredded Mexican cheese blend", "2 bell peppers", "1 onion", "1 tsp cumin", "1 tsp chili powder", "2 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Season and cook chicken breasts in 1 tbsp oil over medium heat until done; shred or slice thin.", "Saut\u00e9 sliced peppers and onions in the same pan until softened.", "Layer one tortilla with cheese, chicken, pepper mixture, and more cheese; top with second tortilla.", "Cook quesadilla in a lightly oiled skillet over medium heat 3 minutes per side until golden.", "Cut into wedges and serve with salsa and sour cream."]'::jsonb, 4, 10, 20, 2.7, 10.8, 480, 33, 36, 22, 3, 730, true, true, true, 'curated'),
  ('Tomato Basil Soup with Grilled Cheese Dippers', 'Smooth, vibrant tomato soup made from canned tomatoes and served alongside crispy golden grilled cheese strips.', 'lunch', 'Soup', 'ultra_budget', ARRAY['american','budget','comfort-food','egg-free','kid-friendly','nut-free','quick','soup','soy-free','standard']::text[], '["2 cans crushed tomatoes", "1 onion", "3 cloves garlic", "2 cups chicken broth", "0.5 cup heavy cream", "1 tsp dried basil", "4 slices sandwich bread", "4 slices American cheese", "3 tbsp butter", "salt", "pepper", "1 tbsp olive oil"]'::jsonb, '["Saut\u00e9 diced onion and garlic in olive oil over medium heat until soft.", "Add crushed tomatoes, chicken broth, and dried basil; bring to a simmer and cook 15 minutes.", "Blend soup until smooth using an immersion blender; stir in heavy cream.", "Season with salt and pepper and keep warm.", "Butter bread slices and assemble cheese sandwiches; cook in a skillet over medium heat until golden on both sides.", "Cut grilled cheese into strips and serve alongside hot soup for dipping."]'::jsonb, 4, 10, 25, 1.5, 6.0, 380, 12, 34, 22, 4, 820, true, true, true, 'curated'),
  ('Pork Carnitas Bowls', 'Slow-cooked shredded pork crisped in a skillet and served in a bowl with rice, black beans, and fresh pico de gallo.', 'lunch', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','family-style','gluten-free','high-protein','kid-friendly','mexican','nut-free','slow-cooked','soy-free','standard']::text[], '["1.5 lbs pork shoulder", "2 cups white rice", "1 can black beans", "1 orange", "1 lime", "3 cloves garlic", "1 tsp cumin", "1 tsp chili powder", "1 tsp oregano", "salt", "pepper", "2 tomatoes", "0.5 onion", "1 tbsp vegetable oil"]'::jsonb, '["Season pork shoulder with cumin, chili powder, oregano, salt, and pepper.", "Place pork in a pot with squeezed orange juice, lime juice, and garlic; cover with water and simmer 90 minutes until tender.", "Shred pork and pan-fry in oil over high heat until edges crisp up.", "Cook rice and warm black beans.", "Dice tomatoes and remaining onion to make a quick pico de gallo with lime juice and salt.", "Assemble bowls with rice, beans, carnitas, and pico de gallo."]'::jsonb, 6, 15, 100, 2.8, 16.8, 490, 32, 52, 14, 7, 580, true, true, true, 'curated'),
  ('Philly Cheesesteak Sandwiches', 'Thinly sliced beef, sautéed peppers and onions, and gooey melted provolone piled into hoagie rolls.', 'lunch', 'American', 'standard', ARRAY['american','comfort-food','egg-free','gluten-free','high-protein','kid-friendly','nut-free','sandwich','soy-free','standard']::text[], '["1 lb beef sirloin", "4 hoagie rolls", "4 slices provolone cheese", "2 bell peppers", "1 onion", "2 tbsp vegetable oil", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Freeze beef for 30 minutes to make slicing thin easier; slice paper thin.", "Saut\u00e9 sliced peppers and onions in 1 tbsp oil over medium-high heat until softened; season and set aside.", "Cook thin beef slices in remaining oil over high heat, seasoning with garlic powder, salt, and pepper.", "Arrange pepper and onion mixture over beef in the pan and top with provolone slices; let cheese melt.", "Scoop mixture into toasted hoagie rolls and serve immediately."]'::jsonb, 4, 35, 15, 3.9, 15.6, 520, 34, 44, 22, 3, 780, true, true, true, 'curated'),
  ('Southwest Chicken Salad', 'Grilled chicken over a bed of romaine with corn, black beans, tomatoes, avocado, and a zesty lime dressing.', 'lunch', 'Salad', 'budget', ARRAY['american','budget','dairy-free','egg-free','fresh','gluten-free','high-protein','kid-friendly','nut-free','salad','soy-free','standard']::text[], '["2 chicken breasts", "4 cups romaine lettuce", "1 can black beans", "1 cup frozen corn", "1 cup cherry tomatoes", "1 avocado", "3 tbsp olive oil", "2 limes", "1 tsp cumin", "1 tsp chili powder", "salt", "pepper"]'::jsonb, '["Season chicken with chili powder, cumin, salt, and pepper; grill or pan-cook 6-7 minutes per side until done.", "Thaw corn and drain and rinse black beans.", "Whisk together olive oil, lime juice, cumin, salt, and pepper to make the dressing.", "Arrange romaine on plates and top with corn, black beans, halved cherry tomatoes, and diced avocado.", "Slice chicken and lay over the salad; drizzle with lime dressing and serve."]'::jsonb, 4, 10, 15, 2.95, 11.8, 420, 32, 30, 19, 9, 420, true, true, true, 'curated'),
  ('Sausage and Egg Breakfast Burritos', 'Scrambled eggs, savory pork sausage, and melted cheddar wrapped in a warm flour tortilla for a hearty handheld morning meal.', 'breakfast', 'Mexican', 'budget', ARRAY['budget','high-protein','kid-friendly','mexican','nut-free','one-pan','soy-free','standard','wrap']::text[], '["1 lb pork breakfast sausage", "6 eggs", "1 cup shredded cheddar cheese", "6 flour tortillas", "1 onion", "1 bell pepper", "2 tbsp butter", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Cook sausage in a skillet over medium heat, breaking it up, until browned. Remove and set aside.", "In the same skillet, melt butter and saut\u00e9 diced onion and bell pepper for 3 minutes.", "Whisk eggs with garlic powder, salt, and pepper, then pour into the skillet and scramble until just set.", "Stir sausage back in and remove from heat.", "Warm tortillas, fill with egg mixture, top with cheddar, roll up and serve."]'::jsonb, 6, 10, 15, 1.85, 11.1, 450, 24, 32, 24, 2, 680, true, true, true, 'curated'),
  ('Classic Fluffy Buttermilk Pancakes', 'Light and tender buttermilk pancakes cooked to a golden brown and served with maple syrup for a timeless weekend breakfast.', 'breakfast', 'American', 'ultra_budget', ARRAY['american','budget','classic','kid-friendly','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["2 cups all-purpose flour", "2 tbsp sugar", "2 tsp baking powder", "1 tsp baking soda", "1 tsp salt", "2 cups buttermilk", "2 eggs", "3 tbsp butter", "1 tsp vanilla extract"]'::jsonb, '["Whisk flour, sugar, baking powder, baking soda, and salt in a large bowl.", "In another bowl, whisk buttermilk, eggs, melted butter, and vanilla.", "Pour wet ingredients into dry and stir gently until just combined \u2014 a few lumps are fine.", "Heat a nonstick skillet over medium heat and lightly butter it.", "Pour 1/4 cup batter per pancake and cook until bubbles form, about 2 minutes, then flip and cook 1 more minute.", "Serve stacked with butter and maple syrup."]'::jsonb, 4, 10, 20, 0.85, 3.4, 320, 10, 48, 10, 1, 520, true, true, true, 'curated'),
  ('Cheesy Southwest Scrambled Eggs', 'Fluffy eggs scrambled with black beans, corn, and pepper jack cheese for a bold, colorful morning plate.', 'breakfast', 'Southwest', 'ultra_budget', ARRAY['budget','gluten-free','high-protein','kid-friendly','nut-free','one-pan','quick','southwest','soy-free','vegetarian']::text[], '["6 eggs", "1 can black beans", "1 cup frozen corn", "1 cup shredded pepper jack cheese", "1 tsp cumin", "1 tsp chili powder", "1 tbsp butter", "salt", "pepper"]'::jsonb, '["Drain and rinse black beans. Thaw corn if needed.", "Melt butter in a skillet over medium heat and add beans and corn, cooking 2 minutes.", "Whisk eggs with cumin, chili powder, salt, and pepper and pour over the bean mixture.", "Scramble gently until eggs are just cooked through.", "Top with pepper jack cheese, cover for 30 seconds to melt, then serve."]'::jsonb, 4, 5, 10, 1.3, 5.2, 310, 22, 22, 16, 5, 540, true, true, true, 'curated'),
  ('Sheet-Pan Turkey Sausage and Veggie Hash', 'Diced turkey sausage, potatoes, and colorful peppers roasted together on one pan for an easy, satisfying morning meal.', 'breakfast', 'Sheet-Pan', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','sheet-pan','soy-free','standard']::text[], '["1 lb turkey sausage links", "4 medium potatoes", "1 red bell pepper", "1 green bell pepper", "1 onion", "2 tbsp olive oil", "1 tsp smoked paprika", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F. Dice potatoes, peppers, and onion into 1-inch pieces.", "Slice turkey sausage into coins.", "Toss all ingredients with olive oil, smoked paprika, garlic powder, salt, and pepper on a large sheet pan.", "Spread in a single layer and roast 30-35 minutes, stirring once halfway, until potatoes are golden and sausage is cooked through.", "Serve hot directly from the pan."]'::jsonb, 4, 10, 35, 2.4, 9.6, 380, 22, 36, 16, 4, 620, true, true, true, 'curated'),
  ('Cinnamon French Toast with Maple Glaze', 'Thick slices of bread soaked in a spiced egg custard and pan-fried to a caramelized golden crust, finished with warm maple syrup.', 'breakfast', 'American', 'ultra_budget', ARRAY['american','budget','classic','kid-friendly','nut-free','one-pan','quick','soy-free','sweet','vegetarian']::text[], '["8 slices white sandwich bread", "3 eggs", "1 cup milk", "1 tsp cinnamon", "1 tsp vanilla extract", "1 tbsp sugar", "2 tbsp butter", "maple syrup"]'::jsonb, '["Whisk eggs, milk, cinnamon, vanilla, and sugar in a shallow bowl.", "Heat 1 tablespoon butter in a large skillet over medium heat.", "Dip bread slices in egg mixture, letting each side absorb for 10 seconds.", "Cook in batches for 2-3 minutes per side until golden brown, adding remaining butter as needed.", "Serve immediately with maple syrup."]'::jsonb, 4, 5, 15, 0.9, 3.6, 295, 10, 40, 10, 1, 330, true, true, true, 'curated'),
  ('Beef and Potato Breakfast Hash', 'Seasoned ground beef and crispy diced potatoes cooked together in a skillet with onions and garlic for a filling morning plate.', 'breakfast', 'American', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','hearty','high-protein','kid-friendly','nut-free','one-pan','soy-free','standard']::text[], '["1 lb ground beef", "4 medium potatoes", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp Worcestershire sauce", "1 tsp smoked paprika", "salt", "pepper"]'::jsonb, '["Dice potatoes into small cubes and microwave on high for 4 minutes to par-cook.", "Heat olive oil in a large skillet over medium-high heat. Add potatoes and cook without stirring for 3-4 minutes until browned.", "Push potatoes to the side, add ground beef and cook, breaking it up, until no longer pink.", "Stir in diced onion and minced garlic and cook 3 more minutes.", "Season with smoked paprika, Worcestershire, salt, and pepper, then stir everything together and serve."]'::jsonb, 4, 10, 20, 2.7, 10.8, 420, 27, 30, 20, 3, 460, true, true, true, 'curated'),
  ('Spinach and Feta Egg Muffins', 'Individual baked egg cups packed with fresh spinach and crumbled feta cheese, perfect for a grab-and-go morning.', 'breakfast', 'American', 'ultra_budget', ARRAY['baked','budget','gluten-free','meal-prep','nut-free','quick','soy-free','vegetarian']::text[], '["6 eggs", "2 cups fresh spinach", "1/2 cup crumbled feta cheese", "1/4 cup milk", "1 clove garlic", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Preheat oven to 375\u00b0F and grease a muffin tin with olive oil.", "Saut\u00e9 spinach with minced garlic in a skillet for 1-2 minutes until wilted; let cool slightly.", "Whisk eggs with milk, salt, and pepper.", "Divide spinach among 6 muffin cups, pour egg mixture over each, and top with feta.", "Bake 18-22 minutes until set and lightly golden on top.", "Cool for 5 minutes before removing from tin."]'::jsonb, 6, 10, 22, 1.5, 9.0, 130, 10, 2, 9, 0, 320, false, true, true, 'curated'),
  ('Chorizo and Potato Breakfast Skillet', 'Spicy Mexican chorizo crumbled over crispy golden potatoes and topped with runny fried eggs for a bold and satisfying breakfast.', 'breakfast', 'Mexican', 'budget', ARRAY['budget','dairy-free','gluten-free','high-protein','mexican','nut-free','one-pan','soy-free','spicy','vegetarian']::text[], '["1/2 lb Mexican chorizo", "4 medium potatoes", "4 eggs", "1 onion", "2 cloves garlic", "1 tbsp oil", "1 tsp cumin", "salt", "pepper"]'::jsonb, '["Dice and par-cook potatoes in the microwave for 4 minutes.", "Heat oil in a skillet over medium-high heat, add potatoes, and fry until crispy, about 8 minutes.", "Remove potatoes and cook chorizo, breaking it up, until browned. Add diced onion and garlic and cook 2 minutes.", "Stir potatoes back in, season with cumin, salt, and pepper.", "Make 4 wells in the hash, crack an egg into each, cover, and cook until whites are set.", "Serve straight from the skillet."]'::jsonb, 4, 10, 20, 2.2, 8.8, 430, 24, 31, 24, 3, 710, false, true, true, 'curated'),
  ('Banana Oat Breakfast Cookies', 'Mashed ripe bananas and rolled oats come together in soft, chewy no-fuss baked cookies that make a sweet and filling morning treat.', 'breakfast', 'American', 'ultra_budget', ARRAY['baked','budget','dairy-free','egg-free','gluten-free','kid-favorite','kid-friendly','meal-prep','nut-free','quick','soy-free','sweet','vegetarian']::text[], '["3 ripe bananas", "2 cups rolled oats", "1/4 cup honey", "1 tsp cinnamon", "1 tsp vanilla extract", "1/4 cup raisins", "1 pinch salt"]'::jsonb, '["Preheat oven to 350\u00b0F and line a baking sheet with parchment paper.", "Mash bananas thoroughly in a large bowl.", "Stir in oats, honey, cinnamon, vanilla, raisins, and salt until fully combined.", "Drop heaping tablespoons onto the baking sheet and flatten slightly.", "Bake 14-16 minutes until set and lightly golden on the edges.", "Cool on the pan for 5 minutes before serving."]'::jsonb, 4, 10, 16, 0.75, 3.0, 270, 5, 56, 3, 5, 60, true, true, true, 'curated'),
  ('Ham and Swiss Breakfast Casserole', 'A baked egg casserole layered with diced ham, Swiss cheese, and cubed bread that is perfect for feeding a crowd on a lazy morning.', 'breakfast', 'American', 'budget', ARRAY['american','baked','budget','casserole','high-protein','kid-friendly','meal-prep','nut-free','soy-free','standard']::text[], '["1 lb diced ham", "6 eggs", "2 cups milk", "4 cups cubed white bread", "1 1/2 cups shredded Swiss cheese", "1 tsp dry mustard", "1 tsp garlic powder", "salt", "pepper", "1 tbsp butter"]'::jsonb, '["Butter a 9x13 baking dish. Spread bread cubes evenly on the bottom.", "Layer diced ham over the bread and top with Swiss cheese.", "Whisk eggs, milk, dry mustard, garlic powder, salt, and pepper and pour evenly over the casserole.", "Cover and refrigerate at least 30 minutes or overnight.", "Preheat oven to 350\u00b0F and bake uncovered for 40-45 minutes until golden and set in the center.", "Rest 10 minutes before slicing and serving."]'::jsonb, 6, 15, 45, 2.5, 15.0, 360, 28, 22, 18, 1, 820, true, true, true, 'curated'),
  ('Homestyle Biscuits and Sausage Gravy', 'Flaky homemade drop biscuits smothered in a creamy, peppery pork sausage gravy — a Southern breakfast staple that sticks to your ribs.', 'breakfast', 'Southern', 'budget', ARRAY['american','budget','comfort-food','egg-free','hearty','high-protein','kid-friendly','nut-free','one-pan','southern','soy-free','standard']::text[], '["1 lb pork breakfast sausage", "2 cups all-purpose flour", "1 tbsp baking powder", "1 tsp salt", "1/3 cup butter", "3/4 cup milk", "3 tbsp all-purpose flour", "2 1/2 cups milk", "1 tsp black pepper", "1/2 tsp salt"]'::jsonb, '["Preheat oven to 450\u00b0F. Mix 2 cups flour, baking powder, and 1 tsp salt. Cut in butter until crumbly, stir in 3/4 cup milk.", "Drop spoonfuls onto a greased baking sheet and bake 10-12 minutes until golden.", "Meanwhile, cook sausage in a large skillet over medium heat, breaking it up, until browned.", "Sprinkle 3 tablespoons flour over sausage and stir to coat; cook 1 minute.", "Gradually whisk in 2 1/2 cups milk, stirring constantly until gravy thickens, about 5 minutes.", "Season with black pepper and salt, then ladle generously over split biscuits."]'::jsonb, 5, 15, 20, 1.8, 9.0, 520, 22, 46, 28, 1, 900, true, true, true, 'curated'),
  ('Avocado Toast with a Fried Egg', 'Creamy mashed avocado spread on toasted bread and crowned with a perfectly fried egg for a simple yet restaurant-worthy morning meal.', 'breakfast', 'American', 'budget', ARRAY['american','budget','dairy-free','kid-friendly','nut-free','quick','soy-free','trendy','vegetarian']::text[], '["4 slices whole wheat bread", "2 avocados", "4 eggs", "1 lemon", "1/2 tsp red pepper flakes", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Toast bread slices to your preferred doneness.", "Halve avocados, remove pits, and scoop flesh into a bowl. Add a squeeze of lemon juice, salt, and pepper and mash to desired consistency.", "Heat olive oil in a nonstick skillet over medium heat. Crack eggs in and fry 2-3 minutes until whites are set.", "Spread avocado mash generously on each toast.", "Top each with a fried egg, a pinch of red pepper flakes, and an extra grind of pepper. Serve immediately."]'::jsonb, 4, 5, 5, 1.75, 7.0, 310, 12, 24, 20, 7, 290, true, true, true, 'curated'),
  ('Apple Cinnamon Overnight Oats', 'Creamy rolled oats soaked overnight in milk with sweet diced apple and warming cinnamon for a no-cook breakfast ready when you wake up.', 'breakfast', 'American', 'ultra_budget', ARRAY['american','budget','egg-free','gluten-free','kid-friendly','meal-prep','no-cook','nut-free','quick','soy-free','sweet','vegetarian']::text[], '["2 cups rolled oats", "2 cups milk", "2 apples", "2 tbsp honey", "1 tsp cinnamon", "1/4 tsp nutmeg", "1 tsp vanilla extract", "1 pinch salt"]'::jsonb, '["Divide rolled oats evenly among 4 mason jars or containers.", "Pour 1/2 cup milk into each jar and stir in honey, cinnamon, nutmeg, vanilla, and salt.", "Core and finely dice apples and divide among the jars, stirring to combine.", "Seal and refrigerate overnight or at least 6 hours.", "Stir before eating and add a splash more milk if needed. Serve cold or microwave 1-2 minutes."]'::jsonb, 4, 10, 0, 0.9, 3.6, 280, 8, 52, 5, 5, 75, true, true, true, 'curated'),
  ('Denver Omelette', 'A classic folded omelette stuffed with diced ham, onion, and green pepper then finished with melted cheddar for a diner-style breakfast at home.', 'breakfast', 'American', 'budget', ARRAY['american','budget','classic','diner-style','gluten-free','high-protein','kid-friendly','nut-free','one-pan','soy-free','standard']::text[], '["8 eggs", "1 cup diced ham", "1/2 onion", "1 green bell pepper", "1 cup shredded cheddar cheese", "2 tbsp butter", "2 tbsp milk", "salt", "pepper"]'::jsonb, '["Melt 1 tablespoon butter in an omelette pan over medium heat. Saut\u00e9 diced onion, bell pepper, and ham for 3-4 minutes. Remove and set aside.", "Whisk 2 eggs with a splash of milk, salt, and pepper for each omelette.", "Melt a small amount of butter in the pan over medium-low heat and pour in the egg mixture.", "As eggs begin to set, lift edges and tilt pan to let raw egg flow underneath.", "When nearly set, spoon filling on one half and sprinkle with cheddar.", "Fold omelette over and slide onto a plate. Repeat for remaining omelettes."]'::jsonb, 4, 10, 20, 2.1, 8.4, 320, 26, 4, 22, 1, 640, true, true, true, 'curated'),
  ('Savory Chicken and Waffle Bites', 'Mini waffles topped with juicy seasoned chicken tenders and a drizzle of honey butter for a crowd-pleasing sweet-and-savory morning plate.', 'breakfast', 'Southern', 'budget', ARRAY['american','baked','budget','egg-free','gluten-free','high-protein','kid-friendly','nut-free','southern','soy-free','standard','sweet-and-savory']::text[], '["1 lb chicken tenders", "2 cups pancake mix", "1 1/2 cups water", "1 tsp garlic powder", "1 tsp smoked paprika", "1/2 tsp cayenne pepper", "2 tbsp butter", "2 tbsp honey", "salt", "pepper"]'::jsonb, '["Season chicken tenders with garlic powder, smoked paprika, cayenne, salt, and pepper.", "Cook chicken in a lightly oiled skillet over medium-high heat for 4-5 minutes per side until cooked through.", "Meanwhile, prepare waffle batter by mixing pancake mix and water per package directions.", "Cook in a waffle iron until golden. Cut into quarters for bites.", "Melt butter with honey in a small saucepan over low heat.", "Serve chicken pieces over waffle bites with honey butter drizzled over the top."]'::jsonb, 4, 10, 20, 2.8, 11.2, 440, 30, 48, 14, 1, 700, true, true, true, 'curated'),
  ('Bacon and Cheddar Breakfast Quesadillas', 'Crispy bacon and gooey cheddar cheese melted inside a toasted flour tortilla for a simple but deeply satisfying morning quesadilla.', 'breakfast', 'Mexican', 'budget', ARRAY['budget','high-protein','kid-favorite','kid-friendly','mexican','nut-free','one-pan','quick','soy-free','standard']::text[], '["8 strips bacon", "4 large flour tortillas", "1 1/2 cups shredded cheddar cheese", "4 eggs", "2 tbsp butter", "salt", "pepper"]'::jsonb, '["Cook bacon in a skillet until crispy; drain on paper towels and crumble.", "Scramble eggs in the same skillet over medium heat with butter, salt, and pepper until just set.", "Lay tortillas flat and cover half of each with scrambled eggs, crumbled bacon, and cheddar cheese.", "Fold tortillas in half and cook in a dry skillet or griddle over medium heat for 2-3 minutes per side until toasted and cheese is melted.", "Slice into wedges and serve hot."]'::jsonb, 4, 5, 15, 2.3, 9.2, 490, 25, 34, 28, 1, 860, true, true, true, 'curated'),
  ('Loaded Breakfast Grits Bowl', 'Creamy stone-ground grits topped with a fried egg, crumbled bacon, and sharp cheddar for a rich, comforting Southern bowl.', 'breakfast', 'Southern', 'budget', ARRAY['budget','comfort-food','gluten-free','hearty','high-protein','kid-friendly','nut-free','one-pot','southern','soy-free','standard']::text[], '["1 cup quick-cooking grits", "4 cups water", "6 strips bacon", "4 eggs", "1 cup shredded sharp cheddar cheese", "2 tbsp butter", "1/2 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Bring water to a boil in a medium saucepan. Whisk in grits, reduce heat, and cook stirring frequently for 5-7 minutes.", "Remove grits from heat and stir in butter, garlic powder, half the cheese, salt, and pepper.", "Cook bacon in a skillet until crispy; set aside on paper towels and crumble.", "In the same skillet, fry eggs to your liking.", "Divide grits among bowls, top each with a fried egg, crumbled bacon, remaining cheddar, and a pinch of pepper."]'::jsonb, 4, 5, 15, 1.9, 7.6, 390, 20, 30, 22, 1, 680, true, true, true, 'curated'),
  ('Pork and Vegetable Fried Rice Breakfast Bowl', 'Day-old rice stir-fried with ground pork, carrots, peas, and scrambled egg and seasoned with soy sauce for an Asian-inspired morning bowl.', 'breakfast', 'Asian', 'budget', ARRAY['asian','budget','dairy-free','high-protein','kid-friendly','nut-free','one-pan','rice','standard','stir-fry']::text[], '["1/2 lb ground pork", "3 cups cooked white rice", "2 eggs", "1 cup frozen peas and carrots", "3 cloves garlic", "2 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp vegetable oil", "2 green onions", "pepper"]'::jsonb, '["Heat vegetable oil in a large skillet or wok over high heat. Add ground pork and cook, breaking it up, until browned.", "Add minced garlic and frozen peas and carrots; stir-fry 2 minutes.", "Push everything to the side, pour sesame oil in the center, and add rice. Press and stir-fry rice for 3-4 minutes until slightly crispy.", "Push rice to the side, scramble eggs in the pan, then mix everything together.", "Drizzle with soy sauce, season with pepper, top with sliced green onions, and serve."]'::jsonb, 4, 5, 15, 2.0, 8.0, 370, 20, 40, 14, 2, 600, true, true, true, 'curated'),
  ('Blueberry Lemon Cottage Cheese Pancakes', 'Protein-packed cottage cheese blended into tender pancakes dotted with sweet blueberries and brightened with fresh lemon zest.', 'breakfast', 'American', 'budget', ARRAY['american','budget','fruit','kid-friendly','nut-free','one-pan','soy-free','sweet','vegetarian']::text[], '["1 cup cottage cheese", "2 eggs", "1/2 cup all-purpose flour", "1 tsp baking powder", "1 lemon", "1 cup fresh or frozen blueberries", "1 tbsp sugar", "1 tsp vanilla extract", "1 tbsp butter", "maple syrup"]'::jsonb, '["Whisk cottage cheese, eggs, lemon zest, vanilla, and sugar in a bowl.", "Stir in flour and baking powder until a thick batter forms.", "Gently fold in blueberries.", "Melt butter in a nonstick skillet over medium-low heat. Drop 1/4 cup batter per pancake.", "Cook about 3 minutes per side until set and golden \u2014 these are more delicate than regular pancakes, so flip carefully.", "Serve with maple syrup or extra blueberries."]'::jsonb, 4, 10, 20, 1.6, 6.4, 240, 13, 30, 7, 2, 260, true, true, true, 'curated'),
  ('Spiced Ground Turkey Breakfast Bowl', 'Seasoned ground turkey crumbled over white rice with sautéed peppers and a soft-boiled egg for a hearty, protein-rich morning bowl.', 'breakfast', 'American', 'budget', ARRAY['american','budget','dairy-free','gluten-free','high-protein','kid-friendly','meal-prep','nut-free','one-pan','rice','soy-free','standard']::text[], '["1 lb ground turkey", "2 cups cooked white rice", "4 eggs", "1 red bell pepper", "1 onion", "2 cloves garlic", "1 tsp cumin", "1 tsp smoked paprika", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Soft-boil eggs by simmering for 7 minutes in boiling water then plunging into ice water; peel and halve.", "Heat olive oil in a skillet over medium-high heat. Saut\u00e9 diced onion and bell pepper for 3-4 minutes.", "Add minced garlic, ground turkey, cumin, paprika, salt, and pepper. Cook, breaking up turkey, until browned, about 7 minutes.", "Divide warm rice into bowls and top with turkey mixture.", "Place two egg halves on each bowl and season with a pinch of salt and pepper."]'::jsonb, 4, 10, 20, 2.6, 10.4, 400, 35, 28, 14, 2, 380, true, true, true, 'curated'),
  ('Creamy Stovetop Oatmeal with Brown Sugar and Pecans', 'Rich stovetop oatmeal cooked in milk and topped with caramelized brown sugar and crunchy pecans for a warming, indulgent morning bowl.', 'breakfast', 'American', 'ultra_budget', ARRAY['american','budget','comfort-food','egg-free','gluten-free','kid-friendly','nut-free','one-pot','quick','soy-free','sweet','vegetarian']::text[], '["2 cups rolled oats", "3 cups milk", "1 cup water", "3 tbsp brown sugar", "1/2 cup chopped pecans", "1 tsp cinnamon", "1/2 tsp vanilla extract", "1 pinch salt", "1 tbsp butter"]'::jsonb, '["Combine milk, water, and salt in a medium saucepan and bring to a gentle simmer.", "Stir in oats and cook over medium-low heat, stirring frequently, for 5-7 minutes until creamy and thickened.", "Remove from heat and stir in butter, vanilla, and cinnamon.", "Toast pecans in a dry skillet for 2-3 minutes until fragrant.", "Divide oatmeal among bowls and top with brown sugar and toasted pecans."]'::jsonb, 4, 3, 10, 1.1, 4.4, 330, 10, 44, 13, 4, 120, true, true, true, 'curated'),
  ('Salmon and Cream Cheese Bagel Plate', 'Toasted bagels spread generously with cream cheese and topped with smoked salmon, thin cucumber, and capers for an elegant weekday breakfast.', 'breakfast', 'American', 'standard', ARRAY['american','egg-free','gluten-free','no-cook','nut-free','quick','seafood','soy-free','standard']::text[], '["4 bagels", "4 oz cream cheese", "4 oz smoked salmon", "1 cucumber", "2 tbsp capers", "1/2 red onion", "1 lemon", "pepper"]'::jsonb, '["Slice bagels in half and toast to your preferred level.", "Spread cream cheese generously on each bagel half.", "Thinly slice cucumber and red onion.", "Layer smoked salmon over the cream cheese, then add cucumber and red onion slices.", "Scatter capers over the top, squeeze a little lemon juice, and finish with black pepper.", "Serve immediately."]'::jsonb, 4, 10, 3, 3.5, 14.0, 350, 18, 44, 12, 2, 780, false, true, true, 'curated'),
  ('Brown Sugar Cinnamon Baked French Toast Casserole', 'A make-ahead French toast casserole soaked overnight in a sweet custard and baked until puffy and caramelized for an effortless holiday-worthy breakfast.', 'breakfast', 'American', 'ultra_budget', ARRAY['american','baked','budget','casserole','crowd-pleaser','kid-friendly','meal-prep','nut-free','soy-free','sweet','vegetarian']::text[], '["1 loaf French bread", "6 eggs", "2 cups milk", "1/2 cup brown sugar", "2 tsp cinnamon", "1 tsp vanilla extract", "3 tbsp butter", "1/4 tsp nutmeg", "1 pinch salt", "maple syrup"]'::jsonb, '["Cube the French bread and spread it in a greased 9x13 baking dish.", "Whisk eggs, milk, half the brown sugar, cinnamon, vanilla, nutmeg, and salt and pour over the bread. Press gently and refrigerate overnight.", "Preheat oven to 350\u00b0F. Mix remaining brown sugar with butter to form a crumble and sprinkle over the top.", "Bake uncovered for 45-50 minutes until puffed and the top is golden caramel.", "Cool 5 minutes, then serve with maple syrup."]'::jsonb, 6, 15, 50, 1.4, 8.4, 360, 12, 54, 11, 2, 380, true, true, true, 'curated'),
  ('Egg and Bean Tostadas', 'Crispy corn tostadas piled with refried beans, a fried egg, and fresh salsa for a vibrant and filling Mexican-inspired morning plate.', 'breakfast', 'Mexican', 'ultra_budget', ARRAY['budget','gluten-free','high-protein','kid-friendly','mexican','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["8 corn tostada shells", "1 can refried beans", "8 eggs", "1 cup salsa", "1/2 cup shredded Mexican blend cheese", "1 tbsp oil", "1 tsp cumin", "salt", "pepper"]'::jsonb, '["Warm refried beans in a small saucepan with cumin, salt, and a splash of water, stirring until smooth.", "Heat oil in a nonstick skillet over medium heat and fry eggs to your liking.", "Spread a generous layer of refried beans on each tostada shell.", "Top with a fried egg, shredded cheese, and a spoonful of salsa.", "Serve immediately while the tostadas are still crispy."]'::jsonb, 4, 5, 10, 1.45, 5.8, 340, 20, 34, 13, 6, 610, true, true, true, 'curated'),
  ('Peanut Butter Banana Smoothie Bowls', 'Thick blended frozen banana and peanut butter smoothie poured into a bowl and loaded with sliced banana, oats, and honey for a satisfying, spoonable breakfast.', 'breakfast', 'American', 'ultra_budget', ARRAY['american','budget','egg-free','gluten-free','kid-favorite','kid-friendly','no-cook','quick','soy-free','sweet','vegetarian']::text[], '["4 frozen bananas", "1/2 cup peanut butter", "1 cup milk", "2 tbsp honey", "1 cup rolled oats", "2 bananas", "1 tsp cinnamon"]'::jsonb, '["Blend frozen bananas, peanut butter, milk, and honey on high until thick and creamy \u2014 it should be much thicker than a drinkable smoothie.", "Pour into 4 wide bowls.", "Slice fresh bananas and arrange on top along with a handful of dry rolled oats.", "Drizzle with extra honey and dust with cinnamon before serving."]'::jsonb, 4, 10, 0, 1.2, 4.8, 380, 12, 56, 14, 6, 130, true, true, true, 'curated'),
  ('Italian Sausage and Pepper Frittata', 'A thick oven-finished egg frittata loaded with browned Italian sausage, roasted peppers, and mozzarella for a hearty slice-and-serve breakfast.', 'breakfast', 'Italian', 'budget', ARRAY['baked','budget','gluten-free','hearty','high-protein','italian','kid-friendly','nut-free','one-pan','soy-free','standard']::text[], '["1/2 lb Italian pork sausage", "8 eggs", "1/4 cup milk", "1 red bell pepper", "1 green bell pepper", "1 onion", "1 cup shredded mozzarella cheese", "2 tbsp olive oil", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Preheat oven to 375\u00b0F. Heat olive oil in a 10-inch oven-safe skillet over medium-high heat.", "Brown sausage, breaking it up, then add diced onion and bell peppers and cook 4-5 minutes.", "Whisk eggs with milk, Italian seasoning, salt, and pepper.", "Reduce heat to medium-low, pour egg mixture over sausage and vegetables, and let set on the bottom for 3-4 minutes without stirring.", "Sprinkle mozzarella over the top and transfer the skillet to the oven.", "Bake 12-15 minutes until eggs are puffed, set, and golden. Slice into wedges and serve."]'::jsonb, 5, 10, 25, 2.2, 11.0, 340, 24, 6, 24, 1, 640, true, true, true, 'curated'),
  ('Cornmeal Waffles with Honey Butter', 'Slightly crispy, golden waffles made with a blend of cornmeal and flour that lend a satisfying bite, served warm with whipped honey butter.', 'breakfast', 'Southern', 'ultra_budget', ARRAY['american','baked','budget','kid-favorite','kid-friendly','nut-free','southern','soy-free','sweet','vegetarian']::text[], '["1 cup yellow cornmeal", "1 cup all-purpose flour", "2 tsp baking powder", "1 tbsp sugar", "1 tsp salt", "2 eggs", "1 1/2 cups milk", "1/4 cup vegetable oil", "3 tbsp butter", "2 tbsp honey"]'::jsonb, '["Preheat a waffle iron and lightly grease it.", "Whisk cornmeal, flour, baking powder, sugar, and salt in a bowl.", "In another bowl, whisk eggs, milk, and vegetable oil together.", "Pour wet ingredients into dry and stir until just combined.", "Cook waffles according to your waffle iron''s instructions until golden and crispy.", "Beat softened butter with honey until fluffy and serve alongside hot waffles."]'::jsonb, 4, 10, 15, 0.85, 3.4, 410, 9, 58, 16, 2, 420, true, true, true, 'curated'),
  ('Strawberry Cream Cheese Stuffed French Toast', 'Thick slices of brioche bread stuffed with sweet cream cheese and fresh strawberries, dipped in egg custard, and pan-fried to golden perfection.', 'breakfast', 'American', 'budget', ARRAY['american','budget','fruit','indulgent','kid-favorite','kid-friendly','nut-free','one-pan','soy-free','sweet','vegetarian']::text[], '["8 slices brioche or thick white bread", "4 oz cream cheese", "1 cup sliced fresh strawberries", "2 tbsp powdered sugar", "3 eggs", "1/2 cup milk", "1 tsp vanilla extract", "1 tsp cinnamon", "2 tbsp butter", "maple syrup"]'::jsonb, '["Beat cream cheese with powdered sugar and vanilla until smooth. Fold in sliced strawberries.", "Spread the cream cheese mixture on 4 bread slices and top each with another bread slice to form a sandwich.", "Whisk eggs, milk, vanilla, and cinnamon in a shallow bowl.", "Melt butter in a large skillet over medium heat.", "Dip each stuffed sandwich in the egg mixture, coating both sides, and cook for 2-3 minutes per side until deep golden brown.", "Slice diagonally and serve with powdered sugar and maple syrup."]'::jsonb, 4, 15, 15, 2.6, 10.4, 440, 12, 52, 20, 2, 390, true, true, true, 'curated'),
  ('Smoky Black Bean Rice Bowl', 'Seasoned black beans over fluffy white rice topped with salsa and a squeeze of lime.', 'dinner', 'Mexican', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','kid-friendly','mexican','nut-free','one-pot','rice-bowl','soy-free','vegan','vegetarian']::text[], '["2 cans black beans", "2 cups white rice", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp smoked paprika", "1 lime", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Heat olive oil in a skillet over medium heat and saut\u00e9 diced onion until soft, about 5 minutes.", "Add garlic, cumin, and smoked paprika and cook 1 minute.", "Drain and add black beans and diced tomatoes, simmer 10 minutes.", "Season with salt, pepper, and lime juice.", "Serve bean mixture over rice."]'::jsonb, 4, 10, 25, 1.2, 4.8, 380, 14, 68, 4, 12, 480, true, true, true, 'curated'),
  ('Chicken Thigh and Potato Sheet-Pan Dinner', 'Juicy bone-in chicken thighs roasted alongside golden potatoes and caramelized onions.', 'dinner', 'Sheet-Pan', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','sheet-pan','soy-free','standard']::text[], '["4 bone-in chicken thighs", "4 medium potatoes", "1 onion", "2 tbsp olive oil", "1 tsp garlic powder", "1 tsp smoked paprika", "1 tsp dried thyme", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F.", "Cut potatoes into 1-inch chunks and slice onion.", "Toss potatoes and onion with 1 tbsp olive oil, salt, and pepper on a sheet pan.", "Rub chicken thighs with remaining oil, garlic powder, paprika, and thyme; place on top of vegetables.", "Roast 35-40 minutes until chicken is golden and cooked through.", "Rest 5 minutes before serving."]'::jsonb, 4, 10, 40, 2.4, 9.6, 430, 32, 28, 18, 3, 420, true, true, true, 'curated'),
  ('Ground Turkey and Sweet Potato Skillet', 'Savory ground turkey and cubed sweet potatoes cooked together in one skillet with warm spices.', 'dinner', 'Skillet', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','skillet','soy-free','standard']::text[], '["1 lb ground turkey", "2 medium sweet potatoes", "1 onion", "2 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp chili powder", "salt", "pepper"]'::jsonb, '["Peel and dice sweet potatoes into small cubes.", "Heat olive oil in a large skillet over medium-high heat.", "Add sweet potatoes and cook 8 minutes, stirring occasionally.", "Push potatoes to the side, add ground turkey and brown completely.", "Add onion, garlic, cumin, and chili powder; stir everything together and cook 5 more minutes.", "Season with salt and pepper and serve."]'::jsonb, 4, 10, 20, 2.8, 11.2, 340, 28, 24, 12, 4, 390, true, true, true, 'curated'),
  ('Red Lentil and Coconut Milk Curry', 'Creamy red lentils simmered in coconut milk with tomatoes and warming Indian spices.', 'dinner', 'Curry', 'ultra_budget', ARRAY['budget','curry','egg-free','gluten-free','indian','kid-friendly','nut-free','one-pot','soy-free','vegetarian']::text[], '["2 cups red lentils", "1 can coconut milk", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp turmeric", "1 tsp cumin", "1 tsp garam masala", "2 cups water", "salt"]'::jsonb, '["Rinse lentils thoroughly under cold water.", "Heat olive oil in a large pot and saut\u00e9 onion until golden, about 6 minutes.", "Add garlic, turmeric, cumin, and garam masala; stir 1 minute.", "Add lentils, diced tomatoes, coconut milk, and water; bring to a boil.", "Reduce heat and simmer 20-25 minutes until lentils are tender.", "Season with salt and serve over rice."]'::jsonb, 5, 10, 30, 1.5, 7.5, 360, 18, 48, 10, 13, 350, true, true, true, 'curated'),
  ('Salmon Patties with Corn Salsa', 'Crispy pan-fried salmon cakes made from canned salmon served alongside a bright corn and tomato salsa.', 'dinner', 'Seafood', 'budget', ARRAY['american','budget','dairy-free','gluten-free','high-protein','kid-friendly','nut-free','seafood','skillet','soy-free','standard']::text[], '["2 cans salmon", "1 can corn", "2 eggs", "1 cup cornmeal", "1 onion", "2 cloves garlic", "1 can diced tomatoes", "2 tbsp olive oil", "1 tsp cumin", "salt", "pepper"]'::jsonb, '["Drain salmon and mix with eggs, cornmeal, half the onion (diced), garlic, salt, and pepper.", "Form into 8 patties.", "Heat olive oil in a skillet over medium heat and cook patties 3-4 minutes per side until golden.", "In a bowl, combine drained corn, diced tomatoes, remaining onion, cumin, salt, and pepper for salsa.", "Serve salmon patties topped with corn salsa."]'::jsonb, 4, 15, 15, 2.6, 10.4, 390, 28, 36, 13, 3, 580, true, true, true, 'curated'),
  ('Cuban-Spiced Pork and Black Bean Rice', 'Aromatic pork tenderloin seasoned with citrus and cumin served over black beans and yellow rice.', 'dinner', 'Cuban', 'budget', ARRAY['budget','cuban','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','latin','nut-free','rice-bowl','soy-free','standard']::text[], '["1 lb pork tenderloin", "2 cans black beans", "2 cups white rice", "1 orange", "1 lime", "3 cloves garlic", "1 tsp cumin", "1 tsp oregano", "1 tsp turmeric", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Marinate pork in orange juice, lime juice, garlic, cumin, oregano, olive oil, salt, and pepper for 15 minutes.", "Cook rice with turmeric for color according to package directions.", "Heat a skillet over medium-high heat and sear pork 4 minutes per side.", "Transfer to oven at 400\u00b0F and roast 15-20 minutes until internal temp is 145\u00b0F.", "Heat black beans with a pinch of cumin and salt.", "Slice pork and serve over rice and beans."]'::jsonb, 4, 20, 30, 2.7, 10.8, 430, 34, 54, 8, 10, 490, true, true, true, 'curated'),
  ('Cheesy Polenta with Sautéed Mushrooms', 'Creamy stone-ground polenta topped with garlicky mushrooms and melted Parmesan cheese.', 'dinner', 'Italian', 'budget', ARRAY['budget','comfort-food','egg-free','gluten-free','italian','nut-free','one-pot','soy-free','vegetarian','vegetarian-friendly']::text[], '["1 cup polenta", "4 cups water", "1 lb mushrooms", "1 onion", "3 cloves garlic", "1 cup shredded Parmesan cheese", "2 tbsp butter", "2 tbsp olive oil", "1 tsp dried thyme", "salt", "pepper"]'::jsonb, '["Bring water and 1 tsp salt to a boil in a large pot.", "Slowly whisk in polenta, reduce heat to low, and cook stirring frequently for 20-25 minutes.", "Meanwhile, heat olive oil in a skillet over medium-high heat; saut\u00e9 sliced mushrooms and onion until browned, about 10 minutes.", "Add garlic and thyme; cook 2 more minutes.", "Stir butter and Parmesan into cooked polenta; season with salt and pepper.", "Spoon polenta into bowls and top with mushroom mixture."]'::jsonb, 4, 10, 30, 2.2, 8.8, 320, 12, 38, 13, 3, 540, false, true, true, 'curated'),
  ('Korean-Inspired Ground Beef and Rice Bowls', 'Sweet and savory seasoned ground beef with steamed rice, shredded carrots, and a fried egg on top.', 'dinner', 'Korean', 'budget', ARRAY['asian','budget','dairy-free','gluten-free','high-protein','kid-friendly','korean','nut-free','rice-bowl','standard']::text[], '["1 lb ground beef", "2 cups white rice", "2 carrots", "4 eggs", "3 tbsp tamari", "1 tbsp sesame oil", "2 tbsp brown sugar", "3 cloves garlic", "1 tsp grated ginger", "1 tbsp vegetable oil", "2 green onions"]'::jsonb, '["Cook rice according to package directions.", "Mix tamari, brown sugar, sesame oil, garlic, and ginger in a small bowl.", "Brown ground beef in a skillet over medium-high heat, drain excess fat.", "Pour sauce over beef and cook 3 more minutes, stirring well.", "Shred carrots and fry eggs separately in vegetable oil.", "Assemble bowls with rice, beef, carrots, and a fried egg; garnish with green onions."]'::jsonb, 4, 10, 20, 2.85, 11.4, 500, 32, 50, 18, 2, 740, true, true, true, 'curated'),
  ('Tex-Mex Stuffed Bell Peppers', 'Colorful bell peppers filled with seasoned ground beef, rice, corn, and melted cheddar cheese.', 'dinner', 'Tex-Mex', 'budget', ARRAY['baked','budget','comfort-food','egg-free','gluten-free','high-protein','kid-friendly','nut-free','soy-free','standard','tex-mex']::text[], '["4 bell peppers", "1 lb ground beef", "1 cup white rice", "1 can corn", "1 can diced tomatoes", "1 cup shredded cheddar cheese", "1 onion", "2 cloves garlic", "1 tsp chili powder", "1 tsp cumin", "salt", "pepper"]'::jsonb, '["Preheat oven to 375\u00b0F and cook rice according to package directions.", "Cut tops off peppers, remove seeds, and place in a baking dish.", "Brown ground beef with onion and garlic in a skillet; drain fat.", "Stir in cooked rice, drained corn, diced tomatoes, chili powder, cumin, salt, and pepper.", "Fill each pepper with the beef mixture and top with shredded cheddar.", "Bake 30-35 minutes until peppers are tender and cheese is bubbly."]'::jsonb, 4, 20, 40, 2.9, 11.6, 460, 30, 44, 16, 5, 610, true, true, true, 'curated'),
  ('Garlic Herb Roasted Chicken Drumsticks', 'Oven-roasted chicken drumsticks coated in a fragrant garlic-herb blend until perfectly crispy.', 'dinner', 'Roasted', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','oven-roasted','sheet-pan','soy-free','standard']::text[], '["8 chicken drumsticks", "3 cloves garlic", "2 tbsp olive oil", "1 tsp dried rosemary", "1 tsp dried thyme", "1 tsp garlic powder", "1 tsp onion powder", "salt", "pepper", "1 lemon"]'::jsonb, '["Preheat oven to 425\u00b0F and line a baking sheet with foil.", "Pat drumsticks dry with paper towels.", "Mix olive oil, minced garlic, rosemary, thyme, garlic powder, onion powder, salt, and pepper.", "Rub spice mixture all over drumsticks and place on prepared baking sheet.", "Roast 35-40 minutes, turning once, until skin is crispy and juices run clear.", "Squeeze lemon juice over top before serving."]'::jsonb, 4, 10, 40, 2.1, 8.4, 370, 36, 2, 22, 0, 360, true, true, true, 'curated'),
  ('Egg Fried Rice with Peas and Carrots', 'Classic fried rice loaded with scrambled eggs, sweet peas, and carrots in a savory tamari sauce.', 'dinner', 'Stir-Fry', 'ultra_budget', ARRAY['asian','budget','budget-friendly','dairy-free','gluten-free','kid-friendly','nut-free','one-pan','stir-fry','vegetarian']::text[], '["3 cups cooked white rice", "4 eggs", "1 cup frozen peas", "2 carrots", "3 cloves garlic", "2 tbsp tamari", "1 tbsp sesame oil", "2 tbsp vegetable oil", "2 green onions", "salt", "pepper"]'::jsonb, '["Heat vegetable oil in a large skillet or wok over high heat.", "Add diced carrots and cook 3 minutes; add garlic and cook 1 minute.", "Push vegetables to the side, scramble eggs in the center, then mix together.", "Add cold cooked rice and stir-fry 4 minutes until heated through.", "Add frozen peas, tamari, and sesame oil; toss well.", "Season with salt and pepper, garnish with green onions."]'::jsonb, 4, 10, 15, 1.4, 5.6, 340, 13, 50, 9, 3, 540, true, true, true, 'curated'),
  ('Spicy Shrimp and Grits', 'Succulent Gulf shrimp in a tomato and bell pepper sauce served over creamy stone-ground grits.', 'dinner', 'Southern', 'standard', ARRAY['comfort-food','egg-free','gluten-free','high-protein','nut-free','seafood','southern','soy-free','standard']::text[], '["1 lb shrimp", "1 cup grits", "4 cups water", "1 can diced tomatoes", "1 bell pepper", "1 onion", "3 cloves garlic", "2 tbsp butter", "1 tbsp olive oil", "1 tsp cajun seasoning", "1 cup shredded cheddar cheese", "salt", "pepper"]'::jsonb, '["Bring 4 cups salted water to a boil; stir in grits, reduce heat, and cook 20-25 minutes stirring often.", "Stir butter and cheddar into cooked grits; season with salt and pepper.", "Heat olive oil in a skillet over medium-high heat; saut\u00e9 diced onion and bell pepper 5 minutes.", "Add garlic and Cajun seasoning; cook 1 minute.", "Add diced tomatoes and shrimp; cook 4-5 minutes until shrimp are pink.", "Spoon shrimp mixture over grits and serve immediately."]'::jsonb, 4, 10, 30, 4.2, 16.8, 450, 30, 42, 16, 3, 780, false, true, true, 'curated'),
  ('Moroccan Chickpea and Carrot Stew', 'Warmly spiced stew of chickpeas and carrots in a tomato broth fragrant with cumin and cinnamon.', 'dinner', 'Moroccan', 'ultra_budget', ARRAY['african','budget','dairy-free','egg-free','gluten-free','high-fiber','moroccan','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["2 cans chickpeas", "4 carrots", "1 can diced tomatoes", "3 cups vegetable broth", "1 onion", "3 cloves garlic", "2 tbsp olive oil", "1 tsp cumin", "1 tsp coriander", "1 tsp cinnamon", "1 tsp turmeric", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large pot over medium heat; saut\u00e9 diced onion 6 minutes.", "Add garlic, cumin, coriander, cinnamon, and turmeric; stir 1 minute.", "Add sliced carrots, drained chickpeas, diced tomatoes, and broth.", "Bring to a boil, then simmer 25 minutes until carrots are tender.", "Season with salt and pepper.", "Serve over rice or quinoa."]'::jsonb, 5, 10, 35, 1.25, 6.25, 280, 12, 44, 6, 11, 520, false, true, true, 'curated'),
  ('Pulled Chicken Lettuce Cups', 'Slow-simmered pulled chicken tossed in a tangy sauce and served in crisp butter lettuce cups with shredded carrots.', 'dinner', 'Asian-Fusion', 'budget', ARRAY['asian','budget','egg-free','fun','gluten-free','high-protein','kid-friendly','low-carb','nut-free','standard']::text[], '["1 lb chicken thighs", "1 head butter lettuce", "2 carrots", "3 tbsp tamari", "1 tbsp sesame oil", "1 tbsp rice vinegar", "2 tbsp honey", "3 cloves garlic", "1 tsp grated ginger", "1 cup water"]'::jsonb, '["Place chicken thighs, water, garlic, and ginger in a pot; bring to a boil then simmer 20 minutes.", "Remove chicken and shred with two forks.", "Mix tamari, sesame oil, rice vinegar, and honey; toss with shredded chicken.", "Separate lettuce into individual leaves.", "Shred carrots finely.", "Assemble cups with chicken and top with shredded carrots."]'::jsonb, 4, 15, 25, 2.5, 10.0, 290, 28, 18, 11, 2, 660, true, true, true, 'curated'),
  ('Quinoa and Black Bean Power Bowl', 'Protein-packed quinoa and black beans with roasted corn, avocado, and a lime-cilantro dressing.', 'dinner', 'Bowl', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','latin','nut-free','rice-bowl','soy-free','vegan','vegetarian']::text[], '["2 cups quinoa", "2 cans black beans", "1 can corn", "2 avocados", "1 lime", "1 bunch cilantro", "1 onion", "2 cloves garlic", "2 tbsp olive oil", "1 tsp cumin", "salt", "pepper"]'::jsonb, '["Cook quinoa in 4 cups water according to package directions.", "Heat 1 tbsp olive oil in a skillet and roast corn kernels until lightly charred.", "Warm drained black beans with garlic, cumin, salt, and pepper.", "Make dressing by whisking together lime juice, olive oil, cilantro, salt, and pepper.", "Dice avocados and slice onion thinly.", "Build bowls with quinoa, beans, corn, avocado, onion, and drizzle with dressing."]'::jsonb, 5, 15, 20, 2.4, 12.0, 420, 16, 58, 15, 14, 380, true, true, true, 'curated'),
  ('Sausage and Potato Foil Packets', 'Smoked sausage and chunky potatoes with peppers and onions steamed to perfection in individual foil packets.', 'dinner', 'Foil-Pack', 'budget', ARRAY['american','budget','comfort-food','dairy-free','easy','egg-free','gluten-free','kid-friendly','nut-free','one-pan','soy-free','standard']::text[], '["1 lb smoked sausage", "4 medium potatoes", "2 bell peppers", "1 onion", "2 tbsp olive oil", "1 tsp garlic powder", "1 tsp smoked paprika", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F.", "Slice sausage, dice potatoes into small cubes, and chop peppers and onion.", "Toss all vegetables and sausage with olive oil, garlic powder, paprika, salt, and pepper.", "Divide mixture among 4 large sheets of heavy-duty foil and fold into sealed packets.", "Bake 30-35 minutes until potatoes are tender.", "Carefully open packets, avoiding steam, and serve."]'::jsonb, 4, 15, 35, 2.6, 10.4, 420, 18, 38, 22, 4, 820, true, true, true, 'curated'),
  ('Thai Peanut Chicken over Rice', 'Grilled chicken thighs drenched in a creamy peanut sauce with coconut milk served over jasmine rice.', 'dinner', 'Thai', 'budget', ARRAY['asian','budget','egg-free','gluten-free','high-protein','kid-friendly','rice-bowl','standard','thai']::text[], '["1 lb chicken thighs", "2 cups jasmine rice", "3 tbsp peanut butter", "1 can coconut milk", "2 tbsp tamari", "1 tbsp honey", "1 tbsp lime juice", "2 cloves garlic", "1 tsp grated ginger", "2 tbsp vegetable oil", "salt"]'::jsonb, '["Cook jasmine rice according to package directions.", "Season chicken thighs with salt and cook in vegetable oil over medium-high heat 6-7 minutes per side.", "Let chicken rest, then slice.", "In a small pot, whisk together peanut butter, coconut milk, tamari, honey, lime juice, garlic, and ginger; heat over low until smooth.", "Thin sauce with a splash of water if needed.", "Serve sliced chicken over rice and ladle peanut sauce over top."]'::jsonb, 4, 10, 25, 2.95, 11.8, 520, 30, 52, 20, 2, 640, true, true, true, 'curated'),
  ('Crispy Baked Tilapia with Corn Slaw', 'Cornmeal-crusted tilapia fillets baked until golden and crunchy, served alongside a tangy corn and cabbage slaw.', 'dinner', 'Seafood', 'budget', ARRAY['american','baked','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','seafood','soy-free','standard']::text[], '["4 tilapia fillets", "1 cup cornmeal", "1 can corn", "2 cups shredded cabbage", "1 carrot", "1 lime", "2 tbsp olive oil", "1 tbsp apple cider vinegar", "1 tsp garlic powder", "1 tsp paprika", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F and line a baking sheet with foil.", "Mix cornmeal, garlic powder, paprika, salt, and pepper in a shallow bowl.", "Brush fillets with olive oil and press into cornmeal mixture to coat both sides.", "Place on baking sheet and bake 15-18 minutes until crispy and cooked through.", "Combine shredded cabbage, shredded carrot, drained corn, lime juice, vinegar, salt, and pepper for slaw.", "Serve tilapia alongside the slaw."]'::jsonb, 4, 15, 18, 2.8, 11.2, 350, 30, 36, 8, 3, 420, true, true, true, 'curated'),
  ('Indian Spiced Cauliflower and Potato Bake', 'Roasted cauliflower and potato wedges tossed in fragrant Indian spices and finished with yogurt drizzle.', 'dinner', 'Indian', 'ultra_budget', ARRAY['budget','egg-free','gluten-free','indian','nut-free','oven-roasted','sheet-pan','soy-free','vegetarian','vegetarian-friendly']::text[], '["1 head cauliflower", "4 medium potatoes", "1 onion", "3 tbsp olive oil", "1 tsp turmeric", "1 tsp cumin", "1 tsp coriander", "1 tsp garam masala", "1 cup plain yogurt", "1 lemon", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F.", "Cut cauliflower into florets and potatoes into wedges.", "Toss cauliflower, potatoes, and sliced onion with olive oil and all spices; season with salt and pepper.", "Spread on a large baking sheet and roast 30-35 minutes until golden and tender.", "Mix yogurt with lemon juice and a pinch of salt.", "Drizzle yogurt sauce over roasted vegetables before serving."]'::jsonb, 4, 15, 35, 1.45, 5.8, 290, 8, 44, 10, 7, 310, false, true, true, 'curated'),
  ('Pork and Cabbage Stir-Fry', 'Tender sliced pork with shredded cabbage and carrots in a garlicky ginger tamari sauce over rice.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','standard','stir-fry']::text[], '["1 lb pork loin", "4 cups shredded cabbage", "2 carrots", "3 cups white rice", "3 tbsp tamari", "1 tbsp sesame oil", "3 cloves garlic", "1 tsp grated ginger", "2 tbsp vegetable oil", "2 green onions", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Slice pork into thin strips.", "Heat vegetable oil in a wok or large skillet over high heat; cook pork 4-5 minutes until browned.", "Add garlic and ginger; cook 1 minute.", "Add shredded cabbage and julienned carrots; stir-fry 4-5 minutes.", "Pour in tamari and sesame oil, toss to coat, and serve over rice topped with green onions."]'::jsonb, 4, 15, 20, 2.4, 9.6, 440, 28, 54, 10, 4, 680, true, true, true, 'curated'),
  ('Tomato Basil Chicken with Polenta', 'Pan-seared chicken breasts in a fresh tomato and basil sauce served over creamy golden polenta.', 'dinner', 'Italian', 'budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','italian','kid-friendly','nut-free','skillet','soy-free','standard']::text[], '["4 chicken breasts", "1 cup polenta", "4 cups water", "1 can crushed tomatoes", "1 onion", "3 cloves garlic", "1 cup fresh basil", "2 tbsp olive oil", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Bring 4 cups salted water to a boil; whisk in polenta and cook on low heat 20 minutes, stirring often.", "Season chicken breasts with salt and pepper.", "Heat olive oil in a large skillet; sear chicken 5-6 minutes per side until cooked through; remove.", "In the same skillet, saut\u00e9 onion 4 minutes, add garlic and Italian seasoning, then add crushed tomatoes.", "Simmer sauce 10 minutes, return chicken to pan, and heat through.", "Serve chicken and sauce over polenta, topped with fresh basil."]'::jsonb, 4, 10, 35, 2.9, 11.6, 430, 38, 38, 10, 3, 520, true, true, true, 'curated'),
  ('Slow Cooker Pinto Bean Chili', 'Deep and smoky slow-cooked pinto bean chili with ground beef and roasted peppers.', 'dinner', 'Chili', 'ultra_budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','slow-cooker','soy-free','standard']::text[], '["1 lb ground beef", "2 cans pinto beans", "1 can crushed tomatoes", "1 onion", "2 bell peppers", "3 cloves garlic", "1 tbsp chili powder", "1 tsp cumin", "1 tsp smoked paprika", "salt", "pepper"]'::jsonb, '["Brown ground beef in a skillet over medium-high heat; drain fat.", "Transfer beef to a slow cooker.", "Add drained pinto beans, crushed tomatoes, diced onion, diced bell peppers, garlic, and all spices.", "Stir to combine, cover, and cook on low 6-8 hours or high 3-4 hours.", "Season with salt and pepper before serving.", "Serve topped with shredded cheese and sour cream if desired."]'::jsonb, 6, 15, 360, 1.4, 8.4, 360, 26, 38, 12, 11, 580, true, true, true, 'curated'),
  ('Honey Garlic Glazed Salmon with Brown Rice', 'Oven-baked salmon fillets glazed with a sweet honey garlic sauce alongside nutty brown rice.', 'dinner', 'Seafood', 'standard', ARRAY['asian','baked','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','seafood','standard']::text[], '["4 salmon fillets", "2 cups brown rice", "3 tbsp honey", "2 tbsp tamari", "3 cloves garlic", "1 tbsp olive oil", "1 lemon", "1 tsp grated ginger", "salt", "pepper"]'::jsonb, '["Cook brown rice according to package directions.", "Preheat oven to 400\u00b0F and line a baking dish with foil.", "Whisk together honey, tamari, minced garlic, ginger, and lemon juice.", "Season salmon with salt and pepper and place in baking dish; pour glaze over top.", "Bake 12-15 minutes until salmon flakes easily with a fork.", "Serve salmon over brown rice, spooning extra glaze from the pan on top."]'::jsonb, 4, 10, 45, 4.8, 19.2, 480, 36, 50, 13, 3, 540, true, true, true, 'curated'),
  ('Creamy Chicken and Corn Chowder', 'Thick and satisfying chowder packed with tender chicken, sweet corn, and diced potatoes in a rich broth.', 'dinner', 'Chowder', 'budget', ARRAY['american','budget','comfort-food','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["2 chicken breasts", "2 cans corn", "3 medium potatoes", "1 onion", "3 cloves garlic", "4 cups chicken broth", "1 cup milk", "2 tbsp butter", "1 tsp thyme", "salt", "pepper"]'::jsonb, '["Dice potatoes and chicken into small cubes.", "Melt butter in a large pot over medium heat; saut\u00e9 onion and garlic 5 minutes.", "Add chicken cubes and cook 4 minutes until no longer pink.", "Add potatoes, drained corn, chicken broth, and thyme; bring to a boil.", "Reduce heat and simmer 20 minutes until potatoes are tender.", "Stir in milk, season with salt and pepper, and heat through before serving."]'::jsonb, 5, 15, 30, 2.3, 11.5, 350, 26, 40, 8, 3, 680, true, true, true, 'curated'),
  ('Arroz con Pollo', 'A classic Latin one-pot dish of chicken simmered with saffron-scented rice, peas, and colorful peppers.', 'dinner', 'Latin', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','latin','nut-free','one-pot','soy-free','spanish','standard']::text[], '["4 chicken thighs", "2 cups white rice", "1 can diced tomatoes", "1 cup frozen peas", "1 onion", "2 bell peppers", "3 cloves garlic", "3 cups chicken broth", "2 tbsp olive oil", "1 tsp cumin", "1 tsp turmeric", "salt", "pepper"]'::jsonb, '["Season chicken thighs with salt, pepper, and cumin.", "Heat olive oil in a large Dutch oven over medium-high heat; brown chicken 4 minutes per side, then remove.", "Saut\u00e9 diced onion and bell peppers in the same pot 5 minutes.", "Add garlic and turmeric; cook 1 minute.", "Stir in rice, diced tomatoes, and chicken broth; nestle chicken on top.", "Cover and cook on low heat 25-30 minutes until rice is done; stir in frozen peas the last 5 minutes."]'::jsonb, 4, 15, 40, 2.75, 11.0, 480, 30, 58, 12, 4, 620, true, true, true, 'curated'),
  ('Savory Pumpkin and Lentil Stew', 'Warming lentil stew with chunks of pumpkin and warming spices, served over steamed rice.', 'dinner', 'Stew', 'ultra_budget', ARRAY['african','budget','dairy-free','egg-free','gluten-free','high-fiber','nut-free','one-pot','plant-based','soy-free','vegan','vegetarian']::text[], '["1 cup green lentils", "1 can pumpkin puree", "1 can diced tomatoes", "4 cups vegetable broth", "1 onion", "3 cloves garlic", "2 tbsp olive oil", "1 tsp cumin", "1 tsp coriander", "1 tsp turmeric", "salt", "pepper", "2 cups white rice"]'::jsonb, '["Rinse green lentils under cold water.", "Heat olive oil in a large pot over medium heat; saut\u00e9 diced onion 6 minutes.", "Add garlic, cumin, coriander, and turmeric; cook 1 minute.", "Stir in lentils, pumpkin puree, diced tomatoes, and vegetable broth.", "Bring to a boil, reduce heat, and simmer 30 minutes until lentils are tender.", "Season with salt and pepper; serve over cooked rice."]'::jsonb, 5, 10, 40, 1.2, 6.0, 310, 14, 54, 5, 13, 480, false, true, true, 'curated'),
  ('Teriyaki Salmon Rice Bowl', 'Flaky salmon fillets in a homemade teriyaki sauce served over steamed jasmine rice with steamed broccoli.', 'dinner', 'Japanese', 'standard', ARRAY['asian','dairy-free','egg-free','gluten-free','high-protein','japanese','kid-friendly','nut-free','rice-bowl','standard']::text[], '["4 salmon fillets", "2 cups jasmine rice", "2 cups broccoli florets", "3 tbsp tamari", "2 tbsp honey", "1 tbsp rice vinegar", "1 tbsp sesame oil", "2 cloves garlic", "1 tsp grated ginger", "1 tbsp cornstarch", "2 tbsp water"]'::jsonb, '["Cook jasmine rice according to package directions.", "Steam broccoli florets until tender-crisp, about 5 minutes.", "Whisk together tamari, honey, rice vinegar, sesame oil, garlic, and ginger in a small pot.", "Mix cornstarch with water and stir into sauce; heat over medium until thickened.", "Cook salmon in a nonstick skillet 4-5 minutes per side until cooked through.", "Assemble bowls with rice, broccoli, and salmon; spoon teriyaki sauce over top."]'::jsonb, 4, 10, 25, 4.6, 18.4, 490, 36, 54, 13, 3, 620, true, true, true, 'curated'),
  ('Cheesy Scrambled Eggs with Black Beans', 'Fluffy scrambled eggs folded with creamy cheddar and hearty black beans make a satisfying morning meal.', 'breakfast', 'American', 'ultra_budget', ARRAY['american','budget','gluten-free','high-protein','kid-friendly','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["4 eggs", "1 can black beans", "1/2 cup shredded cheddar cheese", "2 tbsp butter", "1/4 cup milk", "1/2 tsp cumin", "salt", "pepper"]'::jsonb, '["Drain and rinse black beans; warm in a small saucepan over low heat.", "Whisk eggs with milk, salt, and pepper in a bowl.", "Melt butter in a skillet over medium-low heat, pour in egg mixture.", "Gently fold eggs until just set, then stir in cheese.", "Serve eggs alongside warm black beans, sprinkled with cumin."]'::jsonb, 2, 5, 8, 1.25, 2.5, 370, 24, 22, 18, 6, 520, true, true, true, 'curated'),
  ('Sweet Potato Hash with Fried Eggs', 'Crispy cubed sweet potatoes sauteed with bell pepper and onion, topped with sunny-side-up eggs.', 'breakfast', 'American', 'ultra_budget', ARRAY['american','budget','colorful','dairy-free','gluten-free','hearty','kid-friendly','nut-free','one-pan','soy-free','vegetarian']::text[], '["2 medium sweet potatoes", "1 red bell pepper", "1 onion", "4 eggs", "2 tbsp olive oil", "1 tsp smoked paprika", "1/2 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Peel and dice sweet potatoes into small cubes.", "Heat olive oil in a large skillet over medium-high heat.", "Add sweet potatoes and cook 10 minutes, stirring occasionally, until starting to crisp.", "Add diced bell pepper and onion; cook 5 more minutes until softened.", "Season with smoked paprika, garlic powder, salt, and pepper.", "Push hash to the sides, crack eggs into center, cover and cook 3 minutes until whites are set."]'::jsonb, 2, 10, 18, 1.4, 2.8, 355, 14, 42, 15, 6, 390, true, true, true, 'curated'),
  ('Banana Oat Pancakes', 'Thick, golden pancakes made with mashed banana and rolled oats for a naturally sweet morning stack.', 'breakfast', 'American', 'ultra_budget', ARRAY['american','budget','gluten-free','kid-friendly','nut-free','quick','soy-free','sweet','vegetarian']::text[], '["2 ripe bananas", "1 cup rolled oats", "2 eggs", "1/4 cup milk", "1 tsp baking powder", "1/2 tsp cinnamon", "1 tbsp butter", "pinch salt"]'::jsonb, '["Blend rolled oats in a blender until a fine powder forms.", "Mash bananas in a bowl; whisk in eggs and milk.", "Stir in ground oats, baking powder, cinnamon, and salt until combined.", "Heat butter in a skillet over medium heat.", "Pour 1/4 cup batter per pancake; cook 2-3 minutes per side until golden."]'::jsonb, 3, 8, 15, 0.8, 2.4, 290, 9, 48, 7, 4, 210, true, true, true, 'curated'),
  ('Corn and Egg Breakfast Scramble', 'Sweet corn kernels and eggs scrambled together with a hint of cumin and fresh cilantro.', 'breakfast', 'Tex-Mex', 'ultra_budget', ARRAY['budget','gluten-free','kid-friendly','nut-free','one-pan','quick','soy-free','tex-mex','vegetarian']::text[], '["4 eggs", "1 cup frozen corn", "1/4 cup diced onion", "2 tbsp butter", "1/2 tsp cumin", "2 tbsp fresh cilantro", "salt", "pepper"]'::jsonb, '["Thaw corn or run under warm water.", "Melt butter in a skillet over medium heat; saute onion 3 minutes.", "Add corn and cook 2 minutes until heated through.", "Whisk eggs, pour over corn mixture, and scramble gently.", "Season with cumin, salt, and pepper; garnish with cilantro."]'::jsonb, 2, 5, 10, 0.95, 1.9, 280, 15, 20, 16, 2, 310, true, true, true, 'curated'),
  ('Rice and Veggie Breakfast Bowl', 'Warm leftover rice topped with a fried egg, sauteed spinach, and a drizzle of sesame oil for a savory morning bowl.', 'breakfast', 'Asian-Inspired', 'ultra_budget', ARRAY['asian-inspired','budget','dairy-free','gluten-free','nut-free','one-bowl','savory','vegetarian']::text[], '["2 cups cooked rice", "2 eggs", "2 cups baby spinach", "2 cloves garlic", "1 tbsp vegetable oil", "1 tsp sesame oil", "1 tbsp tamari", "1/2 tsp ginger powder", "salt", "pepper"]'::jsonb, '["Heat vegetable oil in a skillet over medium heat; saute garlic 1 minute.", "Add spinach and cook until wilted, about 2 minutes; season with salt.", "Push spinach to the side and fry eggs to desired doneness.", "Warm rice in a separate pan or microwave.", "Divide rice into bowls, top with spinach and egg.", "Drizzle with sesame oil and tamari; sprinkle ginger powder."]'::jsonb, 2, 5, 10, 1.1, 2.2, 330, 13, 45, 10, 2, 480, false, true, true, 'curated'),
  ('Creamy Polenta with Fried Egg', 'Velvety stovetop polenta enriched with parmesan and topped with a perfectly fried egg and cracked pepper.', 'breakfast', 'Italian-Inspired', 'ultra_budget', ARRAY['budget','comfort','gluten-free','hearty','italian-inspired','kid-friendly','nut-free','one-pot','soy-free','vegetarian']::text[], '["1 cup polenta", "4 cups water", "1/2 cup grated parmesan", "2 tbsp butter", "4 eggs", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Bring salted water to a boil; whisk in polenta slowly.", "Reduce heat and cook, stirring often, for 15 minutes until thick.", "Stir in butter and parmesan; season with salt and pepper.", "Heat olive oil in a skillet; fry eggs to desired doneness.", "Spoon polenta into bowls and top each with a fried egg."]'::jsonb, 4, 5, 18, 1.2, 4.8, 360, 15, 38, 16, 2, 440, true, true, true, 'curated'),
  ('Peanut Butter Banana Oatmeal', 'Creamy stovetop oatmeal swirled with peanut butter and topped with sliced banana for a filling morning bowl.', 'breakfast', 'American', 'ultra_budget', ARRAY['american','budget','egg-free','gluten-free','kid-friendly','quick','soy-free','sweet','vegetarian']::text[], '["2 cups rolled oats", "4 cups water", "2 bananas", "4 tbsp peanut butter", "2 tbsp honey", "1/2 tsp cinnamon", "pinch salt"]'::jsonb, '["Bring water and salt to a boil in a saucepan.", "Stir in rolled oats and reduce heat to medium.", "Cook, stirring occasionally, for 5 minutes until thick.", "Remove from heat and swirl in peanut butter and honey.", "Ladle into bowls and top with sliced banana and cinnamon."]'::jsonb, 4, 2, 7, 0.7, 2.8, 390, 12, 58, 13, 6, 130, true, true, true, 'curated'),
  ('Veggie Egg Muffin Cups', 'Individual baked egg cups packed with colorful diced vegetables for a portable and protein-rich breakfast.', 'breakfast', 'American', 'budget', ARRAY['american','budget','gluten-free','kid-friendly','meal-prep','nut-free','portable','soy-free','vegetarian']::text[], '["6 eggs", "1 red bell pepper", "1 cup spinach", "1/2 onion", "1/2 cup shredded cheddar cheese", "2 tbsp milk", "1/2 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 375F and grease a 6-cup muffin tin.", "Finely dice bell pepper and onion; chop spinach.", "Divide vegetables evenly among muffin cups.", "Whisk eggs with milk, garlic powder, salt, and pepper; pour over vegetables.", "Top each cup with shredded cheddar.", "Bake 18-20 minutes until eggs are puffed and set."]'::jsonb, 3, 10, 20, 1.6, 4.8, 220, 17, 7, 14, 1, 360, true, true, true, 'curated'),
  ('Cottage Cheese and Fruit Bowl', 'Creamy cottage cheese spooned over fresh seasonal fruit with a drizzle of honey for a light, protein-packed start.', 'breakfast', 'American', 'budget', ARRAY['american','budget','egg-free','gluten-free','high-protein','kid-friendly','light','no-cook','nut-free','quick','soy-free','vegetarian']::text[], '["2 cups cottage cheese", "1 cup strawberries", "1 banana", "1/2 cup blueberries", "2 tbsp honey", "1/4 tsp cinnamon"]'::jsonb, '["Wash and hull strawberries; slice banana.", "Divide cottage cheese into 2 bowls.", "Arrange strawberries, banana slices, and blueberries on top.", "Drizzle with honey and sprinkle with cinnamon."]'::jsonb, 2, 8, 0, 2.2, 4.4, 310, 22, 44, 5, 3, 480, true, true, true, 'curated'),
  ('Savory Quinoa Breakfast Bowl', 'Protein-rich quinoa cooked in vegetable broth and topped with avocado, a soft-boiled egg, and cherry tomatoes.', 'breakfast', 'American', 'budget', ARRAY['american','budget','dairy-free','gluten-free','hearty','meal-prep','nut-free','soy-free','vegetarian']::text[], '["1 cup quinoa", "2 cups vegetable broth", "4 eggs", "1 avocado", "1 cup cherry tomatoes", "1 tbsp olive oil", "1/2 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Rinse quinoa; combine with vegetable broth in a saucepan and bring to a boil.", "Reduce heat, cover, and simmer 15 minutes until liquid is absorbed.", "Meanwhile, soft-boil eggs: simmer in water 7 minutes, then cool in ice water and peel.", "Halve avocado and slice; halve cherry tomatoes.", "Fluff quinoa and season with garlic powder, salt, and pepper.", "Divide into bowls; top with egg halves, avocado, and tomatoes; drizzle with olive oil."]'::jsonb, 4, 8, 18, 2.5, 10.0, 390, 18, 38, 18, 6, 420, false, true, true, 'curated'),
  ('Greek Yogurt Parfait with Granola', 'Layers of thick Greek yogurt, crunchy oat clusters, and mixed berries create a vibrant and creamy parfait.', 'breakfast', 'American', 'budget', ARRAY['american','budget','egg-free','gluten-free','high-protein','kid-friendly','layered','no-cook','nut-free','soy-free','vegetarian']::text[], '["2 cups plain Greek yogurt", "1 cup rolled oats", "3 tbsp honey", "1 tbsp vegetable oil", "1 cup mixed frozen berries", "1/4 tsp cinnamon"]'::jsonb, '["Preheat oven to 325F; toss oats with oil, 1 tbsp honey, and cinnamon on a baking sheet.", "Bake 15 minutes, stirring once, until golden; let cool.", "Thaw berries slightly or warm briefly in microwave.", "Layer yogurt, granola, and berries in glasses or bowls.", "Drizzle remaining honey on top and serve."]'::jsonb, 2, 5, 15, 2.1, 4.2, 420, 20, 60, 9, 4, 80, true, true, true, 'curated'),
  ('Potato and Pepper Breakfast Skillet', 'Diced Yukon Gold potatoes pan-fried with colorful peppers and onion, seasoned with smoky paprika.', 'breakfast', 'American', 'ultra_budget', ARRAY['american','budget','comfort','dairy-free','egg-free','gluten-free','hearty','kid-friendly','nut-free','one-pan','soy-free','vegan','vegetarian']::text[], '["4 medium Yukon Gold potatoes", "1 green bell pepper", "1 red bell pepper", "1 onion", "3 tbsp vegetable oil", "1 tsp smoked paprika", "1/2 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Dice potatoes into 1/2-inch cubes (no need to peel).", "Heat oil in a large cast-iron or heavy skillet over medium-high heat.", "Add potatoes; cook undisturbed 6 minutes, then stir and cook 6 more minutes until crispy.", "Add diced peppers and onion; cook 5 minutes until tender.", "Season with smoked paprika, garlic powder, salt, and pepper."]'::jsonb, 4, 10, 18, 1.1, 4.4, 270, 5, 38, 11, 4, 310, true, true, true, 'curated'),
  ('Mango Coconut Rice Porridge', 'Tender rice simmered in coconut milk with ripe mango and a hint of ginger for a tropical breakfast porridge.', 'breakfast', 'Asian-Inspired', 'budget', ARRAY['asian-inspired','budget','egg-free','gluten-free','kid-friendly','nut-free','one-pot','soy-free','sweet','tropical','vegetarian']::text[], '["1 cup jasmine rice", "1 can coconut milk", "1 cup water", "2 mangos", "2 tbsp honey", "1/2 tsp ginger powder", "pinch salt"]'::jsonb, '["Combine rice, coconut milk, water, and salt in a saucepan; bring to a boil.", "Reduce heat, stir in ginger powder, and cook uncovered 15 minutes, stirring often, until thick and porridge-like.", "Peel and dice mango.", "Spoon porridge into bowls; top with mango and drizzle with honey."]'::jsonb, 4, 5, 18, 2.0, 8.0, 380, 6, 64, 12, 2, 100, true, true, true, 'curated'),
  ('Black Bean and Egg Breakfast Burrito Bowl', 'A hearty rice bowl piled with spiced black beans, scrambled eggs, salsa, and melted cheese.', 'breakfast', 'Tex-Mex', 'ultra_budget', ARRAY['budget','gluten-free','hearty','high-protein','kid-friendly','nut-free','one-bowl','soy-free','tex-mex','vegetarian']::text[], '["1 cup long-grain white rice", "1 can black beans", "4 eggs", "1/2 cup salsa", "1/2 cup shredded cheddar cheese", "1 tbsp vegetable oil", "1/2 tsp cumin", "1/2 tsp chili powder", "salt", "pepper"]'::jsonb, '["Cook rice according to package directions.", "Drain and rinse black beans; heat in a saucepan with cumin, chili powder, and a pinch of salt.", "Scramble eggs in a skillet with oil over medium heat; season with salt and pepper.", "Divide rice into bowls; top with black beans, scrambled eggs, and salsa.", "Sprinkle shredded cheddar over each bowl."]'::jsonb, 4, 5, 20, 1.5, 6.0, 420, 22, 52, 13, 8, 580, true, true, true, 'curated'),
  ('Spinach and Feta Frittata', 'A golden oven-baked egg frittata loaded with wilted spinach, crumbled feta, and roasted red pepper.', 'breakfast', 'Mediterranean', 'budget', ARRAY['budget','gluten-free','meal-prep','mediterranean','nut-free','one-pan','soy-free','vegetarian']::text[], '["6 eggs", "2 cups baby spinach", "1/2 cup crumbled feta cheese", "1 roasted red pepper", "1/4 cup milk", "1 tbsp olive oil", "1/2 tsp oregano", "salt", "pepper"]'::jsonb, '["Preheat oven to 375F.", "Heat olive oil in an oven-safe skillet over medium heat; wilt spinach 2 minutes.", "Dice roasted red pepper and add to skillet.", "Whisk eggs with milk, oregano, salt, and pepper; pour over vegetables.", "Sprinkle feta on top and transfer to oven.", "Bake 18-20 minutes until puffed and golden; slice into wedges."]'::jsonb, 4, 8, 22, 2.3, 9.2, 210, 16, 5, 15, 1, 510, false, true, true, 'curated'),
  ('Warm Lentil and Tomato Salad', 'Tender green lentils tossed with juicy cherry tomatoes, cucumber, and a bright lemon vinaigrette.', 'lunch', 'Mediterranean', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','light','mediterranean','no-cook','nut-free','soy-free','vegan','vegetarian']::text[], '["1 cup green lentils", "1 cup cherry tomatoes", "1 cucumber", "1/4 red onion", "2 tbsp olive oil", "2 tbsp lemon juice", "1 tsp cumin", "2 tbsp fresh parsley", "salt", "pepper"]'::jsonb, '["Rinse lentils; cover with 3 cups water in a saucepan and bring to a boil.", "Reduce heat and simmer 20 minutes until tender; drain and cool slightly.", "Halve tomatoes, dice cucumber, and thinly slice red onion.", "Whisk olive oil, lemon juice, cumin, salt, and pepper together.", "Toss lentils with vegetables, dressing, and fresh parsley; serve warm or at room temperature."]'::jsonb, 4, 10, 22, 1.2, 4.8, 270, 16, 36, 7, 11, 280, false, true, true, 'curated'),
  ('Chicken and Rice Soup', 'A soothing bowl of slow-simmered chicken broth loaded with tender chicken pieces, carrots, and white rice.', 'lunch', 'Soup', 'budget', ARRAY['budget','comfort','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb chicken thighs", "1 cup long-grain white rice", "3 carrots", "3 stalks celery", "1 onion", "4 cloves garlic", "6 cups chicken broth", "1 tsp thyme", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large pot; brown chicken thighs 4 minutes per side and set aside.", "Saute diced onion, sliced carrots, and celery 5 minutes; add garlic and cook 1 minute.", "Return chicken to pot; pour in broth and add thyme.", "Bring to a boil, then simmer 20 minutes until chicken is cooked through.", "Remove chicken, shred, and return to pot with rice.", "Simmer 15 more minutes until rice is tender; season with salt and pepper."]'::jsonb, 6, 12, 45, 2.1, 12.6, 340, 26, 32, 10, 2, 620, true, true, true, 'curated'),
  ('Cuban-Style Black Bean Bowl', 'Richly seasoned black beans over white rice with pickled onions and a squeeze of lime for a satisfying midday meal.', 'lunch', 'Cuban', 'ultra_budget', ARRAY['budget','comfort','cuban','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','nut-free','one-bowl','soy-free','vegan','vegetarian']::text[], '["2 cans black beans", "1 cup long-grain white rice", "1 red onion", "4 cloves garlic", "1/4 cup apple cider vinegar", "2 tbsp olive oil", "1 tsp cumin", "1 tsp oregano", "1 lime", "salt", "pepper"]'::jsonb, '["Thinly slice red onion and soak in vinegar with a pinch of salt for 15 minutes.", "Cook rice according to package directions.", "Heat olive oil over medium heat; saute minced garlic 1 minute.", "Add drained black beans, cumin, oregano, salt, and pepper; cook 8 minutes.", "Lightly mash some beans for a creamier texture.", "Serve beans over rice topped with pickled onion and a squeeze of lime."]'::jsonb, 4, 10, 25, 1.4, 5.6, 380, 16, 66, 7, 13, 490, true, true, true, 'curated'),
  ('Tuna and White Bean Lettuce Wraps', 'Canned tuna mixed with creamy white beans, lemon, and herbs, scooped into crisp romaine leaves.', 'lunch', 'Mediterranean', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','light','mediterranean','no-cook','nut-free','quick','soy-free','standard']::text[], '["2 cans tuna in water", "1 can white beans", "4 stalks celery", "1/4 red onion", "2 tbsp olive oil", "2 tbsp lemon juice", "1 tsp dijon mustard", "2 tbsp fresh parsley", "1 head romaine lettuce", "salt", "pepper"]'::jsonb, '["Drain tuna and white beans; place in a mixing bowl.", "Finely dice celery and red onion; add to bowl.", "Whisk olive oil, lemon juice, and mustard; pour over tuna mixture.", "Fold in parsley; season with salt and pepper.", "Separate large romaine leaves; spoon tuna mixture into each leaf to serve."]'::jsonb, 4, 12, 0, 2.4, 9.6, 290, 28, 22, 9, 6, 530, false, true, true, 'curated'),
  ('Egg Drop Soup with Corn', 'Silky ribbons of egg swirled into a light ginger-scented broth with sweet corn and sliced scallions.', 'lunch', 'Chinese-Inspired', 'ultra_budget', ARRAY['budget','chinese-inspired','dairy-free','gluten-free','kid-friendly','light','nut-free','one-pot','quick','soup','standard']::text[], '["4 cups chicken broth", "1 cup frozen corn", "3 eggs", "2 scallions", "1 tbsp tamari", "1 tsp ginger powder", "1 tsp cornstarch", "2 tbsp water", "salt", "pepper"]'::jsonb, '["Bring chicken broth to a simmer; add corn, tamari, and ginger powder.", "Whisk cornstarch with water and stir into the broth to slightly thicken.", "Beat eggs in a small bowl.", "Slowly drizzle eggs into the simmering broth while stirring gently in a circle.", "Cook 1 minute until egg strands set; season with salt and pepper.", "Ladle into bowls and top with thinly sliced scallions."]'::jsonb, 4, 5, 10, 1.1, 4.4, 130, 10, 12, 4, 1, 580, true, true, true, 'curated'),
  ('Roasted Vegetable and Quinoa Bowl', 'Oven-roasted zucchini, bell pepper, and chickpeas over fluffy quinoa with a lemon-herb drizzle.', 'lunch', 'Sheet-Pan', 'budget', ARRAY['budget','colorful','dairy-free','egg-free','gluten-free','meal-prep','mediterranean','nut-free','sheet-pan','soy-free','vegan','vegetarian']::text[], '["1 cup quinoa", "2 cups vegetable broth", "1 zucchini", "1 red bell pepper", "1 can chickpeas", "3 tbsp olive oil", "1 tsp cumin", "1 tsp smoked paprika", "2 tbsp lemon juice", "1 tbsp fresh parsley", "salt", "pepper"]'::jsonb, '["Preheat oven to 425F; line a baking sheet with foil.", "Dice zucchini and bell pepper; drain and rinse chickpeas.", "Toss vegetables and chickpeas with 2 tbsp olive oil, cumin, smoked paprika, salt, and pepper.", "Spread on baking sheet and roast 20-22 minutes until edges are golden.", "Meanwhile cook quinoa in vegetable broth per package directions.", "Serve quinoa topped with roasted vegetables; drizzle with remaining olive oil and lemon juice, garnish with parsley."]'::jsonb, 4, 12, 25, 2.6, 10.4, 390, 16, 52, 13, 9, 430, false, true, true, 'curated'),
  ('Korean-Inspired Beef and Rice Bowl', 'Seasoned ground beef cooked with garlic, ginger, and tamari, served over steamed rice with cucumber slices.', 'lunch', 'Korean-Inspired', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','korean-inspired','nut-free','one-pan','quick','standard']::text[], '["1 lb ground beef", "2 cups jasmine rice", "4 cloves garlic", "1 tsp ginger powder", "3 tbsp tamari", "1 tbsp sesame oil", "2 tbsp honey", "1 cucumber", "3 scallions", "1 tsp vegetable oil", "pepper"]'::jsonb, '["Cook jasmine rice according to package directions.", "Heat vegetable oil in a skillet over medium-high heat; brown ground beef, breaking apart.", "Drain excess fat; add minced garlic and cook 1 minute.", "Stir in tamari, honey, ginger powder, and pepper; cook 2 minutes.", "Drizzle sesame oil over beef and remove from heat.", "Serve beef over rice with thinly sliced cucumber and scallions."]'::jsonb, 4, 8, 22, 2.9, 11.6, 510, 28, 55, 18, 1, 680, true, true, true, 'curated'),
  ('Red Lentil Coconut Soup', 'Silky red lentils simmered with coconut milk, tomatoes, and warming curry spices into a thick, comforting soup.', 'lunch', 'Indian-Inspired', 'ultra_budget', ARRAY['budget','egg-free','gluten-free','high-fiber','indian-inspired','meal-prep','nut-free','one-pot','soup','soy-free','vegetarian']::text[], '["1 cup red lentils", "1 can coconut milk", "1 can diced tomatoes", "1 onion", "4 cloves garlic", "1 tbsp vegetable oil", "1 tsp curry powder", "1/2 tsp turmeric", "1/2 tsp cumin", "2 cups vegetable broth", "salt", "pepper"]'::jsonb, '["Heat oil in a pot over medium heat; saute diced onion 5 minutes until soft.", "Add minced garlic, curry powder, turmeric, and cumin; stir 1 minute.", "Add rinsed lentils, diced tomatoes, coconut milk, and vegetable broth.", "Bring to a boil, then simmer 20-25 minutes until lentils are completely soft.", "Use an immersion blender to partially blend for a creamy texture.", "Season with salt and pepper; serve hot."]'::jsonb, 6, 10, 30, 1.3, 7.8, 290, 14, 34, 12, 10, 420, false, true, true, 'curated'),
  ('Chicken and Corn Chowder', 'A thick, creamy chowder brimming with tender chicken, sweet corn, and diced potato in a rich broth.', 'lunch', 'Soup', 'budget', ARRAY['budget','comfort','creamy','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb chicken breast", "2 cups frozen corn", "3 medium potatoes", "1 onion", "3 cloves garlic", "2 cups chicken broth", "1 cup milk", "2 tbsp butter", "1 tsp thyme", "salt", "pepper"]'::jsonb, '["Dice chicken breast, potatoes, and onion.", "Melt butter in a large pot; saute onion 4 minutes until soft.", "Add garlic and cook 1 minute; add chicken and cook 4 minutes.", "Add potatoes, corn, broth, and thyme; bring to a boil.", "Simmer 15 minutes until potatoes are tender.", "Stir in milk, season with salt and pepper, and heat through."]'::jsonb, 6, 12, 28, 2.3, 13.8, 330, 24, 35, 9, 3, 520, true, true, true, 'curated'),
  ('Caprese-Style Quinoa Salad', 'Fluffy quinoa tossed with fresh mozzarella, ripe tomatoes, and basil in a tangy balsamic glaze.', 'lunch', 'Italian-Inspired', 'standard', ARRAY['colorful','egg-free','gluten-free','high-protein','italian-inspired','kid-friendly','light','no-cook','nut-free','salad','soy-free','vegetarian']::text[], '["1 cup quinoa", "2 cups water", "8 oz fresh mozzarella", "2 cups cherry tomatoes", "1/4 cup fresh basil", "2 tbsp balsamic vinegar", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Cook quinoa in water per package directions; let cool to room temperature.", "Halve cherry tomatoes and tear mozzarella into chunks.", "Whisk olive oil and balsamic vinegar together.", "Combine quinoa, tomatoes, and mozzarella in a large bowl.", "Drizzle dressing over salad; tear basil on top and season with salt and pepper."]'::jsonb, 4, 8, 18, 3.4, 13.6, 380, 20, 34, 18, 3, 380, true, true, true, 'curated'),
  ('Rainbow Cabbage Slaw with Chicken', 'Crispy shredded cabbage and carrots tossed with pulled rotisserie chicken in a tangy apple cider vinegar dressing.', 'lunch', 'American', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','no-cook','nut-free','quick','salad','soy-free','standard']::text[], '["2 cups shredded rotisserie chicken", "3 cups shredded green cabbage", "1 cup shredded carrots", "1/4 cup red onion", "3 tbsp apple cider vinegar", "2 tbsp olive oil", "1 tbsp honey", "1/2 tsp celery seed", "salt", "pepper"]'::jsonb, '["Thinly slice red onion and combine with cabbage and shredded carrots in a large bowl.", "Add shredded chicken to the bowl.", "Whisk apple cider vinegar, olive oil, honey, and celery seed together.", "Pour dressing over slaw and toss well to coat.", "Season with salt and pepper; refrigerate 15 minutes before serving for best flavor."]'::jsonb, 4, 15, 0, 2.5, 10.0, 270, 22, 14, 13, 3, 380, true, true, true, 'curated'),
  ('Spanish Rice and Pinto Beans', 'Fluffy rice cooked with tomatoes, peppers, and tender pinto beans in a one-pot weeknight staple.', 'dinner', 'Spanish', 'ultra_budget', ARRAY['beans','budget','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','one-pot','rice','soy-free','spanish','vegan','vegetarian']::text[], '["1 cup long-grain white rice", "1 can pinto beans", "1 can diced tomatoes", "1 onion", "1 green bell pepper", "2 cloves garlic", "2 cups water", "1 tsp cumin", "1 tsp chili powder", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Dice onion, bell pepper, and mince garlic.", "Heat oil in a large pot. Saut\u00e9 onion and pepper 5 minutes until soft.", "Add garlic, cumin, and chili powder and cook 1 minute.", "Stir in uncooked rice, diced tomatoes, water, and drained pinto beans.", "Bring to a boil, reduce heat, cover and cook 18 minutes until rice is tender.", "Fluff with a fork and season with salt and pepper."]'::jsonb, 4, 8, 25, 1.1, 4.4, 330, 11, 62, 5, 9, 420, true, true, true, 'curated'),
  ('Egg Fried Rice with Frozen Peas', 'Classic fried rice tossed with scrambled eggs and sweet peas, ready in under 20 minutes.', 'dinner', 'Stir-Fry', 'ultra_budget', ARRAY['asian','budget','dairy-free','eggs','kid-friendly','nut-free','quick','rice','stir-fry','vegetarian']::text[], '["2 cups cooked white rice", "3 eggs", "1 cup frozen peas", "2 cloves garlic", "3 tbsp soy sauce", "1 tbsp vegetable oil", "2 green onions", "salt", "pepper"]'::jsonb, '["Heat oil in a large skillet or wok over high heat.", "Add minced garlic and stir-fry 30 seconds.", "Push garlic to side, crack in eggs and scramble until just set.", "Add rice and frozen peas, stir-fry everything together for 3 minutes.", "Pour soy sauce over rice and toss to coat.", "Garnish with sliced green onions and serve hot."]'::jsonb, 3, 5, 12, 1.05, 3.15, 290, 12, 45, 7, 4, 680, true, true, true, 'curated'),
  ('Potato and Cabbage Hash', 'Crispy skillet potatoes tossed with caramelized cabbage and onion for a satisfying one-pan meal.', 'lunch', 'Skillet', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','one-pan','potatoes','quick','soy-free','vegan','vegetables','vegetarian']::text[], '["4 medium potatoes", "2 cups shredded cabbage", "1 onion", "2 cloves garlic", "2 tbsp vegetable oil", "1 tsp paprika", "salt", "pepper"]'::jsonb, '["Dice potatoes into small cubes and slice onion thinly.", "Heat oil in a large skillet over medium-high heat.", "Cook potatoes for 12 minutes, stirring occasionally, until golden.", "Add onion, cabbage, and garlic and cook another 8 minutes until everything is tender and browned.", "Season with paprika, salt, and pepper before serving."]'::jsonb, 4, 8, 20, 0.75, 3.0, 215, 4, 36, 7, 5, 220, true, true, true, 'curated'),
  ('Curried Chickpea and Potato Stew', 'Tender potatoes and chickpeas simmered in a fragrant curry sauce for a filling dinner bowl.', 'dinner', 'Indian', 'ultra_budget', ARRAY['budget','chickpeas','curry','dairy-free','egg-free','gluten-free','indian','nut-free','one-pot','potatoes','soy-free','vegan','vegetarian']::text[], '["1 can chickpeas", "3 medium potatoes", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tsp curry powder", "1 tsp cumin", "1 tsp turmeric", "2 cups water", "2 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Dice potatoes into cubes. Dice onion and mince garlic.", "Heat oil in a large pot over medium heat. Cook onion 5 minutes until soft.", "Add garlic, curry powder, cumin, and turmeric, stir 1 minute.", "Add chickpeas, potatoes, diced tomatoes, and water.", "Bring to a boil, reduce heat, cover and simmer 20 minutes until potatoes are tender.", "Season with salt and pepper and serve over rice."]'::jsonb, 4, 8, 28, 1.15, 4.6, 290, 11, 48, 6, 9, 410, false, true, true, 'curated'),
  ('Spaghetti with Canned Tomato Sauce', 'A no-fuss spaghetti dinner with a from-scratch tomato sauce that tastes like it simmered all day.', 'dinner', 'Italian', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','italian','kid-friendly','nut-free','pasta','quick','soy-free','tomato','vegan','vegetarian']::text[], '["8 oz spaghetti", "2 cans crushed tomatoes", "1 onion", "4 cloves garlic", "1 tsp Italian seasoning", "1 tsp sugar", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Cook spaghetti in salted boiling water until al dente, then drain.", "While pasta cooks, dice onion and mince garlic.", "Heat olive oil in a saucepan over medium heat and saut\u00e9 onion 5 minutes.", "Add garlic and Italian seasoning, cook 1 minute.", "Pour in crushed tomatoes and sugar, simmer 15 minutes. Season with salt and pepper.", "Toss pasta with sauce and serve immediately."]'::jsonb, 4, 5, 20, 1.0, 4.0, 320, 10, 60, 5, 6, 510, true, true, true, 'curated'),
  ('Lentil and Brown Rice Pilaf', 'Nutty brown rice and earthy lentils cooked together with caramelized onion for a protein-rich side or main.', 'lunch', 'Middle Eastern', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','kid-friendly','lentils','middle-eastern','nut-free','one-pot','rice','soy-free','vegan','vegetarian']::text[], '["1 cup brown rice", "1 cup green lentils", "2 large onions", "3 cups water", "1 tsp cumin", "1 tsp cinnamon", "3 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Rinse lentils and rice separately.", "Slice onions thinly and cook in oil over medium-low heat 20 minutes, stirring, until deep brown.", "Remove half the onions and set aside for topping.", "Add cumin, cinnamon, rice, lentils, and water to the pot. Season with salt.", "Bring to a boil, cover, and simmer on low for 35 minutes until liquid is absorbed.", "Fluff and top with reserved caramelized onions."]'::jsonb, 4, 5, 55, 0.95, 3.8, 350, 15, 62, 7, 12, 200, true, true, true, 'curated'),
  ('Creamy Potato Leek Soup', 'Silky blended potato and leek soup that is rich and comforting without any cream needed.', 'lunch', 'Soup', 'ultra_budget', ARRAY['blended','budget','egg-free','gluten-free','kid-friendly','nut-free','one-pot','potatoes','soup','soy-free','vegetarian']::text[], '["5 medium potatoes", "2 leeks", "1 onion", "4 cups water", "2 cloves garlic", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Peel and dice potatoes. Slice leeks (white and light green parts) and dice onion.", "Heat olive oil in a large pot and cook leeks and onion over medium heat 8 minutes.", "Add garlic and cook 1 minute more.", "Add potatoes and water. Bring to a boil.", "Reduce heat and simmer 20 minutes until potatoes are very soft.", "Blend soup until smooth. Season with salt and pepper."]'::jsonb, 4, 10, 30, 1.1, 4.4, 220, 5, 38, 6, 5, 190, true, true, true, 'curated'),
  ('Tuna Noodle Skillet', 'A quick one-skillet dinner with canned tuna, egg noodles, and a simple creamy sauce kids love.', 'dinner', 'Skillet', 'ultra_budget', ARRAY['budget','high-protein','kid-friendly','nut-free','one-pan','pasta','quick','seafood','soy-free','standard']::text[], '["2 cans tuna in water", "6 oz egg noodles", "1 cup frozen peas", "1 can cream of mushroom soup", "1 cup water", "1 onion", "1 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Dice onion and saut\u00e9 in oil in a large skillet over medium heat for 4 minutes.", "Add cream of mushroom soup and water, stir until smooth.", "Add uncooked egg noodles and bring to a simmer.", "Cover and cook 10 minutes, stirring occasionally, until noodles are tender.", "Stir in drained tuna and frozen peas. Cook 3 more minutes.", "Season with salt and pepper and serve hot."]'::jsonb, 4, 5, 18, 1.4, 5.6, 310, 22, 40, 6, 4, 620, true, true, true, 'curated'),
  ('Black-Eyed Pea and Greens Stew', 'Southern-style stew with black-eyed peas and collard greens simmered in a savory broth.', 'dinner', 'Southern', 'ultra_budget', ARRAY['beans','budget','dairy-free','egg-free','gluten-free','nut-free','one-pot','soup','southern','soy-free','vegan','vegetarian']::text[], '["2 cans black-eyed peas", "1 bunch collard greens", "1 onion", "3 cloves garlic", "1 can diced tomatoes", "3 cups water", "1 tsp smoked paprika", "2 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Remove stems from collard greens and chop leaves into strips.", "Dice onion and mince garlic. Saut\u00e9 in oil over medium heat for 5 minutes.", "Add smoked paprika and garlic, cook 1 minute.", "Add drained peas, diced tomatoes, and water. Bring to a boil.", "Add collard greens, reduce heat and simmer 25 minutes until greens are tender.", "Season with salt and pepper."]'::jsonb, 4, 10, 30, 1.2, 4.8, 265, 14, 40, 5, 10, 450, false, true, true, 'curated'),
  ('Veggie Lo Mein with Cabbage', 'Savory noodles tossed with cabbage, carrots, and a garlic soy sauce in a speedy stir-fry.', 'dinner', 'Stir-Fry', 'ultra_budget', ARRAY['asian','budget','dairy-free','egg-free','kid-friendly','noodles','nut-free','quick','stir-fry','vegan','vegetables','vegetarian']::text[], '["8 oz spaghetti", "2 cups shredded cabbage", "2 carrots", "3 cloves garlic", "3 tbsp soy sauce", "1 tbsp vegetable oil", "1 tsp sesame oil", "2 green onions", "pepper"]'::jsonb, '["Cook spaghetti in boiling water until al dente, then drain and set aside.", "Shred cabbage and julienne carrots. Mince garlic.", "Heat vegetable oil in a large skillet over high heat.", "Stir-fry cabbage and carrots for 4 minutes until slightly tender.", "Add garlic and cook 30 seconds, then add noodles and soy sauce.", "Toss everything together, drizzle with sesame oil, and garnish with green onions."]'::jsonb, 4, 8, 15, 1.1, 4.4, 295, 9, 53, 5, 4, 640, true, true, true, 'curated'),
  ('Baked Potato Bar', 'Fluffy oven-baked potatoes served with canned beans and your favorite simple toppings for a build-your-own dinner.', 'dinner', 'American', 'ultra_budget', ARRAY['american','baked','budget','customizable','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','potatoes','soy-free','vegan','vegetarian']::text[], '["4 large baking potatoes", "1 can pinto beans", "1 tsp cumin", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F.", "Scrub potatoes, prick all over with a fork, rub with olive oil and salt.", "Bake directly on oven rack for 50-60 minutes until tender.", "While potatoes bake, heat beans with cumin, salt, and pepper in a small pot.", "Split potatoes open and top with seasoned beans and desired toppings."]'::jsonb, 4, 5, 60, 0.85, 3.4, 310, 10, 60, 3, 9, 310, true, true, true, 'curated'),
  ('Chickpea Tomato Shakshuka', 'Eggs poached in a spiced tomato and chickpea sauce, served straight from the skillet with crusty bread.', 'dinner', 'Middle Eastern', 'ultra_budget', ARRAY['budget','dairy-free','eggs','middle-eastern','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["4 eggs", "1 can chickpeas", "2 cans crushed tomatoes", "1 onion", "3 cloves garlic", "1 tsp cumin", "1 tsp paprika", "1 tsp chili flakes", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Dice onion and mince garlic. Heat olive oil in a large skillet over medium heat.", "Saut\u00e9 onion 5 minutes, then add garlic, cumin, paprika, and chili flakes. Cook 1 minute.", "Add crushed tomatoes and drained chickpeas. Stir and simmer 10 minutes.", "Make 4 wells in the sauce and crack an egg into each.", "Cover and cook 5-7 minutes until egg whites are set but yolks are still runny.", "Season with salt and pepper and serve from the pan."]'::jsonb, 4, 5, 22, 1.25, 5.0, 270, 14, 32, 10, 8, 490, false, true, true, 'curated'),
  ('Corn and Black Bean Quesadillas', 'Crispy flour tortillas filled with sweet corn, black beans, and melted cheese for an easy weeknight lunch.', 'lunch', 'Mexican', 'ultra_budget', ARRAY['beans','budget','cheese','egg-free','kid-friendly','mexican','nut-free','quick','soy-free','vegetarian']::text[], '["8 flour tortillas", "1 can black beans", "1 can corn", "1 cup shredded cheddar cheese", "1 tsp cumin", "1 tsp chili powder", "salt"]'::jsonb, '["Drain and rinse black beans and corn.", "Mix beans, corn, cumin, chili powder, and a pinch of salt in a bowl.", "Place a tortilla in a dry skillet over medium heat.", "Sprinkle cheese on half, then spoon bean mixture on top of cheese.", "Fold tortilla over and cook 2-3 minutes per side until golden and crispy.", "Cut into wedges and serve with salsa."]'::jsonb, 4, 5, 15, 1.3, 5.2, 340, 14, 49, 10, 7, 560, true, true, true, 'curated'),
  ('Oven-Roasted Vegetable and Rice Bowl', 'Caramelized roasted vegetables over steamed rice with a drizzle of soy sauce for a wholesome dinner bowl.', 'dinner', 'Sheet-Pan', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','kid-friendly','meal-prep','nut-free','rice','sheet-pan','vegan','vegetables','vegetarian']::text[], '["2 cups white rice", "2 medium potatoes", "2 carrots", "1 cup frozen broccoli", "1 onion", "3 tbsp soy sauce", "2 tbsp vegetable oil", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F. Cook rice per package instructions.", "Cube potatoes and carrots, slice onion into wedges.", "Toss potatoes, carrots, and onion with oil, garlic powder, salt, and pepper.", "Spread on a baking sheet and roast 25 minutes.", "Add frozen broccoli to the pan and roast 10 more minutes until everything is golden.", "Serve roasted vegetables over rice and drizzle with soy sauce."]'::jsonb, 4, 10, 35, 1.05, 4.2, 345, 8, 65, 6, 6, 490, true, true, true, 'curated'),
  ('Pasta Fagioli with Elbow Macaroni', 'Cozy macaroni and white bean soup with tomatoes and herbs that comes together fast on a weeknight.', 'dinner', 'Italian', 'ultra_budget', ARRAY['beans','budget','dairy-free','egg-free','italian','kid-friendly','nut-free','one-pot','pasta','soup','soy-free','vegan','vegetarian']::text[], '["1 cup elbow macaroni", "2 cans white beans", "1 can diced tomatoes", "1 onion", "4 cloves garlic", "4 cups water", "1 tsp dried oregano", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Dice onion and mince garlic. Heat olive oil in a large pot over medium heat.", "Cook onion 5 minutes, then add garlic and oregano for 1 minute.", "Add beans, diced tomatoes, and water. Bring to a boil.", "Add macaroni and cook 8-10 minutes until tender.", "Mash some of the beans against the pot wall to thicken the broth.", "Season with salt and pepper and serve hot."]'::jsonb, 6, 5, 18, 0.9, 5.4, 275, 13, 48, 4, 9, 400, true, true, true, 'curated'),
  ('Spiced Lentil Wraps', 'Warm flour tortillas filled with spiced lentils, fresh tomatoes, and crunchy shredded cabbage.', 'lunch', 'Fusion', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','fusion','kid-friendly','lentils','nut-free','quick','soy-free','vegan','vegetarian','wraps']::text[], '["1 cup green lentils", "6 flour tortillas", "1 cup shredded cabbage", "1 tomato", "1 onion", "2 cloves garlic", "1 tsp cumin", "1 tsp paprika", "2 cups water", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Rinse lentils and cook in 2 cups water with a pinch of salt for 20 minutes until tender. Drain.", "Dice onion and mince garlic. Saut\u00e9 in olive oil 5 minutes.", "Add cooked lentils, cumin, and paprika. Stir and cook 3 minutes.", "Dice tomato.", "Warm tortillas, then fill with lentil mixture, shredded cabbage, and diced tomato.", "Roll up and serve immediately."]'::jsonb, 3, 5, 28, 1.05, 3.15, 360, 16, 57, 7, 11, 370, true, true, true, 'curated'),
  ('Frozen Veggie and Egg Scramble', 'A colorful, protein-packed scramble made with frozen mixed vegetables and fluffy eggs for a fast lunch.', 'lunch', 'Skillet', 'ultra_budget', ARRAY['budget','dairy-free','eggs','gluten-free','kid-friendly','nut-free','one-pan','quick','soy-free','vegetables','vegetarian']::text[], '["6 eggs", "2 cups frozen mixed vegetables", "1 onion", "2 cloves garlic", "1 tbsp vegetable oil", "1 tsp paprika", "salt", "pepper"]'::jsonb, '["Cook frozen vegetables in a skillet over medium-high heat with a splash of water until heated, about 4 minutes.", "Push vegetables to the side and add oil, then cook diced onion 3 minutes.", "Add minced garlic and paprika, cook 30 seconds.", "Whisk eggs with salt and pepper, then pour into the skillet.", "Stir gently, cooking until eggs are set but still moist, about 3 minutes.", "Serve immediately."]'::jsonb, 3, 3, 12, 0.95, 2.85, 225, 14, 15, 11, 4, 310, true, true, true, 'curated'),
  ('Refried Bean and Cheese Burritos', 'Soft flour tortillas filled with creamy refried beans and melted cheese for a simple, filling meal.', 'lunch', 'Mexican', 'ultra_budget', ARRAY['beans','budget','cheese','egg-free','kid-friendly','mexican','nut-free','quick','soy-free','vegetarian']::text[], '["1 can refried beans", "6 flour tortillas", "1 cup shredded cheddar cheese", "1 tsp cumin", "1 tsp chili powder", "salt"]'::jsonb, '["Warm refried beans in a small pot with cumin, chili powder, and salt.", "Warm tortillas in a dry skillet or microwave.", "Spread a generous scoop of beans down the center of each tortilla.", "Sprinkle shredded cheese over the beans.", "Fold sides in and roll up into a burrito.", "Serve as-is or toast in a skillet for 1-2 minutes per side for a crispy exterior."]'::jsonb, 3, 3, 8, 1.2, 3.6, 380, 16, 52, 11, 8, 680, true, true, true, 'curated'),
  ('Korean-Style Steamed Egg Bowl', 'Silky smooth steamed eggs in a savory broth served over rice, inspired by Korean gyeran-jjim.', 'dinner', 'Korean', 'ultra_budget', ARRAY['budget','dairy-free','eggs','kid-friendly','korean','nut-free','quick','rice','vegetarian']::text[], '["4 eggs", "2 cups cooked white rice", "1 cup water", "2 tbsp soy sauce", "2 green onions", "1 tsp sesame oil", "salt"]'::jsonb, '["Whisk eggs with water, soy sauce, and a pinch of salt until combined.", "Pour egg mixture into a heat-safe bowl or ramekins.", "Place in a pot with about 1 inch of water and steam over medium heat for 12-15 minutes until set.", "Drizzle sesame oil over the steamed eggs.", "Slice green onions and sprinkle on top.", "Serve over bowls of warm cooked rice."]'::jsonb, 2, 5, 15, 1.0, 2.0, 310, 15, 44, 9, 1, 580, true, true, true, 'curated'),
  ('Pasta with White Bean and Garlic Sauce', 'Tender pasta tossed in a silky white bean and roasted garlic sauce that clings to every noodle.', 'dinner', 'Italian', 'ultra_budget', ARRAY['beans','budget','dairy-free','egg-free','garlic','italian','kid-friendly','nut-free','pasta','quick','soy-free','vegan','vegetarian']::text[], '["8 oz penne pasta", "2 cans white beans", "5 cloves garlic", "3 tbsp olive oil", "1 cup pasta cooking water", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Cook pasta in salted water until al dente. Reserve 1 cup cooking water before draining.", "While pasta cooks, mince garlic and cook in olive oil over medium-low heat for 5 minutes until golden.", "Add drained white beans and Italian seasoning, mash half the beans with a fork.", "Add reserved pasta water and stir to make a sauce.", "Toss cooked pasta into the bean sauce and stir to coat.", "Season with salt and pepper and serve immediately."]'::jsonb, 4, 5, 18, 1.1, 4.4, 340, 16, 58, 7, 10, 350, true, true, true, 'curated'),
  ('Smoky Potato and Corn Chowder', 'A thick, steaming chowder loaded with tender potatoes and sweet corn in a smoky, savory broth.', 'lunch', 'Soup', 'ultra_budget', ARRAY['budget','corn','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','one-pot','potatoes','soup','soy-free','vegan','vegetarian']::text[], '["4 medium potatoes", "1 can corn", "1 onion", "3 cloves garlic", "4 cups water", "1 tsp smoked paprika", "2 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Dice potatoes and onion. Mince garlic.", "Heat oil in a large pot and cook onion over medium heat for 5 minutes.", "Add garlic and smoked paprika, cook 1 minute.", "Add potatoes and water. Bring to a boil.", "Reduce heat and simmer 20 minutes until potatoes are very tender.", "Add drained corn, season with salt and pepper. Mash some potatoes to thicken and serve."]'::jsonb, 4, 8, 28, 0.9, 3.6, 235, 5, 42, 6, 5, 280, true, true, true, 'curated'),
  ('Tomato and Egg Drop Soup', 'A Chinese-style soup with silky egg ribbons and sweet tomato in a light savory broth.', 'lunch', 'Chinese', 'ultra_budget', ARRAY['budget','chinese','dairy-free','eggs','kid-friendly','nut-free','one-pot','quick','soup','vegetarian']::text[], '["3 eggs", "2 tomatoes", "4 cups water", "1 tbsp soy sauce", "1 tsp sesame oil", "2 green onions", "1 tsp cornstarch", "salt", "pepper"]'::jsonb, '["Dice tomatoes. Mix cornstarch with 2 tbsp water to make a slurry.", "Bring water to a boil in a pot. Add tomatoes and soy sauce, simmer 5 minutes.", "Stir in the cornstarch slurry to lightly thicken the broth.", "Whisk eggs in a small bowl. While stirring the soup in circles, slowly drizzle in the eggs.", "Remove from heat after 1 minute once egg ribbons form.", "Drizzle with sesame oil, garnish with green onions, and season with salt and pepper."]'::jsonb, 3, 5, 10, 0.75, 2.25, 115, 7, 6, 6, 1, 420, true, true, true, 'curated'),
  ('Chickpea and Rice Stuffed Cabbage Rolls', 'Tender cabbage leaves stuffed with spiced chickpeas and rice, simmered in a simple tomato sauce.', 'dinner', 'Eastern European', 'ultra_budget', ARRAY['baked','budget','cabbage','chickpeas','dairy-free','eastern-european','egg-free','gluten-free','nut-free','rice','soy-free','vegan','vegetarian']::text[], '["1 head green cabbage", "1 cup white rice", "1 can chickpeas", "1 can crushed tomatoes", "1 onion", "2 cloves garlic", "1 tsp cumin", "1 tsp paprika", "2 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Boil cabbage leaves 3-4 minutes to soften. Cook rice per package instructions.", "Dice onion and mince garlic. Saut\u00e9 in olive oil 5 minutes.", "Mix cooked rice, drained chickpeas, saut\u00e9ed onion, cumin, paprika, salt, and pepper.", "Place filling in cabbage leaves and roll tightly.", "Pour crushed tomatoes into a baking dish, nestle rolls in sauce.", "Cover with foil and bake at 375\u00b0F for 35 minutes."]'::jsonb, 4, 20, 40, 1.35, 5.4, 345, 12, 58, 6, 9, 490, false, true, true, 'curated'),
  ('Smoky Black Bean Breakfast Bowl', 'Seasoned black beans topped with a fried egg and salsa served over warm rice for a hearty morning meal.', 'breakfast', 'Tex-Mex', 'ultra_budget', ARRAY['budget','dairy-free','eggs','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soy-free','tex-mex','vegetarian']::text[], '["1 can black beans", "2 eggs", "1 cup cooked white rice", "1 tsp cumin", "1 tsp chili powder", "2 tbsp salsa", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Drain and rinse black beans, then warm in a small saucepan with cumin, chili powder, salt, and pepper.", "Heat olive oil in a skillet over medium heat and fry eggs to desired doneness.", "Scoop warm rice into bowls, top with seasoned beans, a fried egg, and a spoonful of salsa."]'::jsonb, 2, 5, 10, 1.2, 2.4, 390, 20, 52, 10, 9, 480, true, true, true, 'curated'),
  ('Cinnamon Banana Oatmeal', 'Creamy rolled oats simmered with ripe banana and a touch of cinnamon for a naturally sweet, warming breakfast.', 'breakfast', 'Porridge', 'ultra_budget', ARRAY['budget','comfort-food','egg-free','gluten-free','kid-friendly','nut-free','one-pot','quick','soy-free','vegetarian']::text[], '["2 cups rolled oats", "3 cups water", "1 cup milk", "2 bananas", "1 tsp cinnamon", "1 tbsp sugar", "1 pinch salt"]'::jsonb, '["Combine water, milk, and salt in a saucepan and bring to a gentle boil.", "Stir in oats and cook over medium heat for 5 minutes, stirring frequently.", "Mash one banana into the oats and stir to combine, then sweeten with sugar and cinnamon.", "Serve topped with sliced banana."]'::jsonb, 4, 2, 7, 0.5, 2.0, 280, 9, 52, 4, 6, 105, true, true, true, 'curated'),
  ('Potato and Egg Skillet Hash', 'Diced potatoes pan-fried until crispy then scrambled together with eggs and onion for a satisfying one-pan breakfast.', 'breakfast', 'Skillet', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','gluten-free','kid-friendly','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["3 medium potatoes", "4 eggs", "1 onion", "2 tbsp olive oil", "1 tsp garlic powder", "1 tsp paprika", "salt", "pepper"]'::jsonb, '["Dice potatoes into small cubes and dice the onion.", "Heat olive oil in a large skillet over medium-high heat and cook potatoes for 12 minutes, turning occasionally, until golden and crispy.", "Add onion and cook 3 more minutes until softened.", "Season with garlic powder, paprika, salt, and pepper, then push mixture to the sides.", "Crack eggs into the center of the skillet, scramble gently, and fold into the potato mixture."]'::jsonb, 4, 8, 16, 0.75, 3.0, 270, 11, 33, 10, 3, 220, true, true, true, 'curated'),
  ('Savory Tomato Lentil Porridge', 'Red lentils slow-cooked with tomatoes, ginger, and warm spices into a thick, savory porridge perfect for a filling breakfast.', 'breakfast', 'Indian-Inspired', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','indian-inspired','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["1 cup red lentils", "1 can diced tomatoes", "3 cups water", "1 onion", "2 cloves garlic", "1 tsp ginger powder", "1 tsp cumin", "1 tsp turmeric", "1 tbsp olive oil", "salt"]'::jsonb, '["Rinse lentils and set aside.", "Saut\u00e9 diced onion in olive oil over medium heat for 5 minutes, then add garlic and spices and cook 1 more minute.", "Add lentils, canned tomatoes, and water, then bring to a boil.", "Reduce heat and simmer uncovered for 20 minutes, stirring often, until lentils break down into a thick porridge.", "Season with salt and serve warm."]'::jsonb, 4, 5, 25, 0.8, 3.2, 240, 14, 38, 4, 9, 310, false, true, true, 'curated'),
  ('Peanut Butter Overnight Oats', 'Rolled oats soaked overnight in milk and stirred with peanut butter and honey for a no-cook creamy breakfast ready at sunrise.', 'breakfast', 'No-Cook', 'ultra_budget', ARRAY['budget','egg-free','gluten-free','kid-friendly','make-ahead','no-cook','quick','soy-free','vegetarian']::text[], '["2 cups rolled oats", "2 cups milk", "4 tbsp peanut butter", "2 tbsp honey", "1 tsp cinnamon", "1 pinch salt"]'::jsonb, '["Divide oats equally among four jars or containers.", "Pour half a cup of milk into each jar.", "Stir a tablespoon of peanut butter, half a tablespoon of honey, a pinch of cinnamon, and salt into each jar.", "Cover and refrigerate overnight, then stir before eating."]'::jsonb, 4, 5, 0, 0.7, 2.8, 350, 13, 45, 13, 5, 150, true, true, true, 'curated'),
  ('Egg and Vegetable Scramble with Toast', 'Fluffy scrambled eggs loaded with frozen mixed vegetables and served on crispy toast for a quick and colorful morning plate.', 'breakfast', 'Skillet', 'ultra_budget', ARRAY['budget','comfort-food','kid-friendly','nut-free','one-pan','quick','soy-free','vegetarian']::text[], '["4 eggs", "1 cup frozen mixed vegetables", "4 slices bread", "1 tbsp butter", "2 tbsp milk", "salt", "pepper"]'::jsonb, '["Microwave frozen vegetables for 2 minutes until thawed and warm.", "Whisk eggs with milk, salt, and pepper in a bowl.", "Melt butter in a skillet over medium-low heat, add vegetables, then pour in egg mixture.", "Stir gently until eggs are just set, about 3 minutes.", "Toast bread and serve eggs on top."]'::jsonb, 2, 3, 7, 0.9, 1.8, 310, 17, 34, 11, 4, 370, true, true, true, 'curated'),
  ('Cornmeal Porridge with Brown Sugar', 'Smooth cornmeal cooked in milk until thick and creamy, sweetened with brown sugar for a simple Caribbean-style breakfast.', 'breakfast', 'Porridge', 'ultra_budget', ARRAY['budget','caribbean-inspired','comfort-food','egg-free','gluten-free','kid-friendly','nut-free','one-pot','soy-free','vegetarian']::text[], '["1 cup yellow cornmeal", "3 cups water", "1 cup milk", "3 tbsp brown sugar", "1 tsp vanilla extract", "1 tsp cinnamon", "1 pinch salt"]'::jsonb, '["Whisk cornmeal into cold water in a saucepan until no lumps remain.", "Set over medium heat and stir constantly as the mixture heats and begins to thicken.", "Stir in milk, brown sugar, vanilla, cinnamon, and salt.", "Cook for 10 minutes, stirring frequently, until thick and creamy.", "Serve hot."]'::jsonb, 4, 2, 12, 0.4, 1.6, 230, 6, 47, 2, 2, 95, true, true, true, 'curated'),
  ('Spiced Chickpea Breakfast Tacos', 'Crispy pan-fried chickpeas spiced with cumin and paprika tucked into warm corn tortillas for a bold breakfast bite.', 'breakfast', 'Tex-Mex', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','nut-free','quick','soy-free','tex-mex','vegan','vegetarian']::text[], '["1 can chickpeas", "6 corn tortillas", "1 tbsp olive oil", "1 tsp cumin", "1 tsp paprika", "1 tsp garlic powder", "2 tbsp salsa", "salt", "pepper"]'::jsonb, '["Drain and pat chickpeas dry with paper towels.", "Heat olive oil in a skillet over medium-high heat and add chickpeas.", "Cook 8 to 10 minutes, shaking pan occasionally, until chickpeas are golden and crispy.", "Season with cumin, paprika, garlic powder, salt, and pepper.", "Warm tortillas and fill with spiced chickpeas and a spoonful of salsa."]'::jsonb, 3, 5, 12, 1.0, 3.0, 290, 11, 44, 7, 8, 420, false, true, true, 'curated'),
  ('Rice Congee with Scallions', 'Silky slow-cooked rice porridge simmered until thick and comforting, finished with sliced scallions and a dash of soy sauce.', 'breakfast', 'Asian', 'ultra_budget', ARRAY['asian','budget','comfort-food','dairy-free','egg-free','kid-friendly','make-ahead','nut-free','one-pot','vegan','vegetarian']::text[], '["1 cup white rice", "6 cups water", "2 scallions", "1 tsp soy sauce", "1 tsp sesame oil", "1 tsp ginger powder", "salt", "pepper"]'::jsonb, '["Rinse rice and combine with water in a large pot.", "Bring to a boil, then reduce to the lowest heat and cook uncovered for 45 minutes, stirring occasionally, until thick and creamy.", "Stir in ginger powder, soy sauce, sesame oil, salt, and pepper.", "Ladle into bowls and top with sliced scallions."]'::jsonb, 4, 3, 48, 0.35, 1.4, 175, 4, 37, 2, 1, 195, true, true, true, 'curated'),
  ('Black-Eyed Pea and Tomato Soup', 'Hearty black-eyed peas simmered with canned tomatoes, garlic, and smoky spices into a thick, warming soup.', 'lunch', 'Soup', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','nut-free','one-pot','soup','southern-inspired','soy-free','vegan','vegetarian']::text[], '["2 cans black-eyed peas", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "2 cups water", "1 tsp smoked paprika", "1 tsp cumin", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Saut\u00e9 diced onion in olive oil in a large pot over medium heat for 5 minutes.", "Add minced garlic, smoked paprika, and cumin and cook 1 minute.", "Add black-eyed peas, diced tomatoes, and water.", "Bring to a boil, then simmer 20 minutes.", "Season with salt and pepper and serve with bread if desired."]'::jsonb, 4, 8, 26, 0.9, 3.6, 240, 13, 38, 4, 10, 510, true, true, true, 'curated'),
  ('Potato Leek Soup', 'Tender potatoes and sweet leeks blended into a velvety smooth soup that is deeply satisfying and simply seasoned.', 'lunch', 'Soup', 'ultra_budget', ARRAY['blended','budget','comfort-food','egg-free','gluten-free','kid-friendly','nut-free','one-pot','soup','soy-free','vegetarian']::text[], '["4 medium potatoes", "2 leeks", "3 cups water", "1 cup milk", "2 cloves garlic", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Peel and dice potatoes; slice leeks thinly, using white and light-green parts.", "Saut\u00e9 leeks and garlic in olive oil in a large pot over medium heat for 6 minutes.", "Add potatoes and water, bring to a boil, then simmer 20 minutes until potatoes are soft.", "Stir in milk and blend the soup until smooth using an immersion blender or in batches.", "Season with salt and pepper and reheat gently."]'::jsonb, 4, 10, 28, 0.8, 3.2, 210, 6, 38, 4, 4, 220, true, true, true, 'curated'),
  ('Egg Fried Rice', 'Day-old rice stir-fried with scrambled eggs, frozen peas, soy sauce, and sesame oil for a speedy and satisfying lunch.', 'lunch', 'Stir-Fry', 'ultra_budget', ARRAY['asian','budget','dairy-free','kid-friendly','nut-free','one-pan','quick','stir-fry','vegetarian']::text[], '["3 cups cooked white rice", "3 eggs", "1 cup frozen peas", "2 scallions", "2 tbsp soy sauce", "1 tsp sesame oil", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large skillet or wok over high heat.", "Add cold cooked rice and stir-fry for 3 minutes until heated through.", "Push rice to the sides and scramble eggs in the center, then fold into rice.", "Add frozen peas and cook 2 more minutes.", "Drizzle with soy sauce and sesame oil, toss well, and garnish with sliced scallions."]'::jsonb, 4, 5, 10, 0.7, 2.8, 310, 13, 49, 7, 3, 530, true, true, true, 'curated'),
  ('Red Lentil Soup with Lemon', 'Warming red lentils simmered with cumin, turmeric, and a bright squeeze of lemon into a thick, golden soup.', 'lunch', 'Middle Eastern', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','middle-eastern','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["1 cup red lentils", "1 onion", "3 cloves garlic", "4 cups water", "1 can diced tomatoes", "1 tsp cumin", "1 tsp turmeric", "1 tsp coriander", "1 tbsp olive oil", "1 lemon", "salt", "pepper"]'::jsonb, '["Saut\u00e9 diced onion and minced garlic in olive oil over medium heat for 5 minutes.", "Add spices and stir 30 seconds until fragrant.", "Add lentils, diced tomatoes, and water, then bring to a boil.", "Reduce heat and simmer 25 minutes until lentils are completely soft.", "Squeeze in lemon juice, season with salt and pepper, and blend partially for a creamy texture."]'::jsonb, 4, 8, 30, 0.85, 3.4, 255, 15, 40, 4, 10, 380, false, true, true, 'curated'),
  ('Pinto Bean Quesadillas', 'Flour tortillas stuffed with seasoned mashed pinto beans and toasted in a skillet until golden and crispy.', 'lunch', 'Mexican', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','kid-friendly','mexican','nut-free','one-pan','quick','soy-free','vegan','vegetarian']::text[], '["1 can pinto beans", "4 flour tortillas", "1 tsp cumin", "1 tsp chili powder", "1 tsp garlic powder", "1 tbsp olive oil", "2 tbsp salsa", "salt"]'::jsonb, '["Drain pinto beans and mash with a fork until mostly smooth.", "Season with cumin, chili powder, garlic powder, and salt.", "Spread bean mixture on half of each tortilla and fold in half.", "Heat olive oil in a skillet over medium heat and cook quesadillas 3 minutes per side until golden.", "Slice and serve with salsa."]'::jsonb, 4, 5, 8, 0.75, 3.0, 280, 11, 46, 6, 8, 490, true, true, true, 'curated'),
  ('Curried Potato Soup', 'Soft potato chunks simmered in a fragrant broth of curry powder, canned tomatoes, and onion for a bold and warming bowl.', 'lunch', 'Indian-Inspired', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','indian-inspired','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["4 medium potatoes", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "2 cups water", "2 tsp curry powder", "1 tsp turmeric", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Peel and cube potatoes; dice onion and mince garlic.", "Saut\u00e9 onion in olive oil in a pot over medium heat for 5 minutes, then add garlic, curry powder, and turmeric.", "Add potatoes, diced tomatoes, and water, then bring to a boil.", "Simmer for 20 minutes until potatoes are tender.", "Season with salt and pepper and serve warm."]'::jsonb, 4, 10, 26, 0.65, 2.6, 210, 5, 40, 4, 5, 310, false, true, true, 'curated'),
  ('Tuna and White Bean Salad', 'Canned tuna tossed with white beans, red onion, and a bright lemon-vinegar dressing for a protein-packed no-cook lunch.', 'lunch', 'Salad', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','high-protein','mediterranean','no-cook','nut-free','quick','soy-free','standard']::text[], '["1 can tuna in water", "1 can white beans", "1 small red onion", "1 lemon", "1 tbsp olive oil", "1 tbsp red wine vinegar", "1 tsp dried parsley", "salt", "pepper"]'::jsonb, '["Drain tuna and white beans and place in a large bowl.", "Thinly slice red onion and add to the bowl.", "Whisk together lemon juice, olive oil, red wine vinegar, parsley, salt, and pepper.", "Pour dressing over the tuna and beans and toss to combine.", "Serve immediately or refrigerate for up to one day."]'::jsonb, 3, 8, 0, 1.3, 3.9, 260, 23, 28, 5, 7, 390, false, true, true, 'curated'),
  ('Vegetable Barley Soup', 'Chewy pearl barley cooked with a medley of frozen vegetables and herbs in a simple savory broth for a filling midday bowl.', 'lunch', 'Soup', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','high-fiber','kid-friendly','make-ahead','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["1 cup pearl barley", "2 cups frozen mixed vegetables", "1 onion", "2 cloves garlic", "5 cups water", "1 tsp dried thyme", "1 tsp dried oregano", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Saut\u00e9 diced onion and minced garlic in olive oil over medium heat for 5 minutes.", "Add water, barley, thyme, and oregano, then bring to a boil.", "Reduce heat and simmer 35 minutes until barley is tender.", "Stir in frozen vegetables and cook 5 more minutes.", "Season with salt and pepper and serve."]'::jsonb, 5, 8, 42, 0.6, 3.0, 220, 7, 43, 3, 8, 250, true, true, true, 'curated'),
  ('Rice and Beans with Cumin', 'A classic pairing of white rice and seasoned black beans cooked together with onion and cumin into a hearty and filling plate.', 'dinner', 'Latin American', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','latin-american','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["1 cup white rice", "1 can black beans", "1 onion", "3 cloves garlic", "2 cups water", "1 tsp cumin", "1 tsp chili powder", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Saut\u00e9 diced onion and minced garlic in olive oil in a medium pot over medium heat for 5 minutes.", "Add cumin and chili powder and stir 30 seconds.", "Pour in water and rice, bring to a boil, then cover and simmer 18 minutes.", "Drain and rinse black beans and stir into the cooked rice.", "Season with salt and pepper and fluff with a fork."]'::jsonb, 4, 7, 22, 0.65, 2.6, 340, 13, 63, 4, 9, 370, true, true, true, 'curated'),
  ('Spaghetti with Tomato Garlic Sauce', 'Tender spaghetti tossed in a garlicky canned tomato sauce simmered with olive oil, oregano, and basil.', 'dinner', 'Italian', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','italian','kid-friendly','nut-free','one-pot','quick','soy-free','vegan','vegetarian']::text[], '["1 lb spaghetti", "2 cans diced tomatoes", "4 cloves garlic", "2 tbsp olive oil", "1 tsp dried oregano", "1 tsp dried basil", "1 tsp sugar", "salt", "pepper"]'::jsonb, '["Cook spaghetti in salted boiling water according to package directions, then drain.", "In a separate saucepan, heat olive oil over medium heat and cook thinly sliced garlic for 2 minutes until golden.", "Add canned tomatoes, oregano, basil, and sugar, then simmer 15 minutes.", "Season with salt and pepper, then toss with cooked spaghetti."]'::jsonb, 6, 5, 20, 0.8, 4.8, 360, 11, 68, 6, 4, 350, true, true, true, 'curated'),
  ('Lentil Dal with Basmati Rice', 'Earthy yellow lentils cooked down with tomatoes, garam masala, and ginger and ladled over steamed basmati rice.', 'dinner', 'Indian-Inspired', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-fiber','indian-inspired','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["1 cup yellow lentils", "1 cup basmati rice", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "3 cups water", "1 tsp garam masala", "1 tsp turmeric", "1 tsp ginger powder", "1 tbsp olive oil", "salt"]'::jsonb, '["Cook basmati rice according to package directions and set aside.", "Saut\u00e9 diced onion and garlic in olive oil in a pot over medium heat for 5 minutes.", "Add garam masala, turmeric, and ginger powder and stir 1 minute.", "Add lentils, diced tomatoes, and water, bring to a boil, then simmer 25 minutes until lentils are soft.", "Season with salt and serve over basmati rice."]'::jsonb, 4, 8, 30, 1.0, 4.0, 430, 18, 78, 5, 12, 340, false, true, true, 'curated'),
  ('Pinto Bean Chili', 'A thick and spicy chili built from canned pinto beans, diced tomatoes, onion, and a bold blend of chili spices for a crowd-pleasing dinner.', 'dinner', 'Tex-Mex', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','make-ahead','nut-free','one-pot','soy-free','tex-mex','vegan','vegetarian']::text[], '["2 cans pinto beans", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 cup water", "2 tsp chili powder", "1 tsp cumin", "1 tsp smoked paprika", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Saut\u00e9 diced onion in olive oil over medium heat for 5 minutes, then add garlic and cook 1 minute more.", "Add chili powder, cumin, and smoked paprika and stir to coat.", "Add beans, diced tomatoes, and water, stir well, and bring to a boil.", "Reduce heat and simmer 25 minutes until thickened.", "Season with salt and pepper and serve topped with any desired garnishes."]'::jsonb, 4, 8, 30, 0.85, 3.4, 290, 15, 48, 4, 13, 530, true, true, true, 'curated'),
  ('Stir-Fried Noodles with Cabbage', 'Chewy lo mein-style noodles stir-fried with shredded cabbage, garlic, and soy sauce in a savory and satisfying weeknight dinner.', 'dinner', 'Stir-Fry', 'ultra_budget', ARRAY['asian','budget','dairy-free','egg-free','kid-friendly','nut-free','one-pan','quick','stir-fry','vegan','vegetarian']::text[], '["1 lb spaghetti", "3 cups shredded cabbage", "3 cloves garlic", "3 tbsp soy sauce", "1 tsp sesame oil", "1 tsp sugar", "1 tbsp olive oil", "2 scallions", "pepper"]'::jsonb, '["Cook spaghetti according to package directions until just al dente, then drain.", "Heat olive oil in a large skillet or wok over high heat and stir-fry minced garlic for 30 seconds.", "Add cabbage and cook 4 minutes until wilted.", "Add drained noodles, soy sauce, sesame oil, and sugar, and toss everything together for 2 minutes over high heat.", "Season with pepper and garnish with sliced scallions."]'::jsonb, 5, 5, 15, 0.75, 3.75, 340, 11, 62, 5, 3, 520, true, true, true, 'curated'),
  ('Chickpea and Spinach Stew', 'Tender chickpeas and frozen spinach simmered in a tomato-cumin broth for a deeply flavorful one-pot dinner.', 'dinner', 'Mediterranean', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','mediterranean','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["2 cans chickpeas", "2 cups frozen spinach", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 cup water", "2 tsp cumin", "1 tsp coriander", "1 tsp smoked paprika", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Saut\u00e9 diced onion in olive oil in a large pot over medium heat for 5 minutes.", "Add minced garlic, cumin, coriander, and smoked paprika and cook 1 minute.", "Add chickpeas, diced tomatoes, and water and bring to a boil.", "Stir in frozen spinach and simmer 15 minutes.", "Season with salt and pepper and serve with rice or bread."]'::jsonb, 4, 7, 22, 1.1, 4.4, 300, 15, 44, 6, 12, 490, false, true, true, 'curated'),
  ('Sheet-Pan Roasted Potatoes and Sausage', 'Chunky potato wedges and sliced smoked sausage roasted together on a single pan with bell peppers and Italian seasoning.', 'dinner', 'Sheet-Pan', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','one-pan','sheet-pan','soy-free','standard']::text[], '["4 medium potatoes", "12 oz smoked sausage", "1 green bell pepper", "1 onion", "2 tbsp olive oil", "1 tsp Italian seasoning", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F.", "Cut potatoes into wedges, slice sausage into rounds, and cut bell pepper and onion into chunks.", "Toss everything together with olive oil, Italian seasoning, garlic powder, salt, and pepper.", "Spread in a single layer on a large baking sheet.", "Roast for 35 minutes, flipping halfway through, until potatoes are golden."]'::jsonb, 4, 10, 35, 1.4, 5.6, 430, 17, 44, 21, 5, 720, true, true, true, 'curated'),
  ('Peanut Butter Noodles', 'Spaghetti tossed in a creamy peanut butter sauce with soy sauce, garlic, and a splash of vinegar for an irresistible weeknight dinner.', 'dinner', 'Asian-Inspired', 'ultra_budget', ARRAY['asian-inspired','budget','egg-free','kid-friendly','one-pan','quick','vegetarian']::text[], '["1 lb spaghetti", "4 tbsp peanut butter", "3 tbsp soy sauce", "1 tbsp rice vinegar", "1 tbsp honey", "2 cloves garlic", "1 tsp ginger powder", "2 tbsp warm water", "2 scallions"]'::jsonb, '["Cook spaghetti in salted boiling water until al dente, then drain, reserving a cup of pasta water.", "Whisk together peanut butter, soy sauce, rice vinegar, honey, minced garlic, ginger powder, and warm water into a smooth sauce.", "Toss cooked noodles with the peanut sauce, adding pasta water a little at a time to reach desired consistency.", "Serve garnished with sliced scallions."]'::jsonb, 5, 5, 12, 0.9, 4.5, 420, 15, 68, 10, 3, 510, true, true, true, 'curated'),
  ('White Bean and Tomato Pasta', 'Creamy white beans folded into a chunky tomato pasta sauce and tossed with penne for a hearty protein-rich dinner.', 'dinner', 'Italian', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','high-fiber','italian','kid-friendly','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["1 lb penne pasta", "1 can white beans", "1 can diced tomatoes", "3 cloves garlic", "1 onion", "2 tbsp olive oil", "1 tsp dried rosemary", "1 tsp dried basil", "salt", "pepper"]'::jsonb, '["Cook penne in salted boiling water until al dente, drain, and set aside.", "Saut\u00e9 diced onion in olive oil over medium heat for 5 minutes, then add minced garlic and dried herbs.", "Add diced tomatoes and simmer 10 minutes.", "Stir in white beans and cook 5 more minutes until heated through.", "Toss with pasta, season with salt and pepper, and serve."]'::jsonb, 6, 7, 22, 0.95, 5.7, 400, 16, 70, 5, 9, 400, true, true, true, 'curated'),
  ('Cabbage and Egg Stir-Fry', 'Shredded green cabbage stir-fried with beaten eggs, garlic, and soy sauce for a light and speedy dinner that comes together in minutes.', 'dinner', 'Stir-Fry', 'ultra_budget', ARRAY['asian','budget','dairy-free','kid-friendly','nut-free','one-pan','quick','stir-fry','vegetarian']::text[], '["4 cups shredded green cabbage", "4 eggs", "3 cloves garlic", "2 tbsp soy sauce", "1 tsp sesame oil", "1 tbsp olive oil", "pepper"]'::jsonb, '["Heat olive oil in a large skillet or wok over high heat.", "Add minced garlic and cook 30 seconds, then add shredded cabbage and stir-fry 5 minutes until softened.", "Push cabbage to one side and scramble eggs in the empty space, then fold into the cabbage.", "Add soy sauce and sesame oil, toss everything together, and cook 1 more minute.", "Season with pepper and serve over rice if desired."]'::jsonb, 3, 5, 8, 0.55, 1.65, 190, 12, 10, 11, 3, 480, true, true, true, 'curated'),
  ('Peanut Butter Banana Roll-Ups', 'Flour tortillas spread with creamy peanut butter and rolled up with sliced bananas for a sweet, satisfying bite.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','egg-free','kid-friendly','no-cook','quick','soy-free','vegetarian']::text[], '["4 flour tortillas", "4 tbsp peanut butter", "2 bananas", "1 tsp honey"]'::jsonb, '["Lay tortillas flat on a clean surface.", "Spread 1 tablespoon of peanut butter evenly over each tortilla.", "Peel bananas and slice lengthwise, then place one banana half on each tortilla.", "Drizzle with honey, roll tightly, and slice into bite-sized rounds.", "Serve immediately or wrap in plastic for later."]'::jsonb, 4, 5, 0, 0.65, 2.6, 210, 6, 28, 9, 2, 180, true, true, true, 'curated'),
  ('Spiced Roasted Chickpeas', 'Canned chickpeas tossed with cumin, paprika, and olive oil then roasted until crunchy for an addictive savory snack.', 'snack', 'Mediterranean', 'ultra_budget', ARRAY['budget','crunchy','dairy-free','egg-free','gluten-free','kid-friendly','mediterranean','nut-free','one-pan','roasted','soy-free','vegan','vegetarian']::text[], '["2 cans chickpeas", "2 tbsp olive oil", "1 tsp cumin", "1 tsp paprika", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F and line a baking sheet with foil.", "Drain, rinse, and thoroughly dry chickpeas with paper towels.", "Toss chickpeas with olive oil, cumin, paprika, garlic powder, salt, and pepper.", "Spread in a single layer on the baking sheet.", "Roast 30-35 minutes, shaking pan halfway, until golden and crispy.", "Cool completely before serving \u2014 they crisp up further as they cool."]'::jsonb, 4, 5, 35, 0.55, 2.2, 180, 8, 22, 6, 5, 290, true, true, true, 'curated'),
  ('Cucumber Cream Cheese Coins', 'Crisp cucumber rounds topped with herbed cream cheese make an elegant, refreshing no-cook snack.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','egg-free','fresh','gluten-free','kid-friendly','no-cook','nut-free','quick','soy-free','vegetarian']::text[], '["2 cucumbers", "4 oz cream cheese", "1 tsp dried dill", "1 clove garlic", "salt", "pepper"]'::jsonb, '["Let cream cheese soften at room temperature for 10 minutes.", "Mince garlic and mix into cream cheese along with dill, salt, and pepper.", "Slice cucumbers into 1/4-inch rounds.", "Spread a small dollop of herbed cream cheese onto each cucumber round.", "Arrange on a plate and serve immediately."]'::jsonb, 4, 10, 0, 0.8, 3.2, 95, 3, 5, 7, 1, 160, true, true, true, 'curated'),
  ('Cheesy Popcorn Shake', 'Air-popped popcorn tossed with butter and a generous shower of parmesan cheese for a savory movie-night treat.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','egg-free','gluten-free','kid-friendly','nut-free','quick','soy-free','stovetop','vegetarian']::text[], '["1/2 cup popcorn kernels", "2 tbsp butter", "1/4 cup grated parmesan", "1 tsp garlic powder", "salt"]'::jsonb, '["Heat a large pot over medium-high heat and add kernels with 1 tablespoon butter.", "Cover and shake pot occasionally until popping slows to 2 seconds apart.", "Transfer popcorn to a large bowl.", "Melt remaining butter and drizzle over popcorn.", "Toss with parmesan, garlic powder, and salt until evenly coated.", "Serve warm."]'::jsonb, 4, 2, 8, 0.45, 1.8, 140, 4, 16, 7, 2, 210, true, true, true, 'curated'),
  ('Apple Slices with Cinnamon Honey Dip', 'Crisp apple slices served alongside a quick cinnamon-honey yogurt dipping sauce for a wholesome afternoon snack.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','egg-free','fresh','gluten-free','kid-friendly','no-cook','nut-free','quick','soy-free','vegetarian']::text[], '["3 apples", "1 cup plain yogurt", "2 tbsp honey", "1 tsp cinnamon", "1/4 tsp vanilla extract"]'::jsonb, '["Core and slice apples into thin wedges.", "In a small bowl, stir together yogurt, honey, cinnamon, and vanilla extract.", "Arrange apple slices on a plate with the dip in the center.", "Serve immediately."]'::jsonb, 4, 5, 0, 0.7, 2.8, 115, 3, 24, 1, 2, 35, true, true, true, 'curated'),
  ('Black Bean Salsa Cups', 'Crispy corn tortilla cups filled with a quick black bean, corn, and tomato salsa for a handheld fiesta bite.', 'snack', 'Mexican', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','fresh','kid-friendly','mexican','nut-free','quick','soy-free','vegan','vegetarian']::text[], '["1 can black beans", "1 cup frozen corn", "2 roma tomatoes", "1/4 onion", "2 tbsp lime juice", "1 tsp cumin", "salt", "12 small corn tortillas"]'::jsonb, '["Drain and rinse black beans; thaw corn under warm water.", "Dice tomatoes and onion finely.", "Mix beans, corn, tomatoes, and onion with lime juice, cumin, and salt.", "Warm tortillas briefly in a dry skillet and press into a muffin tin to form cups, then bake at 375\u00b0F for 8 minutes.", "Fill each tortilla cup with bean salsa and serve."]'::jsonb, 4, 10, 8, 0.9, 3.6, 195, 8, 35, 2, 7, 340, true, true, true, 'curated'),
  ('Hard-Boiled Egg and Hot Sauce Bites', 'Perfectly hard-boiled eggs halved and finished with a dash of hot sauce for a protein-packed, two-bite snack.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','dairy-free','gluten-free','nut-free','quick','soy-free','stovetop','vegetarian']::text[], '["6 eggs", "1 tbsp hot sauce", "salt", "pepper"]'::jsonb, '["Place eggs in a saucepan, cover with cold water, and bring to a boil.", "Once boiling, reduce heat and simmer 10 minutes.", "Transfer eggs to an ice bath for 5 minutes, then peel.", "Slice eggs in half lengthwise.", "Season with salt and pepper, then dash each half with hot sauce.", "Serve immediately."]'::jsonb, 3, 2, 15, 0.5, 1.5, 140, 12, 1, 10, 0, 210, false, true, true, 'curated'),
  ('Oat and Honey Energy Balls', 'No-bake rolled oats, peanut butter, honey, and chocolate chip bites that come together in minutes for a filling snack.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','egg-free','gluten-free','kid-friendly','no-bake','soy-free','sweet','vegetarian']::text[], '["1 cup rolled oats", "1/2 cup peanut butter", "3 tbsp honey", "1/4 cup chocolate chips", "1 tsp vanilla extract"]'::jsonb, '["Combine oats, peanut butter, honey, chocolate chips, and vanilla in a bowl.", "Mix until fully combined, then refrigerate dough 15 minutes to firm up.", "Roll into 1-inch balls using your hands.", "Store in the refrigerator for up to one week."]'::jsonb, 4, 15, 0, 0.8, 3.2, 265, 9, 30, 13, 3, 90, true, true, true, 'curated'),
  ('Celery with Pimento Cheese', 'Crisp celery stalks filled with Southern-style pimento cheese spread for a crunchy, savory snack.', 'snack', 'Southern', 'ultra_budget', ARRAY['budget','fresh','gluten-free','kid-friendly','no-cook','nut-free','quick','southern','soy-free','vegetarian']::text[], '["1 bunch celery", "1 cup shredded cheddar cheese", "4 oz cream cheese", "2 tbsp mayonnaise", "2 oz pimentos", "salt", "pepper"]'::jsonb, '["Soften cream cheese at room temperature for 10 minutes.", "Beat together cream cheese, mayonnaise, shredded cheddar, and drained pimentos.", "Season with salt and pepper.", "Trim celery into 3-inch sticks.", "Fill each celery groove with pimento cheese and serve."]'::jsonb, 4, 10, 0, 1.2, 4.8, 195, 8, 4, 16, 1, 380, true, true, true, 'curated'),
  ('Stovetop Cinnamon Sugar Tortilla Chips', 'Flour tortilla strips fried until golden and dusted with cinnamon sugar for a sweet, carnival-style crunch.', 'snack', 'Mexican', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','kid-friendly','mexican','nut-free','quick','soy-free','stovetop','sweet','vegan','vegetarian']::text[], '["4 flour tortillas", "3 tbsp sugar", "1 tsp cinnamon", "2 tbsp vegetable oil"]'::jsonb, '["Cut tortillas into triangles or strips.", "Heat oil in a skillet over medium heat.", "Fry tortilla pieces in batches 1-2 minutes per side until golden and crisp.", "Drain on paper towels briefly.", "Mix sugar and cinnamon, then toss warm chips in the mixture.", "Serve immediately."]'::jsonb, 4, 3, 10, 0.4, 1.6, 175, 3, 25, 7, 1, 140, true, true, true, 'curated'),
  ('Tuna Salad Lettuce Boats', 'Seasoned canned tuna mixed with celery and a touch of mayo spooned into crisp romaine leaves for a low-carb snack.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','dairy-free','fresh','gluten-free','no-cook','nut-free','soy-free','standard']::text[], '["2 cans tuna", "3 tbsp mayonnaise", "2 stalks celery", "1 tbsp lemon juice", "1 tsp onion powder", "salt", "pepper", "1 head romaine lettuce"]'::jsonb, '["Drain tuna and flake into a bowl.", "Dice celery finely and add to tuna.", "Stir in mayonnaise, lemon juice, onion powder, salt, and pepper.", "Separate romaine into individual leaves.", "Spoon tuna salad into each lettuce leaf and serve."]'::jsonb, 4, 10, 0, 1.4, 5.6, 155, 18, 3, 8, 1, 330, false, true, true, 'curated'),
  ('Baked Cheddar Crackers', 'Homemade sharp cheddar cheese crackers baked until golden and flaky for a satisfying, store-bought-quality snack.', 'snack', 'American', 'ultra_budget', ARRAY['american','baked','budget','cheesy','egg-free','kid-friendly','nut-free','soy-free','vegetarian']::text[], '["1 cup shredded sharp cheddar cheese", "4 tbsp butter", "1/2 cup all-purpose flour", "1/4 tsp salt", "1/4 tsp paprika", "1 tbsp cold water"]'::jsonb, '["Preheat oven to 350\u00b0F and line a baking sheet with parchment.", "Mix cheddar, softened butter, flour, salt, and paprika in a bowl until crumbly.", "Add cold water and knead just until dough comes together.", "Roll dough to 1/8-inch thickness and cut into small squares.", "Place on baking sheet and bake 15-18 minutes until edges are golden.", "Cool completely on a rack before serving."]'::jsonb, 6, 15, 18, 0.6, 3.6, 150, 5, 9, 11, 0, 220, true, true, true, 'curated'),
  ('Spicy Edamame with Sea Salt', 'Steamed edamame pods tossed with chili flakes and sea salt for a protein-rich Asian-inspired snack.', 'snack', 'Asian', 'ultra_budget', ARRAY['asian','budget','dairy-free','egg-free','gluten-free','nut-free','quick','stovetop','vegan','vegetarian']::text[], '["1 lb frozen edamame in pods", "1 tsp red chili flakes", "1 tsp sesame oil", "1 tsp sea salt", "1 tsp garlic powder"]'::jsonb, '["Boil edamame pods in salted water for 4-5 minutes until tender.", "Drain well and transfer to a bowl.", "Drizzle with sesame oil and toss with chili flakes, sea salt, and garlic powder.", "Serve warm, eating the beans directly from the pods."]'::jsonb, 4, 2, 5, 1.1, 4.4, 120, 11, 9, 5, 4, 390, false, true, true, 'curated'),
  ('Guacamole with Baked Tortilla Chips', 'Chunky avocado guacamole seasoned with lime and cilantro served alongside crispy oven-baked corn tortilla chips.', 'snack', 'Mexican', 'ultra_budget', ARRAY['baked','budget','dairy-free','egg-free','fresh','kid-friendly','mexican','nut-free','soy-free','vegan','vegetarian']::text[], '["3 avocados", "2 tbsp lime juice", "1/4 onion", "1 roma tomato", "2 tbsp fresh cilantro", "salt", "8 small corn tortillas", "1 tbsp vegetable oil"]'::jsonb, '["Preheat oven to 400\u00b0F.", "Cut tortillas into quarters, brush lightly with oil, and bake 10-12 minutes until crispy.", "Mash avocados with lime juice and salt to desired consistency.", "Fold in finely diced onion, chopped tomato, and cilantro.", "Serve guacamole with the cooled tortilla chips."]'::jsonb, 4, 10, 12, 1.5, 6.0, 240, 3, 24, 15, 6, 200, true, true, true, 'curated'),
  ('Caprese Skewers', 'Mini mozzarella balls, cherry tomatoes, and fresh basil threaded on skewers and drizzled with balsamic glaze.', 'snack', 'Italian', 'budget', ARRAY['budget','egg-free','fresh','gluten-free','italian','kid-friendly','no-cook','nut-free','quick','soy-free','vegetarian']::text[], '["8 oz fresh mozzarella balls", "1 pint cherry tomatoes", "1/4 cup fresh basil leaves", "2 tbsp balsamic glaze", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Thread a basil leaf, cherry tomato, and mozzarella ball onto each skewer.", "Repeat until all skewers are assembled.", "Arrange on a platter.", "Drizzle with olive oil and balsamic glaze.", "Season with salt and pepper and serve immediately."]'::jsonb, 4, 10, 0, 2.1, 8.4, 175, 10, 8, 12, 1, 250, true, true, true, 'curated'),
  ('Ants on a Log', 'Classic celery sticks filled with peanut butter and topped with raisins for a crunchy, sweet, and savory childhood favorite.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','classic','egg-free','gluten-free','kid-friendly','no-cook','quick','soy-free','vegetarian']::text[], '["6 stalks celery", "1/2 cup peanut butter", "1/4 cup raisins"]'::jsonb, '["Wash and trim celery stalks into 3-4 inch pieces.", "Fill the groove of each celery stick with peanut butter.", "Press raisins into the peanut butter in a line.", "Serve on a plate."]'::jsonb, 3, 5, 0, 0.55, 1.65, 185, 7, 16, 12, 2, 130, true, true, true, 'curated'),
  ('Everything Bagel Cream Cheese Dip', 'Whipped cream cheese loaded with everything bagel seasoning served with sliced cucumbers and crackers for dipping.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','creamy','egg-free','gluten-free','kid-friendly','no-cook','nut-free','quick','soy-free','vegetarian']::text[], '["8 oz cream cheese", "2 tbsp everything bagel seasoning", "1 tbsp sour cream", "1 cucumber", "1 sleeve crackers"]'::jsonb, '["Let cream cheese soften at room temperature for 15 minutes.", "Beat cream cheese and sour cream together until smooth and fluffy.", "Stir in everything bagel seasoning.", "Slice cucumber into rounds.", "Transfer dip to a bowl and serve with cucumbers and crackers."]'::jsonb, 4, 15, 0, 1.3, 5.2, 220, 5, 16, 15, 1, 510, true, true, true, 'curated'),
  ('Mango Chili Lime Fruit Cups', 'Frozen mango chunks thawed and tossed with chili powder and fresh lime juice for a street-food-inspired fruity snack.', 'snack', 'Mexican', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','fresh','gluten-free','kid-friendly','mexican','no-cook','nut-free','quick','soy-free','sweet','vegan','vegetarian']::text[], '["1 lb frozen mango chunks", "2 tbsp lime juice", "1/2 tsp chili powder", "1/4 tsp salt"]'::jsonb, '["Thaw mango chunks at room temperature for 20 minutes or quickly in the microwave.", "Transfer mango to a bowl.", "Drizzle with lime juice and toss to coat.", "Sprinkle with chili powder and salt.", "Serve in individual cups."]'::jsonb, 4, 5, 0, 0.9, 3.6, 80, 1, 20, 0, 2, 80, true, true, true, 'curated'),
  ('Pizza Bagel Bites', 'Mini bagels topped with marinara sauce and melted mozzarella cheese for a bite-sized pizza fix kids absolutely love.', 'snack', 'American', 'ultra_budget', ARRAY['american','baked','budget','cheesy','egg-free','gluten-free','kid-friendly','nut-free','quick','soy-free','vegetarian']::text[], '["6 mini bagels", "1/2 cup marinara sauce", "1 cup shredded mozzarella", "1 tsp Italian seasoning", "1 tsp garlic powder"]'::jsonb, '["Preheat oven to 400\u00b0F and line a baking sheet with foil.", "Slice bagels in half and arrange cut-side up on baking sheet.", "Spread a spoonful of marinara on each bagel half.", "Top with shredded mozzarella and sprinkle with Italian seasoning and garlic powder.", "Bake 8-10 minutes until cheese is bubbly and edges are golden.", "Cool 2 minutes before serving."]'::jsonb, 4, 5, 10, 1.1, 4.4, 210, 10, 27, 7, 1, 480, true, true, true, 'curated'),
  ('Savory Roasted Sunflower Seeds', 'Raw sunflower seeds toasted in a skillet with soy sauce and garlic for a crunchy, umami-packed portable snack.', 'snack', 'Asian', 'ultra_budget', ARRAY['asian','budget','crunchy','dairy-free','egg-free','kid-friendly','nut-free','quick','stovetop','vegan','vegetarian']::text[], '["1 cup raw sunflower seeds", "1 tbsp soy sauce", "1/2 tsp garlic powder", "1/4 tsp onion powder", "1/4 tsp black pepper"]'::jsonb, '["Heat a dry skillet over medium heat.", "Add sunflower seeds and toast 3-4 minutes, stirring frequently.", "Drizzle soy sauce over seeds and stir quickly to coat.", "Add garlic powder, onion powder, and pepper and toss to combine.", "Cook 1-2 more minutes until seeds are dry and fragrant.", "Cool completely before eating."]'::jsonb, 4, 2, 6, 0.5, 2.0, 185, 7, 6, 16, 2, 280, true, true, true, 'curated'),
  ('Hummus and Veggie Platter', 'Store-bought hummus surrounded by colorful raw vegetable dippers including carrots, peppers, and broccoli for easy snacking.', 'snack', 'Mediterranean', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','fresh','gluten-free','kid-friendly','mediterranean','no-cook','nut-free','soy-free','vegan','vegetarian']::text[], '["1 container hummus", "2 carrots", "1 red bell pepper", "1 cup broccoli florets", "4 stalks celery", "1 cucumber"]'::jsonb, '["Peel and cut carrots into sticks.", "Slice bell pepper into strips.", "Break broccoli into bite-sized florets.", "Cut celery and cucumber into sticks.", "Arrange vegetables around a bowl of hummus on a large plate.", "Serve immediately."]'::jsonb, 4, 10, 0, 1.4, 5.6, 130, 5, 16, 6, 4, 280, true, true, true, 'curated'),
  ('Cottage Cheese with Pineapple', 'Creamy cottage cheese paired with sweet pineapple chunks for a protein-rich, naturally sweet snack with a tropical twist.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','egg-free','gluten-free','kid-friendly','no-cook','nut-free','quick','soy-free','sweet','vegetarian']::text[], '["2 cups cottage cheese", "1 can pineapple chunks", "1 tsp honey", "1/4 tsp cinnamon"]'::jsonb, '["Divide cottage cheese into four bowls.", "Drain pineapple and spoon chunks over the cottage cheese.", "Drizzle each serving with a bit of honey.", "Dust lightly with cinnamon and serve chilled."]'::jsonb, 4, 5, 0, 1.1, 4.4, 160, 14, 18, 3, 1, 370, true, true, true, 'curated'),
  ('Sweet Potato and Black Bean Quesadilla Wedges', 'Crispy flour tortillas filled with mashed sweet potato and black beans, cut into wedges for an easy shareable snack.', 'snack', 'Mexican', 'ultra_budget', ARRAY['budget','egg-free','filling','kid-friendly','mexican','nut-free','soy-free','stovetop','vegetarian']::text[], '["2 sweet potatoes", "1 can black beans", "1 cup shredded cheddar cheese", "1 tsp cumin", "1/2 tsp chili powder", "salt", "4 large flour tortillas"]'::jsonb, '["Pierce sweet potatoes and microwave 5-6 minutes until tender; scoop out flesh.", "Mash sweet potato with cumin, chili powder, and salt.", "Drain and rinse black beans.", "Spread mashed sweet potato on half of each tortilla, then top with black beans and cheese.", "Fold tortillas and cook in a dry skillet over medium heat 2-3 minutes per side.", "Slice into wedges and serve with salsa if desired."]'::jsonb, 4, 10, 12, 1.3, 5.2, 310, 12, 45, 9, 7, 430, true, true, true, 'curated'),
  ('Trail Mix with Peanuts and Raisins', 'A classic combination of dry-roasted peanuts, raisins, sunflower seeds, and chocolate chips tossed together for a portable energy snack.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','kid-friendly','no-cook','nut-free','portable','soy-free','sweet','vegan','vegetarian']::text[], '["1 cup dry-roasted peanuts", "1/2 cup raisins", "1/2 cup sunflower seeds", "1/4 cup chocolate chips", "1/4 cup dried cranberries"]'::jsonb, '["Combine all ingredients in a large bowl.", "Toss together until evenly mixed.", "Portion into individual snack bags or containers.", "Store in an airtight container at room temperature."]'::jsonb, 6, 5, 0, 0.75, 4.5, 245, 8, 24, 15, 3, 95, true, true, true, 'curated'),
  ('Crispy Wonton Strips with Sweet Chili Sauce', 'Wonton wrappers sliced into strips, baked crispy, and served with sweet chili dipping sauce for an Asian-inspired crunch.', 'snack', 'Asian', 'ultra_budget', ARRAY['asian','baked','budget','crunchy','dairy-free','egg-free','gluten-free','kid-friendly','nut-free','quick','soy-free','vegan','vegetarian']::text[], '["1 pkg wonton wrappers", "2 tbsp vegetable oil", "1 tsp sesame seeds", "1/4 tsp salt", "1/2 cup sweet chili sauce"]'::jsonb, '["Preheat oven to 375\u00b0F.", "Cut wonton wrappers into strips about half an inch wide.", "Toss strips with vegetable oil, sesame seeds, and salt.", "Spread on a baking sheet in a single layer.", "Bake 10-12 minutes until golden and crispy.", "Serve with sweet chili sauce for dipping."]'::jsonb, 4, 5, 12, 1.25, 5.0, 195, 4, 32, 6, 1, 370, true, true, true, 'curated'),
  ('Frozen Yogurt Bark with Berries', 'Plain yogurt spread thin on a sheet pan, topped with mixed berries and honey, then frozen into snackable bark pieces.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','egg-free','frozen','gluten-free','kid-friendly','no-bake','nut-free','soy-free','sweet','vegetarian']::text[], '["2 cups plain yogurt", "2 tbsp honey", "1 cup frozen mixed berries", "1/4 tsp vanilla extract"]'::jsonb, '["Line a baking sheet with parchment paper.", "Stir honey and vanilla into yogurt until combined.", "Spread yogurt evenly on the lined baking sheet about 1/4 inch thick.", "Scatter berries evenly over the top.", "Freeze at least 3 hours until completely solid.", "Break into pieces and serve directly from the freezer."]'::jsonb, 4, 10, 0, 1.2, 4.8, 130, 5, 22, 2, 1, 55, true, true, true, 'curated'),
  ('Microwave Nacho Chips', 'Corn tortilla chips piled with canned refried beans, shredded cheese, and jalapeños then microwaved until melted and bubbly.', 'snack', 'Mexican', 'ultra_budget', ARRAY['budget','cheesy','egg-free','kid-friendly','mexican','microwave','nut-free','quick','soy-free','vegetarian']::text[], '["4 oz corn tortilla chips", "1/2 can refried beans", "1 cup shredded cheddar cheese", "2 tbsp pickled jalape\u00f1os", "2 tbsp sour cream"]'::jsonb, '["Spread tortilla chips in a single layer on a microwave-safe plate.", "Drop small spoonfuls of refried beans over the chips.", "Sprinkle shredded cheddar evenly over the top.", "Microwave on high for 1-2 minutes until cheese is fully melted.", "Top with jalape\u00f1os and a dollop of sour cream.", "Serve immediately."]'::jsonb, 2, 3, 2, 1.0, 2.0, 320, 11, 35, 15, 5, 580, true, true, true, 'curated'),
  ('Soy-Glazed Hard Boiled Eggs', 'Peeled hard-boiled eggs marinated briefly in a sweet soy and garlic glaze for a savory, protein-dense Asian-style snack.', 'snack', 'Asian', 'ultra_budget', ARRAY['asian','budget','dairy-free','nut-free','savory','stovetop','vegetarian']::text[], '["6 eggs", "3 tbsp soy sauce", "1 tbsp sugar", "1 clove garlic", "1/2 cup water", "1 tsp sesame oil"]'::jsonb, '["Hard-boil eggs and peel them.", "Combine soy sauce, sugar, minced garlic, water, and sesame oil in a small saucepan.", "Bring to a simmer over medium heat until sugar dissolves.", "Add peeled eggs to the glaze and spoon sauce over them for 3-4 minutes.", "Remove from heat and let eggs rest in the glaze 10 minutes.", "Slice in half and serve warm or at room temperature."]'::jsonb, 3, 5, 20, 0.65, 1.95, 160, 12, 6, 10, 0, 520, false, true, true, 'curated'),
  ('Smoky Chipotle Black Bean Tacos', 'Hearty black beans seasoned with chipotle and cumin piled into warm corn tortillas with crisp cabbage slaw.', 'dinner', 'Mexican', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','mexican','nut-free','one-pot','quick','soy-free','vegan','vegetarian']::text[], '["2 cans black beans", "1 tsp chipotle powder", "1 tsp cumin", "1 tsp garlic powder", "1 tbsp olive oil", "8 corn tortillas", "2 cups shredded green cabbage", "1 lime", "salt", "pepper"]'::jsonb, '["Drain and rinse black beans.", "Heat olive oil in a skillet over medium heat, add beans, chipotle powder, cumin, and garlic powder.", "Mash beans lightly and cook 5 minutes until heated through.", "Toss shredded cabbage with lime juice, salt, and pepper.", "Warm tortillas in a dry pan for 30 seconds per side.", "Fill tortillas with bean mixture and cabbage slaw and serve."]'::jsonb, 4, 10, 10, 1.1, 4.4, 340, 14, 55, 6, 12, 480, true, true, true, 'curated'),
  ('Lemon Herb Baked Chicken Thighs', 'Juicy bone-in chicken thighs roasted with lemon, garlic, and fresh herbs until golden and tender.', 'dinner', 'Sheet-Pan', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','meal-prep','nut-free','sheet-pan','soy-free','standard']::text[], '["4 bone-in chicken thighs", "2 cloves garlic", "1 lemon", "1 tbsp olive oil", "1 tsp dried oregano", "1 tsp dried thyme", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F.", "Mince garlic and mix with olive oil, lemon juice, oregano, thyme, salt, and pepper.", "Rub mixture all over chicken thighs.", "Place chicken skin-side up on a baking sheet.", "Bake 35-40 minutes until skin is golden and juices run clear.", "Rest 5 minutes before serving."]'::jsonb, 4, 10, 40, 2.1, 8.4, 310, 28, 2, 21, 0, 390, true, true, true, 'curated'),
  ('Spicy Sausage and Peppers Rice Bowl', 'Sliced smoked sausage sautéed with colorful bell peppers and onions served over fluffy white rice.', 'dinner', 'American', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','quick','soy-free','standard']::text[], '["1 lb smoked sausage", "2 bell peppers", "1 onion", "2 cups white rice", "4 cups water", "1 tbsp olive oil", "1 tsp paprika", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Cook rice in water with a pinch of salt according to package directions.", "Slice sausage, peppers, and onion into strips.", "Heat olive oil in a large skillet over medium-high heat.", "Add sausage and cook until browned, about 4 minutes.", "Add peppers, onion, paprika, and garlic powder; cook 6 minutes until softened.", "Serve sausage and pepper mixture over rice."]'::jsonb, 4, 10, 25, 2.5, 10.0, 520, 22, 60, 18, 3, 780, true, true, true, 'curated'),
  ('Vietnamese-Style Beef Noodle Soup', 'A fragrant broth simmered with star anise and ginger loaded with tender beef strips and rice noodles.', 'dinner', 'Soup', 'budget', ARRAY['budget','dairy-free','egg-free','high-protein','noodles','nut-free','soup','standard','vietnamese']::text[], '["1 lb beef sirloin", "8 oz rice noodles", "6 cups beef broth", "1 onion", "2 cloves garlic", "1 tbsp soy sauce", "1 tsp ginger powder", "2 star anise", "1 cup bean sprouts", "2 green onions", "salt", "pepper"]'::jsonb, '["Bring beef broth to a boil with halved onion, garlic, star anise, ginger powder, and soy sauce.", "Simmer broth 15 minutes then remove star anise and onion.", "Thinly slice beef sirloin against the grain.", "Cook rice noodles according to package directions; drain.", "Divide noodles into bowls, top with raw beef slices, and ladle hot broth over to cook the beef.", "Top with bean sprouts and sliced green onions."]'::jsonb, 4, 15, 25, 2.9, 11.6, 420, 32, 48, 9, 2, 820, false, true, true, 'curated'),
  ('Smoky Red Lentil Soup', 'Creamy red lentils blended with smoked paprika, tomatoes, and cumin into a satisfying warming soup.', 'lunch', 'Soup', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','meal-prep','mediterranean','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["2 cups red lentils", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "1 tsp smoked paprika", "1 tsp cumin", "6 cups vegetable broth", "salt", "pepper"]'::jsonb, '["Dice onion and mince garlic.", "Heat olive oil in a large pot over medium heat and saut\u00e9 onion 5 minutes.", "Add garlic, paprika, and cumin; cook 1 minute.", "Add lentils, diced tomatoes, and broth; bring to a boil.", "Reduce heat and simmer 20 minutes until lentils are soft.", "Use an immersion blender to partially blend for a creamy texture; season with salt and pepper."]'::jsonb, 6, 10, 30, 0.95, 5.7, 280, 16, 46, 4, 14, 560, true, true, true, 'curated'),
  ('Cuban-Style Black Beans and Rice', 'Slow-simmered black beans with sofrito spices served over long-grain white rice for a classic island staple.', 'dinner', 'Cuban', 'ultra_budget', ARRAY['budget','cuban','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','latin','nut-free','one-pot','soy-free','vegan','vegetarian']::text[], '["2 cans black beans", "2 cups long-grain white rice", "4 cups water", "1 green bell pepper", "1 onion", "4 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp oregano", "1 bay leaf", "salt", "pepper"]'::jsonb, '["Cook rice in water with a pinch of salt.", "Dice bell pepper and onion; mince garlic.", "Heat olive oil in a pot and saut\u00e9 pepper, onion, and garlic 5 minutes.", "Add drained beans, cumin, oregano, and bay leaf.", "Simmer 15 minutes; remove bay leaf.", "Serve beans over rice."]'::jsonb, 6, 10, 25, 1.0, 6.0, 360, 13, 68, 4, 10, 430, true, true, true, 'curated'),
  ('Sheet-Pan Sausage and Roasted Vegetables', 'Italian sausage links roasted alongside zucchini, cherry tomatoes, and red onion on a single pan.', 'dinner', 'Sheet-Pan', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','italian','kid-friendly','nut-free','one-pan','sheet-pan','soy-free','standard']::text[], '["4 Italian sausage links", "2 zucchini", "1 cup cherry tomatoes", "1 red onion", "2 tbsp olive oil", "1 tsp Italian seasoning", "1 tsp garlic powder", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F.", "Slice zucchini and red onion into chunks.", "Toss vegetables with olive oil, Italian seasoning, garlic powder, salt, and pepper.", "Arrange vegetables on a baking sheet and nestle sausages among them.", "Roast 30-35 minutes, flipping halfway, until sausages are cooked and vegetables are caramelized.", "Serve hot directly from the pan."]'::jsonb, 4, 10, 35, 2.7, 10.8, 410, 20, 12, 32, 3, 710, true, true, true, 'curated'),
  ('Weeknight Egg Drop Soup', 'Silky ribbons of egg swirled into a savory ginger-scented broth with green onions for a quick comforting meal.', 'lunch', 'Asian', 'ultra_budget', ARRAY['asian','budget','dairy-free','kid-friendly','low-cost','nut-free','quick','soup','standard']::text[], '["4 eggs", "6 cups chicken broth", "2 green onions", "1 tsp soy sauce", "1 tsp ginger powder", "1 tbsp cornstarch", "2 tbsp water", "salt", "pepper"]'::jsonb, '["Bring chicken broth to a gentle boil with soy sauce and ginger powder.", "Mix cornstarch with 2 tbsp cold water to make a slurry.", "Stir slurry into broth; simmer 2 minutes until slightly thickened.", "Beat eggs in a small bowl.", "Slowly drizzle beaten eggs into simmering broth while stirring gently in circles.", "Garnish with sliced green onions and serve immediately."]'::jsonb, 4, 5, 10, 0.85, 3.4, 110, 9, 5, 6, 0, 680, true, true, true, 'curated'),
  ('Spiced Ground Turkey and Sweet Potato Skillet', 'Savory ground turkey and cubed sweet potatoes seasoned with warm spices and cooked in a single skillet.', 'dinner', 'Skillet', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','meal-prep','nut-free','one-pan','soy-free','standard']::text[], '["1 lb ground turkey", "2 sweet potatoes", "1 onion", "2 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp chili powder", "1 tsp smoked paprika", "salt", "pepper"]'::jsonb, '["Peel and cube sweet potatoes into small pieces.", "Heat olive oil in a large skillet over medium heat.", "Add sweet potatoes and cook 8 minutes until starting to soften.", "Push sweet potatoes to the side; add diced onion and garlic.", "Add ground turkey and cook, breaking apart, until browned.", "Season with cumin, chili powder, paprika, salt, and pepper; stir everything together and cook 3 more minutes."]'::jsonb, 4, 10, 25, 2.6, 10.4, 370, 30, 28, 13, 4, 450, true, true, true, 'curated'),
  ('Tomato Basil Pasta with Chickpeas', 'Al dente spaghetti tossed with a bright tomato sauce, canned chickpeas, and fresh basil for a filling meal.', 'dinner', 'Italian', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','high-fiber','italian','kid-friendly','nut-free','one-pot','pasta','soy-free','vegan','vegetarian']::text[], '["1 lb spaghetti", "1 can chickpeas", "1 can crushed tomatoes", "4 cloves garlic", "1 tbsp olive oil", "1 tsp dried basil", "1 tsp dried oregano", "1 tsp red pepper flakes", "salt", "pepper"]'::jsonb, '["Cook spaghetti in salted boiling water; reserve 1 cup pasta water before draining.", "Heat olive oil in a large skillet and saut\u00e9 minced garlic 1 minute.", "Add crushed tomatoes, basil, oregano, and red pepper flakes; simmer 10 minutes.", "Drain and rinse chickpeas; add to the sauce.", "Add drained pasta and toss, using reserved pasta water to loosen as needed.", "Season with salt and pepper and serve."]'::jsonb, 6, 10, 20, 1.2, 7.2, 420, 16, 76, 5, 9, 480, true, true, true, 'curated'),
  ('Thai-Inspired Ginger Lime Rice Noodles', 'Rice noodles tossed in a savory ginger-lime broth sauce with crisp cabbage, carrots, and green onions.', 'dinner', 'Thai', 'budget', ARRAY['asian','budget','dairy-free','egg-free','kid-friendly','noodles','nut-free','quick','thai','vegan','vegetarian']::text[], '["8 oz rice noodles", "1 cup vegetable broth", "2 tbsp soy sauce", "1 tbsp lime juice", "1 tsp ginger powder", "1 tsp garlic powder", "1 tsp sesame oil", "2 cups shredded cabbage", "1 cup shredded carrots", "2 green onions", "1 tbsp olive oil"]'::jsonb, '["Cook rice noodles according to package directions; drain and set aside.", "Whisk together vegetable broth, soy sauce, lime juice, ginger powder, garlic powder, and sesame oil.", "Heat olive oil in a large wok or skillet over high heat.", "Add cabbage and carrots; stir-fry 3 minutes.", "Add noodles and pour sauce over; toss well for 2 minutes until heated through.", "Serve topped with sliced green onions."]'::jsonb, 4, 10, 15, 2.0, 8.0, 310, 7, 56, 6, 4, 590, true, true, true, 'curated'),
  ('Chorizo and Potato Hash', 'Crispy diced potatoes and crumbled chorizo cooked together with peppers and onion for a bold satisfying lunch.', 'lunch', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','mexican','nut-free','one-pan','quick','soy-free','vegan','vegetarian']::text[], '["1 lb Mexican chorizo", "4 medium potatoes", "1 bell pepper", "1 onion", "2 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "salt", "pepper"]'::jsonb, '["Dice potatoes into small cubes and boil in salted water 8 minutes; drain.", "Cook chorizo in a large skillet over medium heat, breaking apart, until cooked through; remove and set aside.", "Add olive oil to the skillet and cook potatoes until crispy, about 8 minutes.", "Add diced bell pepper, onion, and garlic; cook 4 minutes.", "Return chorizo to skillet with cumin, salt, and pepper; stir to combine.", "Cook 2 more minutes and serve hot."]'::jsonb, 4, 10, 25, 2.8, 11.2, 490, 22, 42, 26, 4, 820, false, true, true, 'curated'),
  ('Korean-Inspired Ground Beef Bowls', 'Seasoned ground beef in a savory-sweet soy and sesame sauce served over steamed white rice with cucumber.', 'dinner', 'Korean', 'budget', ARRAY['asian','budget','dairy-free','egg-free','high-protein','kid-friendly','korean','meal-prep','nut-free','quick','standard']::text[], '["1 lb ground beef", "2 cups white rice", "4 cups water", "3 tbsp soy sauce", "1 tbsp honey", "1 tbsp sesame oil", "3 cloves garlic", "1 tsp ginger powder", "1 cucumber", "2 green onions"]'::jsonb, '["Cook rice in water according to package directions.", "Mix soy sauce, honey, sesame oil, minced garlic, and ginger powder in a bowl.", "Brown ground beef in a skillet over medium-high heat, breaking apart, about 6 minutes.", "Drain excess fat and pour sauce over beef; toss and cook 2 minutes.", "Slice cucumber thinly.", "Serve beef over rice topped with cucumber and sliced green onions."]'::jsonb, 4, 10, 20, 2.7, 10.8, 500, 28, 55, 18, 2, 740, true, true, true, 'curated'),
  ('Tuscan White Bean and Spinach Soup', 'Creamy cannellini beans simmered with garlic, tomatoes, and wilted spinach in a savory Italian broth.', 'lunch', 'Soup', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','italian','meal-prep','nut-free','one-pot','soup','soy-free','standard']::text[], '["2 cans cannellini beans", "1 can diced tomatoes", "3 cups fresh spinach", "1 onion", "4 cloves garlic", "1 tbsp olive oil", "4 cups chicken broth", "1 tsp dried rosemary", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Dice onion and mince garlic.", "Heat olive oil in a large pot over medium heat and saut\u00e9 onion 5 minutes.", "Add garlic, rosemary, and Italian seasoning; cook 1 minute.", "Add drained beans, diced tomatoes, and broth; bring to a simmer.", "Cook 15 minutes, then mash some beans against the pot to thicken.", "Stir in spinach until wilted; season with salt and pepper."]'::jsonb, 6, 10, 25, 1.1, 6.6, 240, 14, 38, 4, 10, 590, false, true, true, 'curated'),
  ('Honey Garlic Shrimp Stir-Fry', 'Plump shrimp coated in a sticky honey garlic glaze tossed with snap peas and carrots over brown rice.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','egg-free','high-protein','kid-friendly','nut-free','quick','seafood','standard','stir-fry']::text[], '["1 lb shrimp, peeled and deveined", "2 cups brown rice", "4 cups water", "1 cup snap peas", "1 cup shredded carrots", "3 cloves garlic", "2 tbsp honey", "2 tbsp soy sauce", "1 tbsp olive oil", "1 tsp cornstarch"]'::jsonb, '["Cook brown rice in water according to package directions.", "Whisk together honey, soy sauce, minced garlic, and cornstarch.", "Heat olive oil in a wok or large skillet over high heat.", "Add shrimp and cook 2 minutes per side until pink; remove and set aside.", "Add snap peas and carrots to wok; stir-fry 3 minutes.", "Return shrimp, pour sauce over, and toss 1 minute; serve over rice."]'::jsonb, 4, 10, 30, 2.9, 11.6, 420, 28, 58, 7, 4, 650, true, true, true, 'curated'),
  ('Moroccan Chickpea and Tomato Stew', 'Warmly spiced chickpeas slow-simmered with tomatoes, cinnamon, and cumin for a deeply flavorful North African stew.', 'dinner', 'Moroccan', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','meal-prep','moroccan','nut-free','one-pot','soup','soy-free','vegan','vegetarian']::text[], '["2 cans chickpeas", "1 can diced tomatoes", "1 onion", "4 cloves garlic", "1 tbsp olive oil", "1 tsp cumin", "1 tsp coriander", "1 tsp cinnamon", "1 tsp smoked paprika", "3 cups vegetable broth", "salt", "pepper"]'::jsonb, '["Dice onion and mince garlic.", "Heat olive oil in a pot over medium heat; saut\u00e9 onion 5 minutes.", "Add garlic, cumin, coriander, cinnamon, and paprika; stir 1 minute.", "Add drained chickpeas, diced tomatoes, and broth.", "Simmer 20 minutes until stew thickens slightly.", "Season with salt and pepper; serve with flatbread or rice."]'::jsonb, 4, 10, 30, 1.3, 5.2, 290, 13, 46, 6, 11, 540, false, true, true, 'curated'),
  ('Pulled Chicken Tostadas', 'Tender slow-cooked pulled chicken seasoned with chipotle and lime piled onto crispy baked corn tostadas.', 'lunch', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','meal-prep','mexican','nut-free','quick','soy-free','standard']::text[], '["1 lb chicken breast", "8 corn tortillas", "1 can diced tomatoes", "1 tsp chipotle powder", "1 tsp cumin", "1 tsp garlic powder", "1 lime", "1 cup shredded lettuce", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F.", "Simmer chicken breast in diced tomatoes with chipotle powder, cumin, garlic powder, salt, and pepper for 20 minutes.", "Shred chicken with two forks and squeeze lime juice over; return to sauce.", "Brush tortillas with olive oil and bake 8-10 minutes until crispy.", "Top tostadas with pulled chicken and shredded lettuce.", "Serve immediately."]'::jsonb, 4, 10, 30, 2.2, 8.8, 360, 30, 40, 8, 5, 570, true, true, true, 'curated'),
  ('Baked Cod with Lemon and Capers', 'Flaky baked cod fillets topped with briny capers, lemon slices, and herbs for a light and elegant dinner.', 'dinner', 'Seafood', 'standard', ARRAY['dairy-free','egg-free','gluten-free','high-protein','mediterranean','nut-free','seafood','sheet-pan','soy-free','standard']::text[], '["4 cod fillets", "1 lemon", "2 tbsp capers", "3 cloves garlic", "2 tbsp olive oil", "1 tsp dried thyme", "1 tsp dried parsley", "salt", "pepper"]'::jsonb, '["Preheat oven to 400\u00b0F.", "Place cod fillets on a lined baking sheet.", "Drizzle olive oil over fillets and season with salt, pepper, thyme, and parsley.", "Top each fillet with minced garlic, capers, and lemon slices.", "Bake 15-18 minutes until fish flakes easily with a fork.", "Serve immediately with your choice of vegetable side."]'::jsonb, 4, 10, 18, 4.2, 16.8, 210, 34, 3, 8, 0, 480, false, true, true, 'curated'),
  ('Smoky Pulled Pork Sandwiches', 'Slow-cooked pulled pork smothered in tangy homemade barbecue sauce served on soft rolls with crunchy coleslaw.', 'dinner', 'American', 'budget', ARRAY['american','barbecue','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','slow-cook','soy-free','standard']::text[], '["2 lbs pork shoulder", "6 sandwich rolls", "3 cups shredded cabbage", "1 cup ketchup", "2 tbsp apple cider vinegar", "1 tbsp brown sugar", "1 tsp smoked paprika", "1 tsp garlic powder", "1 tsp onion powder", "salt", "pepper"]'::jsonb, '["Season pork shoulder with paprika, garlic powder, onion powder, salt, and pepper.", "Place pork in a slow cooker and cook on low 8 hours or high 4 hours.", "Mix ketchup, apple cider vinegar, and brown sugar for the barbecue sauce.", "Shred pork and toss with barbecue sauce.", "Toss cabbage with a splash of vinegar and pinch of salt for quick coleslaw.", "Serve pulled pork on rolls topped with coleslaw."]'::jsonb, 6, 15, 240, 2.5, 15.0, 480, 32, 46, 17, 3, 720, true, true, true, 'curated'),
  ('Garlic Shrimp Fried Rice', 'Day-old white rice stir-fried with shrimp, eggs, green peas, and a savory garlic soy sauce.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','high-protein','kid-friendly','nut-free','quick','seafood','standard','stir-fry']::text[], '["1 lb shrimp, peeled and deveined", "4 cups cooked white rice", "2 eggs", "1 cup frozen peas", "4 cloves garlic", "3 tbsp soy sauce", "1 tbsp sesame oil", "2 tbsp olive oil", "3 green onions", "pepper"]'::jsonb, '["Heat olive oil in a large wok or skillet over high heat.", "Add minced garlic and cook 30 seconds.", "Add shrimp and cook 2 minutes per side until pink; push to the side.", "Crack in eggs and scramble until just set; mix with shrimp.", "Add rice, peas, soy sauce, and sesame oil; stir-fry 4 minutes.", "Season with pepper and top with sliced green onions."]'::jsonb, 4, 10, 15, 2.8, 11.2, 450, 30, 52, 12, 3, 780, true, true, true, 'curated'),
  ('Classic Chicken Tortilla Soup', 'A hearty tomato-based soup loaded with shredded chicken, black beans, corn, and crushed tortilla chips.', 'lunch', 'Soup', 'budget', ARRAY['budget','dairy-free','egg-free','high-protein','kid-friendly','meal-prep','mexican','nut-free','soup','soy-free','standard']::text[], '["1 lb chicken breast", "1 can black beans", "1 cup frozen corn", "1 can diced tomatoes", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "4 cups chicken broth", "1 tsp cumin", "1 tsp chili powder", "1 cup tortilla chips", "salt", "pepper"]'::jsonb, '["Heat olive oil in a large pot and saut\u00e9 diced onion and garlic 4 minutes.", "Add diced tomatoes, broth, cumin, and chili powder; bring to a boil.", "Add whole chicken breast, reduce heat, and simmer 20 minutes.", "Remove chicken, shred with two forks, and return to pot.", "Add drained black beans and corn; simmer 5 minutes.", "Season with salt and pepper; serve topped with crushed tortilla chips."]'::jsonb, 6, 10, 35, 2.0, 12.0, 330, 26, 38, 7, 8, 710, true, true, true, 'curated'),
  ('Egg and Veggie Fried Rice', 'Fluffy scrambled eggs stir-fried with mixed vegetables and soy-seasoned rice for a quick satisfying lunch.', 'lunch', 'Stir-Fry', 'ultra_budget', ARRAY['asian','budget','dairy-free','kid-friendly','nut-free','one-pan','quick','stir-fry','vegetable','vegetarian']::text[], '["4 eggs", "4 cups cooked white rice", "1 cup frozen mixed vegetables", "1 onion", "3 cloves garlic", "2 tbsp soy sauce", "1 tbsp sesame oil", "2 tbsp olive oil", "pepper"]'::jsonb, '["Heat olive oil in a large wok over high heat.", "Add diced onion and garlic; cook 2 minutes.", "Add frozen vegetables and stir-fry 3 minutes until thawed and heated through.", "Push everything to the side; crack in eggs and scramble until just set.", "Add rice and soy sauce; toss everything together 3 minutes over high heat.", "Drizzle sesame oil, season with pepper, and serve."]'::jsonb, 4, 5, 15, 1.0, 4.0, 370, 14, 54, 11, 3, 620, true, true, true, 'curated'),
  ('Crispy Baked Fish Tacos with Mango Slaw', 'Crunchy breadcrumb-coated tilapia fillets tucked into warm corn tortillas with a bright mango and cabbage slaw.', 'dinner', 'Mexican', 'budget', ARRAY['baked','budget','dairy-free','egg-free','high-protein','kid-friendly','mexican','nut-free','seafood','sheet-pan','soy-free','standard']::text[], '["1 lb tilapia fillets", "8 corn tortillas", "1 cup breadcrumbs", "1 mango", "2 cups shredded green cabbage", "1 lime", "1 tsp cumin", "1 tsp chili powder", "1 tsp garlic powder", "2 tbsp olive oil", "salt"]'::jsonb, '["Preheat oven to 425\u00b0F.", "Mix breadcrumbs with cumin, chili powder, garlic powder, and salt.", "Coat tilapia fillets in olive oil then press into breadcrumb mixture.", "Bake on a lined sheet pan 15-18 minutes until golden and crispy.", "Dice mango and toss with shredded cabbage and lime juice for slaw.", "Warm tortillas and assemble tacos with fish and mango slaw."]'::jsonb, 4, 15, 18, 2.8, 11.2, 390, 28, 50, 9, 5, 530, true, true, true, 'curated'),
  ('Lemon Garlic Green Bean and Chicken Skillet', 'Tender chicken breast strips and crisp-tender green beans sautéed in a bright lemon garlic pan sauce.', 'dinner', 'Skillet', 'budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','quick','soy-free','standard','vegetable']::text[], '["1 lb chicken breast", "1 lb green beans", "4 cloves garlic", "1 lemon", "2 tbsp olive oil", "1 tsp Italian seasoning", "1 cup chicken broth", "salt", "pepper"]'::jsonb, '["Slice chicken breast into strips and season with salt, pepper, and Italian seasoning.", "Heat olive oil in a large skillet over medium-high heat.", "Cook chicken strips 5-6 minutes per side until golden; remove and set aside.", "Add trimmed green beans and garlic to skillet; cook 4 minutes.", "Pour chicken broth and lemon juice into pan; scrape up any browned bits.", "Return chicken to pan and simmer 3 minutes; serve hot."]'::jsonb, 4, 10, 25, 2.6, 10.4, 280, 34, 10, 11, 4, 420, true, true, true, 'curated'),
  ('Pinto Bean Enchiladas in Red Sauce', 'Corn tortillas stuffed with seasoned pinto beans and onion rolled up and smothered in homemade red enchilada sauce.', 'dinner', 'Mexican', 'ultra_budget', ARRAY['baked','budget','dairy-free','egg-free','gluten-free','high-fiber','kid-friendly','meal-prep','mexican','nut-free','soy-free','standard']::text[], '["2 cans pinto beans", "8 corn tortillas", "1 can tomato sauce", "1 onion", "3 cloves garlic", "1 tbsp olive oil", "2 tsp chili powder", "1 tsp cumin", "1 tsp garlic powder", "1 cup chicken broth", "salt"]'::jsonb, '["Preheat oven to 375\u00b0F.", "Simmer tomato sauce, chicken broth, chili powder, and cumin in a small pan 5 minutes for enchilada sauce.", "Saut\u00e9 diced onion and garlic in olive oil; add drained pinto beans and garlic powder.", "Mash beans lightly and season with salt.", "Spoon bean filling into tortillas, roll up, and place seam-side down in a baking dish.", "Pour enchilada sauce over top and bake 25 minutes until bubbly."]'::jsonb, 4, 15, 35, 1.4, 5.6, 380, 16, 62, 6, 13, 650, true, true, true, 'curated'),
  ('Smoky Chicken Tinga Tacos', 'Shredded chicken simmered in a chipotle-tomato sauce piled into warm corn tortillas with onion and cilantro.', 'dinner', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','mexican','nut-free','one-pot','soy-free','standard','stovetop']::text[], '["1.5 lbs chicken thighs", "1 can diced tomatoes", "2 chipotle peppers in adobo", "1 onion", "3 cloves garlic", "1 tsp cumin", "1 tsp oregano", "1 tbsp olive oil", "12 corn tortillas", "salt", "pepper"]'::jsonb, '["Season chicken thighs with salt, pepper, and cumin.", "Heat olive oil in a large skillet over medium-high heat and sear chicken 4 minutes per side, then set aside.", "Saute diced onion and garlic in the same pan until soft, about 3 minutes.", "Blend diced tomatoes and chipotle peppers until smooth, then pour into the pan.", "Return chicken to pan, cover, and simmer 20 minutes until cooked through.", "Shred chicken in the sauce and serve in warm corn tortillas."]'::jsonb, 4, 10, 30, 2.5, 10.0, 390, 30, 32, 12, 4, 520, true, true, true, 'curated'),
  ('Sichuan-Style Mapo Tofu', 'Silken tofu and ground pork bathed in a bold, fragrant sauce of chili bean paste, ginger, and Sichuan spices.', 'dinner', 'Chinese', 'budget', ARRAY['budget','chinese','dairy-free','egg-free','high-protein','nut-free','one-pot','spicy','standard','stovetop']::text[], '["1 lb ground pork", "1 block silken tofu", "2 tbsp chili bean paste", "1 tbsp soy sauce", "1 tsp sesame oil", "1 tsp cornstarch", "3 cloves garlic", "1 tbsp fresh ginger", "2 green onions", "1 tbsp vegetable oil", "0.5 cup chicken broth", "1 tsp Sichuan peppercorn", "2 cups white rice"]'::jsonb, '["Cook white rice according to package directions.", "Heat vegetable oil in a wok or skillet over high heat and brown ground pork, breaking it apart.", "Add minced garlic, ginger, and chili bean paste; stir-fry 1 minute until fragrant.", "Pour in chicken broth and soy sauce, then gently add cubed tofu.", "Mix cornstarch with 2 tbsp water and stir into the pan to thicken the sauce.", "Finish with sesame oil, Sichuan peppercorn, and sliced green onions; serve over rice."]'::jsonb, 4, 10, 20, 2.75, 11.0, 420, 28, 40, 14, 2, 680, false, true, true, 'curated'),
  ('Thai Basil Ground Beef Stir-Fry', 'Ground beef tossed in a savory oyster sauce glaze with Thai basil, garlic, and chilies served over jasmine rice.', 'dinner', 'Thai', 'budget', ARRAY['budget','dairy-free','egg-free','high-protein','kid-friendly','nut-free','quick','standard','stir-fry','stovetop','thai']::text[], '["1 lb ground beef", "2 cups jasmine rice", "3 cloves garlic", "2 tbsp oyster sauce", "1 tbsp soy sauce", "1 tsp fish sauce", "1 tsp sugar", "1 cup fresh basil leaves", "1 bell pepper", "1 tbsp vegetable oil", "2 red chilies"]'::jsonb, '["Cook jasmine rice according to package directions.", "Heat vegetable oil in a large skillet or wok over high heat.", "Add minced garlic and sliced chilies and stir-fry 30 seconds.", "Add ground beef and cook, breaking apart, until browned, about 5 minutes.", "Stir in oyster sauce, soy sauce, fish sauce, and sugar; toss with sliced bell pepper and cook 2 minutes.", "Remove from heat, stir in fresh basil, and serve over jasmine rice."]'::jsonb, 4, 8, 20, 2.6, 10.4, 450, 26, 44, 16, 2, 640, true, true, true, 'curated'),
  ('Butter Chicken with Fluffy Basmati', 'Tender chicken pieces slow-simmered in a rich, creamy tomato and spice sauce served alongside fragrant basmati rice.', 'dinner', 'Indian', 'budget', ARRAY['budget','creamy','egg-free','gluten-free','high-protein','indian','kid-friendly','nut-free','one-pot','soy-free','standard','stovetop']::text[], '["1.5 lbs chicken thighs", "1 can diced tomatoes", "0.5 cup heavy cream", "1 onion", "3 cloves garlic", "1 tbsp fresh ginger", "2 tbsp butter", "1 tbsp garam masala", "1 tsp cumin", "1 tsp turmeric", "1 tsp paprika", "2 cups basmati rice", "salt"]'::jsonb, '["Cook basmati rice according to package directions.", "Cut chicken into bite-size pieces and season with garam masala, cumin, turmeric, and salt.", "Melt butter in a large skillet over medium-high heat and brown chicken on all sides, then set aside.", "Saute diced onion, garlic, and ginger until soft, about 4 minutes.", "Stir in diced tomatoes and paprika; simmer 8 minutes, then blend until smooth.", "Return chicken to the sauce, add heavy cream, and simmer 10 minutes before serving over basmati rice."]'::jsonb, 4, 12, 35, 2.9, 11.6, 510, 34, 48, 18, 3, 490, true, true, true, 'curated'),
  ('Mediterranean Baked Lemon Herb Chicken', 'Bone-in chicken thighs roasted with olives, cherry tomatoes, and fresh herbs until golden and deeply fragrant.', 'dinner', 'Mediterranean', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','mediterranean','nut-free','oven-baked','sheet-pan','soy-free','standard']::text[], '["2 lbs bone-in chicken thighs", "1 cup cherry tomatoes", "0.5 cup Kalamata olives", "1 lemon", "3 cloves garlic", "2 tbsp olive oil", "1 tsp oregano", "1 tsp thyme", "0.5 tsp paprika", "salt", "pepper"]'::jsonb, '["Preheat oven to 425\u00b0F.", "Pat chicken dry and rub with olive oil, garlic, oregano, thyme, paprika, salt, and pepper.", "Arrange chicken on a sheet pan with cherry tomatoes and olives.", "Squeeze lemon juice over everything and lay lemon slices around the pan.", "Roast 35-40 minutes until skin is golden and chicken is cooked through.", "Serve with crusty bread or rice to soak up the pan juices."]'::jsonb, 4, 10, 40, 2.8, 11.2, 390, 32, 6, 24, 1, 510, true, true, true, 'curated'),
  ('Classic Italian Sunday Meat Sauce', 'A slow-simmered tomato sauce loaded with ground beef and Italian sausage served over spaghetti for a hearty family meal.', 'dinner', 'Italian', 'budget', ARRAY['budget','egg-free','gluten-free','high-protein','italian','kid-friendly','nut-free','one-pot','pasta','soy-free','standard','stovetop']::text[], '["1 lb spaghetti", "0.5 lb ground beef", "0.5 lb Italian sausage", "2 cans crushed tomatoes", "1 onion", "4 cloves garlic", "2 tbsp olive oil", "1 tsp oregano", "1 tsp basil", "0.5 tsp red pepper flakes", "salt", "pepper", "0.25 cup grated Parmesan"]'::jsonb, '["Heat olive oil in a large pot over medium heat and saute diced onion until soft, about 5 minutes.", "Add garlic and cook 1 minute, then add ground beef and sausage; brown completely.", "Stir in crushed tomatoes, oregano, basil, red pepper flakes, salt, and pepper.", "Simmer sauce on low heat 25-30 minutes, stirring occasionally.", "Cook spaghetti according to package directions and drain.", "Serve sauce over spaghetti and top with Parmesan."]'::jsonb, 6, 10, 40, 2.2, 13.2, 530, 28, 62, 16, 5, 590, true, true, true, 'curated'),
  ('Korean Pork Bulgogi Rice Bowls', 'Thinly sliced pork marinated in a sweet-savory gochujang glaze, seared quickly and served over steamed rice with pickled cucumber.', 'dinner', 'Korean', 'budget', ARRAY['budget','dairy-free','egg-free','high-protein','korean','nut-free','rice-bowl','standard','stir-fry','stovetop']::text[], '["1.5 lbs pork loin", "3 cups white rice", "2 tbsp gochujang", "2 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp brown sugar", "3 cloves garlic", "1 tbsp fresh ginger", "1 cucumber", "2 tbsp rice vinegar", "2 green onions", "1 tbsp vegetable oil"]'::jsonb, '["Slice pork loin thinly across the grain.", "Mix gochujang, soy sauce, sesame oil, brown sugar, minced garlic, and ginger into a marinade; toss with pork and let sit 15 minutes.", "Thinly slice cucumber, toss with rice vinegar and a pinch of salt, and set aside.", "Cook white rice according to package directions.", "Heat vegetable oil in a skillet over high heat and cook pork in a single layer 2-3 minutes per side until caramelized.", "Serve pork over rice bowls with pickled cucumber and sliced green onions."]'::jsonb, 4, 20, 20, 2.95, 11.8, 480, 36, 52, 12, 2, 620, false, true, true, 'curated'),
  ('Cajun Shrimp and Andouille Dirty Rice', 'Spiced shrimp and smoky andouille sausage cooked down with seasoned rice and the Cajun holy trinity into one soul-warming pot.', 'dinner', 'Cajun', 'budget', ARRAY['budget','cajun','dairy-free','egg-free','gluten-free','high-protein','nut-free','one-pot','soy-free','spicy','standard','stovetop']::text[], '["1 lb large shrimp, peeled", "0.5 lb andouille sausage", "1.5 cups long-grain white rice", "1 onion", "2 stalks celery", "1 bell pepper", "3 cloves garlic", "2 tbsp vegetable oil", "1 tbsp Cajun seasoning", "1 can diced tomatoes", "2 cups chicken broth", "2 green onions", "salt", "pepper"]'::jsonb, '["Slice andouille sausage and cook in a large pot with oil over medium-high heat until browned, then set aside.", "Saute diced onion, celery, and bell pepper in the same pot 5 minutes, then add garlic.", "Stir in rice and toast 2 minutes, then add diced tomatoes and chicken broth.", "Bring to a boil, reduce heat, cover, and cook 18 minutes until rice is tender.", "Season shrimp with Cajun seasoning and nestle into the rice; cover and cook 5 more minutes.", "Fold in sausage and top with sliced green onions before serving."]'::jsonb, 4, 12, 35, 2.85, 11.4, 470, 32, 50, 14, 3, 780, false, true, true, 'curated'),
  ('Jamaican Jerk Chicken Drumsticks', 'Chicken drumsticks coated in a bold jerk spice paste and grilled until charred and smoky with a fiery Caribbean kick.', 'dinner', 'Caribbean', 'budget', ARRAY['budget','caribbean','dairy-free','egg-free','grilled','high-protein','nut-free','spicy','standard']::text[], '["2 lbs chicken drumsticks", "2 tbsp soy sauce", "2 tbsp brown sugar", "1 tbsp allspice", "1 tsp cinnamon", "0.5 tsp nutmeg", "1 tsp thyme", "3 cloves garlic", "2 green onions", "1 tbsp fresh ginger", "1 tbsp vegetable oil", "2 scotch bonnet or jalapeno peppers", "1 lime", "salt", "pepper"]'::jsonb, '["Blend garlic, green onions, ginger, peppers, soy sauce, brown sugar, allspice, cinnamon, nutmeg, thyme, lime juice, and oil into a smooth paste.", "Score drumsticks with a knife and coat thoroughly in jerk paste.", "Marinate in the refrigerator at least 1 hour or overnight.", "Preheat grill or grill pan to medium-high heat.", "Grill drumsticks 8-10 minutes per side, turning occasionally, until cooked through and charred.", "Rest 5 minutes before serving with rice and peas or coleslaw."]'::jsonb, 4, 15, 25, 2.4, 9.6, 360, 30, 10, 20, 1, 540, false, true, true, 'curated'),
  ('Ethiopian Beef Tibs with Injera', 'Strips of sauteed beef with onions, jalapenos, and warming Ethiopian spices served atop spongy injera flatbread.', 'dinner', 'Ethiopian', 'budget', ARRAY['budget','egg-free','ethiopian','high-protein','nut-free','spicy','standard','stovetop']::text[], '["1.5 lbs beef sirloin", "1 onion", "2 jalapeno peppers", "3 cloves garlic", "2 tbsp butter", "1 tbsp berbere spice", "1 tsp mitmita spice", "1 tbsp soy sauce", "4 pieces injera flatbread", "2 tbsp fresh rosemary", "salt", "pepper"]'::jsonb, '["Slice beef sirloin into thin strips and season with salt and pepper.", "Melt butter in a large skillet over high heat and sear beef in batches until browned, then set aside.", "In the same pan, saute sliced onion and jalapenos until softened, about 4 minutes.", "Add minced garlic, berbere, and mitmita spice; stir 1 minute.", "Return beef to the pan, splash in soy sauce, and toss everything together over high heat 2 minutes.", "Serve over injera flatbread with fresh rosemary on top."]'::jsonb, 4, 12, 20, 2.95, 11.8, 400, 34, 22, 18, 3, 490, false, true, true, 'curated'),
  ('Lebanese Lamb Kofta with Yogurt Sauce', 'Spiced ground lamb patties grilled until juicy and served with a cool garlicky yogurt sauce and warm pita bread.', 'dinner', 'Middle Eastern', 'standard', ARRAY['egg-free','grilled','high-protein','kid-friendly','mediterranean','middle-eastern','nut-free','soy-free','standard']::text[], '["1.5 lbs ground lamb", "1 onion", "3 cloves garlic", "1 tsp cumin", "1 tsp coriander", "0.5 tsp cinnamon", "0.5 tsp allspice", "0.25 cup fresh parsley", "1 cup plain yogurt", "1 tbsp lemon juice", "4 pita breads", "salt", "pepper"]'::jsonb, '["Grate onion and squeeze out excess liquid, then mix with ground lamb, garlic, cumin, coriander, cinnamon, allspice, parsley, salt, and pepper.", "Shape mixture into oval patties or sausage shapes around skewers.", "Preheat grill or grill pan to medium-high and cook kofta 4-5 minutes per side.", "Mix yogurt with lemon juice, minced garlic, salt, and a pinch of cumin for the sauce.", "Warm pita breads on the grill for 1 minute per side.", "Serve kofta in or alongside pita with yogurt sauce drizzled over."]'::jsonb, 4, 15, 15, 3.8, 15.2, 450, 30, 28, 24, 2, 480, true, true, true, 'curated'),
  ('Chicken Pozole Rojo', 'A vibrant red Mexican soup brimming with shredded chicken and hominy in a deeply spiced ancho chili broth.', 'dinner', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','mexican','nut-free','one-pot','soup','soy-free','standard','stovetop']::text[], '["1.5 lbs chicken thighs", "2 cans hominy, drained", "3 dried ancho chilies", "1 can diced tomatoes", "1 onion", "4 cloves garlic", "1 tsp cumin", "1 tsp oregano", "4 cups chicken broth", "1 tbsp vegetable oil", "1 lime", "salt", "pepper", "0.5 head cabbage"]'::jsonb, '["Toast dried ancho chilies in a dry pan 1 minute per side, then soak in hot water 15 minutes.", "Blend soaked chilies with diced tomatoes, garlic, and 1 cup chicken broth until smooth.", "Heat oil in a large pot, saute diced onion, then add chili puree and cook 5 minutes.", "Add chicken thighs and remaining chicken broth; simmer 25 minutes until chicken is cooked.", "Remove chicken, shred with two forks, and return to pot with drained hominy.", "Simmer 10 more minutes, season with salt and pepper, and serve with shredded cabbage and lime wedges."]'::jsonb, 6, 20, 45, 2.1, 12.6, 370, 28, 38, 10, 6, 560, true, true, true, 'curated'),
  ('Chinese Pork Fried Rice', 'Day-old rice stir-fried with pork, eggs, peas, and classic seasonings for the ultimate savory weeknight staple.', 'dinner', 'Chinese', 'ultra_budget', ARRAY['budget','chinese','dairy-free','high-protein','kid-friendly','nut-free','one-pan','quick','standard','stir-fry','stovetop']::text[], '["3 cups cooked white rice", "0.5 lb pork loin", "3 eggs", "1 cup frozen peas", "3 green onions", "3 cloves garlic", "2 tbsp soy sauce", "1 tbsp oyster sauce", "1 tsp sesame oil", "2 tbsp vegetable oil", "salt", "pepper"]'::jsonb, '["Dice pork loin into small cubes and season with salt and pepper.", "Heat vegetable oil in a wok or large skillet over high heat and cook pork until golden, then push to the side.", "Add garlic and stir-fry 30 seconds, then scramble eggs in the pan until just set.", "Add cold rice and press it into the pan; let it sit undisturbed 2 minutes to lightly crisp.", "Stir in frozen peas, soy sauce, and oyster sauce; toss everything together over high heat 2 minutes.", "Finish with sesame oil and sliced green onions before serving."]'::jsonb, 4, 8, 15, 1.4, 5.6, 410, 22, 52, 12, 3, 590, true, true, true, 'curated'),
  ('Thai Red Curry Chicken', 'Chunks of chicken breast cooked in coconut milk with red curry paste, bell peppers, and fresh basil for a fragrant dinner.', 'dinner', 'Thai', 'budget', ARRAY['budget','creamy','egg-free','gluten-free','high-protein','nut-free','one-pot','soy-free','standard','stovetop','thai']::text[], '["1.5 lbs chicken breast", "1 can coconut milk", "2 tbsp red curry paste", "1 red bell pepper", "1 green bell pepper", "1 onion", "2 tbsp fish sauce", "1 tbsp brown sugar", "1 cup fresh basil", "1 tbsp vegetable oil", "2 cups jasmine rice", "1 lime"]'::jsonb, '["Cook jasmine rice according to package directions.", "Slice chicken into bite-size pieces and season lightly with salt.", "Heat oil in a large wok or pot and fry red curry paste 1-2 minutes until fragrant.", "Add coconut milk and bring to a gentle simmer, stirring until combined.", "Add chicken and sliced bell peppers; cook 15 minutes until chicken is done.", "Season with fish sauce and brown sugar, stir in basil, squeeze lime over, and serve with jasmine rice."]'::jsonb, 4, 10, 25, 2.7, 10.8, 460, 34, 46, 16, 3, 620, false, true, true, 'curated'),
  ('Indian Chana Masala with Basmati', 'Hearty chickpeas slow-cooked in a warmly spiced onion-tomato gravy that deepens in flavor the longer it simmers.', 'dinner', 'Indian', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-fiber','indian','kid-friendly','nut-free','one-pot','soy-free','stovetop','vegan','vegetarian']::text[], '["2 cans chickpeas, drained", "1 can diced tomatoes", "1 onion", "4 cloves garlic", "1 tbsp fresh ginger", "2 tbsp vegetable oil", "1 tsp cumin seeds", "1 tsp garam masala", "1 tsp turmeric", "1 tsp coriander", "0.5 tsp cayenne pepper", "2 cups basmati rice", "salt", "0.25 cup fresh cilantro", "1 lemon"]'::jsonb, '["Cook basmati rice according to package directions.", "Heat oil in a large pot over medium heat and toast cumin seeds 30 seconds.", "Add diced onion and cook until golden brown, about 8 minutes.", "Stir in garlic, ginger, turmeric, coriander, and cayenne; cook 2 minutes.", "Add diced tomatoes and cook 5 minutes, then add chickpeas and 0.5 cup water.", "Simmer 15 minutes, stir in garam masala and lemon juice, top with cilantro, and serve with basmati rice."]'::jsonb, 4, 10, 35, 1.3, 5.2, 390, 16, 66, 8, 12, 410, true, true, true, 'curated'),
  ('Italian Sausage and Peppers Hoagies', 'Juicy Italian sausage links nestled with roasted sweet peppers and onions inside a toasted hoagie roll.', 'dinner', 'Italian', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','italian','kid-friendly','nut-free','quick','sandwich','soy-free','standard','stovetop']::text[], '["4 Italian sausage links", "3 bell peppers", "1 large onion", "4 hoagie rolls", "3 cloves garlic", "2 tbsp olive oil", "1 tsp oregano", "0.5 tsp red pepper flakes", "salt", "pepper"]'::jsonb, '["Slice bell peppers and onion into strips.", "Heat olive oil in a large skillet over medium-high heat and cook sausage links until browned on all sides, about 8 minutes; remove and slice.", "In the same pan, saute peppers and onion with garlic, oregano, and red pepper flakes until softened and slightly caramelized, about 10 minutes.", "Return sliced sausage to the pan and toss everything together for 2 minutes.", "Toast hoagie rolls under the broiler 1-2 minutes.", "Pile sausage, peppers, and onions into rolls and serve immediately."]'::jsonb, 4, 8, 25, 2.5, 10.0, 480, 22, 46, 22, 4, 780, true, true, true, 'curated'),
  ('Korean Sundubu Jjigae Soft Tofu Stew', 'A bubbling, fiery Korean stew of silken soft tofu, ground pork, and zucchini in a rich gochugaru-spiked broth.', 'dinner', 'Korean', 'budget', ARRAY['budget','dairy-free','high-protein','korean','nut-free','one-pot','soup','spicy','standard','stovetop']::text[], '["2 tubes soft tofu", "0.25 lb ground pork", "1 zucchini", "3 cloves garlic", "1 tbsp gochugaru", "1 tbsp soy sauce", "1 tbsp sesame oil", "2 cups chicken broth", "2 eggs", "2 green onions", "1 tbsp vegetable oil", "2 cups white rice"]'::jsonb, '["Cook white rice according to package directions.", "Heat vegetable oil in a small pot or stone pot over medium heat and cook ground pork until browned.", "Add minced garlic and gochugaru; stir 1 minute until the oil turns red and fragrant.", "Pour in chicken broth and soy sauce; bring to a boil.", "Gently spoon in soft tofu and add sliced zucchini; simmer 5 minutes.", "Crack an egg directly into each bowl, pour hot stew over, drizzle with sesame oil, and top with green onions."]'::jsonb, 2, 8, 20, 2.6, 5.2, 380, 24, 38, 14, 3, 700, false, true, true, 'curated'),
  ('Cajun Blackened Catfish with Dirty Greens', 'Catfish fillets coated in a bold spice crust and seared until blackened, served with braised collard greens.', 'dinner', 'Cajun', 'budget', ARRAY['budget','cajun','egg-free','gluten-free','high-protein','nut-free','southern','soy-free','standard','stovetop']::text[], '["4 catfish fillets", "1 bunch collard greens", "4 slices bacon", "1 onion", "3 cloves garlic", "2 tbsp Cajun seasoning", "1 tsp smoked paprika", "2 tbsp butter", "1 cup chicken broth", "1 tbsp apple cider vinegar", "salt", "pepper"]'::jsonb, '["Cook bacon in a large pot until crisp; remove and crumble, leaving drippings in pot.", "Saute sliced onion and garlic in drippings 4 minutes, then add chopped collard greens, chicken broth, and vinegar.", "Cover and braise greens over medium-low heat 25 minutes until tender.", "Meanwhile, pat catfish dry and coat both sides generously with Cajun seasoning and smoked paprika.", "Melt butter in a cast iron skillet over high heat until smoking, then cook catfish 3-4 minutes per side until blackened.", "Serve catfish over collard greens topped with crumbled bacon."]'::jsonb, 4, 10, 35, 2.8, 11.2, 380, 30, 10, 22, 4, 730, false, true, true, 'curated'),
  ('Caribbean Rice and Peas with Stewed Chicken', 'Coconut-infused kidney bean rice pairs with slow-braised chicken thighs seasoned with Caribbean herbs and spices.', 'dinner', 'Caribbean', 'budget', ARRAY['budget','caribbean','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','soy-free','standard','stovetop']::text[], '["2 lbs chicken thighs", "1.5 cups long-grain rice", "1 can kidney beans, drained", "0.5 can coconut milk", "1 onion", "3 cloves garlic", "2 green onions", "1 sprig fresh thyme", "1 scotch bonnet or habanero pepper", "1 tbsp vegetable oil", "1.5 cups chicken broth", "1 tsp allspice", "salt", "pepper"]'::jsonb, '["Season chicken thighs with allspice, salt, and pepper and brown in oil in a large pot; remove.", "Saute onion, garlic, and green onions in the same pot until softened.", "Add rice, kidney beans, coconut milk, chicken broth, thyme, and whole scotch bonnet pepper.", "Nestle chicken on top, bring to a boil, then cover and cook on low 25 minutes.", "Remove thyme sprig and scotch bonnet pepper (do not break it open).", "Fluff rice, check seasoning, and serve family-style from the pot."]'::jsonb, 4, 12, 35, 2.6, 10.4, 530, 34, 54, 16, 6, 480, true, true, true, 'curated'),
  ('Middle Eastern Spiced Lamb and Rice Pilaf', 'Fragrant basmati rice studded with tender ground lamb, toasted pine nuts, and a warming blend of cinnamon and allspice.', 'dinner', 'Middle Eastern', 'standard', ARRAY['dairy-free','egg-free','gluten-free','high-protein','kid-friendly','middle-eastern','one-pot','soy-free','standard','stovetop']::text[], '["1 lb ground lamb", "2 cups basmati rice", "1 onion", "3 cloves garlic", "1 tsp cinnamon", "1 tsp allspice", "0.5 tsp cumin", "0.25 tsp nutmeg", "2 tbsp olive oil", "0.25 cup pine nuts", "2.5 cups chicken broth", "salt", "pepper", "0.25 cup fresh parsley"]'::jsonb, '["Toast pine nuts in a dry skillet until golden; set aside.", "Heat olive oil in a pot and brown ground lamb, breaking it apart; drain excess fat.", "Add diced onion and garlic; cook 5 minutes until softened.", "Stir in cinnamon, allspice, cumin, and nutmeg; cook 1 minute.", "Add rinsed basmati rice and chicken broth; bring to a boil, then reduce heat, cover, and cook 18 minutes.", "Fluff rice, fold in pine nuts, top with fresh parsley, and serve."]'::jsonb, 4, 10, 30, 3.5, 14.0, 520, 28, 52, 20, 3, 430, true, true, true, 'curated'),
  ('Mexican Birria-Style Beef Tacos', 'Slow-braised chili-marinated beef served in crispy fried tortillas with rich consomme for dipping.', 'dinner', 'Mexican', 'budget', ARRAY['braised','budget','dairy-free','egg-free','gluten-free','high-protein','mexican','nut-free','one-pot','soy-free','standard','stovetop']::text[], '["2 lbs beef chuck", "3 dried guajillo chilies", "2 dried ancho chilies", "1 can diced tomatoes", "1 onion", "4 cloves garlic", "1 tsp cumin", "1 tsp oregano", "0.5 tsp cinnamon", "2 cups beef broth", "12 corn tortillas", "1 tbsp vegetable oil", "salt", "pepper", "0.5 cup white onion", "0.25 cup fresh cilantro"]'::jsonb, '["Toast dried chilies in a dry pan 1 minute per side, then soak in hot water 15 minutes.", "Blend soaked chilies with diced tomatoes, garlic, cumin, oregano, and cinnamon until smooth.", "Season beef chuck with salt and pepper, then place in a large pot with chili puree, beef broth, and sliced onion.", "Braise covered over low heat 2.5 hours until beef is fall-apart tender.", "Shred beef and reserve the broth (consomme) for dipping.", "Dip corn tortillas in consomme, fry briefly in oiled skillet until crispy, fill with beef, and serve with diced onion and cilantro."]'::jsonb, 6, 20, 150, 2.8, 16.8, 460, 34, 30, 20, 4, 560, false, true, true, 'curated'),
  ('Chinese Beef and Broccoli Stir-Fry', 'Tender sliced beef and crisp broccoli florets glazed in a savory ginger-garlic oyster sauce over steamed white rice.', 'dinner', 'Chinese', 'budget', ARRAY['budget','chinese','dairy-free','egg-free','high-protein','kid-friendly','nut-free','quick','standard','stir-fry','stovetop']::text[], '["1 lb flank steak", "3 cups broccoli florets", "3 cloves garlic", "1 tbsp fresh ginger", "3 tbsp oyster sauce", "2 tbsp soy sauce", "1 tsp sesame oil", "1 tsp cornstarch", "2 tbsp vegetable oil", "0.5 cup beef broth", "2 cups white rice"]'::jsonb, '["Cook white rice according to package directions.", "Thinly slice flank steak against the grain and toss with soy sauce and cornstarch.", "Heat vegetable oil in a wok over high heat until smoking; sear beef in batches and set aside.", "Stir-fry broccoli in the same wok 3 minutes, then add garlic and ginger.", "Return beef to wok, pour in oyster sauce and beef broth, and toss until glossy and sauce thickens.", "Drizzle with sesame oil and serve over rice."]'::jsonb, 4, 12, 20, 2.75, 11.0, 440, 30, 46, 14, 4, 660, true, true, true, 'curated'),
  ('Indian Keema Aloo Spiced Beef and Potato', 'Ground beef and tender potatoes simmered together with onions, tomatoes, and classic Indian spices into a deeply satisfying dry curry.', 'dinner', 'Indian', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','indian','kid-friendly','nut-free','one-pot','soy-free','standard','stovetop']::text[], '["1 lb ground beef", "3 potatoes", "1 onion", "1 can diced tomatoes", "3 cloves garlic", "1 tbsp fresh ginger", "1 tsp cumin", "1 tsp coriander", "1 tsp turmeric", "0.5 tsp cayenne pepper", "1 tsp garam masala", "2 tbsp vegetable oil", "0.25 cup fresh cilantro", "2 cups basmati rice", "salt"]'::jsonb, '["Cook basmati rice according to package directions.", "Dice potatoes into small cubes.", "Heat oil in a large skillet and brown ground beef, breaking it apart; drain excess fat.", "Add diced onion and cook 5 minutes, then add garlic, ginger, cumin, coriander, turmeric, and cayenne.", "Stir in diced tomatoes and potatoes; cover and cook 20 minutes until potatoes are tender.", "Sprinkle with garam masala, top with cilantro, and serve with basmati rice."]'::jsonb, 4, 10, 30, 1.5, 6.0, 480, 26, 58, 14, 5, 390, true, true, true, 'curated'),
  ('Italian Chicken Cacciatore', 'Braised chicken thighs nestled in a rustic sauce of tomatoes, bell peppers, mushrooms, and olives with fresh herbs.', 'dinner', 'Italian', 'budget', ARRAY['braised','budget','dairy-free','egg-free','high-protein','italian','kid-friendly','nut-free','one-pot','soy-free','standard','stovetop']::text[], '["2 lbs chicken thighs", "1 can diced tomatoes", "2 bell peppers", "1 cup mushrooms", "0.5 cup Kalamata olives", "1 onion", "4 cloves garlic", "2 tbsp olive oil", "1 tsp oregano", "1 tsp thyme", "0.5 cup chicken broth", "salt", "pepper", "1 lb pasta"]'::jsonb, '["Season chicken thighs with salt and pepper; brown in olive oil in a large pot 4 minutes per side, then set aside.", "Saute diced onion, sliced bell peppers, and mushrooms in the same pot until softened.", "Add garlic, oregano, and thyme; cook 1 minute.", "Pour in diced tomatoes and chicken broth; return chicken to the pot and nestle in olives.", "Cover and braise over medium-low heat 30 minutes until chicken is tender.", "Cook pasta separately according to package directions and serve chicken and sauce on top."]'::jsonb, 4, 12, 45, 2.6, 10.4, 510, 36, 50, 16, 5, 530, true, true, true, 'curated'),
  ('Ethiopian Misir Wat Red Lentil Stew', 'Slow-simmered red lentils cooked with caramelized onions and the blazing Ethiopian spice blend berbere for a richly satisfying stew.', 'dinner', 'Ethiopian', 'ultra_budget', ARRAY['budget','dairy-free','egg-free','ethiopian','gluten-free','high-fiber','nut-free','one-pot','soy-free','spicy','stovetop','vegan','vegetarian']::text[], '["2 cups red lentils", "2 onions", "4 cloves garlic", "1 tbsp fresh ginger", "3 tbsp berbere spice", "3 tbsp vegetable oil", "1 can diced tomatoes", "4 cups water", "1 tsp turmeric", "salt", "4 pieces injera flatbread"]'::jsonb, '["Dice onions finely and cook in oil over medium heat, stirring often, until very deeply golden, about 20 minutes.", "Add minced garlic and ginger; cook 2 minutes, then stir in berbere and turmeric.", "Add diced tomatoes and cook 5 minutes until thickened.", "Rinse red lentils and add with 4 cups water; bring to a boil.", "Reduce heat and simmer 20-25 minutes, stirring occasionally, until lentils are completely soft and stew is thick.", "Season with salt and serve over or alongside injera flatbread."]'::jsonb, 4, 10, 50, 1.1, 4.4, 340, 18, 54, 8, 14, 350, false, true, true, 'curated'),
  ('Thai Pad See Ew Noodles with Chicken', 'Wide rice noodles stir-fried with chicken, egg, and Chinese broccoli in a caramelized sweet soy sauce.', 'dinner', 'Thai', 'budget', ARRAY['budget','dairy-free','high-protein','kid-friendly','noodles','nut-free','quick','standard','stir-fry','stovetop','thai']::text[], '["1 lb wide rice noodles", "1 lb chicken thighs", "3 cups Chinese broccoli or regular broccoli", "3 eggs", "3 cloves garlic", "3 tbsp soy sauce", "2 tbsp oyster sauce", "1 tbsp dark soy sauce", "1 tsp sugar", "2 tbsp vegetable oil", "pepper"]'::jsonb, '["Soak wide rice noodles in warm water 20 minutes until pliable, then drain.", "Slice chicken into thin strips and season with pepper.", "Heat oil in a wok over high heat and sear chicken until cooked, then push to one side and scramble eggs.", "Add garlic and broccoli florets; stir-fry 2 minutes.", "Add noodles and pour in soy sauce, dark soy sauce, oyster sauce, and sugar.", "Toss vigorously over high heat 2-3 minutes until noodles are well coated and slightly charred in spots."]'::jsonb, 4, 25, 15, 2.4, 9.6, 490, 28, 60, 14, 4, 700, true, true, true, 'curated'),
  ('Mediterranean Shakshuka with Merguez', 'Eggs poached in a spiced tomato and pepper sauce with slices of North African merguez sausage, served with crusty bread.', 'dinner', 'Mediterranean', 'budget', ARRAY['budget','dairy-free','high-protein','mediterranean','nut-free','one-pan','quick','soy-free','spicy','standard','stovetop']::text[], '["6 eggs", "0.5 lb merguez or chorizo sausage", "2 cans diced tomatoes", "2 bell peppers", "1 onion", "4 cloves garlic", "2 tbsp olive oil", "1 tsp cumin", "1 tsp smoked paprika", "0.5 tsp coriander", "0.25 tsp cayenne pepper", "0.25 cup fresh parsley", "4 slices crusty bread", "salt", "pepper"]'::jsonb, '["Slice sausage into rounds and brown in olive oil in a large oven-safe skillet over medium-high heat; remove and set aside.", "Saute diced onion and sliced bell peppers in the same pan until soft, about 6 minutes.", "Add garlic, cumin, paprika, coriander, and cayenne; stir 1 minute.", "Pour in diced tomatoes, season with salt and pepper, and simmer 10 minutes until thickened.", "Return sausage to pan, create wells in the sauce, and crack an egg into each well.", "Cover and cook over medium-low heat 6-8 minutes until egg whites are set; top with fresh parsley and serve with bread."]'::jsonb, 4, 10, 30, 2.7, 10.8, 380, 22, 26, 22, 5, 640, false, true, true, 'curated'),
  ('Korean Kimchi Jjigae Pork Stew', 'A bold, fermented kimchi stew simmered with tender pork belly and silken tofu in a fiery, umami-rich broth.', 'dinner', 'Korean', 'budget', ARRAY['budget','dairy-free','egg-free','high-protein','korean','nut-free','one-pot','soup','spicy','standard','stovetop']::text[], '["0.5 lb pork belly", "2 cups kimchi", "1 block firm tofu", "1 onion", "3 cloves garlic", "1 tbsp gochugaru", "1 tbsp soy sauce", "1 tsp sesame oil", "2 cups chicken broth", "2 green onions", "1 tbsp vegetable oil", "2 cups white rice"]'::jsonb, '["Cook white rice according to package directions.", "Slice pork belly into small pieces and cook in oil in a pot over medium-high heat until lightly browned.", "Add sliced onion, garlic, and gochugaru; stir-fry 2 minutes.", "Add kimchi and its juice; cook 5 minutes, stirring occasionally.", "Pour in chicken broth and soy sauce; bring to a boil, then simmer 15 minutes.", "Add cubed firm tofu and simmer 5 more minutes; finish with sesame oil and sliced green onions, serve with rice."]'::jsonb, 4, 10, 30, 2.85, 11.4, 420, 22, 42, 18, 3, 720, false, true, true, 'curated'),
  ('Cheesy Scrambled Egg Breakfast Burritos', 'Fluffy scrambled eggs and melted cheddar wrapped in warm flour tortillas make a satisfying handheld morning meal.', 'breakfast', 'Mexican', 'budget', ARRAY['budget','handheld','kid-friendly','mexican','nut-free','quick','soy-free','vegetarian']::text[], '["6 eggs", "1 cup shredded cheddar cheese", "4 flour tortillas", "2 tbsp butter", "1/4 cup salsa", "salt", "pepper"]'::jsonb, '["Crack eggs into a bowl, season with salt and pepper, and whisk until smooth.", "Melt butter in a skillet over medium-low heat and pour in eggs.", "Stir gently until eggs are just set, then remove from heat.", "Warm tortillas in the microwave for 20 seconds.", "Divide eggs among tortillas, top with cheese and salsa, then roll up tightly."]'::jsonb, 4, 5, 8, 1.8, 7.2, 340, 17, 28, 17, 1, 520, true, true, true, 'curated'),
  ('Veggie-Loaded Breakfast Hash', 'Crispy diced potatoes sauteed with colorful bell peppers and onions create a hearty skillet that fills everyone up.', 'breakfast', 'American', 'ultra_budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','hearty','kid-friendly','nut-free','one-pan','soy-free','vegan','vegetarian','veggie-forward']::text[], '["4 medium potatoes", "1 bell pepper", "1 onion", "2 cloves garlic", "2 tbsp olive oil", "1 tsp paprika", "salt", "pepper"]'::jsonb, '["Dice potatoes into small cubes and microwave for 4 minutes to par-cook.", "Chop bell pepper and onion into bite-sized pieces.", "Heat olive oil in a large skillet over medium-high heat.", "Add potatoes and cook without stirring for 4 minutes until a golden crust forms.", "Add pepper, onion, garlic, paprika, salt, and pepper; cook another 5 minutes, stirring occasionally.", "Serve hot topped with fried eggs if desired."]'::jsonb, 4, 8, 14, 1.2, 4.8, 230, 4, 40, 7, 4, 280, true, true, true, 'curated'),
  ('Creamy Tomato Soup with Cheese Croutons', 'Smooth blended tomatoes and cream simmer into a velvety soup topped with buttery toasted bread cubes.', 'lunch', 'Soup', 'budget', ARRAY['american','budget','comfort-food','egg-free','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["2 cans crushed tomatoes", "1 onion", "3 cloves garlic", "1 cup chicken broth", "1/2 cup heavy cream", "2 tbsp butter", "3 slices bread", "1/2 cup shredded cheddar cheese", "1 tsp sugar", "salt", "pepper"]'::jsonb, '["Saute diced onion and garlic in butter over medium heat for 5 minutes.", "Add crushed tomatoes, broth, and sugar; simmer 15 minutes.", "Use an immersion blender to puree the soup until smooth, then stir in cream.", "Cube the bread and toast in a skillet with a little butter until golden.", "Top toasted bread cubes with cheese and broil 1 minute.", "Serve soup bowls topped with cheesy croutons."]'::jsonb, 4, 8, 20, 2.1, 8.4, 300, 8, 28, 16, 3, 680, true, true, true, 'curated'),
  ('Rainbow Veggie Quesadillas', 'Colorful bell peppers and melted cheese packed between crispy golden tortillas make a satisfying midday meal.', 'lunch', 'Mexican', 'budget', ARRAY['budget','egg-free','kid-favorite','kid-friendly','mexican','nut-free','quick','soy-free','vegetarian','veggie-forward']::text[], '["4 large flour tortillas", "2 cups shredded Mexican blend cheese", "1 red bell pepper", "1 yellow bell pepper", "1 green bell pepper", "1 tbsp olive oil", "1/2 tsp cumin", "sour cream", "salsa"]'::jsonb, '["Thinly slice all three bell peppers.", "Saute peppers in olive oil with cumin over medium heat for 4 minutes until softened.", "Place a tortilla in a dry skillet over medium heat.", "Top half the tortilla with cheese and peppers, then fold in half.", "Cook 2-3 minutes per side until golden and cheese is melted.", "Cut into wedges and serve with sour cream and salsa."]'::jsonb, 4, 8, 12, 2.4, 9.6, 380, 15, 38, 19, 2, 620, true, true, true, 'curated'),
  ('Tuna Melt Sandwiches', 'Classic canned tuna salad piled on toasted bread and broiled with melted cheese creates an irresistible lunchtime classic.', 'lunch', 'American', 'budget', ARRAY['american','budget','high-protein','kid-friendly','nut-free','quick','sandwich','soy-free','standard']::text[], '["2 cans tuna in water", "3 tbsp mayonnaise", "1 stalk celery", "1 tbsp lemon juice", "8 slices sandwich bread", "4 slices cheddar cheese", "salt", "pepper"]'::jsonb, '["Drain tuna and combine with mayonnaise, diced celery, lemon juice, salt, and pepper.", "Toast bread slices lightly in a toaster.", "Divide tuna mixture evenly onto four bread slices.", "Top each with a slice of cheddar cheese.", "Broil open-faced on a baking sheet for 2-3 minutes until cheese is bubbly.", "Top with remaining toast slices and serve immediately."]'::jsonb, 4, 8, 5, 2.2, 8.8, 350, 24, 30, 14, 2, 740, true, true, true, 'curated'),
  ('Chicken Noodle Soup', 'Tender shredded chicken and egg noodles swim in a golden herb-scented broth loaded with carrots and celery.', 'lunch', 'Soup', 'budget', ARRAY['american','budget','comfort-food','dairy-free','high-protein','kid-friendly','nut-free','one-pot','soup','soy-free','standard']::text[], '["1 lb chicken thighs", "2 cups egg noodles", "2 carrots", "2 stalks celery", "1 onion", "3 cloves garlic", "6 cups chicken broth", "1 tsp dried thyme", "salt", "pepper"]'::jsonb, '["Place chicken thighs, broth, chopped onion, carrots, and celery in a large pot.", "Bring to a boil, then reduce heat and simmer 20 minutes.", "Remove chicken, shred with two forks, and return to the pot.", "Add garlic, thyme, salt, pepper, and egg noodles.", "Cook another 8 minutes until noodles are tender.", "Taste, adjust seasoning, and serve hot."]'::jsonb, 6, 10, 30, 2.0, 12.0, 270, 22, 24, 7, 2, 710, true, true, true, 'curated'),
  ('Grilled Cheese and Apple Stacks', 'Buttery crispy sourdough filled with melted sharp cheddar and thin apple slices strikes a perfect sweet-savory balance.', 'lunch', 'American', 'budget', ARRAY['american','budget','egg-free','kid-favorite','kid-friendly','nut-free','quick','sandwich','soy-free','vegetarian']::text[], '["8 slices sourdough bread", "8 slices sharp cheddar cheese", "2 apples", "4 tbsp butter"]'::jsonb, '["Core apples and slice them very thinly.", "Butter one side of each bread slice.", "Place bread butter-side down in a skillet over medium heat.", "Layer two slices of cheese and a few apple slices on each sandwich base.", "Top with remaining bread slices butter-side up.", "Cook 3-4 minutes per side until golden and cheese is fully melted."]'::jsonb, 4, 5, 10, 2.5, 10.0, 430, 16, 44, 22, 3, 680, true, true, true, 'curated'),
  ('Mac and Cheese with Broccoli', 'Creamy homemade cheddar sauce coats tender macaroni with bright steamed broccoli florets mixed right in.', 'lunch', 'American', 'budget', ARRAY['american','budget','comfort-food','egg-free','high-protein','kid-favorite','kid-friendly','nut-free','one-pot','soy-free','vegetarian','veggie-forward']::text[], '["2 cups elbow macaroni", "2 cups shredded cheddar cheese", "1 cup milk", "2 tbsp butter", "2 tbsp flour", "2 cups broccoli florets", "1/2 tsp mustard powder", "salt", "pepper"]'::jsonb, '["Cook macaroni according to package directions; during the last 3 minutes add broccoli florets.", "Drain pasta and broccoli and set aside.", "Melt butter in the same pot, whisk in flour, and cook 1 minute.", "Slowly pour in milk, whisking constantly until sauce thickens.", "Remove from heat and stir in cheese, mustard powder, salt, and pepper.", "Return pasta and broccoli to the pot, stir to coat, and serve."]'::jsonb, 4, 5, 18, 2.3, 9.2, 480, 21, 56, 18, 3, 520, true, true, true, 'curated'),
  ('Sheet-Pan Honey Garlic Chicken Thighs', 'Bone-in chicken thighs roasted under a sticky honey-garlic glaze become deeply caramelized and juicy in the oven.', 'dinner', 'Sheet-Pan', 'budget', ARRAY['american','budget','dairy-free','egg-free','high-protein','kid-favorite','kid-friendly','nut-free','one-pan','sheet-pan','standard']::text[], '["6 bone-in chicken thighs", "3 tbsp honey", "3 cloves garlic", "2 tbsp soy sauce", "1 tbsp olive oil", "1 tsp paprika", "salt", "pepper"]'::jsonb, '["Preheat oven to 425 degrees F and line a baking sheet with foil.", "Mix honey, minced garlic, soy sauce, olive oil, and paprika to make the glaze.", "Pat chicken dry, season with salt and pepper, and arrange on the baking sheet.", "Brush glaze generously over each piece.", "Roast 35-40 minutes until cooked through and caramelized, basting once halfway.", "Rest 5 minutes before serving."]'::jsonb, 6, 8, 40, 2.6, 15.6, 370, 28, 12, 22, 0, 560, true, true, true, 'curated'),
  ('Slow-Simmered Beef and Bean Chili', 'Ground beef and kidney beans slow-simmered with tomatoes and smoky spices build a deeply flavored bowl of comfort.', 'dinner', 'American', 'budget', ARRAY['american','budget','comfort-food','egg-free','gluten-free','high-protein','kid-friendly','meal-prep','nut-free','one-pot','soy-free','standard']::text[], '["1 lb ground beef", "2 cans kidney beans", "1 can diced tomatoes", "1 can tomato sauce", "1 onion", "3 cloves garlic", "2 tsp chili powder", "1 tsp cumin", "1 tsp paprika", "salt", "pepper", "shredded cheddar cheese"]'::jsonb, '["Brown ground beef and diced onion in a large pot over medium-high heat; drain excess fat.", "Add garlic, chili powder, cumin, and paprika; cook 1 minute.", "Stir in diced tomatoes, tomato sauce, and drained beans.", "Bring to a boil, then reduce heat and simmer 25 minutes, stirring occasionally.", "Taste and adjust seasoning.", "Serve topped with shredded cheese."]'::jsonb, 6, 10, 30, 2.4, 14.4, 380, 28, 30, 14, 9, 720, true, true, true, 'curated'),
  ('Baked Spaghetti Casserole', 'Cooked spaghetti layered with meaty tomato sauce and bubbly mozzarella creates a crowd-pleasing baked pasta dinner.', 'dinner', 'Italian', 'budget', ARRAY['baked','budget','comfort-food','egg-free','high-protein','italian','kid-favorite','kid-friendly','meal-prep','nut-free','soy-free','standard']::text[], '["12 oz spaghetti", "1 lb ground beef", "1 jar marinara sauce", "2 cups shredded mozzarella cheese", "1 onion", "2 cloves garlic", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Preheat oven to 375 degrees F and cook spaghetti until just al dente.", "Brown beef and diced onion in a skillet; drain fat and add garlic.", "Stir in marinara sauce and Italian seasoning; simmer 5 minutes.", "Combine meat sauce with drained spaghetti and transfer to a 9x13 baking dish.", "Top evenly with mozzarella cheese.", "Bake 20 minutes until cheese is golden and bubbling."]'::jsonb, 6, 15, 30, 2.5, 15.0, 490, 30, 52, 16, 3, 680, true, true, true, 'curated'),
  ('Black Bean Tacos with Corn Salsa', 'Seasoned black beans tucked into warm corn tortillas and topped with a bright corn and tomato salsa deliver bold flavor fast.', 'dinner', 'Mexican', 'ultra_budget', ARRAY['budget','egg-free','gluten-free','kid-friendly','mexican','nut-free','one-pan','quick','soy-free','vegetarian','veggie-forward']::text[], '["2 cans black beans", "8 corn tortillas", "1 cup corn kernels", "1 tomato", "1/2 onion", "1 lime", "1 tsp cumin", "1 tsp chili powder", "1 tbsp olive oil", "salt", "shredded cheddar cheese"]'::jsonb, '["Drain and rinse beans, then saute in olive oil with cumin and chili powder for 4 minutes.", "Lightly mash beans with a fork, leaving some texture.", "Combine corn, diced tomato, diced onion, lime juice, and a pinch of salt for the salsa.", "Warm tortillas directly over a gas flame or in a dry skillet.", "Fill each tortilla with beans, corn salsa, and a sprinkle of cheddar cheese."]'::jsonb, 4, 10, 8, 1.4, 5.6, 340, 14, 56, 7, 11, 490, true, true, true, 'curated'),
  ('Teriyaki Salmon with Steamed Rice', 'Salmon fillets glazed in a sweet teriyaki sauce pan-sear to a caramelized finish and pair perfectly with fluffy steamed rice.', 'dinner', 'Asian', 'standard', ARRAY['asian','dairy-free','egg-free','high-protein','kid-friendly','nut-free','quick','standard','stove-top']::text[], '["4 salmon fillets", "3 tbsp soy sauce", "2 tbsp honey", "1 tsp minced ginger", "2 cloves garlic", "1 tbsp vegetable oil", "2 cups white rice", "4 cups water", "sesame seeds"]'::jsonb, '["Cook rice by combining with water in a pot, bringing to a boil, then simmering covered 18 minutes.", "Mix soy sauce, honey, minced ginger, and garlic to make teriyaki glaze.", "Heat oil in a skillet over medium-high heat and sear salmon skin-side down 4 minutes.", "Flip salmon, pour glaze over the top, and cook another 3-4 minutes until cooked through.", "Serve salmon over steamed rice and drizzle remaining glaze from the pan on top.", "Garnish with sesame seeds."]'::jsonb, 4, 8, 25, 4.2, 16.8, 490, 36, 50, 12, 1, 780, true, true, true, 'curated'),
  ('Cheesy Stuffed Bell Peppers', 'Halved bell peppers filled with seasoned ground beef, rice, and marinara then baked under a blanket of melted mozzarella.', 'dinner', 'American', 'budget', ARRAY['american','baked','budget','comfort-food','egg-free','gluten-free','high-protein','kid-friendly','nut-free','soy-free','standard']::text[], '["4 bell peppers", "1 lb ground beef", "1 cup cooked white rice", "1 cup marinara sauce", "1 cup shredded mozzarella cheese", "1 onion", "2 cloves garlic", "1 tsp Italian seasoning", "salt", "pepper"]'::jsonb, '["Preheat oven to 375 degrees F. Halve peppers lengthwise and remove seeds.", "Brown beef and diced onion; drain fat, then add garlic and Italian seasoning.", "Stir in cooked rice and marinara sauce; season with salt and pepper.", "Arrange pepper halves in a baking dish and fill each with beef mixture.", "Top with shredded mozzarella and cover with foil.", "Bake 30 minutes, remove foil, and bake another 10 minutes until cheese is bubbly."]'::jsonb, 4, 15, 40, 2.9, 11.6, 420, 30, 28, 19, 3, 620, true, true, true, 'curated'),
  ('Shrimp Stir-Fry with Snap Peas', 'Plump shrimp and crisp snap peas are tossed in a savory ginger-soy sauce over steaming jasmine rice.', 'dinner', 'Stir-Fry', 'standard', ARRAY['asian','dairy-free','egg-free','high-protein','kid-friendly','nut-free','quick','standard','stir-fry']::text[], '["1 lb frozen shrimp", "2 cups snap peas", "2 cups jasmine rice", "3 tbsp soy sauce", "1 tbsp sesame oil", "2 cloves garlic", "1 tsp fresh ginger", "1 tbsp vegetable oil", "1 tsp cornstarch", "2 tbsp water"]'::jsonb, '["Cook jasmine rice according to package directions.", "Thaw shrimp, pat dry, and toss with a pinch of salt.", "Stir together soy sauce, sesame oil, garlic, ginger, cornstarch, and water for sauce.", "Heat vegetable oil in a large wok or skillet over high heat.", "Stir-fry shrimp 2 minutes until pink, then add snap peas and stir-fry 2 more minutes.", "Pour sauce over everything, toss to coat, and serve immediately over rice."]'::jsonb, 4, 10, 20, 3.8, 15.2, 380, 28, 46, 7, 2, 840, true, true, true, 'curated'),
  ('Chicken and Vegetable Fried Rice', 'Day-old rice stir-fried with tender chicken, eggs, and colorful mixed vegetables in a savory soy-sesame sauce.', 'dinner', 'Stir-Fry', 'budget', ARRAY['asian','budget','dairy-free','high-protein','kid-favorite','kid-friendly','meal-prep','nut-free','one-pan','standard','stir-fry']::text[], '["2 cups cooked white rice", "1 lb chicken breast", "3 eggs", "1 cup frozen mixed vegetables", "3 tbsp soy sauce", "1 tbsp sesame oil", "2 cloves garlic", "2 tbsp vegetable oil", "2 green onions", "pepper"]'::jsonb, '["Dice chicken breast into small cubes and season with pepper.", "Heat oil in a large wok over high heat and cook chicken until golden; remove and set aside.", "Scramble eggs in the same pan until just set; push to the side.", "Add garlic and frozen vegetables; stir-fry 2 minutes.", "Add day-old rice and toss everything together with soy sauce and sesame oil.", "Return chicken, mix thoroughly, and garnish with sliced green onions."]'::jsonb, 4, 10, 15, 2.7, 10.8, 420, 32, 40, 13, 2, 760, true, true, true, 'curated'),
  ('Creamy Potato and Corn Chowder', 'Chunky diced potatoes and sweet corn simmer in a rich buttery broth until thick, warming, and deeply satisfying.', 'dinner', 'Soup', 'ultra_budget', ARRAY['american','budget','comfort-food','egg-free','kid-friendly','nut-free','one-pot','soup','soy-free','standard','veggie-forward']::text[], '["4 medium potatoes", "2 cups corn kernels", "1 onion", "3 cups chicken broth", "1 cup milk", "3 tbsp butter", "2 tbsp flour", "2 cloves garlic", "salt", "pepper", "shredded cheddar cheese"]'::jsonb, '["Peel and dice potatoes into small cubes; dice onion.", "Melt butter in a large pot, saute onion and garlic 3 minutes.", "Whisk in flour and cook 1 minute, then pour in broth and add potatoes.", "Bring to a boil and simmer 15 minutes until potatoes are tender.", "Stir in corn and milk; simmer 5 more minutes.", "Season with salt and pepper and serve topped with cheddar."]'::jsonb, 6, 10, 25, 1.3, 7.8, 280, 8, 40, 9, 3, 590, true, true, true, 'curated'),
  ('Pasta with Butter and Parmesan', 'Silky hot pasta tossed simply with good butter and freshly grated Parmesan proves the most comforting of all pantry dinners.', 'dinner', 'Italian', 'ultra_budget', ARRAY['budget','egg-free','italian','kid-favorite','kid-friendly','nut-free','quick','soy-free','vegetarian']::text[], '["12 oz spaghetti", "4 tbsp butter", "1 cup grated Parmesan cheese", "2 cloves garlic", "salt", "pepper", "fresh parsley"]'::jsonb, '["Boil a large pot of salted water and cook spaghetti until al dente.", "Reserve 1 cup of pasta water before draining.", "Melt butter in the empty pot over low heat and add minced garlic for 1 minute.", "Return drained pasta to the pot and toss with butter.", "Add Parmesan and a splash of pasta water, tossing until a glossy sauce forms.", "Season with black pepper and serve garnished with parsley."]'::jsonb, 4, 5, 12, 1.2, 4.8, 460, 17, 64, 15, 2, 450, true, true, true, 'curated'),
  ('Crispy Baked Fish Sticks', 'Flaky white fish coated in seasoned panko breadcrumbs bake up perfectly crunchy without a drop of frying oil.', 'dinner', 'American', 'budget', ARRAY['american','baked','budget','dairy-free','high-protein','kid-favorite','kid-friendly','nut-free','soy-free','standard']::text[], '["1 lb tilapia fillets", "1 cup panko breadcrumbs", "1/2 cup flour", "2 eggs", "1 tsp garlic powder", "1 tsp paprika", "salt", "pepper", "cooking spray", "ketchup"]'::jsonb, '["Preheat oven to 425 degrees F and coat a baking sheet with cooking spray.", "Cut tilapia into finger-shaped strips.", "Set up three bowls: flour, beaten eggs, and panko mixed with garlic powder and paprika.", "Dredge each fish strip in flour, then egg, then press into seasoned panko.", "Arrange on the baking sheet and spray lightly with cooking spray.", "Bake 14-16 minutes until golden and crunchy, serving with ketchup."]'::jsonb, 4, 12, 16, 2.6, 10.4, 320, 28, 30, 7, 1, 420, true, true, true, 'curated'),
  ('Apple Slices with Peanut Butter Dip', 'Crisp apple wedges are paired with a creamy honey-peanut butter dip for a quick and naturally sweet afternoon snack.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','egg-free','gluten-free','kid-favorite','kid-friendly','no-cook','quick','soy-free','sweet','vegetarian']::text[], '["3 apples", "1/2 cup peanut butter", "2 tbsp honey", "1 tsp cinnamon"]'::jsonb, '["Core apples and slice into wedges.", "Stir together peanut butter, honey, and cinnamon until smooth.", "Arrange apple slices on a plate and serve with dip on the side."]'::jsonb, 4, 5, 0, 0.9, 3.6, 220, 7, 28, 10, 4, 90, true, true, true, 'curated'),
  ('Mini Caprese Skewers', 'Cherry tomatoes, fresh mozzarella balls, and basil leaves threaded onto toothpicks and drizzled with balsamic glaze.', 'snack', 'Italian', 'budget', ARRAY['budget','egg-free','gluten-free','italian','kid-friendly','no-cook','nut-free','quick','soy-free','vegetarian','veggie-forward']::text[], '["1 cup cherry tomatoes", "8 oz fresh mozzarella balls", "1/4 cup fresh basil leaves", "2 tbsp balsamic glaze", "1 tbsp olive oil", "salt", "pepper"]'::jsonb, '["Rinse cherry tomatoes and basil leaves.", "Thread one cherry tomato, one basil leaf folded, and one mozzarella ball onto each toothpick.", "Arrange skewers on a platter.", "Drizzle with olive oil and balsamic glaze and season with a pinch of salt and pepper."]'::jsonb, 4, 10, 0, 2.2, 8.8, 170, 10, 7, 11, 1, 260, true, true, true, 'curated'),
  ('Homemade Cinnamon Applesauce', 'Tender cooked apples blended into a smooth, lightly spiced sauce that is far tastier than anything from a jar.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','kid-favorite','kid-friendly','make-ahead','nut-free','soy-free','sweet','vegan','vegetarian']::text[], '["6 apples", "1/4 cup water", "2 tbsp sugar", "1 tsp cinnamon", "1 tbsp lemon juice"]'::jsonb, '["Peel, core, and chop apples into chunks.", "Combine apples, water, sugar, and cinnamon in a saucepan over medium heat.", "Cover and cook 15 minutes, stirring occasionally, until apples are very soft.", "Remove from heat, stir in lemon juice, and mash or blend to desired consistency.", "Serve warm or refrigerate and serve cold."]'::jsonb, 6, 8, 15, 0.6, 3.6, 110, 0, 28, 0, 3, 2, true, true, true, 'curated'),
  ('Cheese and Crackers Snack Board', 'Sliced cheddar and Colby Jack arranged with buttery crackers and a handful of grapes makes an effortless nibble plate.', 'snack', 'American', 'budget', ARRAY['american','budget','egg-free','gluten-free','kid-favorite','kid-friendly','no-cook','nut-free','quick','soy-free','standard']::text[], '["4 oz cheddar cheese", "4 oz Colby Jack cheese", "1 pkg butter crackers", "1 cup grapes", "1/4 cup sliced deli turkey"]'::jsonb, '["Slice cheeses into bite-sized squares or rectangles.", "Rinse and separate grapes into small clusters.", "Arrange crackers, cheese slices, grapes, and turkey on a large plate or wooden board.", "Serve immediately or cover and refrigerate until ready to eat."]'::jsonb, 4, 8, 0, 2.0, 8.0, 280, 14, 24, 14, 1, 480, true, true, true, 'curated'),
  ('Popcorn Trail Mix', 'Air-popped popcorn tossed with pretzels, raisins, and a drizzle of honey makes a crunchy sweet-salty snack mix kids love.', 'snack', 'American', 'ultra_budget', ARRAY['american','budget','dairy-free','egg-free','gluten-free','kid-favorite','kid-friendly','no-cook','nut-free','salty','soy-free','sweet','vegetarian']::text[], '["4 cups popped popcorn", "1 cup mini pretzels", "1/2 cup raisins", "2 tbsp honey", "1/4 tsp cinnamon"]'::jsonb, '["Pop popcorn and let cool completely.", "Combine popcorn, pretzels, and raisins in a large bowl.", "Warm honey slightly in the microwave for 15 seconds.", "Drizzle honey and sprinkle cinnamon over the mix.", "Toss gently to coat everything and serve in individual cups."]'::jsonb, 4, 5, 3, 0.7, 2.8, 160, 3, 34, 2, 2, 210, true, true, true, 'curated'),
  ('Baked Cinnamon Sugar Tortilla Chips', 'Flour tortillas brushed with butter and dusted with cinnamon sugar bake into crisp chips perfect for dipping or snacking.', 'snack', 'Mexican', 'ultra_budget', ARRAY['baked','budget','egg-free','kid-favorite','kid-friendly','mexican','nut-free','quick','soy-free','sweet','vegetarian']::text[], '["4 flour tortillas", "2 tbsp butter", "2 tbsp sugar", "1 tsp cinnamon", "applesauce"]'::jsonb, '["Preheat oven to 375 degrees F.", "Melt butter and brush one side of each tortilla.", "Mix sugar and cinnamon together and sprinkle over the buttered side.", "Cut each tortilla into eight triangles and arrange on a baking sheet.", "Bake 8-10 minutes until crispy and golden.", "Serve with applesauce for dipping."]'::jsonb, 4, 5, 10, 0.65, 2.6, 190, 3, 30, 6, 1, 230, true, true, true, 'curated'),
  ('Cajun Dirty Rice with Andouille Sausage', 'A spicy Louisiana classic made with andouille sausage, ground beef, and long-grain rice cooked with the holy trinity of onion, bell pepper, and celery.', 'dinner', 'Cajun', 'budget', ARRAY['budget','cajun','dairy-free','egg-free','gluten-free','high-protein','nut-free','one-pot','southern','soy-free','spicy','standard']::text[], '["1 lb andouille sausage, sliced", "0.5 lb ground beef", "2 cups long-grain white rice", "4 cups chicken broth", "1 onion, diced", "1 green bell pepper, diced", "3 stalks celery, diced", "3 cloves garlic, minced", "1 tsp Cajun seasoning", "0.5 tsp thyme", "2 tbsp vegetable oil", "salt and pepper to taste"]'::jsonb, '["Heat oil in a large pot over medium-high heat; brown sausage slices and ground beef, then drain excess fat.", "Add onion, bell pepper, celery, and garlic to the pot and cook until softened, about 5 minutes.", "Stir in Cajun seasoning and thyme, then add rice and toast for 1 minute.", "Pour in chicken broth, bring to a boil, then reduce heat, cover, and simmer 18 minutes until rice is tender.", "Fluff with a fork, adjust seasoning, and serve hot."]'::jsonb, 6, 10, 30, 2.4, 14.4, 520, 28, 48, 20, 2, 890, false, true, true, 'curated'),
  ('Honey Garlic Baked Chicken Thighs', 'Bone-in chicken thighs glazed with a sticky honey-garlic sauce and baked until golden with crispy skin.', 'dinner', 'American', 'budget', ARRAY['american','baked','budget','dairy-free','easy','egg-free','family-friendly','high-protein','kid-friendly','nut-free','standard']::text[], '["4 bone-in chicken thighs", "3 tbsp honey", "4 cloves garlic, minced", "2 tbsp soy sauce", "1 tbsp vegetable oil", "1 tsp paprika", "salt and pepper to taste", "fresh parsley for garnish"]'::jsonb, '["Preheat oven to 400\u00b0F; mix honey, garlic, soy sauce, oil, and paprika into a glaze.", "Season chicken thighs with salt and pepper, then coat generously with the honey-garlic glaze.", "Place thighs skin-side up in a baking dish and bake 35-40 minutes until internal temp reaches 165\u00b0F.", "Baste with pan juices halfway through cooking for extra caramelization.", "Let rest 5 minutes, garnish with parsley, and serve."]'::jsonb, 4, 10, 40, 2.1, 8.4, 380, 30, 14, 22, 0, 620, true, true, true, 'curated'),
  ('Beef and Broccoli Lo Mein', 'Tender strips of beef and crisp broccoli tossed with egg noodles in a savory oyster-soy sauce — a better-than-takeout weeknight dinner.', 'dinner', 'Chinese', 'budget', ARRAY['budget','chinese','dairy-free','high-protein','kid-friendly','noodles','nut-free','standard','stir-fry','takeout-style']::text[], '["1 lb beef sirloin, thinly sliced", "8 oz lo mein noodles", "3 cups broccoli florets", "3 tbsp soy sauce", "2 tbsp oyster sauce", "1 tbsp cornstarch", "3 cloves garlic, minced", "1 tsp sesame oil", "2 tbsp vegetable oil", "1 tsp sugar", "0.5 tsp ginger powder"]'::jsonb, '["Toss sliced beef with cornstarch, 1 tbsp soy sauce, and ginger; let marinate 10 minutes.", "Cook lo mein noodles per package directions, then drain and set aside.", "Heat oil in a large skillet or wok over high heat; sear beef 2-3 minutes and remove.", "Add broccoli to the same pan and stir-fry 3 minutes; add garlic and cook 30 seconds.", "Return beef to pan, add noodles, remaining soy sauce, oyster sauce, sugar, and sesame oil; toss everything together and serve hot."]'::jsonb, 4, 15, 20, 2.9, 11.6, 490, 32, 52, 14, 3, 980, true, true, true, 'curated'),
  ('Smothered Pork Chops with Onion Gravy', 'Pan-seared bone-in pork chops braised in a rich caramelized onion gravy until fall-apart tender, served over mashed potatoes.', 'dinner', 'Southern', 'budget', ARRAY['budget','comfort-food','egg-free','gravy','high-protein','kid-friendly','nut-free','pork','southern','soy-free','standard']::text[], '["4 bone-in pork chops", "2 large onions, sliced", "2 cups chicken broth", "0.25 cup all-purpose flour", "2 tbsp vegetable oil", "1 tsp garlic powder", "1 tsp onion powder", "0.5 tsp paprika", "salt and pepper to taste", "1 tbsp butter"]'::jsonb, '["Season pork chops with garlic powder, onion powder, paprika, salt, and pepper; dredge lightly in flour.", "Heat oil in a large skillet over medium-high heat; sear chops 3 minutes per side until browned, then remove.", "In the same pan, melt butter and cook onions over medium heat, stirring occasionally, until deeply caramelized, about 15 minutes.", "Whisk in 2 tbsp flour, then gradually add chicken broth, scraping up browned bits; bring to a simmer.", "Return pork chops to the pan, cover, and simmer on low heat 20-25 minutes until tender; serve over mashed potatoes."]'::jsonb, 4, 10, 45, 2.7, 10.8, 430, 34, 18, 24, 1, 720, true, true, true, 'curated'),
  ('Turkey Taco Stuffed Bell Peppers', 'Colorful bell peppers filled with seasoned ground turkey, black beans, corn, and melted cheese for a satisfying weeknight meal.', 'dinner', 'Mexican', 'budget', ARRAY['baked','budget','egg-free','family-friendly','gluten-free','high-protein','kid-friendly','mexican','nut-free','soy-free','standard','turkey']::text[], '["1 lb ground turkey", "4 large bell peppers, halved and seeded", "1 can black beans, drained", "1 cup frozen corn", "1 can diced tomatoes with green chiles", "1 packet taco seasoning", "1 cup shredded cheddar cheese", "1 small onion, diced", "1 tbsp vegetable oil"]'::jsonb, '["Preheat oven to 375\u00b0F; place pepper halves cut-side up in a baking dish.", "Cook onion in oil over medium heat 3 minutes; add turkey and brown, breaking it up.", "Stir in taco seasoning, diced tomatoes, black beans, and corn; simmer 5 minutes.", "Fill each pepper half with the turkey mixture and top with shredded cheese.", "Bake 25-30 minutes until peppers are tender and cheese is bubbly; serve hot."]'::jsonb, 4, 15, 35, 2.8, 11.2, 420, 36, 32, 14, 8, 850, true, true, true, 'curated'),
  ('Spicy Sausage and Potato Hash Skillet', 'A hearty one-pan breakfast of spicy pork sausage, crispy diced potatoes, peppers, and onions topped with fried eggs.', 'breakfast', 'American', 'budget', ARRAY['american','breakfast','budget','dairy-free','gluten-free','high-protein','nut-free','one-pan','skillet','soy-free','standard']::text[], '["0.5 lb pork breakfast sausage, crumbled", "3 medium russet potatoes, diced small", "1 red bell pepper, diced", "1 onion, diced", "4 eggs", "2 tbsp vegetable oil", "0.5 tsp paprika", "0.5 tsp garlic powder", "red pepper flakes to taste", "salt and pepper to taste"]'::jsonb, '["Heat oil in a large cast-iron skillet over medium-high heat; cook diced potatoes 12-15 minutes, stirring occasionally, until golden and crispy.", "Push potatoes to the sides and brown sausage in the center, breaking it up, about 5 minutes.", "Add bell pepper and onion; cook 4 minutes until softened; mix everything together with paprika and garlic powder.", "Make 4 wells in the hash and crack an egg into each well.", "Cover and cook 3-4 minutes until egg whites are set but yolks are still runny; season and serve straight from the skillet."]'::jsonb, 4, 10, 25, 1.9, 7.6, 440, 24, 38, 22, 3, 680, false, true, true, 'curated'),
  ('Creamy Tuscan White Bean Chicken', 'Pan-seared chicken breasts simmered in a creamy sun-dried tomato and cannellini bean sauce with fresh spinach and Italian herbs.', 'dinner', 'Italian', 'standard', ARRAY['creamy','egg-free','gluten-free','high-protein','italian','kid-friendly','mediterranean','nut-free','one-pan','soy-free','standard']::text[], '["4 boneless chicken breasts", "1 can cannellini beans, drained", "0.5 cup sun-dried tomatoes, chopped", "2 cups baby spinach", "0.5 cup heavy cream", "3 cloves garlic, minced", "1 cup chicken broth", "1 tsp Italian seasoning", "0.25 cup Parmesan cheese, grated", "2 tbsp olive oil", "salt and pepper to taste"]'::jsonb, '["Season chicken with Italian seasoning, salt, and pepper; sear in olive oil over medium-high heat 5 minutes per side until golden.", "Remove chicken and cook garlic and sun-dried tomatoes in the same pan for 1 minute.", "Pour in chicken broth and heavy cream; bring to a simmer and stir in Parmesan.", "Add beans and spinach; stir until spinach wilts, about 2 minutes.", "Return chicken to the pan and simmer 5 minutes until cooked through; serve with crusty bread."]'::jsonb, 4, 10, 25, 3.8, 15.2, 480, 42, 24, 22, 6, 740, true, true, true, 'curated'),
  ('BBQ Pulled Pork Shoulder in Slow Cooker', 'A pork shoulder slow-cooked all day with smoky BBQ sauce until it shreds effortlessly, perfect piled high on toasted buns.', 'dinner', 'BBQ', 'budget', ARRAY['bbq','budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','pork','slow-cooker','soy-free','standard']::text[], '["3 lb pork shoulder", "1.5 cups BBQ sauce", "1 onion, sliced", "3 cloves garlic, minced", "1 tbsp brown sugar", "1 tsp paprika", "1 tsp garlic powder", "1 tsp onion powder", "0.5 tsp cumin", "salt and pepper to taste", "6 hamburger buns"]'::jsonb, '["Mix paprika, garlic powder, onion powder, cumin, brown sugar, salt, and pepper; rub all over pork shoulder.", "Place sliced onions and garlic in the slow cooker and set rubbed pork on top.", "Pour 1 cup BBQ sauce over the pork; cook on low 8-10 hours or high 5-6 hours until fork-tender.", "Remove pork and shred with two forks; discard excess cooking liquid but keep some for moisture.", "Return shredded pork to slow cooker, stir in remaining BBQ sauce, and serve on toasted buns."]'::jsonb, 6, 10, 480, 2.5, 15.0, 540, 38, 44, 20, 1, 880, true, true, true, 'curated'),
  ('Ground Beef Enchiladas with Red Sauce', 'Corn tortillas stuffed with seasoned ground beef and cheese, rolled and smothered in homemade red enchilada sauce with melted cheese on top.', 'dinner', 'Mexican', 'budget', ARRAY['baked','beef','budget','comfort-food','egg-free','family-friendly','gluten-free','high-protein','kid-friendly','mexican','nut-free','soy-free','standard']::text[], '["1 lb ground beef", "10 corn tortillas", "2 cups red enchilada sauce", "1.5 cups shredded Mexican cheese blend", "1 small onion, diced", "2 cloves garlic, minced", "1 tsp cumin", "1 tsp chili powder", "salt to taste", "sour cream and cilantro for serving"]'::jsonb, '["Preheat oven to 375\u00b0F; cook ground beef with onion and garlic over medium heat until browned; drain fat.", "Season beef with cumin, chili powder, and salt; stir in 0.25 cup enchilada sauce.", "Warm tortillas to make them pliable; fill each with beef mixture and a sprinkle of cheese; roll tightly.", "Place rolled enchiladas seam-side down in a greased baking dish; pour remaining sauce over the top and sprinkle with remaining cheese.", "Bake 20-25 minutes until cheese is melted and bubbly; serve with sour cream and cilantro."]'::jsonb, 5, 20, 30, 2.3, 11.5, 460, 28, 38, 20, 4, 820, true, true, true, 'curated'),
  ('Crispy Panko Tilapia Tacos with Slaw', 'Panko-breaded tilapia fillets fried golden and served in warm corn tortillas with a crunchy lime cabbage slaw and chipotle crema.', 'dinner', 'Mexican', 'budget', ARRAY['budget','crispy','fish','high-protein','kid-friendly','mexican','nut-free','seafood','soy-free','standard','tacos']::text[], '["1 lb tilapia fillets", "1 cup panko breadcrumbs", "2 eggs, beaten", "0.25 cup all-purpose flour", "8 corn tortillas", "2 cups shredded cabbage", "1 lime", "0.25 cup sour cream", "1 tbsp hot sauce", "0.5 tsp cumin", "2 tbsp vegetable oil", "salt and pepper to taste"]'::jsonb, '["Cut tilapia into strips; season with cumin, salt, and pepper; dredge in flour, dip in egg, then coat with panko.", "Fry fish strips in hot oil over medium-high heat 3-4 minutes per side until golden and cooked through; drain on paper towels.", "Toss shredded cabbage with lime juice and a pinch of salt to make the slaw.", "Mix sour cream with hot sauce to make chipotle crema.", "Warm tortillas and build tacos with fish strips, slaw, and a drizzle of crema."]'::jsonb, 4, 20, 15, 2.6, 10.4, 390, 28, 42, 12, 3, 580, true, true, true, 'curated'),
  ('Italian Sausage and Pepper Hoagies', 'Sweet Italian sausage links simmered with sauteed peppers and onions in marinara, piled into toasted hoagie rolls with melted provolone.', 'lunch', 'Italian', 'budget', ARRAY['budget','comfort-food','egg-free','gluten-free','high-protein','italian','kid-friendly','nut-free','pork','sandwiches','sausage','soy-free','standard']::text[], '["4 Italian sausage links", "2 bell peppers, sliced", "1 large onion, sliced", "1 cup marinara sauce", "4 hoagie rolls", "4 slices provolone cheese", "2 tbsp olive oil", "2 cloves garlic, minced", "0.5 tsp Italian seasoning", "salt and pepper to taste"]'::jsonb, '["Cook sausage links in a large skillet over medium heat, turning occasionally, until browned and cooked through, about 15 minutes; slice on the bias.", "In the same pan, heat olive oil and saute peppers, onion, and garlic until tender and slightly caramelized, about 10 minutes.", "Add marinara and Italian seasoning; simmer 5 minutes; return sliced sausage to the pan.", "Toast hoagie rolls and top with the sausage and pepper mixture; lay provolone on top.", "Broil 1-2 minutes until cheese melts; serve immediately."]'::jsonb, 4, 10, 30, 2.8, 11.2, 580, 26, 52, 28, 3, 1100, true, true, true, 'curated'),
  ('Sheet Pan Lemon Herb Salmon with Asparagus', 'Salmon fillets roasted alongside fresh asparagus with lemon zest, dill, and garlic on one sheet pan for an easy elegant dinner.', 'dinner', 'Mediterranean', 'standard', ARRAY['dairy-free','egg-free','fish','gluten-free','high-protein','kid-friendly','mediterranean','nut-free','seafood','sheet-pan','soy-free','standard']::text[], '["4 salmon fillets (6 oz each)", "1 lb asparagus, trimmed", "2 lemons", "3 cloves garlic, minced", "2 tbsp olive oil", "1 tsp dried dill", "0.5 tsp paprika", "salt and pepper to taste", "fresh parsley for garnish"]'::jsonb, '["Preheat oven to 400\u00b0F and line a sheet pan with foil; toss asparagus with 1 tbsp olive oil, salt, and pepper.", "Place salmon fillets on the sheet pan with the asparagus; mix remaining olive oil, garlic, dill, paprika, and juice of one lemon.", "Spoon the herb mixture over the salmon fillets and lay lemon slices on top.", "Roast 12-15 minutes until salmon flakes easily and asparagus is tender-crisp.", "Garnish with fresh parsley and serve with remaining lemon wedges."]'::jsonb, 4, 10, 15, 4.5, 18.0, 380, 40, 8, 20, 3, 420, true, true, true, 'curated'),
  ('Beef and Black Bean Burrito Bowl', 'Seasoned ground beef over cilantro-lime rice with black beans, corn, pico de gallo, and sour cream for a customizable bowl.', 'dinner', 'Mexican', 'budget', ARRAY['beef','bowl','budget','egg-free','family-friendly','gluten-free','high-protein','kid-friendly','mexican','nut-free','soy-free','standard']::text[], '["1 lb ground beef", "2 cups white rice", "1 can black beans, drained", "1 cup frozen corn", "1 packet taco seasoning", "4 cups water", "1 lime", "0.25 cup cilantro, chopped", "1 cup salsa", "0.5 cup sour cream", "1 cup shredded cheddar cheese"]'::jsonb, '["Cook rice in water per package directions; stir in lime juice and cilantro when done.", "Brown ground beef over medium-high heat, drain fat, and add taco seasoning with 0.25 cup water; simmer 3 minutes.", "Warm black beans in a small pot and heat corn in the microwave or a skillet.", "Assemble bowls with rice as the base, then top with seasoned beef, beans, corn, and salsa.", "Finish with shredded cheese and a dollop of sour cream; serve immediately."]'::jsonb, 4, 10, 25, 2.4, 9.6, 620, 38, 68, 18, 8, 920, true, true, true, 'curated'),
  ('Classic Southern Fried Chicken Drumsticks', 'Buttermilk-marinated chicken drumsticks seasoned with a blend of Southern spices and fried to a shatteringly crispy golden crust.', 'dinner', 'Southern', 'budget', ARRAY['budget','chicken','comfort-food','dairy-free','egg-free','fried','high-protein','kid-friendly','nut-free','southern','soy-free','standard']::text[], '["8 chicken drumsticks", "1 cup buttermilk", "1.5 cups all-purpose flour", "1 tsp paprika", "1 tsp garlic powder", "1 tsp onion powder", "0.5 tsp cayenne pepper", "1 tsp salt", "0.5 tsp black pepper", "vegetable oil for frying"]'::jsonb, '["Marinate drumsticks in buttermilk for at least 1 hour or overnight in the refrigerator.", "Mix flour with all spices in a shallow dish; remove chicken from buttermilk and dredge in seasoned flour.", "Heat 2 inches of oil in a deep skillet to 350\u00b0F; fry chicken in batches 12-15 minutes, turning occasionally, until golden and internal temp reaches 165\u00b0F.", "Drain on a wire rack over a sheet pan to keep the crust crispy.", "Rest 5 minutes before serving with hot sauce and coleslaw."]'::jsonb, 4, 10, 30, 2.0, 8.0, 510, 36, 30, 26, 1, 780, true, true, true, 'curated'),
  ('Kielbasa and Sauerkraut with Roasted Potatoes', 'Sliced smoked kielbasa braised with tangy sauerkraut and served alongside crispy roasted potatoes seasoned with caraway and mustard.', 'dinner', 'Eastern European', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','eastern-european','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pan','sausage','soy-free','vegan','vegetarian']::text[], '["1 lb smoked kielbasa, sliced", "1 can sauerkraut, drained", "4 medium potatoes, cubed", "1 onion, sliced", "2 tbsp vegetable oil", "1 tbsp whole-grain mustard", "0.5 tsp caraway seeds", "1 tbsp brown sugar", "salt and pepper to taste"]'::jsonb, '["Preheat oven to 400\u00b0F; toss potato cubes with 1 tbsp oil, salt, pepper, and caraway seeds; spread on a sheet pan and roast 25-30 minutes until golden.", "Meanwhile, cook kielbasa and onion in remaining oil in a large skillet over medium-high heat until browned, about 8 minutes.", "Add sauerkraut, mustard, and brown sugar to the skillet; stir to combine and cook 5 minutes until heated through.", "Serve kielbasa mixture alongside the roasted potatoes."]'::jsonb, 4, 10, 30, 1.4, 5.6, 480, 22, 42, 24, 5, 1200, true, true, true, 'curated'),
  ('Thai Peanut Ground Pork Noodles', 'Ground pork stir-fried with rice noodles, crunchy cabbage, and a bold peanut-lime sauce with a hit of chili and fish sauce.', 'dinner', 'Thai', 'budget', ARRAY['asian','budget','egg-free','high-protein','noodles','pork','spicy','standard','thai']::text[], '["1 lb ground pork", "8 oz rice noodles", "2 cups shredded cabbage", "2 cloves garlic, minced", "3 tbsp peanut butter", "2 tbsp soy sauce", "1 tbsp fish sauce", "1 lime, juiced", "1 tsp chili garlic sauce", "1 tbsp vegetable oil", "green onions and peanuts for garnish"]'::jsonb, '["Soak rice noodles in hot water per package directions until tender; drain.", "Whisk together peanut butter, soy sauce, fish sauce, lime juice, and chili garlic sauce with 2 tbsp warm water to make sauce.", "Cook ground pork in oil over medium-high heat, breaking it up, until cooked through; add garlic and cook 1 minute.", "Add cabbage and toss 2 minutes; add drained noodles and peanut sauce; toss everything together over high heat until well coated.", "Serve topped with chopped green onions and crushed peanuts."]'::jsonb, 4, 15, 15, 2.7, 10.8, 530, 30, 50, 22, 3, 980, false, true, true, 'curated'),
  ('Chicken and Sausage Jambalaya', 'A classic one-pot Cajun rice dish with chicken thighs, smoked sausage, the holy trinity of vegetables, and Creole spices.', 'dinner', 'Cajun', 'budget', ARRAY['budget','cajun','dairy-free','egg-free','gluten-free','high-protein','nut-free','one-pot','rice','southern','soy-free','standard']::text[], '["1 lb chicken thighs, boneless, cubed", "0.5 lb smoked sausage, sliced", "2 cups long-grain white rice", "1 can diced tomatoes", "3 cups chicken broth", "1 onion, diced", "1 green bell pepper, diced", "3 stalks celery, diced", "3 cloves garlic, minced", "1.5 tsp Cajun seasoning", "0.5 tsp thyme", "2 tbsp vegetable oil"]'::jsonb, '["Heat oil in a large heavy pot over medium-high heat; brown chicken and sausage in batches and remove.", "Add onion, bell pepper, celery, and garlic to the pot; cook 5 minutes until softened.", "Stir in Cajun seasoning and thyme; add diced tomatoes and cook 2 minutes.", "Return meat to the pot; add rice and chicken broth; bring to a boil, then reduce to low, cover, and cook 20 minutes.", "Remove from heat and let steam 5 minutes, then fluff with a fork and serve."]'::jsonb, 6, 15, 35, 2.6, 15.6, 550, 34, 56, 18, 3, 920, false, true, true, 'curated'),
  ('Mediterranean Beef Kofta with Tzatziki', 'Spiced ground beef kofta skewers flavored with cumin, coriander, and fresh herbs, served with cool cucumber tzatziki and warm pita.', 'dinner', 'Mediterranean', 'budget', ARRAY['beef','budget','egg-free','gluten-free','grilled','high-protein','kid-friendly','mediterranean','middle-eastern','nut-free','soy-free','standard']::text[], '["1 lb ground beef", "0.5 onion, grated", "3 cloves garlic, minced", "1 tsp cumin", "1 tsp coriander", "0.5 tsp paprika", "0.25 cup fresh parsley, chopped", "1 cup Greek yogurt", "0.5 cucumber, grated and squeezed dry", "1 clove garlic, grated (for tzatziki)", "1 tbsp lemon juice", "4 pita breads", "salt and pepper to taste"]'::jsonb, '["Combine ground beef, grated onion, minced garlic, cumin, coriander, paprika, parsley, salt, and pepper; mix well.", "Divide into 8 portions and shape each around a skewer into a log shape; refrigerate 15 minutes.", "Make tzatziki by combining yogurt, grated cucumber, grated garlic, lemon juice, and salt.", "Grill or broil kofta skewers 3-4 minutes per side until cooked through and charred.", "Serve in warm pita bread with tzatziki and sliced tomatoes and cucumbers."]'::jsonb, 4, 20, 15, 2.9, 11.6, 500, 34, 38, 22, 2, 680, true, true, true, 'curated'),
  ('Breakfast Sausage Biscuit Casserole', 'A crowd-pleasing breakfast bake with layers of fluffy biscuit pieces, crumbled sausage, eggs, and melted cheddar all in one dish.', 'breakfast', 'Southern', 'budget', ARRAY['breakfast','budget','casserole','family-friendly','gluten-free','high-protein','kid-friendly','make-ahead','nut-free','pork','southern','soy-free','standard']::text[], '["1 lb pork breakfast sausage", "1 can refrigerated biscuits", "6 eggs", "0.5 cup milk", "1.5 cups shredded cheddar cheese", "1 tsp garlic powder", "0.5 tsp black pepper", "salt to taste"]'::jsonb, '["Preheat oven to 350\u00b0F; cook and crumble sausage in a skillet over medium heat until browned; drain on paper towels.", "Cut biscuits into quarters and spread across the bottom of a greased 9x13 baking dish; top with cooked sausage and 1 cup of cheese.", "Whisk eggs with milk, garlic powder, salt, and pepper; pour evenly over the sausage and biscuit layer.", "Top with remaining cheese and bake 35-40 minutes until eggs are set and top is golden.", "Let cool 5 minutes before slicing and serving."]'::jsonb, 6, 15, 40, 1.9, 11.4, 490, 26, 30, 30, 1, 980, true, true, true, 'curated'),
  ('Spicy Kung Pao Chicken', 'Tender chunks of chicken with crunchy peanuts and dried chilies in a bold sweet-spicy-tangy kung pao sauce over steamed rice.', 'dinner', 'Chinese', 'budget', ARRAY['asian','budget','chicken','chinese','dairy-free','egg-free','high-protein','nut-free','spicy','standard','stir-fry']::text[], '["1.5 lb boneless chicken breast, cubed", "0.5 cup dry roasted peanuts", "6 dried red chili peppers", "3 tbsp soy sauce", "1 tbsp rice vinegar", "1 tbsp hoisin sauce", "1 tsp sugar", "1 tbsp cornstarch", "3 cloves garlic, minced", "1 tsp ginger, minced", "2 tbsp vegetable oil", "3 green onions, sliced"]'::jsonb, '["Toss chicken cubes with 1 tbsp soy sauce and cornstarch; let marinate 10 minutes.", "Whisk remaining soy sauce, rice vinegar, hoisin, and sugar to make the sauce.", "Heat oil in a wok or large skillet over high heat; stir-fry dried chilies and chicken until chicken is golden, about 5 minutes.", "Add garlic and ginger; stir-fry 30 seconds; pour in sauce and toss to coat.", "Add peanuts and green onions; toss everything together and serve immediately over steamed rice."]'::jsonb, 4, 15, 15, 2.7, 10.8, 440, 40, 16, 22, 2, 940, false, true, true, 'curated'),
  ('Loaded Ground Beef Tater Tot Casserole', 'A Midwestern comfort classic with a cheesy seasoned ground beef filling topped with crispy golden tater tots.', 'dinner', 'American', 'ultra_budget', ARRAY['american','beef','budget','casserole','comfort-food','egg-free','family-friendly','gluten-free','high-protein','kid-friendly','nut-free','soy-free','standard']::text[], '["1 lb ground beef", "1 bag (32 oz) frozen tater tots", "1 can cream of mushroom soup", "1 cup frozen mixed vegetables", "1.5 cups shredded cheddar cheese", "1 small onion, diced", "1 tsp garlic powder", "salt and pepper to taste"]'::jsonb, '["Preheat oven to 375\u00b0F; brown ground beef with onion over medium heat and drain fat.", "Season beef with garlic powder, salt, and pepper; stir in cream of mushroom soup and frozen vegetables.", "Spread the beef mixture evenly in a greased 9x13 baking dish and top with 1 cup of shredded cheese.", "Arrange tater tots in a single layer over the top and sprinkle with remaining cheese.", "Bake 40-45 minutes until tater tots are golden and crispy; let rest 5 minutes before serving."]'::jsonb, 6, 15, 45, 1.5, 9.0, 560, 24, 52, 28, 4, 900, true, true, true, 'curated'),
  ('Chicken Marsala with Egg Noodles', 'Pan-seared chicken cutlets in a rich Marsala wine and mushroom cream sauce served over buttered egg noodles.', 'dinner', 'Italian', 'standard', ARRAY['chicken','comfort-food','creamy','high-protein','italian','kid-friendly','nut-free','pasta','soy-free','standard']::text[], '["4 boneless chicken breasts, pounded thin", "8 oz egg noodles", "8 oz baby bella mushrooms, sliced", "0.5 cup Marsala wine", "0.5 cup heavy cream", "0.5 cup chicken broth", "0.25 cup all-purpose flour", "2 tbsp butter", "2 tbsp olive oil", "2 cloves garlic, minced", "1 tbsp fresh parsley", "salt and pepper to taste"]'::jsonb, '["Cook egg noodles per package directions; drain and toss with 1 tbsp butter.", "Dredge chicken cutlets in flour seasoned with salt and pepper; shake off excess.", "Heat oil and 1 tbsp butter over medium-high heat; cook chicken 3-4 minutes per side until golden; remove and rest.", "In the same pan, cook mushrooms and garlic 4 minutes; pour in Marsala and broth, scraping up browned bits; simmer 3 minutes.", "Stir in heavy cream and simmer 2 minutes until slightly thickened; return chicken to sauce and heat through; serve over egg noodles with parsley."]'::jsonb, 4, 15, 25, 4.2, 16.8, 580, 40, 42, 24, 2, 560, true, true, true, 'curated'),
  ('Smoky Black-Eyed Pea and Ham Hock Soup', 'A deeply savory Southern soup of slow-simmered black-eyed peas with a smoky ham hock, onion, and collard greens.', 'dinner', 'Southern', 'ultra_budget', ARRAY['budget','comfort-food','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','nut-free','one-pot','pork','soup','southern','soy-free','standard']::text[], '["1 lb dried black-eyed peas, soaked overnight", "1 smoked ham hock", "1 onion, diced", "3 cloves garlic, minced", "2 cups chopped collard greens", "6 cups water", "1 tsp smoked paprika", "0.5 tsp thyme", "1 bay leaf", "salt and pepper to taste", "hot sauce for serving"]'::jsonb, '["Drain soaked black-eyed peas and place in a large pot with ham hock, water, onion, garlic, bay leaf, and thyme.", "Bring to a boil, then reduce heat and simmer covered for 1 hour until peas are nearly tender.", "Remove ham hock; shred the meat off the bone and discard the bone and skin; return meat to pot.", "Add collard greens and smoked paprika; simmer 20 more minutes until greens are tender.", "Season with salt and pepper; discard bay leaf; serve with hot sauce and cornbread."]'::jsonb, 6, 10, 90, 1.2, 7.2, 310, 24, 38, 7, 10, 640, true, true, true, 'curated'),
  ('Philly Cheesesteak Quesadillas', 'Shaved beef, sauteed peppers and onions, and melted provolone cheese folded into crispy flour tortillas for a mash-up lunch.', 'lunch', 'American', 'budget', ARRAY['american','beef','budget','comfort-food','egg-free','high-protein','kid-friendly','lunch','nut-free','sandwiches','soy-free','standard']::text[], '["0.75 lb shaved beef (or thin-sliced sirloin)", "4 large flour tortillas", "1 green bell pepper, sliced thin", "1 onion, sliced thin", "1.5 cups shredded provolone cheese", "2 tbsp vegetable oil", "1 tsp Worcestershire sauce", "salt and pepper to taste"]'::jsonb, '["Saute bell pepper and onion in 1 tbsp oil over medium-high heat 6-8 minutes until caramelized; remove.", "In the same pan, cook shaved beef in remaining oil over high heat 2-3 minutes; season with Worcestershire, salt, and pepper.", "Lay a tortilla flat; cover half with provolone, then beef, then peppers and onions; fold in half.", "Cook quesadilla in a lightly oiled skillet over medium heat 2-3 minutes per side until golden and cheese melts.", "Cut into wedges and serve with hot sauce or ketchup."]'::jsonb, 4, 10, 20, 2.8, 11.2, 520, 32, 34, 28, 2, 860, true, true, true, 'curated'),
  ('Baked Honey Mustard Pork Tenderloin', 'A whole pork tenderloin coated in a tangy honey mustard glaze roasted until juicy and caramelized, sliced thin and served with roasted carrots.', 'dinner', 'American', 'standard', ARRAY['american','baked','dairy-free','easy','egg-free','family-friendly','gluten-free','high-protein','kid-friendly','nut-free','pork','soy-free','standard']::text[], '["1.5 lb pork tenderloin", "3 tbsp Dijon mustard", "2 tbsp honey", "1 tbsp olive oil", "2 cloves garlic, minced", "0.5 tsp thyme", "1 lb carrots, peeled and cut into sticks", "salt and pepper to taste"]'::jsonb, '["Preheat oven to 425\u00b0F; mix Dijon mustard, honey, olive oil, garlic, and thyme to make the glaze.", "Season pork tenderloin with salt and pepper; coat generously with the honey-mustard glaze.", "Toss carrot sticks with a little olive oil, salt, and pepper; arrange around the tenderloin in a roasting pan.", "Roast 20-25 minutes until pork reaches 145\u00b0F internal temperature; remove and let rest 5 minutes.", "Slice tenderloin into medallions and serve with roasted carrots and pan juices."]'::jsonb, 4, 10, 25, 3.5, 14.0, 330, 38, 18, 10, 3, 560, true, true, true, 'curated'),
  ('Chicken Tikka Masala Over Basmati Rice', 'Charred marinated chicken in a rich creamy tomato-spiced masala sauce served over fluffy basmati rice — a beloved Indian restaurant staple made at home.', 'dinner', 'Indian', 'standard', ARRAY['aromatic','chicken','creamy','egg-free','gluten-free','high-protein','indian','kid-friendly','nut-free','soy-free','standard']::text[], '["1.5 lb boneless chicken thighs, cubed", "1 cup plain yogurt", "1 can crushed tomatoes", "0.5 cup heavy cream", "1 onion, diced", "4 cloves garlic, minced", "1 tbsp ginger, minced", "2 tbsp butter", "2 tsp garam masala", "1 tsp cumin", "1 tsp paprika", "0.5 tsp turmeric", "2 cups basmati rice", "4 cups water", "salt to taste"]'::jsonb, '["Marinate chicken in yogurt with 1 tsp garam masala, cumin, and a pinch of salt for at least 30 minutes.", "Cook basmati rice in water per package directions; fluff and keep warm.", "Broil marinated chicken on a foil-lined sheet pan 8-10 minutes until slightly charred; set aside.", "Melt butter in a saucepan; cook onion until soft, then add garlic, ginger, remaining garam masala, paprika, and turmeric; cook 2 minutes.", "Stir in crushed tomatoes and simmer 10 minutes; blend sauce smooth if desired; add cream and chicken; simmer 5 minutes and serve over basmati rice."]'::jsonb, 4, 15, 30, 3.9, 15.6, 590, 40, 54, 22, 3, 680, true, true, true, 'curated'),
  ('Crispy Carnitas Street Tacos', 'Slow-cooked pork shoulder crisped in its own fat and piled into warm corn tortillas with fresh white onion, cilantro, and salsa verde.', 'dinner', 'Mexican', 'budget', ARRAY['budget','dairy-free','egg-free','gluten-free','high-protein','kid-friendly','mexican','nut-free','pork','slow-cooker','soy-free','standard','tacos']::text[], '["2 lb pork shoulder, cut into large chunks", "1 orange, juiced", "1 lime, juiced", "4 cloves garlic, minced", "1 tsp cumin", "1 tsp chili powder", "0.5 tsp oregano", "salt and pepper to taste", "12 small corn tortillas", "1 white onion, diced fine", "0.5 cup cilantro, chopped", "1 cup salsa verde"]'::jsonb, '["Season pork chunks with cumin, chili powder, oregano, salt, and pepper; place in slow cooker with orange juice, lime juice, and garlic.", "Cook on low 8 hours or high 5 hours until pork is completely fall-apart tender.", "Shred pork with forks and spread on a sheet pan; broil 5-7 minutes until edges are crispy.", "Warm corn tortillas directly over a gas flame or in a dry skillet.", "Fill tortillas with crispy carnitas and top with diced onion, cilantro, and a drizzle of salsa verde."]'::jsonb, 6, 15, 480, 2.3, 13.8, 420, 32, 30, 18, 3, 620, true, true, true, 'curated'),
  ('Tuna Noodle Casserole with Peas', 'A nostalgic mid-century casserole of egg noodles, canned tuna, sweet peas, and cream of mushroom sauce topped with buttery breadcrumbs.', 'dinner', 'American', 'ultra_budget', ARRAY['american','budget','casserole','comfort-food','family-friendly','high-protein','kid-friendly','nut-free','seafood','soy-free','standard']::text[], '["2 cans tuna in water, drained", "8 oz egg noodles", "1 can cream of mushroom soup", "1 cup frozen peas", "1 cup milk", "1 cup shredded cheddar cheese", "0.5 cup breadcrumbs", "2 tbsp butter", "1 tsp garlic powder", "salt and pepper to taste"]'::jsonb, '["Preheat oven to 375\u00b0F; cook egg noodles per package directions until just al dente; drain.", "Mix cream of mushroom soup with milk, garlic powder, salt, and pepper in a large bowl; stir in tuna, peas, and cooked noodles.", "Pour into a greased 9x13 baking dish; top with shredded cheddar cheese.", "Mix breadcrumbs with melted butter and sprinkle over the top.", "Bake 25-30 minutes until bubbly and breadcrumbs are golden brown; let rest 5 minutes before serving."]'::jsonb, 6, 15, 30, 1.3, 7.8, 390, 26, 42, 12, 3, 780, true, true, true, 'curated');
